-- 세팅 과정 607개를 오른손잡이 기준 좌우 명시로 다시 씀 (D-74). 운영 화면에서 그사이 고친 카드(지금 글이 아래 '이전 글'과 다름)는 건드리지 않는다.
update public.techniques set steps = array['턱을 당겨 뒤통수가 바닥에 닿지 않게 한다','엉덩이 → 등 순서로 둥글게 닿으며 넘어진다','닿는 순간 팔을 45도로 펴서 손바닥으로 바닥을 친다(옆낙법은 넘어지는 쪽 팔 하나 — 왼쪽으로 넘어지면 왼팔)','무릎을 굽혀 세우고 바로 일어날 수 있게 자세를 모은다']::text[] where slug = 'breakfall' and owner_id is null and steps = array['턱을 당겨 뒤통수가 바닥에 닿지 않게 한다','엉덩이 → 등 순서로 둥글게 닿으며 넘어진다','닿는 순간 팔을 45도로 펴서 손바닥으로 바닥을 친다(옆낙법은 한 팔)','무릎을 굽혀 세우고 바로 일어날 수 있게 자세를 모은다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 내 왼손은 상대 오른쪽 소매 끝을 잡는다','상대 오른손이 내 왼쪽 깃을 잡으면, 소매 잡은 내 왼손으로 그 손목을 아래로 당겨 떼어낸다','내 두 그립은 팔꿈치를 몸에 붙여 짧게 유지한다','그립을 먼저 잡은 쪽이 테이크다운이나 가드 풀링을 시작한다']::text[] where slug = 'grip-fighting' and owner_id is null and steps = array['한 손은 상대 깃(칼라), 반대 손은 같은 쪽 소매 끝을 잡는다','상대가 내 깃을 잡으면 손목을 돌리고 팔을 당겨 바로 떼어낸다','내 그립은 팔꿈치를 몸에 붙여 짧게 유지한다','그립을 먼저 잡은 쪽이 테이크다운이나 가드 풀링을 시작한다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 내 왼손은 상대 오른쪽 소매(또는 손목)를 잡는다','내 오른발을 상대 왼쪽 골반에 밟고 엉덩이를 뒤로 떨어뜨리며 상대를 당긴다','내 왼다리를 상대 오른쪽 허리 뒤로 감는다','내 오른발도 골반에서 빼 상대 등 뒤로 감고 두 발목을 걸어 클로즈드 가드를 완성한다(또는 바로 오픈 가드)']::text[] where slug = 'pulling-guard' and owner_id is null and steps = array['깃과 소매(또는 손목)를 잡는다','한 발을 상대 골반에 밟고 엉덩이를 뒤로 떨어뜨리며 상대를 당긴다','밟은 발 반대 다리를 상대 허리에 감는다','양 다리를 상대 등 뒤에서 걸어 클로즈드 가드를 완성한다(또는 바로 오픈 가드)']::text[];
update public.techniques set steps = array['자세를 낮추고 앞발인 내 왼발을 상대 다리 사이로 깊게 내딛는다','양팔로 상대 양 무릎 뒤를 감아 당긴다','머리를 상대 오른쪽 옆구리에 붙이고 가슴을 앞으로 민다','뒷발인 내 오른발을 끌어와 머리 쪽(상대 오른쪽)으로 돌며 눕히고 바로 사이드로 올라간다']::text[] where slug = 'double-leg-takedown' and owner_id is null and steps = array['자세를 낮추고 앞발을 상대 다리 사이로 깊게 내딛는다','양팔로 상대 무릎 뒤를 감아 당긴다','머리를 상대 옆구리에 붙이고 가슴을 앞으로 민다','뒷발을 끌어와 옆으로 돌며 눕히고 바로 사이드로 올라간다']::text[];
update public.techniques set steps = array['자세를 낮춰 들어가며 상대 오른다리(앞다리)를 양팔로 안는다','머리를 상대 가슴 안쪽(상대 오른다리의 안쪽 선)에 붙여 길로틴을 막는다','잡은 상대 오른다리를 내 두 허벅지 사이에 끼우고 일어선다','상대 오른다리를 든 채 상대 왼다리를 내 다리로 걸거나 몸을 돌려 넘어뜨리고 패스 자세를 잡는다']::text[] where slug = 'single-leg-takedown' and owner_id is null and steps = array['앞발을 내딛으며 상대 한쪽 다리를 양팔로 안는다','머리를 상대 가슴 안쪽에 붙여 길로틴을 막는다','잡은 다리를 내 허벅지 사이에 끼우고 일어선다','다리를 바깥으로 밀거나 걸어 넘어뜨리고 패스 자세를 잡는다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 상대를 상대 오른쪽 뒤 모서리로 민다','내 왼발을 상대 오른발 바깥 옆에 깊게 딛고 가슴을 붙인다','내 오른다리를 상대 오른다리 뒤로 높이 넘긴다','내 오른다리를 뒤로 크게 후리며 깃 잡은 오른손으로 상체를 뒤로 눌러 넘긴다']::text[] where slug = 'o-soto-gari' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 뒤쪽 모서리로 밀어 뒤꿈치에 체중이 실리게 한다','소매를 잡은 손 쪽 발(지지 발)을 상대 같은 쪽 발 바깥 옆에 깊게 내딛는다','반대 다리를 상대 다리 바깥쪽으로 크게 휘둘러 올린다','다리를 뒤로 후리며 깃 잡은 손으로 상체를 아래로 눌러 넘어뜨린다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 뒤로 밀어 상대 왼발에 체중을 싣게 한다','상대 다리 사이로 내 오른다리를 넣어 상대 왼쪽 종아리 안쪽을 건다','건 오른다리를 상대 왼쪽 바깥으로 둥글게 후리며 상체는 상대 왼쪽 뒤로 민다','넘어가면 상대 다리 사이로 들어가 패스 자세를 잡는다']::text[] where slug = 'o-uchi-gari' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 뒤쪽으로 밀어 한쪽 발에 체중을 싣게 한다','상대 다리 사이로 내 다리를 넣어 그 발의 종아리 안쪽을 건다','건 다리를 둥글게 뒤로 후리며 상체는 그쪽 뒤로 민다','넘어가면 다리 사이로 들어가 패스 자세를 잡는다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 앞으로 당겨 발끝에 체중을 싣게 한다','내 오른발을 상대 오른발 앞에 딛고 왼발을 뒤로 돌려 등을 상대 가슴에 붙인다','깃 잡은 내 오른팔 팔꿈치를 상대 오른쪽 겨드랑이 아래에 넣는다','무릎을 굽혀 엉덩이를 상대 허리보다 낮게 둔다','다리를 펴며 상체를 숙이고 왼손으로 소매를 당겨 내 오른쪽 어깨 너머로 넘긴다']::text[] where slug = 'seoi-nage' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 앞으로 당긴다','소매 쪽으로 돌아 들어가며 등을 상대 가슴에 붙인다','무릎을 굽혀 엉덩이를 상대보다 낮게 둔다','다리를 펴며 상체를 숙여 어깨 위로 넘긴다']::text[];
update public.techniques set steps = array['상대 오른 손목을 내 왼손으로 잡는다(마주 보고 거울처럼)','내 오른손을 뻗어 상대 오른팔 삼두(팔꿈치 위)를 잡는다','그 팔을 내 오른쪽 엉덩이 쪽으로 끌어당기며 내 왼발을 상대 오른쪽 옆으로 딛는다','상대 오른쪽으로 돌아 등 뒤에 붙어 허리를 안거나 시트벨트를 잡는다']::text[] where slug = 'arm-drag-standing' and owner_id is null and steps = array['상대 한 손목을 같은 쪽 손으로 잡는다','반대 손으로 그 팔의 삼두(팔꿈치 위)를 잡아 내 옆으로 끌어 당긴다','당기며 상대 옆으로 빠져 등 뒤로 돌아 들어간다','허리를 안거나(바디락) 시트벨트를 잡아 백을 잡는다']::text[];
update public.techniques set steps = array['상대가 다리로 들어오면 양 다리를 뒤로 쭉 빼고 엉덩이를 바닥 쪽으로 낮춘다','가슴과 체중을 상대 등 위로 실어 누른다','내 오른팔을 상대 왼쪽 겨드랑이 아래로 넣어 언더훅을 잡거나, 오른팔로 목 앞을 감아 프론트 헤드락을 잡는다','상대가 손을 놓으면 그 쪽(상대 왼쪽)으로 돌아 백이나 터틀 탑으로 간다']::text[] where slug = 'sprawl' and owner_id is null and steps = array['상대가 다리로 들어오면 양 다리를 뒤로 쭉 빼고 엉덩이를 바닥 쪽으로 낮춘다','가슴과 체중을 상대 등 위로 실어 누른다','한 팔은 상대 겨드랑이 아래로 넣어 언더훅을 잡거나 목 앞을 감아 프론트 헤드락을 잡는다','상대가 손을 놓으면 옆으로 돌아 백이나 터틀 탑으로 간다']::text[];
update public.techniques set steps = array['상대 머리가 내 오른쪽 겨드랑이 아래로 숙여진 순간 오른팔로 목을 감아 오른 손목 안쪽 뼈를 턱 밑에 넣는다','내 왼손으로 오른손을 잡고 오른쪽 팔꿈치를 내 오른쪽 옆구리에 붙인다','상대가 밀고 들어오면 엉덩이를 빼 버티고, 자리가 잡히면 가슴을 펴며 오른팔을 천천히 위로 끌어올린다','서서 안 끝나면 그립을 유지한 채 앉아 두 다리로 허리를 감고 조인다(탭하면 바로 푼다)']::text[] where slug = 'standing-guillotine' and owner_id is null and steps = array['상대 머리가 아래로 숙여진 순간(테이크다운 시도 등) 한 팔을 목 앞으로 감는다','감은 손을 반대 손으로 잡아 그립을 만든다(팔꿈치는 가슴에 붙임)','엉덩이를 뒤로 빼고 가슴을 펴서 목을 당긴다','앉아서 끝낼 땐 뒤로 눕지 말고 몸을 옆으로 틀어 체중으로 조인다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 상대를 당긴다','내 오른발을 상대 왼쪽 골반에, 또는 왼발을 상대 오른쪽 이두에 대며 앉는다','앉으며 바로 내 오른다리로 상대 왼다리에 데라히바 훅을 걸거나 왼발로 스파이더를 잡는다','상대 균형을 흔들며 스윕을 노린다']::text[] where slug = 'standing-guard-pull' and owner_id is null and steps = array['깃 · 소매 그립을 잡고 상대를 당긴다','한 발을 상대 골반이나 이두에 대며 앉는다','앉으며 바로 훅이나 발 위치를 잡는다(데라히바 · 스파이더 등)','상대 균형을 흔들며 스윕을 노린다']::text[];
update public.techniques set steps = array['내 오른팔로 상대 왼쪽 겨드랑이 언더훅(또는 상대 왼쪽 깃)을 잡고 상대 가까이 붙는다','엉덩이를 바닥에 앉히며 내 오른발은 상대 왼쪽 허벅지 안쪽, 왼발은 상대 오른쪽 허벅지 안쪽에 넣는다','상체를 세운 채 상대 체중을 받는다','바로 버터플라이 스윕으로 잇는다(내 왼쪽으로 기울며 오른발 훅으로 들어 넘김)']::text[] where slug = 'butterfly-guard-pull' and owner_id is null and steps = array['깃이나 언더훅을 잡고 상대 가까이 붙는다','엉덩이를 바닥에 앉히며 양 발을 상대 허벅지 안쪽에 넣는다','상체를 세운 채 상대 체중을 받는다','바로 버터플라이 스윕으로 잇는다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 상대 쪽으로 몸을 낮춘다','내 오른발을 상대 왼쪽 골반에 대고 뒤로 구르듯 앉는다','구르는 힘으로 상대를 앞으로 당겨 포스처를 깬다','내 왼다리, 오른다리를 상대 허리 뒤로 감아 발목을 걸고 클로즈드 가드로']::text[] where slug = 'rolling-guard-pull' and owner_id is null and steps = array['깃과 소매를 잡고 상대 쪽으로 몸을 낮춘다','한 발을 상대 골반에 대고 뒤로 구르듯 앉는다','구르는 힘으로 상대를 앞으로 당겨 포스처를 깬다','다리를 감아 클로즈드 가드로']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 상대 가까이 선다(상대가 받아 줄 수 있을 때만, 화이트 벨트 시합에선 금지)','내 오른발을 상대 왼쪽 골반에 먼저 대고 뛰어 올라 양 다리를 상대 허리 뒤에서 감는다','오른손 깃 그립으로 상대 상체를 당겨 무너뜨린다(상대가 버티고 서 있으면 함께 넘어질 수 있어 주의)','바닥에 닿으면 클로즈드 가드로']::text[] where slug = 'jumping-guard' and owner_id is null and steps = array['깃과 소매를 잡고 상대 가까이 선다(상대가 받아 줄 수 있을 때만 하고, 화이트 벨트 시합에선 금지)','한 발을 상대 골반에 먼저 대고 뛰어 올라 양 다리를 상대 허리에 감는다','상대 목을 당겨 무너뜨린다(상대가 버티고 서 있으면 함께 넘어질 수 있어 주의)','바닥에 닿으면 클로즈드 가드로']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 엉덩이를 바닥에 앉힌다','내 오른발로 상대 왼쪽 무릎이나 골반을 막는다','상체를 세워 상대가 들어오지 못하게 한다','소매를 놓은 내 왼손으로 상대 오른쪽 발목 뒤를 잡아 스윕이나 싱글 레그로 잇는다']::text[] where slug = 'sitting-guard-pull' and owner_id is null and steps = array['그립을 잡고 엉덩이를 바닥에 앉힌다','한 발은 상대 무릎이나 골반을 막는다','상체를 세워 상대가 들어오지 못하게 한다','상대 발목을 잡아 스윕이나 싱글 레그로 잇는다']::text[];
update public.techniques set steps = array['무릎을 굽혀 자세를 낮춘다(허리를 숙이지 않는다)','상대 두 팔 사이로 머리를 넣으며 내 왼발(앞발)을 상대 다리 사이로 내딛는다','양팔로 상대 무릎이나 허벅지를 안고 머리를 상대 오른쪽 옆구리에 붙여 밀어붙인다','내 오른발을 끌어와 머리 쪽(상대 오른쪽)으로 돌며 눕히고 위로 올라간다']::text[] where slug = 'level-change-takedown' and owner_id is null and steps = array['무릎을 굽혀 자세를 낮춘다(허리를 숙이지 않는다)','상대 팔 사이로 머리를 넣으며 다리로 들어간다','무릎이나 허벅지를 안아 상체를 밀어붙인다','옆으로 돌며 눕히고 위로 올라간다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 목 뒤를, 왼손으로 상대 오른쪽 팔꿈치(삼두)를 잡는다','당기며 아래로 강하게 낚아채 상대 머리를 내린다','상대가 손을 짚으면 가슴으로 머리를 누르고 오른팔로 목을 감아 프론트 헤드락을 잡는다','상대 오른쪽(팔꿈치 잡은 쪽)으로 돌아 백을 잡거나 길로틴으로 잇는다']::text[] where slug = 'snap-down-from-standing' and owner_id is null and steps = array['상대 목 뒤와 팔꿈치(또는 삼두)를 잡는다','당기며 아래로 강하게 낚아채 상대 머리를 내린다','상대가 손을 짚으면 가슴으로 머리를 눌러 프론트 헤드락을 잡는다','백이나 길로틴으로 잇는다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 깃(또는 목 뒤)을 잡고 머리를 당겨 상대 오른발(앞발)에 체중을 싣게 한다','몸을 낮추며 내 왼손으로 상대 오른발 발목 바깥쪽을 잡는다','오른손 깃은 상대 뒤쪽으로 밀고 왼손 발목은 내 쪽으로 당겨 상대를 앉힌다','발목을 놓지 않고 패스 자세로 올라간다']::text[] where slug = 'ankle-pick' and owner_id is null and steps = array['깃(또는 목 뒤)을 잡고 상대 머리를 당겨 앞발에 체중을 싣게 한다','몸을 낮추며 깃 잡은 손 반대 손으로 그 앞발 발목 바깥쪽을 잡는다','깃을 밀고 발목을 당겨 상대를 앉힌다','발목을 놓지 않고 패스 자세로 올라간다']::text[];
update public.techniques set steps = array['그립 싸움 중 상대 오른발(앞발)이 가까워지는 순간을 잡는다','자세를 낮추고 머리를 상대 가슴 안쪽에 붙이며 양팔로 상대 오른다리를 안는다','무릎을 세워 상대 오른다리를 내 두 허벅지 사이에 끼운다','일어서며 피니시 자세로']::text[] where slug = 'single-leg-entry' and owner_id is null and steps = array['그립 싸움 중 상대 앞발이 가까워지는 순간을 잡는다','자세를 낮추고 머리를 상대 가슴 안쪽에 붙이며 다리를 안는다','무릎을 세워 다리를 내 허벅지 사이에 끼운다','일어서며 피니시 자세로']::text[];
update public.techniques set steps = array['자세를 낮추고 뒷발인 내 오른발로 바닥을 밀어 앞발인 왼발을 상대 다리 사이로 깊게 넣는다','내 왼쪽 무릎이 바닥에 닿게 하며 양팔로 상대 양 무릎 뒤를 감싼다','머리는 상대 오른쪽 옆구리에 붙인다','내 오른발을 끌어와 일어서며 넘어뜨릴 준비']::text[] where slug = 'double-leg-entry' and owner_id is null and steps = array['자세를 낮추고 뒷발로 바닥을 밀어 앞발을 상대 다리 사이로 깊게 넣는다','앞무릎이 바닥에 닿게 하며 양팔로 무릎 뒤를 감싼다','머리는 상대 옆구리에 붙인다','뒷발을 끌어와 일어서며 넘어뜨릴 준비']::text[];
update public.techniques set steps = array['양다리를 안은 채 머리를 상대 오른쪽 옆구리에 붙인다','뒷발인 내 오른발을 끌어와 서서 상대를 들거나 민다','머리 쪽인 상대 오른쪽으로 돌며(코너 돌기) 상대를 눕힌다','바로 사이드 컨트롤로 올라간다']::text[] where slug = 'double-leg-finish' and owner_id is null and steps = array['다리를 안은 채 머리를 상대 옆구리에 붙인다','뒷발을 끌어와 서서 상대를 들거나 민다','머리 쪽으로 돌며(코너 돌기) 상대를 눕힌다','바로 사이드 컨트롤로 올라간다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른팔을 밀어 올리며 몸을 낮춘다','머리는 상대 오른다리 바깥쪽에 두고, 내 오른팔은 상대 오른다리 안쪽 깊숙이(사타구니 가까이) 넣어 허벅지를 안는다','상대 오른다리를 안고 일어서며 상대를 들어 올린다','머리 쪽인 상대 오른쪽으로 돌리며 눕히고 패스 자세로']::text[] where slug = 'high-crotch' and owner_id is null and steps = array['상대 한쪽 팔을 밀어 올리며 몸을 낮춘다','머리는 상대 다리 바깥쪽에 두고, 팔은 같은 쪽 다리 안쪽 깊숙이(사타구니 가까이) 넣어 허벅지를 안는다','다리를 안고 일어서며 상대를 들어 올린다','옆으로 돌리며 눕히고 패스 자세로']::text[];
update public.techniques set steps = array['내 오른팔로 상대 왼쪽 언더훅(또는 상대 왼쪽 깃)을 잡고 밀어 상대 오른다리에 체중을 싣게 한다','내 왼손을 내려 상대 오른쪽 무릎 바깥쪽을 잡는다(탭)','오른팔 언더훅으로 밀며 왼손으로 무릎을 당겨 상대를 상대 오른쪽 무릎 위로 넘어뜨린다','넘어가면 바로 사이드로']::text[] where slug = 'knee-tap' and owner_id is null and steps = array['언더훅(또는 깃)을 잡고 상대를 밀어 반대쪽 다리에 체중을 싣게 한다','자유로운 손을 내려 그 무릎 바깥쪽을 잡는다(탭)','언더훅으로 밀며 무릎을 당겨 상대를 그 무릎 위로 넘어뜨린다','넘어가면 바로 사이드로']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매(팔)를 잡아 당기며 상대 다리 사이로 무릎을 꿇고 들어간다','내 오른팔을 상대 다리 사이로 넣어 상대 오른쪽 허벅지를 안고 상대를 내 어깨에 걸친다','등으로 상대를 들어 잡은 상대 오른팔 쪽(내 왼쪽)으로 넘긴다','넘어진 상대 위로 사이드 컨트롤']::text[] where slug = 'firemans-carry' and owner_id is null and steps = array['상대 한 팔(소매)을 잡아 당기며 상대 다리 사이로 무릎을 꿇고 들어간다','반대 팔을 상대 다리 사이로 넣어 잡은 팔과 같은 쪽 허벅지를 안아 상대를 어깨에 걸친다','등으로 상대를 들어 잡은 팔 쪽으로 넘긴다','넘어진 상대 위로 사이드 컨트롤']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 앞으로 당긴다','내 왼쪽(소매 쪽)으로 몸을 돌려 들어가며 허리를 붙인다','내 오른다리를 상대 왼쪽 허벅지 안쪽으로 높게 들어 올린다','상체를 숙이고 왼손으로 소매를 당기며 다리를 들어 넘긴다']::text[] where slug = 'uchi-mata' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 앞으로 당긴다','소매 쪽으로 돌아 들어가며 허리를 붙인다','안쪽 다리를 상대 허벅지 안쪽으로 높게 들어 올린다','상체를 숙이며 다리를 들어 넘긴다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 앞으로 당긴다','내 왼쪽으로 몸을 돌려 들어가며 내 오른쪽 엉덩이를 상대 앞에 붙인다','내 오른다리로 상대 오른쪽 허벅지 바깥쪽을 쓸어 올린다','상체를 숙이고 왼손으로 소매를 당기며 넘긴다']::text[] where slug = 'harai-goshi' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 앞으로 당긴다','돌아 들어가며 엉덩이를 상대 앞에 붙인다','다리를 상대 허벅지 바깥쪽으로 쓸어 올린다','상체를 숙이며 넘긴다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 앞으로 당긴다','내 왼쪽으로 돌아 들어가며 내 오른다리를 상대 오른발 앞(정강이 앞)에 뻗어 가로막는다','엉덩이를 붙이지 않고 그립으로 상대를 내 오른다리 위로 당겨 넘긴다','넘어가면 왼손 소매 그립을 놓지 않고 사이드로']::text[] where slug = 'tai-otoshi' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 앞으로 당긴다','돌아 들어가며 한 다리를 상대 발 앞에 뻗어 가로막는다','엉덩이를 붙이지 않고 그립으로 상대를 다리 위로 당겨 넘긴다','넘어가면 소매를 놓지 않고 사이드로']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매를 잡고 상대를 당긴다','내 오른발을 상대 오른발 앞에 딛고 몸을 돌려 들어가며 내 오른팔을 상대 오른쪽 겨드랑이 아래로 넣어 팔을 감는다','무릎을 굽혀 엉덩이를 낮게 붙인다','다리를 펴며 숙여 내 오른쪽 어깨 너머로 넘긴다']::text[] where slug = 'ippon-seoi-nage' and owner_id is null and steps = array['한쪽 소매를 잡고 상대를 당긴다','돌아 들어가며 반대 팔을 상대 겨드랑이 아래로 넣어 팔을 감는다','무릎을 굽혀 엉덩이를 낮게 붙인다','다리를 펴며 숙여 어깨 너머로 넘긴다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡는다','내 왼쪽으로 돌아 들어가며 깃 잡은 내 오른쪽 팔꿈치를 상대 오른쪽 겨드랑이에 넣는다','무릎을 굽혀 엉덩이를 낮게 붙인다','다리를 펴며 숙여 내 오른쪽 어깨 너머로 넘긴다']::text[] where slug = 'morote-seoi-nage' and owner_id is null and steps = array['깃과 소매를 잡는다','돌아 들어가며 깃 잡은 팔꿈치를 상대 겨드랑이에 넣는다','엉덩이를 낮게 붙인다','다리를 펴며 숙여 넘긴다']::text[];
update public.techniques set steps = array['상대를 상대 오른쪽 뒤로 밀어 상대 오른발 뒤꿈치에 체중을 싣게 한다','내 오른발 발바닥으로 상대 오른발 뒤꿈치 안쪽을 쓸어 낸다','상체는 상대 오른쪽 뒤로 밀어 균형을 깬다','넘어가면 상대 다리 사이로 들어가 패스']::text[] where slug = 'kouchi-gari' and owner_id is null and steps = array['상대를 뒤로 밀어 한 발 뒤꿈치에 체중을 싣게 한다','발바닥으로 상대 같은 쪽 발뒤꿈치 안쪽을 쓸어 낸다','상체는 뒤로 밀어 균형을 깬다','넘어가면 다리 사이로 들어가 패스']::text[];
update public.techniques set steps = array['상대를 상대 오른쪽 뒤로 밀어 상대 오른발 뒤꿈치에 체중을 싣게 한다','내 왼발 발바닥으로 상대 오른발 뒤꿈치 바깥쪽을 쓸어 낸다','상체는 상대 오른쪽 뒤로 눌러 넘긴다','넘어가면 바로 사이드로']::text[] where slug = 'kosoto-gari' and owner_id is null and steps = array['상대를 뒤로 밀어 뒤꿈치에 체중을 싣게 한다','발바닥으로 상대 발뒤꿈치 바깥쪽을 쓸어 낸다','상체는 뒤로 눌러 넘긴다','넘어가면 바로 사이드로']::text[];
update public.techniques set steps = array['상대를 상대 오른쪽 뒤로 밀어 체중을 상대 오른발 뒤에 싣는다','내 왼다리로 상대 오른다리 바깥에서 종아리 뒤를 걸어 감는다','건 채 상체를 밀며 체중으로 넘긴다','넘어가면 사이드나 하프 탑']::text[] where slug = 'kosoto-gake' and owner_id is null and steps = array['상대를 뒤로 밀어 체중을 뒤에 싣는다','다리로 상대 다리 바깥에서 종아리를 걸어 감는다','건 채 상체를 밀며 체중으로 넘긴다','넘어가면 사이드나 하프 탑']::text[];
update public.techniques set steps = array['상대가 오른발을 앞으로 옮기는 순간을 본다','그 오른발이 바닥에 닿기 직전 내 왼발 발바닥으로 발목 바깥을 쓸어 낸다','내 왼손으로 소매를 아래로 당기고 오른손 깃으로 상체를 기울여 상대 오른쪽으로 넘긴다','넘어가면 사이드로']::text[] where slug = 'deashi-harai' and owner_id is null and steps = array['상대가 발을 옮기는 순간을 본다','옮기는 발이 바닥에 닿기 직전 발바닥으로 발목을 쓸어 낸다','그립으로 상대 상체를 반대로 당긴다','넘어가면 사이드로']::text[];
update public.techniques set steps = array['상대를 앞으로 당겨 상대 오른발(앞발)에 체중을 싣게 한다','내 왼발 발바닥을 상대 오른발 발목 앞에 대어 막는다','왼손 소매는 내 왼쪽 뒤로 크게 당기고 오른손 깃은 들어 돌리며 상체를 끌어 넘긴다','넘어가면 사이드로']::text[] where slug = 'sasae-tsurikomi-ashi' and owner_id is null and steps = array['상대를 앞으로 당겨 앞발에 체중을 싣게 한다','발바닥을 상대 발목 앞에 대어 막는다','그립으로 크게 돌리며 상체를 끌어 넘긴다','넘어가면 사이드로']::text[];
update public.techniques set steps = array['상대 오른쪽 옆 뒤로 돌아 내 왼다리를 상대 양 다리 뒤로 길게 뻗는다','내 오른손으로 상대 허리띠나 등 뒤 깃을 잡고 내 왼쪽 엉덩이로 앉으며 당긴다','상대가 내 왼다리에 걸려 뒤로 넘어진다','바로 사이드나 하프 탑으로']::text[] where slug = 'tani-otoshi' and owner_id is null and steps = array['상대 옆이나 뒤로 돌아 한 다리를 상대 양 다리 뒤로 길게 뻗는다','상대 허리나 깃을 잡고 뒤로 앉으며 당긴다','상대가 내 다리에 걸려 뒤로 넘어진다','바로 사이드나 하프 탑으로']::text[];
update public.techniques set steps = array['내 오른팔로 상대 왼쪽 언더훅(또는 등 뒤 깃), 왼손으로 상대 오른쪽 소매를 잡고 앞으로 당긴다','뒤로 앉으며 내 오른발을 상대 왼쪽 허벅지 안쪽에 넣는다(버터플라이 훅)','당기며 오른발 훅으로 들어 올려 내 왼쪽 어깨 위로 넘긴다','굴러 올라와 마운트나 사이드']::text[] where slug = 'sumi-gaeshi' and owner_id is null and steps = array['깃이나 언더훅을 잡고 상대를 앞으로 당긴다','뒤로 앉으며 한 발을 상대 허벅지 안쪽에 넣는다(버터플라이 훅)','당기며 훅으로 들어 올려 머리 위로 넘긴다','굴러 올라와 마운트나 사이드']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡고 상대를 당긴다','내 오른발을 상대 배나 골반에 대며 뒤로 눕는다(왼발은 상대 두 발 사이)','양손으로 당기며 오른발로 들어 올려 내 머리 위로 넘긴다','굴러 올라와 마운트']::text[] where slug = 'tomoe-nage' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 당긴다','한 발을 상대 배나 골반에 대며 뒤로 눕는다','당기며 발로 들어 올려 머리 위로 넘긴다','굴러 올라와 마운트']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 목 옆 깃(또는 목 뒤)을 깊게 잡고 왼손으로 상대 오른쪽 소매를 잡는다','깃을 아래로, 내 오른쪽 엉덩이 옆으로 비스듬히 강하게 끌어당긴다','동시에 내 왼발을 왼쪽으로 빼서 상대가 내 오른쪽 옆을 지나 앞으로 쏠리게 한다','상대 왼쪽 옆으로 빠져 등에 붙고 허리를 안거나 백을 잡는다']::text[] where slug = 'collar-drag' and owner_id is null and steps = array['상대 깃을 깊게 잡는다','뒤로 앉거나 물러나며 깃을 강하게 아래로 끌어 당긴다','상대가 앞으로 쏠리면 옆으로 빠져 등 뒤로','백을 잡거나 위로 올라간다']::text[];
update public.techniques set steps = array['싱글 레그로 상대 오른다리를 잡아 들어 올린다','상대가 버티면 다리를 든 채 상대 오른쪽을 돌아 등 뒤로 간다','허리를 안고 바닥으로 끌어내린다','양발 훅을 넣고 백 컨트롤']::text[] where slug = 'single-leg-to-back-take' and owner_id is null and steps = array['싱글 레그로 다리를 잡아 들어 올린다','상대가 버티면 다리를 든 채 상대 뒤로 돈다','허리를 안고 바닥으로 끌어내린다','훅을 넣고 백 컨트롤']::text[];
update public.techniques set steps = array['상대 오른팔을 양손으로 잡는다(내 왼손은 손목, 오른손은 팔꿈치 위, 투 온 원)','그 팔을 내 몸에 붙여 가두고 상대 오른쪽 옆으로 선다','팔을 당기며 상대 오른쪽에서 등 뒤로 돌아간다','허리를 안고 백으로']::text[] where slug = 'russian-tie-to-back-take' and owner_id is null and steps = array['상대 한 팔을 양손으로 잡는다(손목 + 팔꿈치 위, 투 온 원)','그 팔을 내 몸에 붙여 가두고 상대 옆으로 선다','팔을 당기며 상대 뒤로 돌아간다','허리를 안고 백으로']::text[];
update public.techniques set steps = array['상대가 앉으면 바로 허리를 세우고 내 깃 · 소매를 잡은 상대 그립을 뗀다','양손으로 상대 양 무릎이나 바지를 잡아 다리를 컨트롤한다','내 두 발을 상대 다리 사이에서 빼 상대 다리 바깥으로 옮긴다','토레안도나 니슬라이스로 패스 시작']::text[] where slug = 'guard-pull-defense' and owner_id is null and steps = array['상대가 앉으면 바로 허리를 세우고 그립을 뗀다','상대 무릎이나 바지를 잡아 다리를 컨트롤한다','발 위치를 상대 다리 바깥으로 옮긴다','토레안도나 니슬라이스로 패스 시작']::text[];
update public.techniques set steps = array['클린치에서 내 오른팔로 상대 왼쪽 언더훅을 잡거나 오른손으로 상대 왼쪽 깃을 잡는다','엉덩이를 뒤로 떨어뜨리며 상대를 당긴다','내 왼다리, 오른다리 순서로 상대 허리 뒤에 감는다','두 발목을 걸어 클로즈드 가드 완성']::text[] where slug = 'guard-pull-from-clinch' and owner_id is null and steps = array['클린치에서 언더훅이나 깃을 잡는다','엉덩이를 뒤로 떨어뜨리며 상대를 당긴다','다리를 상대 허리에 감는다','클로즈드 가드 완성']::text[];
update public.techniques set steps = array['클린치에서 내 오른팔을 상대 왼팔 아래로 넣어 언더훅을 잡는다(팔꿈치는 몸에 붙임)','상대가 오른팔로 내 왼쪽에 언더훅을 넣으면, 위에 있던 내 왼팔을 안쪽으로 좁게 파고들어 다시 언더훅을 만든다','머리는 언더훅 쪽인 상대 턱 왼쪽 옆에 붙이고 골반을 가까이 붙인다','오른팔 언더훅으로 상대 왼쪽을 들어 올리며 테이크다운이나 백으로 잇는다']::text[] where slug = 'underhook-pummeling' and owner_id is null and steps = array['클린치에서 상대 팔 아래로 내 팔을 넣어 언더훅을 잡는다','상대가 똑같이 넣으면 반대 팔을 빼서 다시 아래로 넣는다(퍼멀)','머리는 언더훅 반대쪽 상대 어깨에 붙인다','언더훅을 잡은 쪽으로 테이크다운을 건다']::text[];
update public.techniques set steps = array['상대 오른팔이 내 왼팔 아래로 언더훅을 넣었으면 내 왼팔로 위에서 눌러 떼어낸다','내 오른손으로 상대 머리(턱 옆)를 밀며 엉덩이를 뒤로 뺀다','한 발 물러나며 오른손 깃 · 왼손 소매 그립을 다시 잡는다','거리를 회복해 스탠딩으로']::text[] where slug = 'break-clinch' and owner_id is null and steps = array['상대 언더훅 팔을 아래로 눌러 떼어낸다','머리를 밀며 엉덩이를 뒤로 뺀다','한 발 물러나며 그립을 다시 잡는다','거리를 회복해 스탠딩으로']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른팔(손목이나 팔꿈치)을 잡아 위로 밀어 올린다','무릎을 굽혀 자세를 낮추며 상대 오른팔 아래로 머리를 넣는다(허리를 숙이지 않는다)','머리로 상대 오른팔을 밀어 올리며 상대 오른쪽을 지나 등 뒤로 돌아 나온다','가슴을 상대 등에 붙여 허리를 안고 바닥으로 끌어내려 백을 잡는다']::text[] where slug = 'duck-under' and owner_id is null and steps = array['상대 팔을 잡아 위로 들어 올린다','그 팔 아래로 머리를 숙여 빠져 들어간다','상대 뒤로 나오며 허리를 안는다','바닥으로 끌어내려 백']::text[];
update public.techniques set steps = array['상대 오른팔을 양손으로 잡는다(내 왼손은 손목, 오른손은 팔꿈치 위)','그 팔을 내 가슴에 붙여 가두고 상대 오른쪽 옆으로 선다','팔을 당기며 상대 오른쪽에서 등 뒤로 돈다','허리를 안고 백']::text[] where slug = 'two-on-one-to-back-take' and owner_id is null and steps = array['상대 한 팔을 양손으로 잡는다','팔을 내 가슴에 붙여 가두고 옆으로 선다','팔을 당기며 상대 뒤로 돈다','허리를 안고 백']::text[];
update public.techniques set steps = array['클린치에서 양팔로 상대 허리를 감아 내 오른손으로 왼 손목을 잡는다(바디락)','가슴을 붙이고 엉덩이를 상대 가까이 둔다','내 왼다리로 상대 오른다리 바깥 뒤를 걸고 상대 오른쪽 뒤로 밀어 넘긴다(또는 허리를 비틀어 넘김)','넘어지면 사이드로']::text[] where slug = 'body-lock-takedown' and owner_id is null and steps = array['클린치에서 양팔로 상대 허리를 감아 손을 맞잡는다(바디락)','가슴을 붙이고 엉덩이를 상대 가까이 둔다','다리를 걸거나 옆으로 비틀어 넘긴다','넘어지면 사이드로']::text[];
update public.techniques set steps = array['상대가 허리를 안으면 엉덩이를 뒤로 빼고 자세를 낮춘다','내 오른팔부터 상대 왼팔 아래로 파고들어 언더훅을 되찾는다(퍼멀, 양팔이면 더 좋다)','머리를 언더훅 쪽인 상대 왼쪽 어깨(턱 옆)에 붙여 들리지 않게 한다','오른팔 언더훅을 잡으면 상대 왼쪽 옆으로 돌아 나간다']::text[] where slug = 'pummeling-escape-from-body-lock' and owner_id is null and steps = array['상대가 허리를 안으면 엉덩이를 뒤로 빼고 자세를 낮춘다','양팔을 상대 팔 아래로 넣어 언더훅을 되찾는다(퍼멀)','머리를 상대 어깨에 붙여 들리지 않게 한다','언더훅을 잡으면 상대 옆으로 돈다']::text[];
update public.techniques set steps = array['상대가 뒤에서 허리를 안으면 자세를 낮추고 양손으로 상대 손을 잡는다','상대 오른손 손가락이나 손목을 떼어 그립을 끊는다','끊는 순간 내 오른쪽으로 엉덩이를 돌려 상대와 마주 본다','클린치나 거리로 돌아간다']::text[] where slug = 'grip-break-and-face' and owner_id is null and steps = array['상대가 뒤에서 허리를 안으면 자세를 낮추고 손을 잡는다','상대 손가락이나 손목을 떼어 그립을 끊는다','끊는 순간 엉덩이를 돌려 상대와 마주 본다','클린치나 거리로 돌아간다']::text[];
update public.techniques set steps = array['뒤에서 양팔로 허리를 안아 내 오른손으로 왼 손목을 잡고 가슴을 상대 등에 붙인다','내 오른발로 상대 오른발 발목을 뒤에서 걸거나 상대를 들어 올린다','상대 오른쪽(내 오른쪽)으로 틀며 바닥으로 끌어내린다','떨어지면 바로 양발 훅을 넣어 백 컨트롤']::text[] where slug = 'mat-return' and owner_id is null and steps = array['뒤에서 허리를 안고 가슴을 상대 등에 붙인다','상대 한 발을 내 발로 걸거나 들어 올린다','옆으로 틀며 바닥으로 끌어내린다','떨어지면 바로 훅을 넣어 백 컨트롤']::text[];
update public.techniques set steps = array['턱을 당기고 내 오른손으로 목 앞에 오는 상대 오른팔 손목을 잡아 막은 채 무릎을 굽힌다','왼쪽 무릎, 오른쪽 무릎 순서로 바닥에 대고 엉덩이를 뒤로 빼 낮게 내려간다','양 팔꿈치를 양 무릎에 붙여 터틀을 만들고 상대 발이 내 배 앞으로 못 들어오게 막는다','상대 훅이 들어오기 전에 내 오른쪽으로 돌아앉아 상대를 마주 보고 가드로 돌아가거나 일어선다']::text[] where slug = 'controlled-descent' and owner_id is null and steps = array['뒤에서 잡히면 한 손으로 상대 손을 막고 무릎을 굽힌다','한 무릎을 먼저 바닥에 대고 엉덩이를 뒤로 뺀다','팔꿈치를 무릎에 붙여 터틀을 만든다','상대 훅이 들어오기 전에 돌아선다']::text[];
update public.techniques set steps = array['뒤에서 잡히면 자세를 낮추고 내 왼손으로 내 배 앞에 깍지 낀 상대 손을 눌러 막는다','오른발을 내 오른쪽으로 빼며 엉덩이를 상대 오른쪽 옆으로 뺀다','내 오른팔을 상대 오른팔 위로 넘겨 상대 다리 사이로 넣어 상대 오른쪽 허벅지 안쪽을 잡는다','내 오른팔로 상대 오른쪽 어깨를 누르며 엉덩이를 돌려 상대 뒤로 들어가 허리를 안는다']::text[] where slug = 'standing-switch' and owner_id is null and steps = array['뒤에서 잡혔을 때 한 손으로 상대 손을 막고 엉덩이를 옆으로 뺀다','같은 쪽 팔을 뒤로 뻗어 상대 허벅지 안쪽을 잡는다','엉덩이를 돌리며 상대 뒤로 들어간다','허리를 안고 백']::text[];
update public.techniques set steps = array['뒤에서 허리를 안기면 자세를 낮추고 내 두 손으로 내 배 앞의 상대 두 팔을 눌러 잡는다','내 오른발을 뒤로 빼 상대 오른다리 바깥 뒤쪽에 걸어 넣는다','상체를 내 오른쪽으로 틀며 상대를 내 오른다리 위로 뒤로 넘긴다','상대가 넘어가면 그대로 상대 위로 올라간다']::text[] where slug = 'counter-throw-from-rear-clinch' and owner_id is null and steps = array['뒤에서 안기면 자세를 낮추고 상대 팔을 잡는다','한 발을 상대 다리 뒤로 걸어 넣는다','엉덩이를 틀며 상대를 옆이나 뒤로 넘긴다','넘어가면 위로 올라간다']::text[];
update public.techniques set steps = array['상대 머리가 내려오면 내 오른팔을 상대 목 앞으로 감아 머리를 내 오른쪽 겨드랑이에 끼운다','내 오른쪽 손목 뼈를 상대 목 아래에 대고 내 왼손으로 내 오른손을 맞잡는다','양 팔꿈치를 몸에 붙이고 오른쪽 손목을 위로 끌어올리며 가슴을 편다','앉아서 마무리할 땐 양다리로 상대 허리를 감고 천천히 조인다']::text[] where slug = 'guillotine-choke-from-clinch' and owner_id is null and steps = array['클린치에서 상대 머리가 내려오면 팔을 목 앞으로 감는다','손을 맞잡고 팔꿈치를 몸에 붙인다','엉덩이를 빼며 가슴을 펴 조인다','앉아서 마무리할 땐 몸을 옆으로 튼다']::text[];
update public.techniques set steps = array['뒤에서 내 오른팔을 상대 목 앞으로 감아 넣는다','내 오른손을 내 왼팔 이두에 걸고 내 왼손은 상대 뒤통수에 둔다','가슴을 상대 등에 붙이고 체중으로 상대를 뒤로 끌어내린다','양 팔꿈치를 모아 천천히 조인다']::text[] where slug = 'rnc-from-standing-back' and owner_id is null and steps = array['뒤에서 한 팔을 상대 목 앞으로 넣는다','그 손을 반대 팔 이두에 걸고 반대 손은 상대 뒤통수에 둔다','가슴을 등에 붙이고 체중으로 상대를 뒤로 끌어내린다','팔꿈치를 모아 조인다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 손목을 잡고 내 오른팔로 상대 오른쪽 위팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','상대 오른쪽 팔꿈치를 내 가슴에 붙이고 상대 오른쪽 옆으로 선다','팔을 비틀지 말고 그립을 유지한 채 상대를 바닥으로 데려간다','사이드나 남북에서 상대 오른손을 상대 등 쪽으로 천천히 돌려 탭을 받는다']::text[] where slug = 'kimura-from-standing' and owner_id is null and steps = array['상대 손목을 잡고 반대 팔로 윗팔을 감아 내 손목을 잡는다','팔꿈치를 몸에 붙이고 상대 옆으로 선다','팔을 등 뒤로 돌리며 상대를 바닥으로 끌어내린다','사이드나 남북에서 마무리']::text[];
update public.techniques set steps = array['오른발을 반 보 앞에 두고 양 무릎을 굽혀 자세를 낮춘다','등은 펴고 머리는 세워 시선을 상대 가슴에 둔다','양 팔꿈치는 몸에 붙이고 양손은 앞에 두어 상대 그립을 막는다','발을 교차하지 않고 앞으로 갈 땐 오른발 먼저, 왼발이 따라오게 작게 끌며 옮긴다']::text[] where slug = 'standing-stance' and owner_id is null and steps = array['한 발을 반 보 앞에 두고 무릎을 굽혀 자세를 낮춘다','등은 펴고 머리는 세워 시선을 상대 가슴에 둔다','팔꿈치는 몸에 붙이고 손은 앞에 두어 상대 그립을 막는다','발을 교차하지 않고 앞발 먼저, 뒷발이 따라오게 작게 끌며 옮긴다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 목 뒤를 잡고 오른쪽 팔꿈치를 아래로 내려 머리를 누른다','내 왼손은 상대 오른쪽 팔꿈치나 손목을 잡아 팔을 묶는다','머리를 당기고 밀어 상대가 발을 옮기게 하며 균형을 흔든다','상대가 머리를 들면 스냅 다운, 자세를 세우면 덕 언더나 테이크다운으로 잇는다']::text[] where slug = 'collar-tie' and owner_id is null and steps = array['한 손으로 상대 목 뒤를 잡고 팔꿈치를 아래로 내려 머리를 누른다','반대 손은 상대 같은 쪽 팔꿈치나 손목을 잡아 팔을 묶는다','머리를 당기고 밀어 상대가 발을 옮기게 하며 균형을 흔든다','상대가 머리를 들면 스냅 다운, 자세를 세우면 덕 언더나 테이크다운으로 잇는다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 깃, 왼손으로 상대 오른쪽 소매를 잡고 앞으로 당겨 발끝에 체중을 싣게 한다','오른발을 상대 오른발 앞에 딛고 내 왼쪽으로 돌아 들어가며 오른손 깃을 풀어 상대 허리 뒤를 감싼다','무릎을 굽혀 내 엉덩이를 상대 골반보다 낮게 붙인다','다리를 펴고 상체를 숙이며 왼손 소매를 내 왼쪽 앞으로 당겨 내 오른쪽 허리 위로 넘긴다','넘어가면 왼손 소매를 놓지 않고 사이드로']::text[] where slug = 'o-goshi' and owner_id is null and steps = array['깃과 소매를 잡고 상대를 앞으로 당겨 발끝에 체중을 싣게 한다','소매 쪽으로 돌아 들어가며 깃 잡은 팔을 풀어 상대 허리를 감싼다','무릎을 굽혀 내 엉덩이를 상대 골반보다 낮게 붙인다','다리를 펴고 상체를 숙이며 소매를 당겨 허리 위로 넘긴다','넘어가면 소매를 놓지 않고 사이드로']::text[];
update public.techniques set steps = array['양 다리를 상대 허리 뒤에서 교차해 발목을 잠근다','무릎을 조이고 다리로 당겨 상대 가슴을 내 쪽으로 무너뜨린다(포스처 깨기)','내 오른손은 상대 목 뒤(또는 왼쪽 깃)를 당기고, 왼손은 상대 오른쪽 소매를 잡아 내 몸을 짚지 못하게 한다','상대 오른손이 내 가슴을 밀면 내 왼손으로 그 팔을 안쪽에서 바깥으로 쳐내 바닥에 짚게 만든다']::text[] where slug = 'closed-guard-basics' and owner_id is null and steps = array['양 다리를 상대 허리 뒤에서 교차해 발목을 잠근다','무릎을 조이고 다리로 당겨 상대 가슴을 내 쪽으로 무너뜨린다(포스처 깨기)','한 손은 상대 목 뒤(또는 깃)를 당기고, 반대 손은 소매를 잡아 상대가 내 몸을 짚지 못하게 한다','상대 팔이 내 가슴을 밀면 안쪽에서 바깥으로 쳐내 바닥에 짚게 만든다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 오른쪽 깃, 왼손으로 상대 오른쪽 소매(또는 팔꿈치)를 잡고 상대를 앞으로 당긴다','가드를 열고 엉덩이를 내 오른쪽으로 살짝 빼서 오른쪽 정강이를 상대 배 앞에 가로로 댄다(니 쉴드)','내 왼다리는 바닥 가까이 내려 상대 오른쪽 무릎 바깥에 건다','오른다리는 밀고 왼다리는 당기며(가위) 소매를 당겨 상대 오른쪽(내 왼쪽)으로 넘기고 마운트로 올라간다']::text[] where slug = 'scissor-sweep' and owner_id is null and steps = array['깃과 소매(또는 팔꿈치)를 잡고 상대를 앞으로 당긴다','가드를 열고 엉덩이를 살짝 빼서 한 무릎을 상대 배 앞에 가로로 댄다(니 쉴드)','반대 다리는 바닥 가까이 내려 상대 무릎 바깥에 건다','위 다리는 밀고 아래 다리는 당기며(가위) 소매를 당겨 넘기고 마운트로 올라간다']::text[];
update public.techniques set steps = array['상대가 상체를 세우고 내 가슴을 누를 때 — 가드를 풀고 내 오른손으로 뒤 바닥을 짚으며 앉아 일어난다','내 왼팔을 상대 오른쪽 어깨 위로 넘겨 상대 오른팔 삼두(팔 뒤)를 감싼다','엉덩이를 높이 들어 상대 오른쪽 어깨를 쳐서 상대를 내 오른쪽으로 넘긴다','넘어가면 다리를 돌려 마운트. 상대가 오른손을 바닥에 짚으면 기무라, 앞으로 밀면 길로틴으로 잇는다']::text[] where slug = 'hip-bump-sweep' and owner_id is null and steps = array['상대가 상체를 세우고 내 가슴을 누를 때 — 가드를 풀고 한 손으로 뒤 바닥을 짚으며 앉아 일어난다','반대 팔을 상대 어깨 위로 넘겨 삼두(팔 뒤)를 감싼다','엉덩이를 높이 들어 상대 어깨를 옆으로 친다','넘어가면 다리를 180도 돌려 마운트. 상대가 손을 짚으면 기무라, 앞으로 밀면 길로틴으로 잇는다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매(손목)를 잡아 당기고, 오른손은 상대 왼쪽 허벅지 아래로 넣어 다리를 안는다','가드를 열고 내 오른다리를 상대 왼쪽 겨드랑이 쪽으로 높게 올린다','내 왼다리는 바닥 가까이 진자처럼 크게 휘둘러 엉덩이를 띄운다','오른다리로 겨드랑이를 밀고 안은 상대 왼다리를 들어 내 왼쪽(소매 쪽)으로 넘기며 마운트로 올라간다']::text[] where slug = 'flower-sweep' and owner_id is null and steps = array['한 손으로 상대 한쪽 소매(손목)를 잡아 당기고, 반대 손은 상대 반대쪽 허벅지 아래로 넣어 다리를 안는다','가드를 열고 다리를 안은 쪽 내 다리를 상대 겨드랑이 쪽으로 높게 올린다','소매 잡은 쪽 다리는 바닥 가까이 진자처럼 크게 휘둘러 엉덩이를 띄운다','올린 다리로 겨드랑이를 밀고 안은 다리를 들어 소매 쪽으로 넘기며 마운트로 올라간다']::text[];
update public.techniques set steps = array['내 오른손을 상대 오른쪽 깃 깊숙이 넣는다(네 손가락은 깃 안쪽, 엄지는 바깥, 손바닥은 위로)','내 왼손은 내 오른팔 위로 교차해 상대 왼쪽 깃을 잡는다','상대를 다리로 당기며 양 팔꿈치를 아래로 떨어뜨린다','양 손목을 비틀어 상대 목 양옆을 조인다']::text[] where slug = 'cross-collar-choke-guard' and owner_id is null and steps = array['한 손을 상대 깃 깊숙이 넣는다(네 손가락은 깃 안쪽, 엄지는 바깥, 손바닥은 위로)','반대 손은 첫 손 위로 교차해 반대 깃을 잡는다','상대를 다리로 당기며 팔꿈치를 아래로 떨어뜨린다','손목을 비틀어 양쪽 목 옆을 조인다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 손목을 내 가슴에 붙이고, 내 오른손으로 상대 오른팔 삼두를 당겨 고정한다','내 오른발을 상대 왼쪽 골반에 대고 밀어 몸을 돌려 상대와 직각이 된다','그 오른다리를 상대 얼굴 위로 넘기고, 왼다리는 상대 등(오른쪽 옆구리)에 붙여 조인다','무릎을 모으고 상대 오른손 엄지가 위로 향한 채 엉덩이를 천천히 들어 팔꿈치를 편다']::text[] where slug = 'closed-guard-armbar' and owner_id is null and steps = array['상대 한 팔을 가슴에 붙여 손목을 잡고, 반대 손은 그 팔의 삼두를 잡아 중앙으로 당긴다','같은 쪽 발을 상대 골반에 밟고 엉덩이를 돌려 몸을 상대와 직각으로 만든다','반대 다리를 상대 등 위로 올려 머리를 누르고 자세를 낮춘다','다리를 모아 무릎을 조이고 엉덩이를 들어 팔꿈치를 편다(엄지는 위로)']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 손목을 잡아 밀어 상대 왼팔은 바깥, 오른팔은 내 다리 안쪽에 남게 만든다','가드를 열고 내 왼발로 상대 오른쪽 골반을 밀어 엉덩이를 띄운 뒤, 오른다리를 상대 목 뒤로 올린다','오른발목을 내 왼쪽 무릎 뒤에 걸어 삼각형을 만들고, 두 손으로 머리를 당겨 자세를 낮춘다','엉덩이를 내 왼쪽으로 빼 직각을 만들고 상대 오른팔을 상대 목 앞 너머(내 오른쪽)로 넘긴 뒤 다리를 조인다']::text[] where slug = 'triangle-choke' and owner_id is null and steps = array['상대 한 손목을 잡아 밀어 한 팔은 안쪽, 한 팔은 바깥쪽이 되게 만든다','가드를 열고 안쪽 팔 쪽 발로 상대 골반을 밀어 엉덩이를 띄운 뒤, 바깥 팔 쪽 다리를 상대 목 뒤로 올린다','그 발목을 반대 무릎 뒤에 걸어 삼각형을 만들고, 두 손으로 머리를 당겨 자세를 낮춘다','목 위 다리 반대쪽으로 몸을 틀어 각도를 만들고 안쪽 팔을 얼굴 반대로 넘긴 뒤 다리를 조인다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 손목을 잡고 오른팔로 상대 오른쪽 위팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','가드를 열고 엉덩이를 내 오른쪽으로 빼 몸을 비스듬히 세운다(가슴이 상대 오른팔 쪽)','내 왼다리를 상대 등 위로 넘겨 상대가 앞으로 구르지 못하게 묶는다','상대 오른쪽 팔꿈치를 내 몸에 붙인 채 상대 오른손을 등 뒤 머리 쪽으로 천천히 돌린다']::text[] where slug = 'kimura-guard' and owner_id is null and steps = array['상대 손목을 잡고 반대 팔로 윗팔을 감아 내 손목을 잡는다(8자 그립)','엉덩이를 옆으로 빼서 상대와 직각에 가깝게 눕는다','팔꿈치를 상대 어깨에 눌러 붙인 채 다리로 상대 몸을 묶는다','상대 손이 등 뒤 머리 쪽으로 가게 돌려 탭을 받는다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른팔 삼두를 잡고 내 오른손으로 머리를 당겨 자세를 무너뜨린다','내 오른발로 상대 왼쪽 골반을 밀며 몸을 돌리고, 왼다리를 상대 오른쪽 어깨 위로 넘긴다','왼다리를 바깥으로 돌려 상대를 바닥에 엎드리게 만들고 내 오른팔로 상대 허리를 잡는다','상대 오른손을 내 왼쪽 허벅지 쪽에 붙인 채 상체를 앞으로 천천히 숙여 어깨를 꺾는다']::text[] where slug = 'omoplata' and owner_id is null and steps = array['상대 한 팔의 삼두를 잡고 머리를 당겨 포스처를 깬다','가드를 열고 그 팔 쪽으로 엉덩이를 빼며 같은 쪽 다리를 상대 팔 위 · 등 뒤로 넘긴다','발목을 상대 목에 걸고 반대 다리를 모아 어깨를 감싼다','앉아 올라오며 상대 허리를 잡아 못 일어나게 하고 엉덩이를 앞으로 밀어 어깨를 꺾는다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 손목, 오른손으로 상대 오른팔 삼두를 잡는다(투 온 원)','다리로 상대를 당겨 가슴을 붙이고 상대 오른팔을 내 오른쪽으로 끌어 넘긴다','가드를 풀고 내 왼쪽(상대 오른쪽 옆)으로 일어나며 왼팔로 상대 등 너머 왼쪽 겨드랑이를 잡는다','양발 훅을 넣고 내 오른팔이 상대 오른쪽 어깨 위로 가는 시트벨트를 잡아 백 컨트롤로']::text[] where slug = 'arm-drag-guard' and owner_id is null and steps = array['상대 한 손목을 잡고 반대 손으로 삼두를 잡는다(투 온 원)','다리로 상대를 당겨 가슴을 붙이고 팔을 내 몸 반대쪽으로 끌어 넘긴다','가드를 풀고 옆으로 일어나며 반대 팔로 상대 등 뒤 겨드랑이를 잡는다','훅을 넣고 시트벨트를 잡아 백 컨트롤로']::text[];
update public.techniques set steps = array['상대 머리가 내 가슴 쪽으로 숙여질 때(힙 범프를 막으려 밀 때 등) 내 오른팔을 상대 목 앞으로 감는다','내 왼손으로 감은 오른손을 잡아 그립을 만들고 양 팔꿈치를 몸에 붙인다','상대 머리가 있는 내 오른쪽으로 몸을 살짝 틀고 다리를 감아 못 빠지게 한다','뒤로 젖히지 말고 가슴을 펴며 체중으로 목을 조인다']::text[] where slug = 'guillotine-guard' and owner_id is null and steps = array['상대 머리가 내 가슴 쪽으로 숙여질 때(힙 범프를 막으려 밀 때 등) 한 팔을 목 앞으로 감는다','감은 손을 반대 손으로 잡아 그립을 만들고 팔꿈치를 몸에 붙인다','상대 머리가 있는 쪽으로 몸을 틀고 다리를 감아 못 빠지게 한다','뒤로 젖히지 말고 가슴을 펴며 체중으로 목을 조인다']::text[];
update public.techniques set steps = array['당겨 무너지면 먼저 머리를 들고 시선을 위로 둔다','두 손으로 상대 배나 골반을 누르고 팔꿈치는 몸에 붙인다','엉덩이를 뒤로 빼며 허리를 세운다','무릎을 벌려 베이스를 만든다']::text[] where slug = 'posture-recovery' and owner_id is null and steps = array['당겨 무너지면 먼저 머리를 들고 시선을 위로','손을 상대 가슴이나 갈비에 짚어 팔꿈치를 편다','엉덩이를 뒤로 빼며 허리를 세운다','무릎을 벌려 베이스를 만든다']::text[];
update public.techniques set steps = array['상대가 내 다리를 머리 쪽으로 누르면 양발을 상대 양쪽 골반에 대어 밀어낸다','턱을 당기고 목이 꺾이지 않게 한다','엉덩이를 내 오른쪽으로 빼고 몸을 왼쪽 옆으로 세워 압력을 피한다','가드를 다시 잠그거나 오픈 가드로']::text[] where slug = 'stack-defense' and owner_id is null and steps = array['상대가 내 다리를 머리 쪽으로 누르면 발을 상대 골반에 대어 밀어낸다','턱을 당기고 목이 꺾이지 않게 한다','엉덩이를 옆으로 빼서 압력을 피한다','가드를 다시 잠그거나 오픈 가드로']::text[];
update public.techniques set steps = array['오모플라타 자세(내 왼다리가 상대 오른쪽 어깨 위)에서 내 오른팔로 상대 허리를 잡아 못 구르게 한다','상대가 앞으로 구르지 않고 버티면 내 몸을 상대 쪽으로 기울여 상대를 상대 왼쪽 옆으로 민다','내 왼다리로 상대 오른쪽 어깨를 계속 누른다','넘어가면 위로 올라와 마운트나 사이드']::text[] where slug = 'omoplata-sweep' and owner_id is null and steps = array['오모플라타 자세에서 상대 허리를 잡아 못 구르게 한다','상대가 앞으로 못 넘어가면 반대쪽으로 몸을 돌려 상대를 옆으로 민다','다리로 상대 어깨를 계속 누른다','넘어가면 위로 올라와 마운트나 사이드']::text[];
update public.techniques set steps = array['내 왼팔로 상대 오른팔을 위에서 감아(오버훅) 내 가슴에 붙인다','내 오른손으로 상대 왼쪽 손목이나 소매를 잡는다','가드를 열고 엉덩이를 내 오른쪽(오버훅 반대쪽)으로 살짝 빼 각도를 만든다','내 오른다리로 상대 왼쪽 허벅지를 들어 올리며 오버훅 쪽(내 왼쪽, 상대 오른쪽)으로 굴려 마운트로 올라간다']::text[] where slug = 'overhook-sweep' and owner_id is null and steps = array['상대 한 팔을 위에서 감아(오버훅) 내 몸에 붙인다','반대 손으로 상대 반대 손목이나 소매를 잡는다','오버훅 쪽으로 엉덩이를 빼며 다리로 상대 다리를 들어 올린다','넘기고 마운트']::text[];
update public.techniques set steps = array['상대 오른팔에 기무라 그립(내 왼손은 손목, 오른팔은 위팔 위)을 잡고 상대가 왼손을 바닥에 짚어 버티게 만든다','그립을 유지한 채 엉덩이를 내 오른쪽으로 빼고 왼다리를 상대 등 위로 넘긴다','상대 오른팔을 당기며 내 왼쪽(상대 오른쪽)으로 몸을 돌려 넘긴다','위로 올라와 상대 오른팔 기무라를 계속 공격']::text[] where slug = 'kimura-sweep' and owner_id is null and steps = array['기무라 그립을 잡고 상대가 손을 바닥에 짚어 버티게 만든다','그립을 유지한 채 엉덩이를 옆으로 빼고 다리를 상대 등 위로 넘긴다','상대 팔을 당기며 그쪽으로 몸을 돌려 넘긴다','위로 올라와 기무라를 계속 공격']::text[];
update public.techniques set steps = array['클로즈드 가드에서 상대가 서면 내 왼손으로 상대 오른쪽 발목(바지)을 잡고 오른손으로 뒤 바닥을 짚고 앉는다','가드를 풀고 상대 오른다리를 양팔로 안는다','가슴과 어깨로 상대 오른쪽 무릎을 밀어 상대를 뒤로 눕힌다','상대 오른다리를 놓지 않고 패스 자세로']::text[] where slug = '100-percent-sweep' and owner_id is null and steps = array['클로즈드 가드에서 상대가 서면 한 손은 상대 발목(바지), 반대 손은 뒤 바닥을 짚고 앉는다','가드를 풀고 상대 다리 하나를 양팔로 안는다','어깨로 상대 무릎을 밀며 앞으로 밀어 눕힌다','다리를 놓지 않고 패스 자세로']::text[];
update public.techniques set steps = array['상대가 오른팔을 내 목 앞으로 밀어 넣으면 내 왼손으로 그 팔꿈치를 내 오른쪽으로 민다','내 오른팔로 상대 목 뒤를 감아 상대 오른팔을 상대 머리와 내 머리 사이에 가둔다(헤드 앤 암)','엉덩이를 돌려 상대를 상대 오른쪽(팔이 빠진 쪽, 내 왼쪽)으로 기울여 균형을 깬다','상대 오른쪽으로 넘기고 위로 올라간다']::text[] where slug = 'arm-trap-sweep' and owner_id is null and steps = array['상대가 내 목 앞으로 팔을 밀어 넣으면 그 팔꿈치를 반대쪽으로 민다','그 팔을 내 머리와 팔로 감싸 가둔다(헤드 앤 암)','가둔 쪽으로 엉덩이를 돌려 균형을 깬다','넘기고 위로']::text[];
update public.techniques set steps = array['상대 오른팔 암 드래그가 안 넘어가면 내 왼팔로 상대 등 너머 왼쪽 겨드랑이를 감아 가슴을 붙인다','내 왼쪽 엉덩이로 돌아 누워 상대 오른팔이 못 돌아오게 내 배로 막는다','내 왼다리로 상대 오른쪽 무릎을 바깥으로 차 내며 상대 오른쪽(내 왼쪽)으로 굴린다','위로 올라와 마운트나 사이드']::text[] where slug = 'clamp-sweep' and owner_id is null and steps = array['암 드래그가 안 넘어가면 반대 팔로 상대 겨드랑이를 감아 가슴을 붙인다','한쪽 엉덩이로 돌아 상대 팔이 못 돌아오게 배로 막는다','무릎을 상대 무릎 쪽으로 차 내며 옆으로 굴린다','위로 올라와 마운트나 사이드']::text[];
update public.techniques set steps = array['내 왼팔로 상대 오른팔을 위에서 감아 오버훅을 잡는다','오버훅 쪽(내 왼쪽)으로 몸을 틀고 내 오른손으로 상대 왼쪽 손목을 잡는다','상대 오른팔을 내 왼쪽 옆구리에 가둔다','스윕 · 오모플라타 · 트라이앵글로 잇는다']::text[] where slug = 'closed-guard-to-overhook-guard' and owner_id is null and steps = array['상대 한 팔을 위에서 감아 오버훅을 잡는다','오버훅 쪽으로 몸을 틀고 반대 손으로 상대 손목을 잡는다','상대 팔을 내 옆구리에 가둔다','스윕 · 오모플라타 · 트라이앵글로 잇는다']::text[];
update public.techniques set steps = array['상대가 팔을 빼며 버티면 상대 오른팔은 내 다리 사이(안쪽), 왼팔은 바깥에 둔다','바깥 팔 쪽 내 오른다리를 상대 왼쪽 어깨 위로 넘겨 목 뒤에 건다','오른발목을 내 왼쪽 무릎 뒤에 걸어 삼각형을 만든다','두 손으로 머리를 당기고 엉덩이를 내 왼쪽으로 빼 각도를 틀어 무릎을 조인다']::text[] where slug = 'switch-to-triangle' and owner_id is null and steps = array['암바나 오모플라타를 막으면 상대 한 팔이 안쪽에 남는다','그 팔 쪽 다리를 상대 목 뒤로 올린다','반대 다리로 발목을 걸어 삼각형','머리를 당기고 각도를 틀어 조인다']::text[];
update public.techniques set steps = array['상대 오른손이 내 가슴이나 깃을 잡을 때 내 오른손으로 그 손등을 위에서 덮는다','손목이 굽혀진 채 팔꿈치가 못 움직이게 내 왼손으로 상대 오른쪽 팔꿈치를 고정한다','상대 오른손 손등을 상대 팔 안쪽으로 밀어 손목을 접는다','천천히 눌러 탭을 받는다']::text[] where slug = 'wrist-lock-closed-guard' and owner_id is null and steps = array['상대 손이 내 가슴이나 깃을 잡을 때 그 손등을 위에서 덮는다','손목이 굽혀진 채 팔꿈치가 못 움직이게 반대 손으로 팔을 고정','손등을 팔 안쪽으로 밀어 손목을 접는다','천천히 눌러 탭을 받는다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 깃을 목 가까이 깊게 잡는다(엄지가 깃 안쪽)','내 왼손으로 상대 뒤통수를 눌러 머리를 숙이게 한다','가드를 열고 내 왼쪽 옆으로 몸을 돌려 상대 머리가 내 오른팔 아래로 들어가게 한다','내 오른쪽 팔꿈치를 바닥 쪽으로 당기며 천천히 조인다']::text[] where slug = 'loop-choke-closed-guard' and owner_id is null and steps = array['상대 깃을 한 손으로 잡고 상대 머리를 숙이게 한다','잡은 팔 아래로 상대 머리를 넣듯 팔꿈치를 돌려 깃으로 목을 감는다','반대 팔을 상대 등 뒤로 넘겨 그립을 받친다','몸을 돌리며 조인다']::text[];
update public.techniques set steps = array['상대가 서려 할 때 내 오른손으로 상대 왼쪽 발목, 왼손으로 상대 오른쪽 발목(바지)을 잡는다','다리로 상대 허리를 조이며 뒤로 눕는다','양 발목을 당기고 양 무릎으로 상대 배를 밀어 뒤로 앉힌다','위로 올라와 마운트나 패스 자세']::text[] where slug = 'muscle-sweep' and owner_id is null and steps = array['상대가 서려 할 때 양 발목(바지)을 잡는다','다리로 상대 허리를 조이며 뒤로 눕는다','발목을 당기고 무릎으로 상대 배를 밀어 뒤로 앉힌다','위로 올라와 마운트나 패스 자세']::text[];
update public.techniques set steps = array['상대 가드 안에서 내 오른팔을 상대 목 뒤로 넣는다','내 오른손으로 내 왼팔 소매 안쪽을 잡는다(네 손가락을 소매 안에)','소매 잡힌 내 왼손 손날을 상대 목 앞에 댄다','가슴으로 눌러 자세를 낮추며 두 팔을 모아 조인다']::text[] where slug = 'ezekiel-choke-closed-guard' and owner_id is null and steps = array['상대 클로즈드 가드 안에서 한 팔을 상대 목 뒤로 감는다','반대 손으로 그 팔 소매 안쪽을 잡는다','자유로운 손날을 상대 목 앞으로 넣는다','가슴을 눌러 자세를 낮추며 조인다']::text[];
update public.techniques set steps = array['클로즈드 가드 안에서 허리를 세우고 양손을 상대 뒤통수에 깍지 낀다','팔꿈치를 모아 머리를 천천히 내 가슴 쪽으로 당긴다','상대가 가드를 풀면 바로 손을 놓고 패스로 간다','목 크랭크라 세게 당기지 않는다(대회·체육관 규칙 확인)']::text[] where slug = 'can-opener' and owner_id is null and steps = array['클로즈드 가드 안에서 양손을 상대 뒤통수에 깍지 낀다','허리를 세우며 상대 머리를 가슴 쪽으로 당긴다','상대가 목이 불편해 가드를 풀면 바로 열어 패스','(목 크랭크라 체육관 규칙 확인)']::text[];
update public.techniques set steps = array['내 왼팔 오버훅으로 상대 오른팔을 가두고 내 오른손은 상대 왼쪽 손목을 잡는다','엉덩이를 내 오른쪽(오버훅 반대쪽)으로 빼며 내 오른쪽 무릎을 상대 배에 댄다','다리로 밀고 상대 오른팔을 당겨 내 왼쪽(상대 오른쪽)으로 넘긴다','마운트로']::text[] where slug = 'overhook-control-sweep' and owner_id is null and steps = array['오버훅으로 상대 팔을 가두고 반대 손은 상대 손목','오버훅 반대쪽으로 엉덩이를 빼며 무릎을 상대 배에 댄다','다리로 밀고 팔을 당겨 넘긴다','마운트로']::text[];
update public.techniques set steps = array['내 왼팔 오버훅(상대 오른팔)을 유지한 채 가드를 연다','내 다리로 상대 오른다리를 감는다','오버훅 쪽(내 왼쪽)으로 돌아 옆으로 눕는다','하프가드에서 내 오른팔로 상대 왼쪽 겨드랑이 언더훅 싸움']::text[] where slug = 'overhook-to-half-guard' and owner_id is null and steps = array['오버훅을 유지한 채 가드를 연다','한쪽 다리로 상대 다리 하나를 감는다','오버훅 쪽으로 옆으로 돌아 눕는다','하프가드에서 언더훅 싸움']::text[];
update public.techniques set steps = array['상대가 왼팔로 내 오른팔을 오버훅하면 내 오른손으로 상대 왼쪽 손목을 잡는다','내 왼팔을 상대 왼팔 아래로 넣어 내 오른쪽 손목을 잡는다','상대 왼쪽 어깨를 바닥에 누르며 몸을 낮춘다','상대 왼팔을 상대 등 뒤로 돌린다']::text[] where slug = 'kimura-from-overhook-control' and owner_id is null and steps = array['상대가 내 팔을 오버훅으로 잡으면 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다','상대 어깨를 바닥에 누르며 몸을 낮춘다','팔을 등 뒤로 돌린다']::text[];
update public.techniques set steps = array['상대가 왼팔로 내 오른팔을 오버훅하고 몸을 틀면 내 오른팔을 상대 왼쪽 겨드랑이 아래로 더 깊게 넣는다','내 오른팔을 상대 목 앞을 지나 반대편까지 꿰어 내 왼팔 이두를 잡는다','내 왼팔로 상대 머리를 누르며 몸을 낮춘다','가슴으로 조인다']::text[] where slug = 'darce-from-overhook-control' and owner_id is null and steps = array['상대가 오버훅을 잡고 몸을 틀면 그 팔 아래로 내 팔을 넣는다','목 반대편까지 깊게 꿰어 이두를 잡는다','상대 머리를 누르며 몸을 낮춘다','가슴으로 조인다']::text[];
update public.techniques set steps = array['상대가 왼팔로 내 오른팔을 오버훅하면 내 오른쪽 팔꿈치를 몸 쪽으로 당겨 빼낸다','빠지면 바로 내 두 손으로 상대 양 무릎을 눌러 가드를 연다','내 오른쪽 무릎을 상대 오른쪽 허벅지 위로 미끄러뜨려(니슬라이스) 다리를 지난다','상대 오른쪽에서 사이드 컨트롤']::text[] where slug = 'overhook-pass-to-side-control' and owner_id is null and steps = array['오버훅 잡힌 팔꿈치를 몸 쪽으로 당겨 빼낸다','빠지면 바로 상대 무릎을 눌러 가드를 연다','니슬라이스로 다리를 지난다','사이드 컨트롤']::text[];
update public.techniques set steps = array['상대가 왼팔로 내 오른쪽 겨드랑이 아래 언더훅을 잡으면 내 오른팔로 그 팔을 위에서 감는다(위저)','오른팔을 조여 상대 왼쪽 어깨를 바닥 쪽으로 누른다','엉덩이를 뒤로 빼 상대가 못 일어나게 한다','내 오른쪽(상대 왼쪽 옆)으로 돌아 상대 등 뒤로 가서 백이나 패스']::text[] where slug = 'whizzer' and owner_id is null and steps = array['상대가 언더훅을 잡으면 그 팔을 위에서 감는다(위저)','팔을 조여 상대 어깨를 바닥 쪽으로 누른다','엉덩이를 뒤로 빼 상대가 못 일어나게 한다','상대 등 뒤로 돌아 백이나 패스']::text[];
update public.techniques set steps = array['상대가 왼팔로 내 오른팔을 오버훅하면 오른쪽 팔꿈치를 몸에 붙이고 허리를 세운다','내 왼손으로 상대 오른쪽 골반을 눌러 거리를 만든다','내 오른쪽 팔꿈치를 아래로 돌려 오버훅을 빼낸다','클로즈드 가드 안 자세로 돌아간다']::text[] where slug = 'break-overhook-guard' and owner_id is null and steps = array['오버훅 잡힌 팔꿈치를 몸에 붙이고 허리를 세운다','반대 손으로 상대 골반을 눌러 거리를 만든다','팔꿈치를 아래로 돌려 오버훅을 빼낸다','클로즈드 가드 안 자세로 돌아간다']::text[];
update public.techniques set steps = array['내 왼팔로 상대 오른팔 오버훅을 깊게 감고 내 오른손으로 상대 왼쪽 소매를 잡는다','가드를 열고 내 왼발을 바닥에 디뎌 엉덩이를 띄운다','내 오른다리로 상대 왼다리를 들어 올리며 소매를 당겨 오버훅 쪽(내 왼쪽, 상대 오른쪽)으로 굴린다','따라 올라가 마운트로 간다']::text[] where slug = 'overhook-guard-sweep' and owner_id is null and steps = array['오버훅을 깊게 감고 반대 손은 상대 반대 소매','오버훅 쪽으로 엉덩이를 빼며 다리로 상대 다리 들기','소매를 당겨 넘긴다','마운트']::text[];
update public.techniques set steps = array['내 왼팔 오버훅(상대 오른팔)을 잡은 채 가드를 열고 내 오른발로 상대 왼쪽 골반을 밀어 엉덩이를 뺀다','내 왼다리를 상대 오른쪽 어깨 위로 넘겨 등 쪽으로 보낸다','왼다리를 바깥으로 돌려 상대를 엎드리게 하고 내 오른팔로 허리를 잡는다','앉아서 상체를 앞으로 천천히 숙여 상대 오른쪽 어깨를 꺾는다']::text[] where slug = 'omoplata-from-overhook-guard' and owner_id is null and steps = array['오버훅을 잡은 채 가드를 열고 엉덩이를 뺀다','오버훅 쪽 다리를 상대 팔 위 · 등 뒤로 넘긴다','발목을 목에 걸고 다리를 모은다','앉아 올라오며 어깨를 꺾는다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 손목을 잡아 상대 골반 쪽으로 밀어 상대 왼팔을 내 다리 바깥으로 뺀다','내 왼발을 상대 오른쪽 골반에 대고 밀어 엉덩이를 들어 올린다','뺀 팔 쪽인 내 오른다리를 상대 목 뒤로 넘긴다','내 왼쪽 무릎 뒤에 오른발목을 걸어 트라이앵글 컨트롤']::text[] where slug = 'closed-guard-to-triangle' and owner_id is null and steps = array['상대 한 손목을 잡아 내 골반 쪽으로 밀어 그 팔을 내 다리 바깥으로 뺀다','반대쪽 발을 상대 골반에 대고 밀어 엉덩이를 들어 올린다','뺀 팔 쪽 다리를 상대 목 뒤로 넘긴다','반대 다리로 발목을 걸어 트라이앵글 컨트롤']::text[];
update public.techniques set steps = array['상대가 일어서면 내 오른손으로 상대 왼쪽, 왼손으로 오른쪽 소매(또는 손목)를 잡아 내 다리를 못 밀게 한다','다리로 매달려 엉덩이를 상대 골반 쪽으로 끌어올린다(무릎은 상대 갈비 높이)','상대가 오른쪽 무릎을 들어 뿌리치려 하면 엉덩이를 상대 오른다리 쪽(내 왼쪽)으로 틀어 따라간다','소매를 당기며 100% 스윕이나 발목 잡아 넘기기로 잇는다']::text[] where slug = 'closed-guard-vs-standing' and owner_id is null and steps = array['상대가 일어서면 양 소매(또는 손목)를 잡아 손으로 내 다리를 못 밀게 한다','다리로 매달려 엉덩이를 상대 골반 쪽으로 끌어올린다(무릎은 상대 갈비 높이)','상대가 한쪽 무릎을 들어 뿌리치려 하면 그쪽으로 엉덩이를 틀어 따라간다','소매를 당기며 100% 스윕이나 발목 잡아 넘기기로 잇는다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매, 오른손으로 상대 왼쪽 깃을 잡아 상체를 내 쪽으로 당긴다','내 오른쪽 어깨를 바닥에서 떼고 엉덩이를 내 오른쪽으로 빼서 몸을 비스듬히 만든다','내 오른쪽 무릎을 상대 왼쪽 겨드랑이 쪽으로 올려 상체를 가둔다','이 각도에서 암바 · 트라이앵글 · 오모플라타 중 열린 쪽으로 간다']::text[] where slug = 'closed-guard-hip-angle' and owner_id is null and steps = array['상대 한쪽 소매와 깃을 잡아 상체를 내 쪽으로 당긴다','한쪽 어깨를 바닥에서 떼고 그쪽 엉덩이를 옆으로 빼서 몸을 비스듬히 만든다','빼낸 쪽 무릎을 상대 겨드랑이 쪽으로 올려 상체를 가둔다','이 각도에서 암바 · 트라이앵글 · 오모플라타 중 열린 쪽으로 간다']::text[];
update public.techniques set steps = array['앉은 자세에서 내 왼손은 뒤 바닥을 짚고 오른손은 앞을 막는다(프레임)','오른발을 세우고 엉덩이를 들어 올린다','오른발과 왼손 사이로 왼다리를 빼서 뒤로 보낸다','무릎을 펴고 일어서며 오른손은 계속 상대를 막는다']::text[] where slug = 'technical-stand-up' and owner_id is null and steps = array['앉은 자세에서 한 손은 뒤 바닥을 짚고 반대 손은 앞을 막는다(프레임)','짚은 손 반대 발을 세우고 엉덩이를 들어 올린다','세운 발과 손 사이로 반대 다리를 빼서 뒤로 보낸다','무릎을 펴고 일어서며 앞 손은 계속 상대를 막는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에 있을 때 — 등을 대고 누워 내 왼발을 엉덩이 가까이 세워 바닥을 민다','내 오른쪽 어깨 쪽으로 돌아 누우며 엉덩이를 뒤로(내 왼쪽으로) 뺀다','양 팔꿈치와 손으로 상대를 밀어(프레임) 생긴 공간을 유지한다','내 오른쪽 무릎을 상대와 나 사이로 넣어 가드를 되찾는다']::text[] where slug = 'shrimp-hip-escape' and owner_id is null and steps = array['등을 대고 누워 한 발로 바닥을 민다','같은 쪽 어깨로 돌아 누우며 엉덩이를 뒤로 뺀다','팔꿈치와 손으로 상대를 밀어(프레임) 생긴 공간을 유지한다','무릎을 상대와 나 사이로 넣어 가드를 되찾는다']::text[];
update public.techniques set steps = array['앉은 가드에서 내 왼손으로 상대 오른쪽 발목(뒤꿈치)을 잡고 오른손으로 상대 왼쪽 소매를 잡는다','내 왼발을 상대 오른쪽 골반에 대고 민다','내 오른발로 상대 왼다리 오금을 걸어 당긴다','골반을 밀고 발목과 오금을 당겨 뒤로 눕힌 뒤, 오른쪽 발목을 놓지 않고 바로 일어나 패스 자세로 간다']::text[] where slug = 'tripod-sweep' and owner_id is null and steps = array['앉은 가드에서 한 손으로 상대 발목(뒤꿈치)을 잡고 반대 손으로 소매를 잡는다','발목 잡은 쪽 발을 상대 골반에 대고 민다','반대 발로 상대 반대 다리 오금을 걸어 당긴다','골반을 밀고 발목과 오금을 당겨 뒤로 눕힌 뒤, 발목을 놓지 않고 바로 일어나 패스 자세로 간다']::text[];
update public.techniques set steps = array['트라이포드와 같은 그립(내 왼손 상대 오른쪽 발목 · 오른손 상대 왼쪽 소매)에서 시작한다','상대 오른쪽 골반에 댄 내 왼발은 그대로 밀고, 오금을 걸던 오른발을 바닥으로 내린다','내린 오른발로 상대 왼쪽 발목 바깥을 낫처럼 걸어 안쪽으로 쓸면서 골반을 밀고 발목을 당긴다','상대가 옆으로 넘어지면 오른쪽 발목을 놓지 않고 일어나 패스 자세로 간다']::text[] where slug = 'sickle-sweep' and owner_id is null and steps = array['트라이포드와 같은 그립(발목 · 소매)에서 시작한다','발목 잡은 쪽 골반에 댄 발은 그대로 밀고, 오금을 걸던 발을 바닥으로 내린다','내린 발로 상대 반대 발목 바깥을 낫처럼 걸어 안쪽으로 쓸면서 골반을 밀고 발목을 당긴다','상대가 옆으로 넘어지면 발목을 놓지 않고 일어나 패스 자세로 간다']::text[];
update public.techniques set steps = array['상대가 오른손으로 내 왼쪽 바지를 잡으면 내 왼발을 원을 그려 상대 엄지 쪽으로 뺀다','상대 오른손이 내 오른쪽 깃을 잡으면 내 양손으로 그 손목을 돌리고 오른 어깨를 뒤로 틀어 뗀다','끊는 동시에 내 왼손으로 상대 오른쪽 소매, 오른손으로 상대 왼쪽 깃을 먼저 잡는다','내 왼발은 상대 오른쪽 이두, 오른발은 상대 왼쪽 골반에 대어 거리를 회복한다']::text[] where slug = 'grip-break' and owner_id is null and steps = array['상대가 내 바지나 발목을 잡으면 발을 돌려 그립 약한 방향으로 뺀다','깃을 잡히면 손목을 돌리고 몸을 틀어 뗀다','끊는 동시에 내 그립을 먼저 잡는다','발을 상대 골반 · 이두에 대어 거리를 회복한다']::text[];
update public.techniques set steps = array['누워서 내 오른발은 상대 왼쪽 골반, 왼발은 상대 오른쪽 골반 앞에 발바닥을 댄다','내 오른손으로 상대 왼쪽 소매, 왼손으로 상대 오른쪽 소매(또는 깃)를 잡는다','양 발로 밀고 양손으로 당겨 거리를 지킨다','상대가 서면 상대가 앞에 낸 다리 쪽으로 데라히바나 스파이더로 바꾼다']::text[] where slug = 'feet-on-hips-guard' and owner_id is null and steps = array['누워서 양 발바닥을 상대 골반 앞에 댄다','양 소매나 깃을 잡아 상대 팔을 컨트롤한다','발로 밀고 손으로 당겨 거리를 지킨다','상대가 서면 데라히바나 스파이더로 바꾼다']::text[];
update public.techniques set steps = array['발 골반 가드에서 내 오른손은 상대 왼쪽 소매, 왼손은 오른쪽 소매를 잡고 당긴다','상대가 뒤로 버티는 순간 양 소매는 계속 당긴 채 양 발로 상대 양 골반을 강하게 민다','상대가 엉덩이부터 주저앉으면 바로 상대 오른쪽 소매를 놓고 내 왼손을 짚고 일어난다','상대 양 발목이나 양 무릎을 잡고 패스 자세로 간다']::text[] where slug = 'push-sweep-from-feet-on-hips' and owner_id is null and steps = array['발 골반 가드에서 양 소매를 당긴다','상대가 뒤로 버티는 순간 양 발로 골반을 강하게 민다','상대가 뒤로 앉으면 발목을 잡고 일어난다','패스 자세로']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 소매, 왼손은 오른쪽 소매(또는 깃)를 잡고 양 발을 상대 양 골반에 댄다','상대가 앞으로 밀고 들어올 때 뒤로 구르며 양 발로 골반을 들어 상대를 내 머리 위로 띄운다','양손 그립을 놓지 않고 그대로 뒤로 굴러 상대를 내 머리 너머로 넘긴다','상대가 등으로 떨어지면 따라 굴러 마운트로 올라온다']::text[] where slug = 'balloon-sweep' and owner_id is null and steps = array['양 소매(또는 깃)를 잡고 양 발을 상대 골반에 댄다','상대가 앞으로 밀고 들어올 때 뒤로 구르며 양 발로 골반을 들어 상대를 머리 위로 띄운다','그립을 놓지 않고 그대로 뒤로 굴러 상대를 머리 너머로 넘긴다','상대가 등으로 떨어지면 따라 굴러 마운트로 올라온다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 발목 뒤꿈치를 잡는다','내 오른발을 상대 왼쪽 골반에서 떼어 잡은 왼쪽 발목 뒤에 건다','내 왼발은 상대 오른쪽 골반에 대고 민다','왼쪽 발목은 당기고 오른쪽 골반은 밀어 상대를 뒤로 눕힌다','발목을 놓지 않고 일어나 패스 자세로 간다']::text[] where slug = 'feet-on-hips-tripod-sweep' and owner_id is null and steps = array['한 발은 골반에 두고 같은 쪽 손으로 상대 발목을 잡는다','반대 발로 상대 반대 오금을 건다','밀고 걸며 뒤로 눕힌다','발목을 놓지 않고 일어난다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 발목을, 왼손으로 상대 오른쪽 소매를 잡는다','상대 왼쪽 골반에 댄 내 오른발은 계속 밀고, 내 왼발을 떼어 상대 오른쪽 발목 바깥에 낫처럼 건다','내 왼발로 상대 오른쪽 발목을 안쪽으로 쓸면서 오른발로 골반을 밀고 잡은 왼쪽 발목을 당긴다','상대가 뒤로 넘어지면 왼쪽 발목을 잡은 채 일어나 패스 자세로 간다']::text[] where slug = 'feet-on-hips-sickle-sweep' and owner_id is null and steps = array['한 손으로 상대 발목을 잡고 반대 손으로 소매를 잡는다','발목 잡은 쪽 골반에 댄 발은 그대로 밀고, 반대 발을 떼어 상대 반대 발목 바깥을 낫처럼 건다','건 발로 상대 발목을 안쪽으로 쓸면서 골반을 밀고 잡은 발목을 당긴다','상대가 옆으로 넘어지면 발목을 잡은 채 일어나 패스 자세로 간다']::text[];
update public.techniques set steps = array['상대가 오른발을 앞으로 내면 내 왼손으로 상대 오른쪽 발목을 잡는다','내 왼다리를 상대 오른다리 바깥으로 감아 발등을 상대 오른쪽 허벅지 안쪽에 건다','내 오른발은 상대 왼쪽 골반에 그대로 남긴다','내 오른손으로 상대 왼쪽 소매를 잡아 데라히바를 완성한다']::text[] where slug = 'feet-on-hips-to-de-la-riva' and owner_id is null and steps = array['상대가 한 발을 앞으로 내면 그 발목을 잡는다','같은 쪽 다리를 상대 다리 바깥으로 감아 훅을 건다','반대 발은 골반에 남긴다','소매를 잡아 데라히바 완성']::text[];
update public.techniques set steps = array['앉은 가드에서 내 오른손으로 상대 왼쪽 깃을 목 뒤 가까이 깊게 잡는다','엉덩이를 내 왼쪽으로 빼면서 깃을 내 오른쪽 옆구리 옆으로 지나가게 바닥 쪽으로 끌어 당긴다','상대가 앞으로 엎어지면 상체를 세워 상대 왼쪽 옆구리를 지나 등 뒤로 돌아간다','백을 잡거나 프론트 헤드락으로 잇는다']::text[] where slug = 'collar-drag-from-open-guard' and owner_id is null and steps = array['앉은 가드에서 한 손으로 상대 깃을 깊게 잡는다','엉덩이를 옆으로 빼면서 깃을 내 몸 옆으로 지나가게 바닥 쪽으로 끌어 당긴다','상대가 앞으로 엎어지면 그 등 쪽으로 상체를 세워 돌아간다','백을 잡거나 프론트 헤드락으로 잇는다']::text[];
update public.techniques set steps = array['스윕이 막히면 바로 그립을 놓지 않고 몸을 상대 쪽으로 돌린다','내 왼손으로 뒤 바닥을 짚고 오른발로 디뎌 왼다리를 뒤로 빼며 테크니컬 스탠드업으로 일어난다','또는 앉아서 내 양 발을 상대 양쪽 골반에 대어 거리를 회복한다','다시 가드 그립부터 잡는다']::text[] where slug = 'recovery-from-failed-sweep' and owner_id is null and steps = array['스윕이 막히면 바로 그립을 놓지 않고 몸을 상대 쪽으로 돌린다','손으로 바닥을 짚고 테크니컬 스탠드업으로 일어난다','또는 앉아서 발을 상대 골반에 대어 거리 회복','다시 가드 그립부터']::text[];
update public.techniques set steps = array['상대가 무릎 서서 다가오면 내 왼다리를 상대 오른다리 안쪽에 넣고 엉덩이를 그 다리 쪽으로 붙인다','상대 오른쪽 허벅지 아래로 몸을 밀어 넣어 상대 엉덩이 바로 밑에 자리 잡는다','상대 오른다리를 내 양 다리로 감싸고 내 오른팔로 상대 오른쪽 허벅지를 안는다','머리는 상대 엉덩이 쪽에 붙여 크로스페이스와 언더훅을 피하며 딥 하프를 완성한다']::text[] where slug = 'open-guard-to-deep-half' and owner_id is null and steps = array['상대가 무릎 서서 다가오면 한쪽 다리를 상대 가까운 다리 안쪽에 넣고 엉덩이를 그 다리 쪽으로 바짝 붙인다','상대 허벅지 아래로 몸을 밀어 넣어 상대 엉덩이 바로 밑에 자리 잡는다','상대 다리를 양 다리로 감싸고 가까운 팔로 허벅지를 안는다','머리는 상대 엉덩이 쪽에 붙여 크로스페이스와 언더훅을 피하며 딥 하프를 완성한다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 오른쪽 깃, 왼손으로 상대 오른쪽 소매를 잡는다','내 오른쪽 정강이를 상대 배 앞에 가로로 대고, 왼다리는 바닥 가까이 상대 오른쪽 무릎 바깥에 둔다','상대를 당겨 체중을 싣게 한 뒤 오른 정강이는 밀고 왼다리는 상대 무릎을 쓸어 가위처럼 돌린다','상대가 상대 오른쪽으로 넘어지면 따라 올라가 마운트로 간다']::text[] where slug = 'scissor-sweep-from-open-guard' and owner_id is null and steps = array['깃과 소매를 잡고 한 무릎을 상대 배 앞에 가로로 댄다','반대 다리는 바닥 가까이 상대 무릎 바깥에 둔다','상대를 당겨 체중을 내 쪽으로 실은 뒤, 윗다리는 밀고 아랫다리는 당겨 가위처럼 돌린다','따라 올라가 마운트로 간다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 소매를 잡아 바깥으로 밀고, 상대 오른팔은 내 다리 사이에 둔다','상대 왼팔을 민 쪽인 내 오른다리를 상대 목 뒤로 올린다','내 오른발목을 내 왼다리 오금에 끼우고 왼쪽 무릎을 접어 잠근다','몸을 비스듬히 틀어 각도를 만들고 양손으로 상대 머리를 당기며 무릎을 조인다']::text[] where slug = 'triangle-choke-from-open-guard' and owner_id is null and steps = array['상대 한 팔을 소매로 밀어 바깥에 두고, 반대 팔은 내 다리 사이(안쪽)에 둔다','바깥으로 민 팔 쪽 다리를 상대 목 뒤로 올린다','반대 다리로 그 발목을 걸어 삼각형을 만든다(안쪽 팔은 삼각형 안에 갇힌다)','몸을 옆으로 틀어 각도를 만들고 머리를 당기며 무릎을 조여 조른다']::text[];
update public.techniques set steps = array['내 양손으로 상대 오른팔을 잡고 몸을 돌려 상대 오른쪽 옆구리 쪽으로 붙는다','내 오른다리를 상대 머리 위로 넘기며 엎드린다','무릎을 모아 상대 오른쪽 팔꿈치를 내 골반에 붙이고 엄지가 위를 보게 손목을 잡는다','엉덩이를 밀어 올리며 팔꿈치를 편다']::text[] where slug = 'belly-down-armbar-open-guard' and owner_id is null and steps = array['상대 팔을 잡고 몸을 상대 옆으로 돌린다','다리를 상대 머리 위로 넘기며 엎드린다','무릎을 모아 상대 팔꿈치를 내 골반에 붙이고 엄지가 위를 보게 손목을 잡는다','엉덩이를 밀어 올리며 팔꿈치를 편다']::text[];
update public.techniques set steps = array['앉은 가드에서 내 오른손으로 상대 왼쪽 발목을 잡는다','내 왼손으로 상대 오른쪽 깃이나 소매를 잡는다','왼쪽 발목을 당기며 깃을 밀어 상대를 뒤로 눕힌다','발목을 놓지 않고 일어나 패스한다']::text[] where slug = 'foot-grab-sweep' and owner_id is null and steps = array['앉은 가드에서 상대 한쪽 발목을 잡는다','반대 손은 상대 깃이나 소매','발목을 당기며 깃을 밀어 뒤로 눕힌다','발목을 놓지 않고 일어나 패스']::text[];
update public.techniques set steps = array['앉은 가드에서 상대 왼발이 앞에 오면 내 오른손으로 그 뒤꿈치를 잡는다','내 왼손은 뒤로 바닥을 짚는다','엉덩이를 들어 일어나며 내 오른쪽 어깨로 상대 왼쪽 허벅지를 앞으로 민다','뒤꿈치는 당기고 몸은 밀어 상대를 뒤로 넘긴다','따라 올라가 헤드쿼터 자세를 잡는다']::text[] where slug = 'ankle-pick-sweep' and owner_id is null and steps = array['앉은 가드에서 상대 발목 바깥을 한 손으로 잡는다','반대 손으로 상대 무릎 안쪽을 민다','어깨를 상대 다리에 붙이며 일어난다','넘어가면 헤드쿼터 자세']::text[];
update public.techniques set steps = array['상대가 서 있을 때 내 오른손은 상대 왼쪽 발목, 왼손은 오른쪽 발목(뒤꿈치)을 잡는다','내 양 발로 상대 양 무릎이나 양 골반을 밀며 양 발목을 당긴다','상대가 뒤로 넘어진다','발목을 놓지 않고 일어나 패스한다']::text[] where slug = 'lumberjack-sweep' and owner_id is null and steps = array['상대가 서 있을 때 양 발목(뒤꿈치)을 양손으로 잡는다','발로 상대 무릎이나 골반을 밀며 발목을 당긴다','상대가 뒤로 넘어진다','발목을 놓지 않고 일어나 패스']::text[];
update public.techniques set steps = array['상대가 왼발을 앞에 두면 앉은 자세에서 내 오른쪽 정강이를 상대 왼쪽 정강이 앞에 가로로 댄다','내 오른손으로 상대 왼쪽 발목이나 바지를 잡는다','내 왼손으로 상대 오른쪽 깃이나 소매를 잡아 상대를 당긴다','싱글 레그 X · 스윕으로 잇는다']::text[] where slug = 'shin-to-shin-guard' and owner_id is null and steps = array['앉은 자세에서 내 정강이를 상대 정강이 앞에 가로로 댄다','같은 쪽 손으로 상대 발목이나 바지를 잡는다','반대 손으로 깃이나 소매를 잡아 상대를 당긴다','싱글 레그 X · 스윕으로 잇는다']::text[];
update public.techniques set steps = array['신 투 신에서 내 오른손은 상대 왼쪽 발목, 왼손은 오른쪽 깃이나 소매를 당겨 상대를 앞으로 기울인다','그대로 뒤로 누우며 내 오른 정강이로 상대 왼다리를 들어 올려 오른발로만 서게 만든다','내 왼발로 상대 오른쪽 무릎이나 골반을 밀어 넘어뜨린다','왼쪽 발목을 놓지 않고 따라 올라가 패스 자세로 간다']::text[] where slug = 'shin-to-shin-sweep' and owner_id is null and steps = array['신 투 신에서 상대 발목을 잡고 반대 손으로 깃이나 소매를 당겨 상대를 앞으로 기울인다','그대로 뒤로 누우며 정강이로 상대 다리를 들어 올려 한 발로 서게 만든다','반대 발로 상대 남은 다리의 무릎이나 골반을 밀어 넘어뜨린다','발목을 놓지 않고 따라 올라가 패스 자세로 간다']::text[];
update public.techniques set steps = array['신 투 신에서 내 오른손으로 상대 왼쪽 발목을 잡은 채 뒤로 누우며 그 다리를 내 쪽으로 당긴다','내 오른다리를 상대 왼쪽 허벅지 위로 넘겨 발을 상대 왼쪽 골반에 걸고 무릎은 바깥으로 조인다','내 왼다리를 상대 두 다리 사이로 넣어 왼발을 상대 오른쪽 골반에 댄다','잡은 왼쪽 발목을 가슴에 안아 싱글 레그 X를 완성한다']::text[] where slug = 'shin-to-shin-to-single-leg-x' and owner_id is null and steps = array['신 투 신에서 상대 발목을 잡은 채 뒤로 누우며 상대 다리를 내 쪽으로 당긴다','정강이를 댔던 다리를 상대 허벅지 위로 넘겨 발을 가까운 쪽 골반에 걸고 무릎은 바깥으로 조인다','반대 다리를 상대 다리 사이로 넣어 발을 먼 쪽 골반에 댄다','잡은 발목을 가슴에 안아 싱글 레그 X를 완성한다']::text[];
update public.techniques set steps = array['앉은 가드에서 내 오른손으로 상대 왼쪽 발목을 잡고 왼손으로 바닥을 짚어 테크니컬 스탠드업으로 일어난다','일어나며 상대 왼다리를 내 양팔로 안고 내 양 무릎을 모아 가둔다','머리를 상대 왼쪽 옆구리에 붙이고 등을 편다','상대 왼다리를 들어 올리며 상대를 넘긴다']::text[] where slug = 'technical-stand-up-to-single-leg' and owner_id is null and steps = array['앉은 가드에서 상대 발목을 잡고 테크니컬 스탠드업으로 일어난다','일어나며 상대 다리를 양팔로 안고 무릎을 모아 가둔다','머리를 상대 옆구리에 붙이고 등을 편다','다리를 들어 올리며 상대를 넘긴다']::text[];
update public.techniques set steps = array['상대가 오른 무릎을 세우고 들어오면 몸을 옆으로 틀어 엉덩이를 상대 오른다리에 붙인다','내 왼다리 정강이를 상대 오른쪽 허벅지 안쪽에 대고 발등은 상대 엉덩이 쪽으로 걸어 묶는다','내 오른쪽 무릎을 상대 오른쪽 무릎 바깥에 세워 K 모양을 만들고 손으로 상대 오른쪽 발목을 잡는다','상대가 버티면 다리 사이로 몸을 굴려 싱글 레그 X · X 가드 · 백 테이크로 이어 간다']::text[] where slug = 'k-guard' and owner_id is null and steps = array['상대가 한쪽 무릎을 세우고 들어오면 몸을 옆으로 돌려 그 다리 쪽으로 엉덩이를 붙인다','안쪽 다리 정강이를 상대 허벅지 안쪽에 대고, 발등은 상대 엉덩이 쪽으로 걸어 다리를 묶는다','바깥 다리 무릎을 상대 무릎 바깥에 세워 K 모양을 만들고, 손으로 상대 발목이나 바지를 잡는다','상대가 버티면 다리 사이로 몸을 굴려 싱글 레그 X · X 가드 · 백 테이크로 이어 간다']::text[];
update public.techniques set steps = array['앉아서 내 왼손은 뒤 바닥을 짚고 오른쪽 무릎을 세워 상체를 상대 쪽으로 기울인다','내 오른손으로 상대 왼쪽 깃이나 소매를 먼저 잡고, 세운 오른발 발바닥은 상대 왼쪽 골반이나 무릎 앞에 둔다','상대가 옆으로 돌면 엉덩이를 돌려 항상 상대와 정면을 유지한다','상대가 서면 발목을 잡아 스윕을, 무릎 서면 버터플라이나 신 투 신으로 바꾼다']::text[] where slug = 'seated-guard-basics' and owner_id is null and steps = array['앉아서 한 손은 뒤 바닥을 짚고 한 무릎을 세워 상체를 상대 쪽으로 기울인다','앞 손으로 상대 깃이나 소매를 먼저 잡고, 세운 다리 발바닥은 상대 골반이나 무릎 앞에 둔다','상대가 옆으로 돌면 엉덩이를 돌려 항상 상대와 정면을 유지한다','상대가 서면 발목을 잡아 스윕을, 무릎 서면 버터플라이나 신 투 신으로 바꾼다']::text[];
update public.techniques set steps = array['상대가 내 다리를 내 왼쪽으로 밀고 내 오른쪽으로 패스하려 하면 내 오른손은 상대 골반, 왼손은 어깨를 밀어 거리를 둔다','밀린 내 오른쪽 무릎을 가슴 쪽으로 당기고 오른발을 상대 골반에 다시 댄다','쉬림프로 엉덩이를 내 왼쪽으로 빼서 상대와 정면이 되게 돌아온다','양 발이 다시 상대 앞에 오면 그립을 잡아 가드를 완성한다']::text[] where slug = 'open-guard-retention' and owner_id is null and steps = array['상대가 다리를 옆으로 밀어 패스하려 하면 양 손으로 프레임을 만들어 상대 어깨나 골반을 밀어 거리를 둔다','밀린 다리 무릎을 내 가슴 쪽으로 당기고 발을 상대 골반에 다시 댄다','쉬림프로 엉덩이를 빼서 상대와 정면이 되게 돌아온다','양 발이 다시 상대 앞에 오면 그립을 잡아 가드를 완성한다']::text[];
update public.techniques set steps = array['앉은 자세에서 내 오른발은 상대 왼쪽, 왼발은 오른쪽 허벅지 안쪽에 훅처럼 넣는다','무릎은 바깥으로 벌리고 발등으로 들어 올린다(무릎을 모으지 않는다)','상체를 세우고 내 오른팔로 상대 왼팔 밑 언더훅을, 왼손으로 상대 오른쪽 깃을 잡아 가슴을 붙인다','엉덩이를 상대 가까이 당겨 거리를 없애고 스윕을 노린다']::text[] where slug = 'butterfly-guard' and owner_id is null and steps = array['앉은 자세에서 양 발을 상대 허벅지 안쪽에 훅처럼 넣는다','무릎은 바깥으로 벌리고 발등으로 들어 올린다(무릎을 모으지 않는다)','상체를 세우고 언더훅이나 깃을 잡아 가슴을 붙인다','엉덩이를 상대 가까이 당겨 거리를 없애고 스윕을 노린다']::text[];
update public.techniques set steps = array['버터플라이 가드에서 내 오른팔로 상대 왼팔 밑 언더훅, 왼손으로 상대 오른쪽 손목이나 소매를 잡는다','가슴을 붙인 채 상대를 내 쪽으로 당겨 체중을 싣게 만든다','내 왼쪽으로 옆으로 누우며 내 오른발 훅으로 상대 왼다리를 들어 올린다','상대가 내 왼쪽으로 넘어가면 그대로 따라 굴러 위로 올라온다']::text[] where slug = 'butterfly-sweep' and owner_id is null and steps = array['버터플라이 가드에서 한쪽 팔로 언더훅을 잡고 반대 손으로 상대 손목이나 소매를 잡아 짚지 못하게 한다','가슴을 붙인 채 상대를 내 쪽으로 당겨 체중을 싣게 만든다','손목 잡은 쪽으로 옆으로 누우며 언더훅 쪽 훅 발로 상대 다리를 들어 올린다','상대가 넘어가면 그대로 따라 굴러 위로 올라온다']::text[];
update public.techniques set steps = array['상대가 무릎 서서 들어올 때 내 오른발을 상대 왼쪽 허벅지 안쪽에 훅으로 넣는다','내 왼손으로 상대 오른쪽 소매나 손목을 잡아 상대가 오른손을 짚지 못하게 한다','상대를 당기면서 내 오른발 훅으로 상대 왼다리를 위로 들어 올린다','상대를 내 왼쪽으로 넘기고 따라 올라온다']::text[] where slug = 'elevator-sweep' and owner_id is null and steps = array['상대가 무릎 서서 들어올 때 한 발을 상대 허벅지 안쪽에 훅으로 넣는다','훅 반대쪽 팔(소매나 손목)을 잡아 상대가 손을 짚지 못하게 한다','상대를 당기면서 훅 발로 다리를 위로 들어 올린다','들어 올린 다리 반대쪽으로 상대를 넘기고 따라 올라온다']::text[];
update public.techniques set steps = array['버터플라이 가드에서 내 왼손으로 상대 오른쪽 손목을, 오른손으로 상대 오른팔 삼두를 잡는다','상대 오른팔을 내 가슴 앞을 지나 내 오른쪽 옆구리 옆으로 끌면서 상체를 세운다','엉덩이를 내 왼쪽으로 빼며 상대 오른쪽 겨드랑이 쪽으로 빠져나가 등 뒤로 돈다','양 훅을 넣고 백을 잡는다']::text[] where slug = 'arm-drag-to-back-butterfly' and owner_id is null and steps = array['버터플라이 가드에서 한 손으로 상대 손목을, 반대 손으로 같은 팔 삼두를 잡는다','그 팔을 내 몸 옆으로 지나가게 끌면서 상체를 세운다','팔을 끌고 간 쪽으로 빠져나가 상대 등 뒤로 돈다','훅을 넣고 백을 잡는다']::text[];
update public.techniques set steps = array['내 오른발을 상대 왼쪽 허벅지 안쪽에 훅으로 넣고 왼다리는 뒤로 뺀다','내 오른팔로 상대 왼팔 밑 언더훅을, 왼손으로 상대 오른쪽 소매를 잡는다','상대를 당겨 체중을 내 쪽으로 싣는다','내 왼쪽으로 옆으로 누우며 오른발 훅으로 상대 왼다리를 들어 넘긴다','따라 굴러 사이드 탑으로 간다']::text[] where slug = 'hook-sweep' and owner_id is null and steps = array['한쪽 훅만 상대 허벅지 안쪽에 두고 반대 다리는 뒤로 뺀다','언더훅이나 깃을 잡고 상대를 당긴다','훅으로 다리를 들며 옆으로 눕는다','굴러 사이드 탑']::text[];
update public.techniques set steps = array['상대가 서려 할 때 내 오른발 훅으로 상대 왼다리를 들어 올리며 그 다리 밑으로 몸을 밀어 넣는다','들린 상대 왼다리를 내 오른쪽 어깨에 얹고 오른팔로 안는다','내 오른발은 상대 오른쪽 골반 앞, 왼발은 상대 오른쪽 오금 뒤에 걸어 X 모양을 만든다','엉덩이를 상대 가까이 붙여 X 가드를 완성한다']::text[] where slug = 'butterfly-guard-to-x-guard' and owner_id is null and steps = array['상대가 서려 할 때 한쪽 훅 발로 상대 다리를 들어 올리며 그 다리 밑으로 몸을 밀어 넣는다','들린 다리를 어깨에 얹고 팔로 안는다','양 다리를 상대 반대 다리에 X 모양으로 건다(한 발은 골반 앞, 한 발은 오금)','엉덩이를 상대 가까이 붙여 X 가드를 완성한다']::text[];
update public.techniques set steps = array['버터플라이 위에서 내 오른손으로 상대 왼쪽 훅 무릎을 바닥으로 누른다','가슴으로 상대를 눌러 눕힌다','상대 양 무릎을 상대 왼쪽으로 모아 체중으로 깔아뭉갠다','내 다리를 빼며 상대 오른쪽 사이드로 간다']::text[] where slug = 'butterfly-smash' and owner_id is null and steps = array['버터플라이 위에서 상대 한쪽 훅 무릎을 바닥으로 누른다','가슴으로 상대를 눌러 눕힌다','상대 양 무릎을 한쪽으로 모아 체중으로 깔아뭉갠다','다리를 빼며 사이드로']::text[];
update public.techniques set steps = array['상대가 머리를 숙이고 들어오면 내 오른팔을 상대 목 앞으로 감아 머리를 오른 겨드랑이에 낀다','내 왼손으로 내 오른손을 맞잡고 양 훅으로 상대를 당겨 붙인다','뒤로 누우며 양 다리로 상대 허리를 감는다','가슴을 펴며 조인다']::text[] where slug = 'guillotine-from-butterfly' and owner_id is null and steps = array['상대가 머리를 숙이고 들어오면 팔을 목 앞으로 감는다','손을 맞잡고 훅으로 상대를 당겨 붙인다','뒤로 누우며 다리로 상대를 감는다','가슴을 펴며 조인다']::text[];
update public.techniques set steps = array['내 오른팔로 상대 왼팔 밑 언더훅을 깊게 잡고 가슴을 붙인 뒤, 왼손으로 상대 오른쪽 손목이나 소매를 잡는다','상대를 당겨 체중을 내 쪽으로 싣게 한다','내 왼쪽으로 옆으로 누우며 내 오른발 훅으로 상대 왼다리를 들어 올린다','상대를 내 왼쪽으로 넘기고 따라 올라가 사이드 탑으로 간다']::text[] where slug = 'underhook-sweep-butterfly' and owner_id is null and steps = array['언더훅을 깊게 잡고 가슴을 붙인 뒤 반대 손으로 상대 손목이나 소매를 잡아 짚지 못하게 한다','상대를 당겨 체중을 내 쪽으로 싣게 한다','손목 잡은 쪽으로 옆으로 누우며 언더훅 쪽 훅 발로 상대 다리를 들어 올린다','넘기고 따라 올라가 사이드 탑으로 간다']::text[];
update public.techniques set steps = array['상대가 오른손을 바닥에 짚으면 내 왼손으로 그 손목을 잡는다','내 오른팔로 상대 오른쪽 윗팔을 위에서 감아 내 왼손목을 잡는다','엉덩이를 내 오른쪽으로 빼며 누워 각도를 만든다','팔꿈치를 90도로 둔 채 상대 오른 손목을 상대 등 쪽으로 천천히 돌린다']::text[] where slug = 'kimura-from-butterfly' and owner_id is null and steps = array['상대가 손을 바닥에 짚으면 그 손목을 잡는다','반대 팔로 윗팔을 감아 내 손목을 잡는다','옆으로 누우며 훅으로 상대를 밀어 어깨를 바닥에 붙인다','팔을 등 뒤로 돌린다']::text[];
update public.techniques set steps = array['상대 오른팔이 내 왼다리 바깥에 오면 내 왼손으로 그 팔 삼두를 잡는다','엉덩이를 빼며 내 왼다리를 상대 오른쪽 어깨 위로 넘겨 상대 오른팔을 감는다','상체를 세워 앉고 내 오른손으로 상대 허리띠를 잡아 구르지 못하게 한다','다리를 모은 채 상체를 천천히 앞으로 기울여 어깨를 꺾는다']::text[] where slug = 'omoplata-from-butterfly' and owner_id is null and steps = array['상대 팔이 내 다리 바깥에 걸릴 때 그 팔 삼두를 잡는다','엉덩이를 빼며 다리를 상대 팔 위 · 등 뒤로 넘긴다','발목을 목에 걸고 다리를 모은다','앉아 올라오며 어깨를 꺾는다']::text[];
update public.techniques set steps = array['상대 오른다리를 하프가드로 감은 상태에서 내 오른발을 상대 오른쪽 허벅지 안쪽 훅으로 바꾼다','내 왼다리는 상대 오른다리를 계속 감는다','내 왼팔로 상대 오른팔 밑 언더훅을 잡고 상체를 세운다','오른발 훅으로 들어 스윕이나 백 테이크로 간다']::text[] where slug = 'butterfly-half-guard' and owner_id is null and steps = array['하프가드에서 안쪽 다리를 상대 허벅지 안쪽 훅으로 바꾼다','바깥 다리는 상대 다리를 계속 감는다','언더훅을 잡고 상체를 세운다','훅으로 들어 스윕이나 백 테이크']::text[];
update public.techniques set steps = array['내 왼팔로 상대 오른팔 밑 언더훅을 잡고 오른손으로 상대 왼쪽 소매나 손목을 잡는다','내 오른발 훅으로 상대 오른다리를 들어 올린다','내 오른쪽으로 옆으로 누우며 상대 체중을 띄운다','상대가 내 오른쪽으로 넘어가면 따라 올라가 사이드를 잡는다']::text[] where slug = 'butterfly-half-guard-sweep' and owner_id is null and steps = array['언더훅을 잡고 훅 다리로 상대 다리를 든다','언더훅 반대쪽으로 옆으로 누우며 상대 체중을 띄운다','상대 체중이 뜨면 그대로 옆으로 굴린다','위로 올라와 사이드를 잡는다']::text[];
update public.techniques set steps = array['상대 오른다리를 하프로 잡은 상태에서 내 오른발 훅으로 상대를 밀어 거리를 만든다','감고 있던 내 왼다리를 빼서 상대 오른쪽 허벅지 안쪽에 넣는다','내 오른발 훅은 상대 왼쪽 허벅지 안쪽으로 옮겨 양 훅을 넣고 상체를 세운다','버터플라이 가드로 돌아온다']::text[] where slug = 'reguard-from-butterfly-half' and owner_id is null and steps = array['훅으로 상대를 밀어 거리를 만든다','감은 다리를 빼서 상대 허벅지 안쪽에 넣는다','양 훅이 들어가면 상체를 세운다','버터플라이 가드']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 하프로 잡았을 때 내 왼손으로 상대 오른쪽 훅 무릎을 바닥으로 누른다','내 오른팔로 상대 왼팔 밑 언더훅이나 깃을 잡아 상체를 눌러 둔다','내 오른쪽 정강이를 상대 오른쪽 허벅지 위로 미끄러뜨린다','상대 오른쪽 사이드로 간다']::text[] where slug = 'knee-slice-from-butterfly-half' and owner_id is null and steps = array['상대 훅 무릎을 바닥으로 누른다','언더훅이나 깃을 잡아 상체를 눌러 둔다','정강이를 상대 허벅지 위로 미끄러뜨린다','사이드로']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 하프로 잡았을 때 상대 오른쪽 훅 다리를 내 왼손으로 눌러 바닥에 붙인다','가슴으로 상대 상체를 눌러 눕힌다','상대 양 무릎을 상대 왼쪽으로 모아 깔아뭉갠다','내 오른다리를 빼며 상대 오른쪽 사이드로 간다']::text[] where slug = 'smash-from-butterfly-half' and owner_id is null and steps = array['상대 훅 다리를 바깥으로 눌러 바닥에 붙인다','가슴으로 상대 상체를 눌러 눕힌다','양 무릎을 한쪽으로 모아 깔아뭉갠다','다리를 빼며 사이드']::text[];
update public.techniques set steps = array['상대 오른다리를 하프로 잡고 내 왼팔로 상대 오른팔 밑 언더훅, 오른발 훅으로 상대를 띄운다','언더훅을 유지한 채 상체를 세우며 무릎으로 일어난다','내 오른손으로 상대 오른다리를 안고 네발 자세(도그파이트)를 만든다','스윕이나 백 테이크로 잇는다']::text[] where slug = 'half-butterfly-to-dogfight' and owner_id is null and steps = array['언더훅을 잡고 훅으로 상대를 띄운다','상체를 세우며 무릎으로 일어난다','상대 다리를 안고 네발 자세(도그파이트)','스윕이나 백 테이크로']::text[];
update public.techniques set steps = array['상대 오른다리를 하프로 잡고 내 왼팔로 상대 오른팔 밑 언더훅을 깊게 잡아 머리를 상대 등 뒤로 넣는다','내 오른발 훅으로 상대를 들며 내 왼쪽 어깨 너머로 구른다','구르면서 상대 등 뒤로 나온다','양 훅을 넣고 백을 잡는다']::text[] where slug = 'rolling-back-take-from-half-butterfly' and owner_id is null and steps = array['언더훅을 깊게 잡고 상대 등 뒤로 머리를 넣는다','훅으로 상대를 들며 어깨 너머로 구른다','구르면서 상대 등 뒤로 나온다','훅을 넣고 백']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼발 훅을 바닥에 누른다','내 왼쪽 엉덩이를 뒤로 빼 상대 오른발 훅에 들리지 않게 한다','내 오른쪽 무릎을 상대 왼쪽 허벅지 위로 올린다','니슬라이스로 상대 왼쪽 사이드로 간다']::text[] where slug = 'pass-butterfly-hook-control' and owner_id is null and steps = array['상대 훅 발을 손으로 바닥에 누른다','반대쪽 엉덩이를 뒤로 빼 들리지 않게 한다','무릎을 상대 허벅지 위로 올린다','니슬라이스로 사이드']::text[];
update public.techniques set steps = array['상대 오른다리를 하프로 잡고 내 왼팔 언더훅 상태에서 내 오른손으로 상대 왼쪽 무릎 뒤를 잡는다','내 오른발 훅으로 상대 오른다리를 들어 올린다','내 왼손으로 상대 오른쪽 겨드랑이나 허리띠를 밀어 상대를 내 오른쪽으로 굴린다','따라 올라가 마운트로 간다']::text[] where slug = 'john-wayne-sweep' and owner_id is null and steps = array['하프 버터플라이에서 상대 먼 쪽 무릎 뒤를 손으로 잡는다','훅으로 상대 다리를 들어 올린다','반대 손으로 상대 겨드랑이나 허리띠를 잡고 밀어 굴린다','따라 올라가 마운트']::text[];
update public.techniques set steps = array['상대 오른다리 바깥으로 내 왼다리를 감아 발등을 상대 오른쪽 허벅지 안쪽에 건다','내 왼손으로 상대 오른쪽 발목(또는 바지 끝)을 잡는다','내 오른발은 상대 왼쪽 골반에 대어 거리를 지킨다','내 오른손으로 상대 왼쪽 소매나 깃을 잡아 상체를 컨트롤한다']::text[] where slug = 'de-la-riva-guard' and owner_id is null and steps = array['상대 한쪽 다리 바깥으로 내 다리를 감아 발을 상대 골반 앞에 건다','같은 쪽 손으로 발목(또는 바지 끝)을 잡는다','반대 발은 상대 허벅지나 골반에 대어 거리를 지킨다','반대 손으로 소매나 깃을 잡아 상체를 컨트롤한다']::text[];
update public.techniques set steps = array['내 왼다리 훅 · 왼손 상대 오른쪽 발목 · 오른손 상대 왼쪽 소매 그립을 잡는다','내 오른발로 상대 왼쪽 엉덩이를 밀면서 오른쪽 발목과 왼쪽 소매를 내 쪽으로 당긴다','내 왼다리 훅을 뻗어 상대 오른쪽 무릎을 바깥으로 돌려 균형을 무너뜨린다','상대가 뒤로 넘어지면 발목을 놓지 않고 따라 올라가 패스 자세로 간다']::text[] where slug = 'de-la-riva-sweep' and owner_id is null and steps = array['데라히바 훅 · 발목 · 반대 소매 그립을 잡는다','골반에 댄 발로 상대 먼 쪽 엉덩이를 밀면서 발목과 소매를 내 쪽으로 당긴다','훅 다리를 뻗어 상대 무릎을 바깥으로 돌려 균형을 무너뜨린다','상대가 뒤로 넘어지면 발목을 놓지 않고 따라 올라가 패스 자세로 간다']::text[];
update public.techniques set steps = array['데라히바(내 왼다리 훅)에서 내 오른손으로 상대 허리띠를 잡고 당겨 상대를 엉덩이로 앉힌다','턱을 당기고 목이 아닌 어깨로 바닥을 짚으며 거꾸로 구른다','내 왼다리 훅을 유지한 채 상대 오른다리를 따라 돌아 등 뒤로 나온다','양 훅을 넣고 백 컨트롤을 잡는다']::text[] where slug = 'berimbolo-entry' and owner_id is null and steps = array['데라히바에서 상대 허리띠를 잡고 상대를 앉힌다','머리를 상대 다리 사이로 넣으며 거꾸로 구른다(인버트)','상대 다리를 안고 돌아 상대 등 뒤로 나온다','훅을 넣고 백 컨트롤']::text[];
update public.techniques set steps = array['데라히바(내 왼다리 훅)에서 상대를 당겨 체중을 내 위로 싣게 한다','엉덩이를 상대 밑으로 넣으며 상대 왼다리를 내 오른쪽 어깨에 얹고 오른팔로 안는다','상대 왼쪽 골반에 댄 내 오른발을 떼어 상대 오른쪽 허벅지 앞에 댄다','내 왼다리 훅은 상대 오른쪽 오금 뒤에 그대로 두어 X 모양을 만든다']::text[] where slug = 'de-la-riva-to-x-guard' and owner_id is null and steps = array['데라히바에서 골반에 댄 발로 밀어 상대 체중을 뒤로 보낸다','훅 건 쪽 상대 다리를 들어 어깨에 얹으며 상대 밑으로 들어간다','양 다리를 상대 반대 다리에 X 모양으로 건다(한 발은 골반 앞, 한 발은 오금)','엉덩이를 붙여 X 가드를 완성한다']::text[];
update public.techniques set steps = array['데라히바(내 왼다리 훅)에서 내 오른손으로 상대 허리띠를 잡고 당겨 상대를 앉힌다','턱을 당기고 어깨로 구르며 상대 밑으로 들어간다','훅이 걸리지 않은 상대 왼다리를 내 오른팔로 잡아 끌어당긴다','회전을 이어 상대를 옆으로 넘기고 위나 백으로 간다']::text[] where slug = 'bolo-sweep' and owner_id is null and steps = array['데라히바에서 상대 허리띠를 잡고 앉힌다','거꾸로 돌며 상대 다리를 내 다리로 감는다','회전으로 상대를 옆으로 넘긴다','백이나 위로']::text[];
