update public.techniques set steps = array['상대가 왼다리로 내 오른다리에 데라히바를 걸면 내 오른다리를 뒤로 돌려 훅을 푼다','뒤로 뺀 내 오른발을 상대 머리 쪽으로 돌려 디디며 몸을 돌린다','상대 다리를 눌러 두고 헤드쿼터 자세를 잡는다','패스로 잇는다']::text[] where slug = 'backstep-from-de-la-riva' and owner_id is null and steps = array['훅 잡힌 다리를 뒤로 돌려 상대 훅을 푼다','뒷발을 상대 머리 쪽으로 돌리며 몸을 돌린다','상대 다리를 눌러 두고 헤드쿼터 자세','패스로 잇는다']::text[];
