update public.techniques set steps = array['상대가 왼다리로 내 오른다리에 데라히바 훅을 걸면 오른다리를 펴서 훅을 느슨하게 한다','내 오른쪽 무릎을 상대 오른쪽 허벅지 위로 올린다','내 오른손으로 상대 왼쪽 깃을 잡아 상체를 눌러 둔다','오른쪽 정강이로 상대 오른쪽 허벅지를 미끄러져 넘어 상대 오른쪽 사이드로 간다']::text[] where slug = 'knee-slice-from-dlr' and owner_id is null and steps = array['훅 다리를 펴서 상대 훅을 느슨하게 한다','무릎을 상대 허벅지 위로 올린다','깃을 잡아 상체를 눌러 둔다','정강이로 미끄러져 사이드']::text[];
update public.techniques set steps = array['데라히바(내 왼다리 훅·상대 오른다리)에서 내 오른손으로 상대 왼쪽 소매를 당겨 무너뜨린다','상대 오른팔을 바깥으로 밀고 왼다리 훅을 풀어 상대 목 뒤로 올린다','내 왼쪽 발목을 내 오른쪽 오금에 끼우고 오른쪽 무릎을 접어 잠근다','엉덩이를 내 오른쪽으로 빼 몸을 틀어 직각을 만들고, 머리를 당기며 무릎을 조인다']::text[] where slug = 'triangle-setup-from-de-la-riva' and owner_id is null and steps = array['데라히바에서 소매를 당겨 상대 자세를 무너뜨린다','훅 다리 쪽 상대 팔을 바깥으로 밀어 두고, 훅 다리를 풀어 상대 목 뒤로 올린다','반대 다리로 발목을 걸어 삼각형을 만든다','머리를 당기며 무릎을 조여 조른다']::text[];
update public.techniques set steps = array['데라히바(내 왼다리 훅·상대 오른다리)에서 내 오른손으로 상대 오른쪽 소매를 잡아 내 몸 앞으로 끌어온다','훅 건 내 왼다리를 풀어 상대 오른팔 위로 넘겨 오른쪽 어깨를 감는다','엉덩이를 돌려 상대와 같은 방향을 보고 두 다리를 모아 어깨를 누른다','내 왼팔을 상대 등 위로 넘겨 허리띠(또는 왼쪽 허리)를 잡아 앞으로 구르지 못하게 한다','앉아 올라오며 엉덩이를 앞으로 밀어 천천히 상대 오른쪽 어깨를 꺾는다']::text[] where slug = 'omoplata-from-de-la-riva' and owner_id is null and steps = array['소매를 당겨 상대 팔을 내 다리 바깥에 둔다','훅 다리를 그 팔 위로 넘긴다','발목을 목에 걸고 다리를 모은다','앉아 올라오며 어깨를 꺾는다']::text[];
update public.techniques set steps = array['내 왼다리 데라히바 훅을 상대 오른다리에 깊게 걸고 내 오른손으로 허리띠나 바지를 잡는다','왼다리 훅과 오른손 그립으로 상대를 앞으로 당겨 무게를 싣게 한다','턱을 당기고 등 위쪽(두 어깨 사이)으로 굴러 상대 아래로 몸을 거꾸로 세운다','왼다리 훅을 풀지 않고 상대 오른다리를 감아 연결을 유지한다','베림볼로나 백 테이크로 잇는다']::text[] where slug = 'de-la-riva-to-inverted-guard' and owner_id is null and steps = array['데라히바에서 허리띠를 잡고 머리를 상대 다리 사이로 넣는다','어깨로 굴러 몸을 거꾸로 세운다','다리로 상대 다리를 감는다','베림볼로나 레그 드래그 방어로']::text[];
update public.techniques set steps = array['상대가 오른다리를 내 두 다리 사이로 넣으면 내 왼손으로 상대 오른쪽 발목을 잡는다','내 오른다리를 상대 오른다리 안쪽에서 감아 오른발을 상대 오른쪽 골반 바깥에 건다','내 왼발은 상대 오른쪽 골반 앞에 댄다','오른다리 훅에 힘을 줘서 상대 오른쪽 무릎이 못 돌게 한다']::text[] where slug = 'reverse-de-la-riva-guard' and owner_id is null and steps = array['상대 발목을 같은 쪽 손으로 잡는다','같은 쪽 다리를 상대 다리 안쪽에서 감아 발을 상대 골반 바깥에 건다','반대 발은 상대 골반에 댄다','훅에 힘을 줘서 상대 무릎이 못 돌게 한다']::text[];
update public.techniques set steps = array['상대가 오른쪽 무릎을 넘겨 오면 내 왼손으로 그 무릎을, 오른손으로 골반을 막는다','왼쪽으로 돌아누워 새우빼기로 엉덩이를 내 오른쪽으로 빼 공간을 만든다','내 오른다리를 다시 상대 오른다리 안쪽에 깊게 감는다','내 왼손으로 상대 오른쪽 발목을 잡고 왼발로 골반을 밀어 자세를 되찾는다']::text[] where slug = 'reverse-de-la-riva-recovery' and owner_id is null and steps = array['상대가 다리를 펴서 훅을 풀려 하면 훅을 더 깊게 감는다','발목 그립을 당기고 골반 발로 민다','상대 무릎이 내 쪽으로 넘어오면 밀어 짚게 만든다','다시 자세를 잡는다']::text[];
update public.techniques set steps = array['리버스 데라히바(내 오른다리 훅·상대 오른다리)에서 상대 두 다리 사이로 머리를 넣는다','등 위쪽(두 어깨 사이)으로 구르며 상대 다리 사이를 지나간다','상대 등 뒤로 나와 내 오른손으로 상대 허리띠 뒤쪽을 잡는다','두 발을 상대 양쪽 허벅지 안쪽에 훅으로 넣고 백을 잡는다']::text[] where slug = 'kiss-of-the-dragon' and owner_id is null and steps = array['리버스 데라히바에서 상대 다리 사이로 머리를 넣는다','어깨로 구르며 상대 다리 사이를 지나간다','상대 등 뒤로 나와 허리띠를 잡는다','훅을 넣고 백']::text[];
update public.techniques set steps = array['리버스 데라히바(내 오른다리 훅·상대 오른다리)에서 골반에 댄 왼발을 떨어뜨려 차며 180도 돈다','내 오른쪽 어깨를 상대 오른쪽 무릎 뒤에 붙인다','훅 건 오른다리를 접어 상대 오른발을 가둔 채 뒤로 당긴다','상대가 앉으면 상대 오른쪽 발목을 잡고 일어나 패스한다']::text[] where slug = 'rdlr-swivel-takedown' and owner_id is null and steps = array['골반에 댄 발을 떨어뜨려 차며 180도 돈다','어깨를 상대 무릎 뒤에 붙인다','훅 다리를 접어 상대 발을 가둔 채 뒤로 당긴다','상대가 앉으면 발목을 잡고 일어나 패스']::text[];
update public.techniques set steps = array['상대가 오른다리로 내 오른다리에 리버스 훅을 걸면 자세를 세우고 내 발목 잡은 상대 왼손을 떼어낸다','내 오른쪽 골반에 댄 상대 왼발을 내 오른손으로 눌러 바닥으로 내린다','훅 걸린 내 오른다리를 빼며 상대 양 무릎을 내 왼쪽으로 모아 누른다','무릎을 누른 채 내 오른쪽으로 돌아 들어가 상대 왼쪽 사이드 컨트롤로 간다']::text[] where slug = 'rdlr-pass' and owner_id is null and steps = array['골반에 댄 상대 발을 손으로 잡아 몸 반대쪽으로 넘긴다','상대 양 무릎을 한쪽으로 모은다','무릎으로 상대 허벅지를 눌러 둔다','돌아 들어가 사이드나 백']::text[];
update public.techniques set steps = array['상대가 오른다리로 내 오른다리에 리버스 훅을 걸면 내 왼손으로 상대 오른쪽 깃을 눌러 구르지 못하게 한다','내 오른손으로 내 오른쪽 발목을 잡은 상대 왼손을 떼어낸다','체중을 왼다리에 싣고 훅 걸린 오른다리를 뒤로 크게 돌려 뺀다','풀린 상대 오른다리를 내 오른손으로 눌러 두고 헤드쿼터 자세로 자리 잡는다']::text[] where slug = 'rdlr-backstep-counter' and owner_id is null and steps = array['훅 잡힌 다리를 뒤로 돌리며 몸을 돌린다','상대 다리를 손으로 눌러 둔다','헤드쿼터 자세로 자리 잡는다','패스']::text[];
update public.techniques set steps = array['데라히바(내 왼다리 훅·상대 오른다리)에서 오른발로 상대 왼쪽 골반을 밀고 왼손으로 발목을 당겨 앉힌다','앉는 순간 발목 잡은 내 왼손을 놓고 상대 허리띠를 잡는다','훅 건 왼다리 쪽(내 왼쪽)으로 몸을 밀어 올려 상대 등 뒤로 돈다','두 발 훅을 상대 양쪽 허벅지 안쪽에 넣고 백 컨트롤로 간다']::text[] where slug = 'de-la-riva-to-back-take' and owner_id is null and steps = array['데라히바에서 골반에 댄 발로 밀고 발목을 당겨 상대를 엉덩이로 앉게 만든다','앉는 순간 발목 잡은 손을 놓고 상대 허리띠를 잡는다','훅 건 다리 쪽으로 몸을 밀어 올려 상대 등 뒤로 돈다','훅을 넣고 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['리버스 데라히바에서 내 왼손으로 상대 오른쪽 발목을 잡고 몸을 내 왼쪽 옆으로 돌려 눕는다','상대가 앞으로 체중을 실으면 오른다리 훅으로 상대 오른다리를 들어 올린다','내 왼발로 상대 왼쪽 골반이나 무릎을 민다','상대가 뒤로 넘어지면 상대 오른쪽 발목을 놓지 않고 따라 올라가 패스 자세로 간다']::text[] where slug = 'reverse-de-la-riva-sweep' and owner_id is null and steps = array['리버스 데라히바에서 발목을 잡고 몸을 옆으로 돌려 눕는다','상대가 앞으로 체중을 실으면 훅 다리로 상대 다리를 들어 올린다','반대 발로 상대 먼 쪽 골반이나 무릎을 민다','상대가 뒤로 넘어지면 발목을 놓지 않고 따라 올라가 패스 자세로 간다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 깃을, 내 왼손으로 상대 오른쪽 소매를 잡는다','내 왼발은 상대 오른쪽 이두(팔 안쪽)에 대고, 내 오른발은 상대 왼쪽 골반에 댄다','오른손으로 깃을 당기고 왼발로 이두를 밀어 상대 자세를 무너뜨린다','상대가 무너지는 쪽으로 트라이앵글 · 오모플라타 · 스윕으로 잇는다']::text[] where slug = 'collar-sleeve-guard' and owner_id is null and steps = array['한 손으로 상대 깃을 잡고, 반대 손으로 상대 소매를 잡는다','소매 잡은 손과 같은 쪽 발은 상대 이두(팔 안쪽)에 대고, 반대 발은 골반에 댄다','깃을 당기고 발로 밀어 상대 자세를 무너뜨린다','상대가 무너지는 쪽으로 트라이앵글 · 오모플라타 · 스윕으로 잇는다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매를, 오른손으로 상대 왼쪽 소매를 잡고 팔이 펴지게 민다','내 왼발바닥은 상대 오른쪽 이두에, 오른발바닥은 상대 왼쪽 이두에 댄다','왼발로 밀 때 오른발은 당기는 식으로 번갈아 상대 균형을 흔든다','상대가 무너지는 쪽으로 스윕이나 트라이앵글로 잇는다']::text[] where slug = 'spider-guard' and owner_id is null and steps = array['양 소매를 잡고 상대 팔이 펴지게 민다','양 발바닥을 상대 이두(팔 안쪽)에 댄다','한쪽은 밀고 한쪽은 당겨 상대 균형을 흔든다','상대가 무너지는 쪽으로 스윕이나 트라이앵글로 잇는다']::text[];
update public.techniques set steps = array['스파이더 가드에서 내 오른발을 상대 왼쪽 이두에서 떼어 상대 왼쪽 무릎 안쪽을 건다','내 왼발은 상대 오른쪽 이두를 계속 밀어 상대 오른팔을 뻗게 한다','건 오른발로 상대 왼쪽 무릎을 당기고 두 소매는 내 머리 쪽으로 당겨 넘긴다','소매를 놓지 않고 일어나 패스 자세로 간다']::text[] where slug = 'spider-sweep' and owner_id is null and steps = array['스파이더 가드에서 한쪽 발을 이두에서 떼어 상대 무릎 안쪽을 건다','반대 발은 이두를 계속 밀어 팔을 뻗게 한다','건 다리로 무릎을 당기고 소매는 반대로 당겨 넘긴다','소매를 놓지 않고 일어나 패스 자세로']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매를 잡고 왼발을 상대 오른팔 바깥에서 안으로 감아 넣는다(올가미)','왼발을 상대 오른쪽 겨드랑이 아래까지 깊게 넣는다','내 오른발은 상대 왼쪽 이두나 왼쪽 골반에 대어 거리를 지킨다','왼손으로 소매를 당기며 라쏘 건 왼다리로 상대를 돌려 균형을 뺏는다']::text[] where slug = 'lasso-guard' and owner_id is null and steps = array['한쪽 소매를 잡고 같은 쪽 발을 상대 팔 바깥에서 안으로 감아 넣는다(올가미)','발을 상대 겨드랑이 아래까지 깊게 넣는다','반대 발은 상대 이두나 골반에 대어 거리를 지킨다','소매를 당기며 라쏘 발로 상대를 돌려 균형을 뺏는다']::text[];
update public.techniques set steps = array['왼다리 라쏘(상대 오른팔)를 깊게 걸고 내 오른손으로 상대 왼쪽 발목이나 바지를 잡는다','내 오른발을 상대 왼쪽 무릎 안쪽에 대고 민다','왼다리로 상대 오른팔을 끌어당기며 오른손으로 발목을 당기고 오른발로 무릎을 밀어 넘긴다','넘어가면 라쏘를 풀고 따라 올라간다']::text[] where slug = 'lasso-sweep' and owner_id is null and steps = array['라쏘를 깊게 걸고 반대 손으로 라쏘 반대쪽 상대 발목이나 바지를 잡는다','반대 발을 그 다리 무릎 안쪽에 대고 민다','라쏘 다리로 상대 팔을 끌어 당기며 발목을 당기고 무릎을 밀어 넘긴다','넘어가면 라쏘를 풀고 따라 올라간다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 오른쪽 소매를 잡고 왼발은 오른쪽 이두, 오른발은 왼쪽 골반에 둔다','골반에 댄 오른발을 내려 상대 왼다리 뒤(오금)를 바깥에서 건다','깃을 당기고 왼발로 이두를 위로 차며 건 오른발로 상대 왼다리를 당긴다','상대가 넘어가면 따라 올라가 위를 잡는다']::text[] where slug = 'collar-sleeve-sweep' and owner_id is null and steps = array['깃과 소매를 잡고 소매 쪽 발을 이두에, 반대 발을 골반에','깃을 당기고 이두를 밀어 상대를 한쪽으로 기울인다','골반 발로 상대 무릎 안쪽을 걸어 당긴다','넘기고 위로']::text[];
update public.techniques set steps = array['상대가 왼발을 앞으로 내면 내 오른발을 골반에서 떼어 상대 왼다리 바깥을 감는다','깃을 잡던 내 오른손을 상대 왼쪽 발목으로 옮긴다','내 왼손의 상대 오른쪽 소매 그립은 유지한다','데라히바(내 오른다리 훅·상대 왼다리)']::text[] where slug = 'collar-sleeve-to-de-la-riva' and owner_id is null and steps = array['상대가 앞발을 내면 골반 발을 떼어 그 다리 바깥을 감는다','깃 손을 발목으로 옮긴다','소매는 유지','데라히바']::text[];
update public.techniques set steps = array['깃을 잡던 내 오른손으로 상대 왼쪽 소매를 잡아 양 소매 그립을 만든다','내 왼발은 상대 오른쪽 이두, 오른발은 상대 왼쪽 이두에 댄다','왼발로 밀 때 오른발은 당기며 균형을 흔든다','스파이더 가드']::text[] where slug = 'collar-sleeve-to-spider' and owner_id is null and steps = array['깃 손으로 반대 소매를 잡아 양 소매 그립','양 발을 양 이두에 댄다','밀고 당겨 균형을 흔든다','스파이더 가드']::text[];
update public.techniques set steps = array['내 왼쪽 깃을 잡은 상대 오른손 그립을 손목을 돌려 먼저 끊는다','내 오른쪽 이두에 댄 상대 왼발을 내 오른손으로 잡아 바닥으로 내린다','내 왼쪽 무릎을 눌러 둔 상대 왼쪽 허벅지 위로 올린다','니슬라이스나 토레안도로 상대 왼쪽 사이드로 간다']::text[] where slug = 'pass-collar-sleeve-guard' and owner_id is null and steps = array['깃 그립을 먼저 끊는다(손목 돌리기)','이두 발을 잡아 바닥으로 내린다','무릎을 상대 다리 위로 올린다','니슬라이스나 토레안도']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 깃·오른쪽 소매를 잡으면 엉덩이를 뒤로 빼고 가슴을 세워 끌리지 않게 한다','두 손으로 내 왼쪽 깃(또는 오른쪽 소매)을 잡은 상대 손을 끊는다','상대 양 무릎 바지를 잡고 두 다리를 내 왼쪽으로 밀어 넘긴다','내 오른쪽으로 크게 돌아 가슴을 눌러 상대 왼쪽 사이드로 간다']::text[] where slug = 'bull-pass-from-collar-sleeve' and owner_id is null and steps = array['상대 양 무릎(바지)을 잡는다','한쪽으로 다리를 밀어 넘기며 반대로 돈다','소매 그립이 늘어나 풀린다','가슴을 누르며 사이드']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매를, 오른손으로 상대 왼쪽 소매를 잡고 팔을 뻗게 한다','내 왼발은 상대 오른쪽 이두나 골반에, 오른발은 상대 왼쪽 이두나 골반에 둔다','왼발로 밀 때 오른발은 당기며 상대 자세를 흔든다','스파이더 · 라쏘 · 데라히바로 바꿀 준비']::text[] where slug = 'double-sleeve-guard' and owner_id is null and steps = array['양 소매를 잡고 상대 팔을 뻗게 한다','발은 이두나 골반에 둔다','밀고 당겨 상대 자세를 흔든다','스파이더 · 라쏘 · 데라히바로 바꿀 준비']::text[];
update public.techniques set steps = array['양 소매(내 왼손-상대 오른쪽, 오른손-상대 왼쪽)를 잡고 양 발을 양쪽 이두에 댄다','내 오른발을 상대 왼쪽 이두에서 떼어 상대 왼쪽 무릎 뒤를 건다','내 왼발로 상대 오른쪽 이두를 밀며 두 소매를 당긴다','넘기고 마운트']::text[] where slug = 'double-sleeve-sweep' and owner_id is null and steps = array['양 소매를 잡고 양 발을 이두에','한쪽 발을 이두에서 떼어 상대 무릎 뒤를 건다','반대 발로 이두를 밀며 소매를 당긴다','넘기고 마운트']::text[];
