update public.techniques set steps = array['엉덩이를 내 왼쪽(상대 오른팔 쪽)으로 새우빼기해 각도를 만든다','내 왼손으로 상대 오른쪽 소매를 당겨 내 몸 앞으로 끌어온다','내 왼다리를 상대 오른팔 위로 넘겨 어깨를 감고 두 다리를 모은다','내 왼팔을 상대 등 위로 넘겨 허리띠(또는 왼쪽 허리)를 잡아 앞으로 구르지 못하게 한다','앉아 올라오며 엉덩이를 앞으로 밀어 천천히 꺾는다']::text[] where slug = 'omoplata-from-double-sleeve' and owner_id is null and steps = array['한쪽 소매를 당겨 그 팔을 내 다리 바깥으로 둔다','같은 쪽 다리를 팔 위 · 등 뒤로 넘긴다','발목을 목에 걸고 다리를 모은다','앉아 올라오며 꺾는다']::text[];
