update public.techniques set steps = array['소매를 잡은 상대 양손을 손목을 돌려 하나씩 끊는다','상대 발이 내 이두에서 떨어지는 순간 두 팔을 상대 두 다리 아래로 넣어 깍지 낀다','앞으로 밀어 상대 엉덩이를 들어 스택한다','상대 두 다리를 내 왼쪽으로 넘기며 내 오른쪽으로 돌아 상대 왼쪽 사이드로 간다']::text[] where slug = 'stack-pass-from-spider' and owner_id is null and steps = array['이두에 걸린 발을 어깨로 들어 올린다','양팔을 상대 다리 아래로 넣어 깍지','엉덩이를 들어 스택','돌아 사이드']::text[];
update public.techniques set steps = array['내 왼발을 상대 오른쪽 이두에서 상대 오른팔 바깥으로 돌려 어깨를 감는다','내 왼손으로 상대 오른쪽 소매를 당기며 엉덩이를 내 왼쪽으로 빼 각도를 만든다','왼다리를 상대 등 뒤로 넘기고 상대와 같은 방향을 본다','내 왼팔을 상대 등 위로 넘겨 허리띠(또는 왼쪽 허리)를 잡아 앞으로 구르지 못하게 한다','앉아 올라오며 엉덩이를 앞으로 밀어 천천히 꺾는다']::text[] where slug = 'spider-guard-to-omoplata' and owner_id is null and steps = array['한쪽 이두 발을 상대 팔 바깥으로 돌려 어깨를 감는다','소매를 당기며 엉덩이를 뺀다','다리를 등 뒤로 넘기고 모은다','앉아 올라오며 꺾는다']::text[];
update public.techniques set steps = array['내 왼발로 상대 오른팔을 바깥으로 밀어 두고, 오른손으로 상대 왼쪽 소매를 당겨 안쪽에 둔다','이두를 밀던 내 왼다리를 떼어 상대 목 뒤로 넘긴다','내 오른쪽 오금에 왼쪽 발목을 걸어 삼각형을 만든다(상대 왼팔은 삼각형 안에 갇힌다)','머리를 당기며 무릎을 조여 조른다']::text[] where slug = 'triangle-from-spider-guard' and owner_id is null and steps = array['한쪽 이두 발로 상대 팔을 바깥으로 밀어 두고 반대 소매를 당겨 그 팔을 안쪽에 둔다','이두를 밀던 발을 떼어 그 다리를 상대 목 뒤로 넘긴다','반대 다리로 발목을 걸어 삼각형을 만든다(당긴 팔은 삼각형 안에 갇힌다)','머리를 당기며 무릎을 조여 조른다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매를 당겨 그 팔을 내 몸 가운데로 뻗게 한다','내 왼발로 상대 오른쪽 골반을 밀어 각도를 만든다','내 오른다리를 상대 머리 위로 넘겨 상대 오른팔을 두 다리 사이에 가둔다','상대 오른팔을 가슴에 안은 채 엎드리고 무릎을 모은다','엉덩이를 천천히 들어 편다']::text[] where slug = 'belly-down-armbar-spider' and owner_id is null and steps = array['소매를 당겨 상대 팔을 뻗게 한다','반대 다리를 머리 위로 넘기며 엎드린다','무릎을 모은다','엉덩이를 들어 편다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 오른쪽 소매를 잡고 왼발은 오른쪽 이두, 오른발은 왼쪽 골반에 댄다','깃을 당겨 무너뜨리면서 소매 잡은 상대 오른팔을 바깥 아래로 밀어 낸다','이두를 밀던 내 왼다리를 떼어 상대 목 뒤로 넘긴다','골반에 댔던 내 오른다리 오금에 왼쪽 발목을 걸어 삼각형을 만든다','깃을 놓고 상대 머리를 당기며 무릎을 조여 조른다']::text[] where slug = 'triangle-from-collar-sleeve' and owner_id is null and steps = array['깃과 소매를 잡고 소매 쪽 발을 이두에, 반대 발을 골반에 댄다','깃을 당겨 상대 자세를 무너뜨리면서 소매 잡은 팔을 바깥 아래로 밀어 낸다','이두를 밀던 발을 떼어 그 다리를 상대 목 뒤로 넘긴다','골반에 댔던 다리로 그 발목을 걸어 삼각형을 만든다','깃을 놓고 상대 머리를 당기며 무릎을 조여 조른다']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 깃, 왼손은 오른쪽 소매를 잡고 왼발은 오른쪽 이두, 오른발은 왼쪽 골반에 댄다','왼손으로 소매를 당기며 이두의 왼발을 상대 오른팔 바깥으로 돌려 그 팔이 내 왼다리 아래에 오게 한다','오른발로 골반을 밀며 엉덩이를 내 왼쪽으로 빼고 왼다리를 상대 오른쪽 어깨 위로 넘겨 다리를 모은다','소매를 놓지 않고 앉아 올라오며 상대 오른팔을 등 뒤로 꺾는다']::text[] where slug = 'omoplata-from-collar-sleeve' and owner_id is null and steps = array['깃과 소매를 잡고 소매 쪽 발을 이두에, 반대 발을 골반에 댄다','소매를 당기면서 이두를 밀던 발을 상대 팔 바깥으로 돌려 그 팔이 내 다리 아래에 오게 한다','골반 발로 밀며 엉덩이를 빼고 그 다리를 상대 어깨 위로 넘겨 다리를 모은다','소매를 놓지 않고 앉아 올라오며 상대 팔을 등 뒤로 꺾는다']::text[];
update public.techniques set steps = array['왼다리 라쏘(상대 오른팔)를 걸고 내 오른손으로 상대 왼쪽 소매나 깃을 잡아 왼팔을 내 쪽으로 당긴다','내 오른발로 상대 왼쪽 골반을 밀어 자세를 무너뜨린다','왼다리를 펴서 겨드랑이에서 발을 빼며 상대 목 뒤로 넘긴다(상대 오른팔은 바깥에 남는다)','내 오른쪽 오금에 왼쪽 발목을 걸어 삼각형을 만들고 머리를 당겨 조른다']::text[] where slug = 'triangle-from-lasso' and owner_id is null and steps = array['라쏘를 깊게 걸고 반대 손으로 상대 반대쪽 소매나 깃을 잡아 그 팔을 내 쪽으로 당긴다','반대 발로 골반을 밀어 상대 자세를 무너뜨린다','라쏘 다리를 위로 펴서 겨드랑이에서 발을 빼며 그 다리를 상대 목 뒤로 넘긴다(라쏘 걸었던 팔은 다리 아래 바깥에 남는다)','반대 다리로 발목을 걸어 삼각형을 만들고 머리를 당겨 조른다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 오른쪽 앞자락 끝(라펠)을 허리띠 아래에서 빼낸다','라펠을 상대 오른다리 뒤(오금)로 돌려 바깥으로 꺼내 내 왼손으로 받는다','꺼낸 라펠 끝을 당겨 상대 오른다리와 자세를 묶는다','내 오른발은 상대 왼쪽 골반에, 왼발은 상대 오른쪽 무릎에 대고 거리를 지킨다','데라히바 · 라쏘 · 웜 가드 스윕으로 잇는다']::text[] where slug = 'lapel-guard-basics' and owner_id is null and steps = array['상대 도복 앞자락 끝(라펠)을 허리띠 아래에서 빼내 손에 잡는다','라펠을 상대 다리 뒤(오금)로 돌려 바깥으로 꺼낸다','꺼낸 라펠 끝을 당겨 상대 다리와 자세를 묶는다','발은 상대 골반이나 무릎에 대고 거리를 지킨다','데라히바 · 라쏘 · 웜 가드 스윕으로 잇는다']::text[];
update public.techniques set steps = array['상대 오른쪽 라펠 끝을 빼서 상대 오른다리 뒤(오금)로 돌려 바깥으로 꺼낸다','꺼낸 라펠을 내 왼쪽 정강이 위로 넘겨 왼다리로 라펠을 감는다','라펠 끝은 내 오른손으로 잡고 감은 왼발은 상대 오른쪽 골반에 둔다','라펠을 당겨 상대 상체를 앞으로 숙이게 하며 스윕을 노린다']::text[] where slug = 'worm-guard-entry' and owner_id is null and steps = array['상대 라펠 끝을 빼서 상대 한쪽 다리 뒤(오금)로 돌려 바깥으로 꺼낸다','꺼낸 라펠을 내 같은 쪽 정강이 위로 넘겨 그 다리로 라펠을 감는다','라펠 끝은 반대 손으로 잡고 감은 발은 상대 골반에 둔다','라펠을 당겨 상대 상체를 앞으로 숙이게 하며 스윕을 노린다']::text[];
update public.techniques set steps = array['내 왼손 라펠로 상대 오른다리를 묶은 채 내 오른손으로 상대 허리띠나 바지를 잡는다','라펠을 내 가슴 쪽으로 당겨 상대 상체를 앞으로 숙이게 한다','상대가 손을 짚으면 묶인 상대 오른다리 바깥쪽(내 왼쪽)으로 돌아 나간다','허리띠를 당겨 상대를 앉히고 등 뒤로 올라가 두 발 훅을 넣는다']::text[] where slug = 'lapel-sweep-to-back' and owner_id is null and steps = array['라펠로 상대 다리를 묶은 채 반대 손으로 허리띠나 바지를 잡는다','라펠을 가슴 쪽으로 당겨 상대 상체를 앞으로 숙이게 한다','상대가 손을 짚으면 묶인 다리 바깥쪽으로 돌아 나간다','허리띠를 당겨 상대를 앉히고 등 뒤로 올라가 훅을 넣는다']::text[];
update public.techniques set steps = array['내 왼손 라펠로 상대 오른다리를 묶은 채 내 오른발을 상대 왼쪽 허벅지 안쪽에 훅으로 넣는다','라펠을 가슴 쪽으로 당겨 상대 자세를 숙이게 한다','오른발 훅으로 상대 왼다리를 들어 올리며 묶인 오른다리 쪽(내 왼쪽)으로 넘긴다','라펠을 놓지 않고 따라 올라가 마운트나 사이드로 간다']::text[] where slug = 'lapel-elevator-sweep' and owner_id is null and steps = array['라펠로 상대 다리를 묶은 채 반대 발을 상대 허벅지 안쪽에 훅으로 넣는다','라펠을 가슴 쪽으로 당겨 상대 자세를 숙이게 한다','훅으로 상대 다리를 들어 올리며 묶인 다리 쪽으로 넘긴다','라펠을 놓지 않고 따라 올라가 마운트나 사이드로 간다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 라펠을 잡고, 내 왼발을 상대 오른다리 바깥에서 감아 데라히바 훅을 건다','상대 오른쪽 발목 대신 오른손의 라펠을 당겨 상대 자세를 묶는다','내 오른발은 상대 왼쪽 골반이나 왼쪽 무릎을 밀어 거리를 지킨다','데라히바 스윕이나 백 테이크로 잇는다']::text[] where slug = 'lapel-to-de-la-riva' and owner_id is null and steps = array['라펠 잡은 손 반대쪽 발을 상대 다리 바깥에서 감아 데라히바 훅을 건다','발목 대신 라펠을 당겨 상대 자세를 묶는다','반대 발은 상대 골반이나 무릎을 밀어 거리를 지킨다','데라히바 스윕이나 백 테이크로 잇는다']::text[];
update public.techniques set steps = array['내 오른손으로 라펠을 당겨 상대가 상체를 숙이면 내 왼손으로 상대 오른쪽 소매를 잡는다','내 왼발을 상대 오른팔 바깥에서 안으로 감아 라쏘를 건다','오른손 라펠과 왼쪽 라쏘를 함께 당겨 상대 상체와 오른팔을 묶는다','라쏘 스윕이나 오모플라타로 잇는다']::text[] where slug = 'lapel-to-lasso' and owner_id is null and steps = array['라펠을 당겨 상대가 상체를 숙이면 반대 손으로 소매를 잡는다','소매 잡은 쪽 발을 그 팔 바깥에서 안으로 감아 라쏘를 건다','라펠과 라쏘를 함께 당겨 상대 상체와 팔을 묶는다','라쏘 스윕이나 오모플라타로 잇는다']::text[];
update public.techniques set steps = array['내 오른손으로 라펠을 잡은 채 내 왼손으로 상대 오른쪽 소매를 잡는다','내 왼발을 상대 오른쪽 이두에 올린다','오른손으로 라펠을 당기며 왼발로 이두를 밀어 상대 오른팔을 편다','스파이더 스윕이나 트라이앵글로 잇는다']::text[] where slug = 'lapel-to-spider' and owner_id is null and steps = array['라펠 반대 손으로 상대 소매를 잡는다','소매 잡은 쪽 발을 상대 이두에 올린다','라펠을 당기며 이두를 밀어 상대 팔을 편다','스파이더 스윕이나 트라이앵글로 잇는다']::text[];
update public.techniques set steps = array['라펠로 상대 오른팔을 상대 몸에 묶어 팔이 아래로 처지게 한다','엉덩이를 내 왼쪽으로 빼며 내 왼다리를 상대 오른팔 위로 넘겨 등 뒤에 건다','두 발을 모아 상대 오른쪽 어깨를 잠그고 내 오른손으로 상대 허리띠를 잡아 구르지 못하게 한다','앉아 올라오며 상체를 상대 머리 쪽으로 눌러 오른쪽 어깨를 꺾는다']::text[] where slug = 'lapel-omoplata-entry' and owner_id is null and steps = array['라펠로 상대 한 팔을 몸에 묶어 팔이 아래로 처지게 한다','엉덩이를 바깥으로 빼며 그쪽 다리를 상대 팔 위로 넘겨 등 뒤에 건다','두 발을 모아 상대 어깨를 잠그고 반대 손으로 허리띠를 잡아 구르지 못하게 한다','앉아 올라오며 상체를 앞으로 눌러 어깨를 꺾는다']::text[];
update public.techniques set steps = array['라펠로 상대 오른팔을 묶어 내 왼다리 바깥에 두고, 상대 왼팔은 내 다리 사이에 둔다','내 왼다리를 상대 오른쪽 어깨 위로 넘겨 상대 목 뒤에 건다','상대 머리를 당겨 내리며 내 오른다리 오금으로 내 왼쪽 발목을 걸어 잠근다','안에 남은 상대 왼팔을 내 왼쪽으로 넘기고 무릎을 모으며 조인다']::text[] where slug = 'lapel-triangle-setup' and owner_id is null and steps = array['라펠로 상대 한 팔을 묶어 내 다리 바깥에 둔다','묶인 팔 쪽 어깨 위로 그쪽 다리를 넘겨 상대 목 뒤에 건다','상대 머리를 당겨 내리며 반대 다리 오금으로 발목을 걸어 잠근다','안에 남은 팔을 반대쪽으로 넘기고 무릎을 모으며 조인다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 라펠을 잡았을 때, 내 왼손으로 내 왼쪽 깃을 몸 쪽으로 당겨 느슨하게 한다','라펠을 내 다리와 몸에서 완전히 빼낸다','빼자마자 내 왼손은 상대 오른쪽 무릎, 오른손은 왼쪽 무릎을 잡아 내 왼쪽으로 민다','무릎을 바닥에 눌러 두고 내 오른쪽으로 돌아 상대 왼쪽 사이드 컨트롤로 간다']::text[] where slug = 'lapel-clear-to-toreando' and owner_id is null and steps = array['상대가 잡은 라펠 쪽 깃을 몸 쪽으로 당겨 느슨하게 한다','라펠을 내 다리와 몸에서 완전히 빼낸다','라펠을 빼자마자 상대 양 무릎을 잡아 옆으로 밀어 토레안도','무릎을 바닥에 눌러 두고 돌아 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['라펠이 내 오른다리에 감겨도 내 오른쪽 무릎을 상대 왼쪽 허벅지 위로 올린다','내 오른손으로 상대 깃을 잡아 상체를 눌러 둔다','오른쪽 정강이로 상대 왼쪽 허벅지를 넘어 미끄러지며 라펠을 풀어낸다','상대 왼쪽에서 사이드 컨트롤을 잡는다']::text[] where slug = 'knee-slice-despite-lapel' and owner_id is null and steps = array['라펠이 다리에 감겨도 무릎을 상대 허벅지 위로 올린다','깃을 잡아 상체를 눌러 둔다','정강이로 미끄러져 라펠을 풀어낸다','사이드']::text[];
update public.techniques set steps = array['상대가 오른손으로 내 라펠을 잡았을 때, 내 왼손으로 상대 오른쪽 손목(소매)을 먼저 잡아 더 감지 못하게 한다','엉덩이를 뒤로 빼고 등을 세워 자세를 지킨다','내 오른손으로 감긴 라펠을 한 겹씩 풀어 몸에서 빼낸다','한 걸음 뒤로 물러나 바로 양손으로 바지나 무릎 그립을 다시 잡고 패스를 시작한다']::text[] where slug = 'distance-creation-to-reset' and owner_id is null and steps = array['라펠을 잡히면 뒤로 물러서며 다리를 편다','라펠을 당겨 느슨하게 하고 몸에서 빼낸다','상대가 따라오면 그립을 다시 잡는다','오픈 가드 패스부터 다시']::text[];
update public.techniques set steps = array['상대가 오른손으로 내 라펠을 잡았을 때, 내 왼손으로 상대 오른쪽 손목이나 소매를 누른다','내 오른손으로 상대 왼쪽 정강이 쪽 바지를 잡는다','상대 왼다리를 내 왼쪽 엉덩이 옆으로 끌어오며 몸을 틀어 라펠을 풀어낸다','내 가슴과 어깨를 상대 왼쪽 골반에 붙여 누르고 상대 왼쪽 사이드로 간다']::text[] where slug = 'leg-drag-while-clearing-lapel' and owner_id is null and steps = array['라펠 감긴 다리를 손으로 잡는다','라펠을 풀며 그 다리를 반대 엉덩이로 끌어온다','무릎을 상대 엉덩이에 붙인다','사이드']::text[];
update public.techniques set steps = array['상대 오른다리를 내 왼쪽 어깨에 올리고 양팔로 그 허벅지를 감아 깃이나 허리띠를 잡는다','내 엉덩이는 낮게 두고 앞으로 걸어 들어가 상대 오른쪽 무릎을 상대 얼굴 쪽으로 접는다','상대 엉덩이가 들리면 체중을 실어 누른 채 내 오른쪽으로 돈다','상대 왼쪽에 자리 잡은 뒤 남은 라펠을 풀고 사이드를 굳힌다']::text[] where slug = 'stack-pass-over-lapel' and owner_id is null and steps = array['라펠 감긴 다리를 어깨로 든다','양팔을 다리 아래로 넣어 깍지','엉덩이를 들어 스택','돌아 사이드']::text[];
update public.techniques set steps = array['웜 가드(상대 왼쪽 라펠을 상대 왼다리 뒤로 돌려 내 오른다리에 감음)에서 오른손으로 라펠을 당긴다','내 오른발로 상대 왼쪽 골반을 밀며 내 왼손으로 상대 오른쪽 발목이나 바지를 잡는다','라펠을 당기며 상대 오른다리를 들어 묶인 왼다리 쪽(상대 왼쪽)으로 넘긴다','라펠을 놓지 않고 따라 올라가 사이드나 마운트로 간다']::text[] where slug = 'worm-guard-sweep' and owner_id is null and steps = array['웜 가드에서 라펠을 가슴 쪽으로 당겨 상대 상체를 숙이게 한다','라펠 감은 발로 상대 골반을 밀며 반대 손으로 상대 발목이나 바지를 잡는다','라펠을 당기며 상대 다리를 들어 묶인 다리 쪽으로 넘긴다','라펠을 놓지 않고 따라 올라가 사이드나 마운트로 간다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 라펠을 빼려 하면 내 왼손으로 왼쪽 깃을 가슴에 눌러 못 빼게 막는다','이미 감겼으면 엉덩이를 뒤로 빼고 등을 세워 숙여지지 않게 한다','라펠 끝을 쥔 상대 손목을 내 두 손으로 잡아 손가락을 떼어낸다','풀린 라펠을 내 왼다리에서 빼내 몸 쪽에 붙이고 바로 패스 그립을 잡는다']::text[] where slug = 'defend-worm-guard-posture' and owner_id is null and steps = array['상대가 라펠을 빼려 하면 라펠 쪽 손으로 먼저 잡아 감지 못하게 막는다','이미 감겼으면 엉덩이를 뒤로 빼고 등을 세워 숙여지지 않게 한다','감긴 다리 무릎을 상대 쪽으로 세우고 체중을 앞발이 아닌 뒷발에 둔다','라펠을 몸 쪽으로 당겨 느슨해지면 다리를 빼내 패스로 간다']::text[];
update public.techniques set steps = array['상대가 서면 상대 왼다리 아래로 들어가 그 다리를 내 오른쪽 어깨에 얹고 내 오른팔로 안는다','내 왼발은 상대 오른쪽 무릎 뒤(오금)에 훅으로 건다','내 오른발은 상대 오른쪽 허벅지 안쪽이나 골반에 대 두 다리가 X 모양이 되게 한다','안은 상대 왼쪽 발목을 가슴으로 당기며 두 훅으로 상대 오른다리를 밀어 벌린다']::text[] where slug = 'x-guard' and owner_id is null and steps = array['상대가 서면 한쪽 다리 아래로 들어가 그 다리를 어깨에 얹고 팔로 안는다','아래쪽 다리는 상대 반대 다리 무릎 뒤(오금)에 훅으로 건다','위쪽 다리 발은 상대 반대 허벅지 안쪽이나 골반에 대 두 다리가 X 모양이 되게 한다','안은 발목을 가슴으로 당기며 두 훅으로 밀어 상대 다리를 벌린다']::text[];
update public.techniques set steps = array['안은 상대 왼다리를 가슴 쪽으로 당기고 두 훅으로 상대 오른다리를 밀어 다리를 벌린다','상대가 뒤로 앉거나 손을 짚어도 안은 상대 왼쪽 발목을 놓지 않는다','상대 왼다리를 든 채 일어나 밀어 눕힌다','상대 왼다리를 놓지 않고 패스 자세로 간다']::text[] where slug = 'x-guard-sweep' and owner_id is null and steps = array['안은 다리를 가슴 쪽으로 당기고 두 훅으로 상대 반대 다리를 밀어 다리를 벌린다','상대가 뒤로 앉거나 손을 짚으면 안은 발목을 놓지 않는다','상대 다리를 든 채 일어나 밀어 눕힌다','다리를 놓지 않고 패스 자세로 간다']::text[];
update public.techniques set steps = array['X 가드에서 두 훅으로 상대 오른다리를 든다','내 오른쪽 어깨에 얹은 상대 왼다리를 내려 그 발목을 내 오른손으로 잡는다','왼쪽 발목을 당겨 손을 못 짚게 하며 들린 오른다리를 도끼질하듯 상대 오른쪽 바깥으로 넘긴다','상대가 등으로 넘어지면 다리를 넘어 마운트로 올라온다']::text[] where slug = 'tomahawk-sweep' and owner_id is null and steps = array['X 가드에서 두 훅으로 상대 반대 다리를 든다','어깨에 얹은 다리를 내려 그 발목을 손으로 잡는다','발목을 당겨 상대가 손을 짚지 못하게 하며 들린 다리를 도끼질하듯 바깥으로 넘긴다','상대가 등으로 넘어지면 다리를 넘어 마운트로 올라온다']::text[];
update public.techniques set steps = array['상대 왼다리를 내 오른팔로 안은 채 내 왼손으로 바닥을 짚는다','오른발로 바닥을 딛고 엉덩이를 들어 왼다리를 뒤로 빼서 일어난다','상대 왼다리를 든 채 서서 밀어 눕힌다','상대 왼다리를 놓지 않고 패스 자세로 간다']::text[] where slug = 'x-guard-technical-stand-up' and owner_id is null and steps = array['상대 다리를 안은 채 한 손으로 바닥을 짚는다','엉덩이를 들고 안쪽 다리를 빼서 일어난다','상대 다리를 든 채 서서 밀어 눕힌다','패스 자세']::text[];
update public.techniques set steps = array['내 오른쪽 어깨에 얹은 상대 왼다리를 내려 왼쪽 발목을 내 오른쪽 겨드랑이에 안는다','내 오른발(바깥 다리)을 상대 왼쪽 골반에 걸고 내 왼다리(안쪽 다리)는 상대 왼쪽 허벅지 안쪽에 둔다','상대 왼다리를 가슴 쪽으로 당긴다','상대 왼다리에 싱글 레그 X가 완성된다']::text[] where slug = 'x-guard-to-single-leg-x' and owner_id is null and steps = array['어깨에 얹은 다리를 내려 발목을 가슴에 안는다','바깥 다리를 상대 골반에 걸고 안쪽 다리는 허벅지 안쪽','상대 다리를 가슴 쪽으로 당긴다','싱글 레그 X']::text[];
update public.techniques set steps = array['X 가드에서 내 오른쪽 어깨에 얹은 상대 왼다리 발목을 내 오른쪽 겨드랑이에 끼운다','내 두 다리로 상대 왼쪽 허벅지를 감아 무릎을 모은다','내 오른쪽 손목 날을 상대 왼쪽 아킬레스 아래에 대고 그립을 가슴에 붙인다','내 오른쪽으로 눕고 엉덩이를 천천히 밀어 상대가 탭할 시간을 준다']::text[] where slug = 'ankle-lock-from-x-guard' and owner_id is null and steps = array['X 가드에서 상대 발목을 겨드랑이에 끼워 길로틴처럼 감는다','손목을 가슴에 붙여 그립을 조인다','감은 팔 쪽으로 몸을 돌리며 눕는다','엉덩이를 밀며 뒤로 당겨 발목을 편다']::text[];
update public.techniques set steps = array['상대가 내 왼다리를 안고 내 오른다리에 X 훅을 걸었을 때, 엉덩이를 낮추고 발을 넓게 서서 균형을 잡는다','내 왼쪽 발목(또는 바지)을 잡은 상대 손을 먼저 떼어낸다','내 오른다리에 걸린 상대 훅을 손으로 눌러 떼며 안긴 왼다리를 빼낸다','뒤로 물러나 거리를 두고 다시 패스 자세를 잡는다']::text[] where slug = 'standing-escape-from-x-guard' and owner_id is null and steps = array['어깨에 얹힌 다리를 뒤로 빼며 엉덩이를 낮춘다','상대 훅 다리를 손으로 눌러 떼어낸다','다리를 빼며 뒤로 물러선다','다시 패스 자세']::text[];
update public.techniques set steps = array['상대가 내 왼다리를 안고 내 오른다리에 X 훅을 걸었을 때, 내 왼손으로 상대 깃이나 머리를 잡아 상체를 고정한다','내 오른손으로 내 오른쪽 무릎 뒤에 걸린 상대 왼다리 무릎을 바닥으로 누른다','엉덩이를 낮추며 체중을 실어 상대 왼쪽 무릎을 바닥에 붙인다','안긴 왼다리를 빼 하프가드 위로 자리 잡고 니슬라이스로 잇는다']::text[] where slug = 'knee-pin-from-x-guard' and owner_id is null and steps = array['어깨에 얹힌 다리를 내려 상대 다리 위에 무릎으로 앉는다','상대 안쪽 훅 다리를 손으로 눌러 뺀다','하프가드 위로 자리 잡는다','니슬라이스']::text[];
update public.techniques set steps = array['상대가 내 왼다리를 안고 내 오른다리에 X 훅을 걸었을 때, 내 왼쪽 발목을 잡은 상대 손을 먼저 떼어낸다','내 오른손으로 상대 왼쪽 골반이나 무릎을 바닥에 누른다','훅만 걸린 내 오른다리를 크게 돌려 상대 몸 위로 넘긴다','안긴 왼다리를 빼고 크로스페이스로 사이드를 굳힌다']::text[] where slug = 'step-over-from-x-guard' and owner_id is null and steps = array['얹힌 다리를 상대 머리 위로 넘겨 돌린다','상대 훅이 풀리면 몸을 돌려 상대 옆으로','무릎을 상대 옆구리에 붙인다','사이드']::text[];
update public.techniques set steps = array['상대가 내 왼다리를 안고 내 오른다리에 X 훅을 걸었을 때, 체중을 상대 위로 떨어뜨려 훅을 뭉갠다','상대 두 무릎을 내 오른쪽으로 모아 누른다','상대 어깨에 얹힌 내 왼다리를 빼낸다','상대 무릎 반대쪽인 내 왼쪽으로 돌아 사이드를 잡는다']::text[] where slug = 'smash-pass-from-x-guard' and owner_id is null and steps = array['체중을 상대 위로 떨어뜨려 훅을 뭉갠다','상대 무릎을 한쪽으로 모아 누른다','얹힌 다리를 빼낸다','사이드']::text[];
update public.techniques set steps = array['상대 왼쪽 발목을 내 오른쪽 겨드랑이에 안고 상대 왼다리를 내 두 다리 사이에 둔다','내 오른발(바깥 다리)을 상대 왼쪽 골반에 건다(중앙선을 넘지 않는다)','내 왼다리(안쪽 다리)는 상대 왼쪽 허벅지 안쪽에서 뒤로 감는다','왼쪽 발목을 가슴으로 당기며 상대 왼쪽 무릎을 상대 왼쪽 바깥으로 돌린다']::text[] where slug = 'single-leg-x-guard' and owner_id is null and steps = array['상대 한쪽 발목을 겨드랑이에 안는다','같은 쪽 다리를 상대 다리 안쪽에서 돌려 발을 골반에 건다(중앙선을 넘지 않는다)','반대 다리는 허벅지 안쪽을 감는다','발목을 가슴으로 당기며 상대 무릎을 바깥으로 돌린다']::text[];
update public.techniques set steps = array['상대 왼쪽 발목을 안고 내 오른발로 상대 왼쪽 골반을 밀며 엉덩이를 든다','상대 왼쪽 무릎을 상대 왼쪽 바깥으로 틀어 넘어뜨린다','상대가 앉으면 상대 왼다리를 든 채 일어난다','상대 왼다리를 놓지 않고 패스 자세로 간다']::text[] where slug = 'single-leg-x-sweep' and owner_id is null and steps = array['발목을 안고 골반 발로 밀며 엉덩이를 든다','상대 무릎을 바깥으로 틀어 넘어뜨린다','상대가 앉으면 다리를 든 채 일어난다','패스 자세']::text[];
update public.techniques set steps = array['상대 왼다리에 싱글 레그 X를 건 채 내 왼손으로 상대 오른발 뒤꿈치를 잡는다','내 오른발로 상대 왼쪽 골반을 밀며 오른발 뒤꿈치를 당긴다','상대가 뒤로 넘어진다','상대 왼다리를 든 채 일어나 사이드로 간다']::text[] where slug = 'heel-grab-sweep' and owner_id is null and steps = array['싱글 레그 X에서 상대 반대 발 뒤꿈치를 손으로 잡는다','골반 발로 밀며 뒤꿈치를 당긴다','상대가 뒤로 넘어진다','일어나 사이드']::text[];
update public.techniques set steps = array['상대 왼다리에 싱글 레그 X를 건 채 엉덩이를 상대 아래로 더 넣는다','겨드랑이에 안은 상대 왼다리를 내 오른쪽 어깨 위로 올려 오른팔로 안는다','내 왼발은 상대 오른쪽 오금, 내 오른발은 상대 오른쪽 골반으로 옮겨 X 훅을 건다','X 가드 스윕으로 잇는다']::text[] where slug = 'slx-to-x-guard' and owner_id is null and steps = array['싱글 레그 X에서 엉덩이를 상대 아래로 더 넣는다','겨드랑이에 안은 다리를 어깨 위로 올려 팔로 안는다','골반 발과 안쪽 훅을 상대 반대 다리로 옮겨 X 모양 훅을 건다','X 가드 스윕으로 잇는다']::text[];
update public.techniques set steps = array['상대 왼쪽 발목을 내 오른쪽 겨드랑이에 끼우고 내 오른쪽 손목 날을 아킬레스 아래에 댄다','내 두 다리로 상대 왼쪽 허벅지를 감아 무릎을 모은다','오른쪽 손목을 가슴에 붙여 그립을 조이고 내 오른쪽으로 눕는다','엉덩이를 천천히 밀고 가슴을 펴 상대가 탭할 시간을 준다']::text[] where slug = 'straight-ankle-lock' and owner_id is null and steps = array['상대 발목을 겨드랑이에 끼우고 팔로 아킬레스 위를 감는다','손목을 가슴에 붙여 그립을 조인다(정강이 아니라 발목에)','감은 팔 쪽으로 몸을 돌려 눕는다','엉덩이를 앞으로 밀며 가슴을 펴 발목을 편다']::text[];
update public.techniques set steps = array['상대가 내 오른발에 앵클락을 걸었을 때, 바로 앉아 내 발목을 감은 상대 왼팔을 잡아 못 눕게 한다','오른발 발끝을 위로 세워 발목이 안 펴지게 한다','내 왼발로 상대 엉덩이나 발목을 밀며 오른다리를 뺀다','위로 올라가 패스한다']::text[] where slug = 'ankle-lock-escape' and owner_id is null and steps = array['바로 앉아 상대 가까운 팔을 잡아 못 눕게 한다','발끝을 위로 세워 발목이 안 펴지게 한다','반대 발로 상대 엉덩이나 발목을 밀며 다리를 뺀다','위로 올라가 패스']::text[];
update public.techniques set steps = array['상대가 내 오른발에 앵클락을 걸었을 때, 오른쪽 무릎을 굽히고 오른발 발끝을 몸 쪽으로 세워 발목을 지킨다','내 두 손으로 내 오른발 뒤꿈치를 잡은 상대 손을 떼어낸다','내 왼발로 상대 다리를 밀며 오른쪽 무릎을 상대 다리 사이에서 빼낸다','뒤로 물러나 서거나 발을 상대 골반에 대 거리를 둔다']::text[] where slug = 'knee-extraction' and owner_id is null and steps = array['잡힌 다리 무릎을 상대 다리 사이에서 빼며 일어선다','상대 훅을 손으로 눌러 떼어낸다','뒤로 물러선다','스탠딩']::text[];
update public.techniques set steps = array['상대가 내 왼다리에 싱글 레그 X를 걸었을 때, 잡힌 왼쪽 무릎을 바깥으로 돌리지 않게 안쪽으로 유지한다','내 왼쪽 골반에 댄 상대 오른발을 손으로 눌러 떼어낸다','왼다리를 빼며 뒤로 물러난다','다시 패스 자세를 잡는다']::text[] where slug = 'standing-escape-from-slx' and owner_id is null and steps = array['잡힌 발의 무릎을 바깥으로 돌리지 않게 안쪽으로 유지한다','상대 골반 발을 손으로 눌러 떼어낸다','다리를 빼며 뒤로 물러난다','다시 패스 자세']::text[];
update public.techniques set steps = array['상대가 내 왼다리에 싱글 레그 X를 걸었을 때, 내 왼쪽 골반에 댄 상대 오른발을 손으로 눌러 떼어낸다','자유로운 오른다리에 체중을 싣는다','오른다리를 상대 엉덩이 뒤로 돌려 디디며 몸을 반 바퀴 돌린다','잡힌 왼다리가 풀리면 가슴을 붙이고 크로스페이스로 사이드를 잡는다']::text[] where slug = 'backstep-from-single-leg-x' and owner_id is null and steps = array['잡힌 다리를 뒤로 돌리며 몸을 돌린다','상대 다리를 손으로 눌러 둔다','상대 옆으로 돌아 들어간다','사이드']::text[];
update public.techniques set steps = array['상대 오른다리 아래로 들어가 그 다리를 내 왼쪽 어깨에 얹고 왼팔로 안되, 몸은 반대로 향한다','내 오른다리로 상대 왼쪽 무릎 뒤를 건다','내 왼발로 상대 왼쪽 허벅지를 민다','안은 상대 오른쪽 발목을 당겨 균형을 뺏는다']::text[] where slug = 'reverse-x-guard' and owner_id is null and steps = array['상대 다리 아래로 들어가 한 다리를 어깨에 얹되 몸은 반대로 향한다','안쪽 다리로 상대 반대 무릎 뒤를 건다','바깥 다리는 허벅지를 민다','발목을 당겨 균형을 뺏는다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 소매나 손목을 잡아 당긴다','상대 왼쪽 무릎 뒤에 건 오른다리를 펴며 엉덩이를 들어 상대 왼다리를 띄운다','소매를 당긴 쪽인 상대 왼쪽으로 상대를 넘긴다','놓지 않고 따라 올라가 마운트를 잡는다']::text[] where slug = 'reverse-x-guard-sweep' and owner_id is null and steps = array['얹은 다리를 안고 훅으로 상대 다리를 든다','상대 체중이 뜨면 옆으로 넘긴다','굴러 올라온다','마운트']::text[];
update public.techniques set steps = array['리버스 X에서 양 다리로 상대 왼다리를 들어 올린다','상대가 왼손으로 바닥을 짚으려 하면 안은 상대 오른쪽 발목을 당긴다','상대를 상대 왼쪽으로 넘겨 등이 닿게 한다','따라 올라가 마운트를 잡는다']::text[] where slug = 'elevation-sweep-to-mount' and owner_id is null and steps = array['양 다리로 상대 다리를 들어 올린다','상대가 손을 짚으면 그쪽 발목을 당긴다','등으로 넘긴다','마운트']::text[];
update public.techniques set steps = array['내 왼쪽 어깨에 얹은 상대 오른다리를 안고 상대 뒤로 돈다','내 오른손으로 상대 허리띠를 잡고 상대를 앉힌다','상대 등 뒤로 나와 두 발로 훅을 넣는다','백 컨트롤을 잡는다']::text[] where slug = 'reverse-x-to-back-take' and owner_id is null and steps = array['얹은 다리를 안고 상대 뒤로 돈다','허리띠를 잡고 상대를 앉힌다','등 뒤로 나와 훅','백']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 안고 리버스 X를 걸었을 때, 내 오른손으로 상대 깃이나 소매를 잡는다','훅만 걸린 왼다리에 체중을 싣고 내 왼손으로 왼쪽 무릎 뒤 훅을 눌러 느슨하게 한다','안긴 오른다리를 뒤로 크게 돌려 빼며 몸을 돌린다','상대 옆에 엉덩이를 내리고 크로스페이스로 사이드를 잡는다']::text[] where slug = 'backstep-pass-from-reverse-x' and owner_id is null and steps = array['얹힌 다리를 뒤로 돌리며 몸을 돌린다','상대 다리를 눌러 둔다','옆으로 돌아 들어간다','사이드']::text[];
update public.techniques set steps = array['X 가드에서 두 훅으로 상대 오른다리를 밀어 상대가 몸을 돌리게 한다','상대 등이 보이면 오른쪽 어깨의 상대 왼다리를 내리고 내 오른손으로 허리띠나 허리를 잡는다','내 왼발 훅으로 상대 오른쪽 무릎 뒤를 당겨 앉히며 등 뒤로 올라온다','가슴을 등에 붙이고 훅을 넣어 백 컨트롤을 완성한다']::text[] where slug = 'x-guard-back-take' and owner_id is null and steps = array['X 가드에서 두 훅으로 상대 반대 다리를 밀어 상대가 몸을 돌리게 한다','상대 등이 보이면 어깨에 얹은 다리를 내리고 허리띠나 허리를 잡는다','상대 무릎 뒤를 당겨 앉히며 등 뒤로 올라온다','가슴을 등에 붙이고 훅을 넣어 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대 오른다리를 내 양 다리로 감아 발목을 잠근다','감은 다리 쪽인 내 왼쪽으로 돌아 눕는다 — 등이 바닥에 평평하면 진다','내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반에 대어 프레임을 만든다(뼈로)','밀기 전에 먼저 브릿지로 상대 체중을 띄운 뒤 엉덩이를 상대에게서 멀리 빼 공간을 만든다']::text[] where slug = 'half-guard-basics' and owner_id is null and steps = array['상대 한쪽 다리를 내 양 다리로 감아 발목을 잠근다','감은 다리 쪽으로 옆으로 돌아 눕는다 — 등이 바닥에 평평하면 진다','위쪽 팔뚝은 상대 목, 아래 팔뚝은 골반에 대어 프레임을 만든다(손바닥이 아니라 뼈로)','밀기 전에 먼저 브릿지로 상대 체중을 띄운 뒤 엉덩이를 빼서 공간을 만든다']::text[];
update public.techniques set steps = array['하프가드에서 위쪽인 내 오른쪽 무릎을 상대 배나 골반 앞에 가로로 세운다(낮은 니 쉴드)','아래쪽인 내 왼다리는 상대 오른다리를 계속 감아 둔다','내 오른손은 내 오른쪽 무릎, 내 왼손은 상대 오른쪽 이두를 잡아 거리를 지킨다','상대가 오른손으로 내 무릎을 밀어 치우면 내 왼팔을 상대 오른쪽 겨드랑이 아래로 넣어 언더훅']::text[] where slug = 'knee-shield-half-guard' and owner_id is null and steps = array['하프가드에서 위쪽 무릎을 상대 배나 골반 앞에 가로로 세운다(낮은 니 쉴드)','아래 다리는 상대 다리를 계속 감아 둔다','같은 쪽 손은 내 무릎, 반대 손은 상대 이두를 잡아 거리를 지킨다','상대가 무릎을 밀어 치우면 그 팔을 따라 들어가 언더훅으로 바꾼다']::text[];
update public.techniques set steps = array['팔로 먼저 뻗지 말고 내 오른쪽 무릎을 들어 올려 상대 몸을 위로 밀어 공간을 만든다','생긴 공간으로 내 왼팔을 넣어 상대 오른쪽 겨드랑이 아래를 감는다','왼손은 상대 등 위가 아니라 골반 가까이, 왼쪽 팔꿈치는 몸에 붙여 짧게 잡는다','언더훅을 잡으면 머리를 상대 오른쪽 겨드랑이 밑으로 빼고 스윕이나 백 테이크로 간다']::text[] where slug = 'half-guard-underhook' and owner_id is null and steps = array['팔로 먼저 뻗지 말고 무릎을 들어 올려 상대 몸을 위로 밀어 공간을 만든다','생긴 공간으로 팔을 넣어 상대 겨드랑이 아래를 감는다','손은 상대 등 위가 아니라 골반 가까이, 팔꿈치는 몸에 붙여 짧게 잡는다','언더훅을 잡으면 머리를 상대 겨드랑이 밑으로 빼고 스윕이나 백 테이크로 간다']::text[];
update public.techniques set steps = array['하프가드에서 내 왼팔로 상대 오른쪽 겨드랑이 아래 언더훅을 잡고 내 왼쪽으로 돌아 눕는다','머리를 상대 오른쪽 겨드랑이 아래로 넣어 자세를 낮춘다','언더훅한 왼팔로 상대 오른다리를 안아 내리고(또는 오른쪽 발목을 잡고) 중심을 뺏는다','앞으로 밀며 올라와 탑으로 간다']::text[] where slug = 'half-guard-underhook-sweep' and owner_id is null and steps = array['하프가드에서 언더훅을 잡고 옆으로 돌아 눕는다','머리를 상대 겨드랑이 아래로 넣어 자세를 낮춘다','언더훅 팔로 상대 다리를 안아 내리고(또는 발목을 잡고) 중심을 뺏는다','앞으로 밀며 올라와 탑으로 간다']::text[];
update public.techniques set steps = array['내 왼팔로 언더훅을 잡고 내 왼쪽으로 돌아 머리를 상대 오른쪽 겨드랑이 아래로 뺀다','무릎을 세워 상대 오른쪽에서 등 뒤로 돌아 올라온다(도그파이트)','내 왼손으로 상대 허리띠나 허리를 잡고 가슴을 상대 등에 붙인다','훅을 넣고 시트벨트를 잡아 백 컨트롤을 완성한다']::text[] where slug = 'half-guard-back-take' and owner_id is null and steps = array['언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로 뺀다','무릎을 세워 상대 등 뒤로 돌아 올라온다(도그파이트)','한 손으로 허리띠나 허리를 잡고 가슴을 상대 등에 붙인다','훅을 넣고 시트벨트를 잡아 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반에 대어 프레임을 만든다','브릿지 → 엉덩이를 상대에게서 멀리 빼기(쉬림프)를 한 번이 아니라 두 번 한다','내 오른쪽 무릎을 상대 배 앞으로 가져온다','내 왼다리를 상대 오른쪽 허리 위로 넘겨 클로즈드 가드나 버터플라이로 돌아온다']::text[] where slug = 'half-guard-recovery' and owner_id is null and steps = array['상대 목과 골반에 프레임을 만든다','브릿지 → 엉덩이 빼기(쉬림프)를 한 번이 아니라 두 번 한다','감아 둔 다리 쪽 무릎을 상대 배 앞으로 가져온다','반대 다리를 상대 허리 위로 넘겨 클로즈드 가드나 버터플라이로 돌아온다']::text[];
update public.techniques set steps = array['하프가드에서 상대 오른다리 아래로 깊게 파고들어 그 허벅지가 내 가슴 위에 오게 한다','내 왼팔로 상대 오른쪽 허벅지를 안고 머리는 상대 오른다리 아래로 숨긴다','내 오른손으로 상대 왼쪽 발목이나 허리띠를 잡아 자세를 고정한다','상대 오른다리를 들어 올리며 돌아 위로 올라온다']::text[] where slug = 'deep-half-guard' and owner_id is null and steps = array['하프가드에서 상대 다리 아래로 깊게 파고들어 허벅지가 내 가슴 위에 오게 한다','감은 다리 쪽 팔로 상대 허벅지를 안고 머리는 상대 다리 아래로 숨긴다','반대 손으로 상대 발목이나 허리띠를 잡아 자세를 고정한다','상대 다리를 들어 올리며 돌아 위로 올라온다']::text[];
update public.techniques set steps = array['상대가 오른손으로 바닥을 짚으면 내 왼손으로 그 손목을 잡는다','내 오른팔로 상대 오른쪽 윗팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','내 왼쪽으로 몸을 돌려 상대 오른쪽 팔꿈치를 내 가슴에 붙인다','상대 오른손을 상대 등 쪽으로 천천히 돌리고, 안 되면 스윕이나 백으로 잇는다']::text[] where slug = 'kimura-half-guard' and owner_id is null and steps = array['상대가 내 머리를 누르거나 바닥을 짚은 손목을 잡는다','반대 팔로 상대 윗팔을 감아 내 손목을 잡는다(8자 그립)','옆으로 돌아 팔꿈치를 몸에 붙이고 상대 어깨를 바닥 쪽으로 누른다','바로 안 꺾이면 스윕이나 백 테이크로 잇는다(기무라 트랩)']::text[];
update public.techniques set steps = array['내 오른쪽 팔뚝은 상대 목, 왼쪽 팔뚝은 상대 오른쪽 골반(손바닥 말고 뼈로)','먼저 브릿지로 상대 체중을 띄운다','프레임으로 공간을 지키며 엉덩이를 상대에게서 멀리 뺀다(한 번 더)','오른쪽 무릎을 넣거나 왼팔로 언더훅을 잡는다']::text[] where slug = 'half-guard-frames' and owner_id is null and steps = array['위 팔뚝은 상대 목, 아래 팔뚝은 골반(손바닥 말고 뼈로)','먼저 브릿지로 상대 체중을 띄운다','프레임으로 공간을 지키며 엉덩이를 뺀다(한 번 더)','무릎을 넣거나 언더훅을 잡는다']::text[];
update public.techniques set steps = array['니 쉴드인 내 오른쪽 무릎을 상대 가슴이나 어깨 높이로 올린다','아래쪽인 내 왼다리는 상대 오른다리를 감는다','내 오른팔로 상대 머리를 밀어 프레임을 만든다','내 왼손으로 상대 오른쪽 소매나 깃을 잡고 스윕 · 회복을 노린다']::text[] where slug = 'z-guard' and owner_id is null and steps = array['니 쉴드 무릎을 상대 가슴이나 어깨 높이로 올린다','아래 다리는 상대 다리를 감는다','같은 쪽 팔로 상대 머리를 밀어 프레임','반대 손으로 소매나 깃을 잡고 스윕 · 회복을 노린다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 소매나 깃을 잡고 오른쪽 무릎(니 쉴드)으로 상대를 민다','상대가 밀고 들어오면 니 쉴드를 풀어 내 오른다리로 상대 왼쪽 허벅지를 든다','내 왼다리로 상대 오른쪽 발목을 걸어 당긴다','상대를 내 왼쪽으로 넘기고 따라 올라와 위를 잡는다']::text[] where slug = 'z-guard-sweep' and owner_id is null and steps = array['깃이나 소매를 잡고 니 쉴드로 상대를 민다','상대가 밀고 들어오면 니 쉴드를 풀어 그 다리로 상대 허벅지를 든다','아래 다리로 상대 발목을 걸어 당긴다','넘기고 위로']::text[];
update public.techniques set steps = array['상대가 오른손으로 니 쉴드(내 오른쪽 무릎)를 밀어 치우면 그 팔을 따라 들어간다','내 왼팔을 상대 오른쪽 겨드랑이 아래로 넣어 언더훅을 잡는다','엉덩이를 상대 쪽으로 당겨 붙인다','언더훅 스윕이나 백 테이크로 잇는다']::text[] where slug = 'z-guard-to-half-guard' and owner_id is null and steps = array['상대가 니 쉴드를 밀어 치우면 그 팔을 따라 들어간다','팔을 상대 겨드랑이 아래로 넣어 언더훅','엉덩이를 상대 쪽으로 당긴다','언더훅 스윕이나 백 테이크']::text[];
update public.techniques set steps = array['니 쉴드(내 오른쪽 무릎)로 상대를 밀어 거리를 만들고 엉덩이를 상대에게서 멀리 뺀다','감았던 내 왼다리를 빼내 상대 오른쪽 허리 위로 넘긴다','니 쉴드였던 오른다리도 상대 왼쪽 허리 뒤로 넘겨 두 발을 잠근다','클로즈드 가드에서 상대 자세를 무너뜨린다']::text[] where slug = 'knee-shield-to-closed-guard' and owner_id is null and steps = array['니 쉴드로 상대를 밀어 거리를 만들고 엉덩이를 뺀다','감았던 아래 다리를 빼내 상대 허리 위로 넘긴다','니 쉴드 다리도 상대 등 뒤로 넘겨 두 발을 잠근다','클로즈드 가드에서 상대 자세를 무너뜨린다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽 무릎(니 쉴드)을 밀려고 오른손을 짚으면 내 왼손으로 그 손목을 잡는다','내 오른팔로 상대 오른쪽 윗팔을 위에서 감아 내 왼쪽 손목을 잡는다(8자 그립)','니 쉴드로 상대를 밀어내며 몸을 내 왼쪽으로 돌려 상대 오른쪽 어깨를 바닥 쪽으로 누른다','상대 오른팔을 상대 등 뒤로 천천히 돌려 꺾고, 안 꺾이면 스윕으로 잇는다']::text[] where slug = 'kimura-from-knee-shield' and owner_id is null and steps = array['상대가 니 쉴드를 밀려고 짚은 손목을 잡는다','반대 팔로 상대 윗팔을 감아 내 손목을 잡는다(8자 그립)','니 쉴드로 상대를 밀어내며 몸을 옆으로 돌려 어깨를 바닥 쪽으로 누른다','팔을 등 뒤로 돌려 꺾고, 안 꺾이면 스윕으로 잇는다']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 니 쉴드에서 내 오른손은 상대 왼쪽 깃, 왼손은 상대 오른쪽 소매를 잡는다','니 쉴드인 내 왼다리를 풀어 왼발로 상대 왼쪽 허벅지 안쪽을 걸어 든다','내 오른다리로 상대 오른쪽 발목을 걸어 당긴다','상대를 상대 오른쪽으로 넘기고 마운트']::text[] where slug = 'sweep-from-knee-shield' and owner_id is null and steps = array['깃과 소매를 잡는다','니 쉴드 다리를 풀어 상대 허벅지 안쪽을 든다','아래 다리로 상대 발목을 걸어 당긴다','넘기고 마운트']::text[];
update public.techniques set steps = array['상대 오른다리를 감고 내 왼팔로 언더훅, 오른쪽 옆으로 돌아 머리를 상대 가슴에 붙인다','내 오른손으로 내 다리 사이에 갇힌 상대 오른쪽 발목을 잡는다','왼발로 바닥을 밀며 무릎으로 올라와 상대 오른쪽 옆구리로 밀고 들어간다','오른다리를 딛지 못한 상대가 넘어지면 갇힌 다리를 빼고 사이드를 잡는다']::text[] where slug = 'old-school-sweep' and owner_id is null and steps = array['언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로','언더훅 팔로 상대 먼 쪽 발목을 잡는다','발목을 당기며 앞으로 밀고 올라온다','사이드 탑']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 감고 왼팔로 언더훅 잡으면 바로 내 오른팔로 위저(오버훅)를 감는다','상대가 잡은 오른발목 쪽 내 오른다리를 뒤로 빼 펴며 엉덩이를 낮춘다','내 왼팔로 크로스페이스를 걸어 상대 머리를 눌러 둔다','다시 하프 탑']::text[] where slug = 'defend-old-school-sweep' and owner_id is null and steps = array['상대가 언더훅 잡으면 바로 위저(오버훅)로 팔을 감는다','잡힌 발목 쪽 다리를 뒤로 빼 펴며 엉덩이를 낮춘다','크로스페이스로 상대 머리를 눌러 둔다','다시 하프 탑']::text[];
update public.techniques set steps = array['상대 오른다리를 감고 내 왼팔로 언더훅, 무릎으로 일어나 내 오른팔로 상대 오른다리를 안는다','상대도 오른팔 위저로 버티면 둘 다 네발 자세(도그파이트)','머리를 상대 오른쪽 옆구리에 붙인다','상대 반응에 따라 스윕 · 백 테이크 · 재하프']::text[] where slug = 'dogfight-position' and owner_id is null and steps = array['언더훅을 잡고 무릎으로 일어나 상대 다리를 안는다','상대도 위저로 버티면 둘 다 네발 자세(도그파이트)','머리를 상대 옆구리에 붙인다','상대 반응에 따라 스윕 · 백 테이크 · 재하프']::text[];
update public.techniques set steps = array['도그파이트(내 왼팔 언더훅)에서 상대가 몸을 상대 왼쪽으로 돌리면 내 오른손으로 상대 왼쪽 발목을 잡아 당긴다','상대가 내 쪽으로 돌면 내 오른손으로 상대 오른쪽 무릎을 밀어 엉덩이를 바닥으로','내 왼쪽 어깨와 머리로 상대 오른쪽 가슴을 밀어붙인다','위로 올라와 사이드']::text[] where slug = 'dogfight-sweep' and owner_id is null and steps = array['상대가 몸을 바깥으로 돌리면 먼 쪽 발목을 잡아 당긴다','상대가 내 쪽으로 돌면 무릎을 밀어 엉덩이를 바닥으로','어깨와 머리로 밀어붙인다','위로 올라와 사이드']::text[];
update public.techniques set steps = array['내 오른팔로 상대 오른다리를 안은 채 왼쪽 어깨를 상대 오른쪽 골반에 붙인다','양발로 바닥을 밀며 상대 쪽으로 돌진한다','오른다리를 안겨 딛지 못한 상대가 뒤로 넘어진다','마운트나 사이드']::text[] where slug = 'forward-drive-sweep-from-dogfight' and owner_id is null and steps = array['상대 다리를 안은 채 어깨를 상대 골반에 붙인다','발로 바닥을 밀며 앞으로 돌진한다','상대가 뒤로 넘어진다','마운트나 사이드']::text[];
update public.techniques set steps = array['스윕이 막히면 내 오른팔로 상대 오른다리를 안은 채 엉덩이를 바닥에 앉힌다','안은 상대 오른다리를 내 양 다리로 감는다','내 오른쪽 옆으로 돌아 눕는다','내 왼팔 언더훅 하프가드']::text[] where slug = 're-pull-half-guard-from-dogfight' and owner_id is null and steps = array['스윕이 막히면 상대 다리를 안은 채 엉덩이를 바닥에 앉힌다','안은 다리를 내 양 다리로 감는다','옆으로 돌아 눕는다','언더훅 하프가드']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 감고 왼팔 언더훅일 때 내 오른팔 위저로 상대 왼쪽 어깨를 눌러 둔다','잡힌 내 오른다리를 뒤로 빼며 엉덩이를 낮춘다','내 왼팔로 크로스페이스를 걸어 머리를 눌러 눕힌다','하프 탑']::text[] where slug = 're-flatten-from-dogfight' and owner_id is null and steps = array['위저로 상대 어깨를 눌러 둔다','잡힌 다리를 뒤로 빼며 엉덩이를 낮춘다','크로스페이스로 머리를 눌러 눕힌다','하프 탑']::text[];
update public.techniques set steps = array['내 오른팔 위저를 겨드랑이에 꽉 붙여 상대 왼팔 언더훅을 묶는다','내 왼팔뚝을 상대 턱 앞으로 넣고 왼쪽 어깨로 얼굴을 상대 오른쪽으로 돌린다','상대 등이 바닥에 닿게 몸으로 눌러 눕힌다','감긴 오른다리를 빼고 가슴을 붙여 사이드 컨트롤로']::text[] where slug = 'crossface-from-dogfight' and owner_id is null and steps = array['위저를 유지한 채 반대 팔로 상대 얼굴을 반대쪽으로 민다','상대 등이 바닥으로 가게 돌린다','다리를 빼며 가슴을 붙인다','사이드']::text[];
update public.techniques set steps = array['상대 왼팔 언더훅을 내 오른팔 위저로 감은 채 내 왼손으로 상대 목 뒤를 잡는다','오른팔 위저와 왼손을 함께 바닥 쪽으로 강하게 낚아챈다','상대 머리가 바닥으로 가면 가슴으로 누른다','프론트 헤드락']::text[] where slug = 'snap-down-from-dogfight' and owner_id is null and steps = array['위저 반대 손으로 상대 목 뒤를 잡는다','위저와 함께 아래로 강하게 낚아챈다','상대 머리가 바닥으로 가면 가슴으로 누른다','프론트 헤드락']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 채 상대가 오른팔 크로스페이스로 누르면 내 왼손으로 상대 오른쪽 목·어깨를 받친다','브릿지로 상대를 띄운다','그 순간 엉덩이를 내 왼쪽으로 빼며 오른쪽 옆으로 누워 공간을 만든다','내 왼팔을 상대 오른쪽 겨드랑이 밑으로 밀어 넣어 언더훅을 되찾는다']::text[] where slug = 'flattened-half-guard' and owner_id is null and steps = array['상대가 언더훅 · 크로스페이스로 눌렀을 때 손을 상대 팔꿈치에 댄다','브릿지하며 어깨를 띄운다','팔꿈치를 가슴에 붙여 작게 돌려 언더훅을 되찾는다','옆으로 돌아 니 쉴드나 언더훅 하프']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 채 브릿지와 엉덩이 빼기로 오른쪽 옆으로 누워 공간을 만든다','내 오른팔로 상대 오른쪽 허벅지 안쪽을 깊게 감는다','머리를 상대 오른다리 밑으로 넣으며 몸을 상대 아래로 밀어 넣는다','상대 오른쪽 허벅지를 가슴에 꼭 붙여 딥 하프를 만든다']::text[] where slug = 'deep-half-entry-from-flattened' and owner_id is null and steps = array['상대 다리 아래로 머리를 넣는다','엉덩이를 빼며 상대 허벅지 아래로 깊게 들어간다','허벅지를 안는다','딥 하프']::text[];
update public.techniques set steps = array['내 오른다리가 감긴 하프 탑에서 상대가 내미는 오른쪽 손목을 내 왼손으로 잡아 바닥에 붙인다','내 오른팔을 상대 오른팔 위로 넘겨 팔 밑으로 넣고 내 왼쪽 손목을 잡는다','상대 오른팔 팔꿈치를 90도로 굽힌 채 내 몸 쪽으로 붙인다','상대 오른손을 상대 등 쪽으로 천천히 돌리고 탭하면 바로 놓는다']::text[] where slug = 'kimura-from-flattened-half-top' and owner_id is null and steps = array['상대가 밀어내는 손목을 잡는다','반대 팔을 팔 아래로 넣어 내 손목','상대 어깨를 바닥에 누르며 몸을 낮춘다','팔을 등 뒤로']::text[];
update public.techniques set steps = array['딥 하프에서 내 오른팔로 상대 오른쪽 허벅지를 안고 왼손으로 상대 왼쪽 발목을 잡는다','엉덩이를 상대 아래로 더 넣는다','상대 오른다리를 들어 올리며 돌아 상대 왼쪽으로 넘긴다','위로 올라온다']::text[] where slug = 'deep-half-sweep' and owner_id is null and steps = array['딥 하프에서 상대 허벅지를 안고 반대 손으로 발목을 잡는다','엉덩이를 상대 아래로 더 넣는다','상대 다리를 들어 올리며 돌아 옆으로 넘긴다','위로 올라온다']::text[];
update public.techniques set steps = array['딥 하프에서 내 오른팔로 감은 상대 오른다리를 계속 안는다','내 왼손을 상대 왼쪽 무릎 아래에 쟁반처럼 받친다','양 다리로 상대 오른다리를 밀어 펴며 받친 왼다리를 내 머리 위로 들어 올린다','상대가 상대 왼쪽으로 넘어가면 따라 일어나 위를 잡는다']::text[] where slug = 'waiter-sweep' and owner_id is null and steps = array['딥 하프에서 상대 다리를 양팔로 안아 들어 올린다(쟁반처럼)','발로 상대 반대 무릎을 밀어 벌린다','상대를 머리 위로 넘긴다','위로 올라온다']::text[];
update public.techniques set steps = array['딥 하프에서 내 오른팔로 상대 오른다리를 안은 채 머리를 바닥에 댄다','무릎으로 일어서며 상대 오른다리를 밀어 올린다','상대가 등으로 넘어진다','마운트']::text[] where slug = 'homer-simpson-sweep' and owner_id is null and steps = array['딥 하프에서 상대 다리를 안은 채 머리를 바닥에 댄다','무릎으로 일어서며 상대 다리를 밀어 올린다','상대가 등으로 넘어진다','마운트']::text[];
