update public.techniques set steps = array['상대가 내 오른다리로 딥 하프를 잡으면 내 오른팔로 내 다리를 안은 상대 오른팔을 위에서 감아(위저) 조인다','안긴 오른다리를 펴며 엉덩이를 낮춘다','상대 오른쪽 어깨를 바닥으로 누른다','오른다리를 빼 사이드']::text[] where slug = 'whizzer-from-deep-half' and owner_id is null and steps = array['상대 팔을 위에서 감아(위저) 조인다','안긴 다리를 펴며 엉덩이를 낮춘다','상대 어깨를 바닥으로 누른다','다리를 빼 사이드']::text[];
