update public.techniques set steps = array['상대 오른쪽 발목만 걸린 쿼터 가드에서 내 오른팔뚝은 상대 목 앞, 왼손은 상대 오른쪽 골반에 프레임을 만든다','엉덩이를 내 왼쪽으로 빼며 왼쪽 무릎을 상대 배 앞으로','내 오른다리를 상대 왼쪽 허리 위로 넘겨 두 다리를 감는다','하프나 클로즈드 가드']::text[] where slug = 'recover-full-guard-from-quarter' and owner_id is null and steps = array['상대 발목만 걸린 쿼터 가드에서 프레임을 만든다','엉덩이를 빼며 무릎을 상대 배 앞으로','다리를 상대 허리 위로 넘긴다','하프나 클로즈드 가드']::text[];
