update public.techniques set steps = array['내 오른쪽 발목이 걸리면 내 오른팔 크로스페이스로 상대를 눌러 둔다','걸린 오른발을 빼며 오른쪽 무릎을 상대 배 위로 미끄러뜨린다','오른쪽 무릎을 상대 왼쪽 바닥에 내려놓아 다리를 넘긴다','마운트']::text[] where slug = 'knee-through-from-quarter' and owner_id is null and steps = array['크로스페이스로 상대를 눌러 둔다','걸린 발을 빼며 무릎을 상대 배 위로 미끄러뜨린다','반대 다리를 넘긴다','마운트']::text[];
update public.techniques set steps = array['상대 오른쪽 발목을 건 쿼터 가드에서 내 왼팔로 언더훅을 잡고 오른쪽 옆으로 돈다','내 오른손으로 걸린 상대 오른쪽 발목을 당겨 중심을 뺏는다','상대 오른쪽 옆구리로 밀며 올라온다','사이드']::text[] where slug = 'sweep-from-quarter-guard' and owner_id is null and steps = array['언더훅을 잡고 옆으로 돈다','걸린 발목을 당겨 상대 중심을 뺏는다','앞으로 밀며 올라온다','사이드']::text[];
update public.techniques set steps = array['내 오른쪽 발목이 걸린 쿼터 탑에서 상대가 짚은 오른쪽 손목을 내 왼손으로 잡아 바닥에 붙인다','내 오른팔을 상대 오른팔 위로 넘겨 팔 밑으로 넣고 내 왼쪽 손목을 잡는다','상대 오른팔 팔꿈치를 90도로 굽혀 내 몸에 붙인다','상대 오른손을 등 쪽으로 천천히 돌리고 탭하면 바로 놓는다']::text[] where slug = 'kimura-from-quarter-guard' and owner_id is null and steps = array['상대가 프레임 짚은 손목을 잡는다','반대 팔을 아래로 넣어 내 손목','상대 어깨를 누른다','팔을 등 뒤로']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 하프에서 상대가 일어서면 상대 오른다리 밑으로 머리와 어깨를 넣는다','상대 오른다리를 내 오른쪽 어깨에 얹어 오른팔로 끌어안는다','내 오른발은 상대 왼쪽 무릎 뒤, 왼발은 상대 왼쪽 골반 앞에 건다','두 발을 X로 엇갈려 X 가드를 잡는다']::text[] where slug = 'half-guard-to-x-guard' and owner_id is null and steps = array['상대가 서면 감은 다리 아래로 머리를 넣는다','반대 다리로 상대 반대 허벅지를 건다','상대 다리를 어깨에 얹는다','X 가드']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 하프에서 상대가 패스하며 체중이 앞으로 쏠리면 상대 오른다리 아래로 몸을 뺀다','상대 오른쪽 엉덩이 뒤로 빠져나온다','터틀이나 등 뒤로','백 테이크']::text[] where slug = 'back-door-escape-from-half' and owner_id is null and steps = array['상대가 패스하며 체중이 앞으로 쏠리면 상대 다리 아래로 몸을 뺀다','상대 엉덩이 뒤로 빠져나온다','터틀이나 등 뒤로','백 테이크']::text[];
update public.techniques set steps = array['감은 상대 오른다리를 내 양 다리로 비틀어 상대 오른쪽 무릎을 바깥으로 돌린다','상대가 균형을 잃으면 내 왼팔 언더훅으로 상대 오른쪽 겨드랑이를 들어 민다','상대를 상대 왼쪽으로 넘긴다','마운트']::text[] where slug = 'knee-torque-sweep' and owner_id is null and steps = array['감은 상대 다리를 양 다리로 비틀어 무릎을 바깥으로 돌린다','상대가 균형을 잃으면 언더훅으로 민다','옆으로 넘긴다','마운트']::text[];
update public.techniques set steps = array['내 오른다리가 감긴 하프 탑에서 내 오른손으로 상대 오른쪽 깃을 깊게 잡고 상대가 언더훅을 잡으러 머리를 숙이기를 기다린다','내 오른팔로 상대 목을 감듯 돌려 상대 머리를 내 오른쪽 겨드랑이 아래로 넣는다','내 왼팔을 상대 등 뒤로 넘겨 바닥을 짚거나 깃을 받쳐 잡는다','내 오른쪽 어깨 쪽으로 굴러 내려가며 조인다']::text[] where slug = 'loop-choke-from-half-top' and owner_id is null and steps = array['상대 깃을 깊게 잡고 상대가 언더훅을 잡으러 머리를 숙이기를 기다린다','깃 잡은 팔로 상대 목을 감듯 돌려 머리를 내 겨드랑이 아래로 넣는다','반대 팔을 상대 등 뒤로 넘겨 바닥을 짚거나 깃을 받쳐 잡는다','몸을 돌려 옆으로 굴러 내려가며 조인다']::text[];
update public.techniques set steps = array['내 오른다리가 감기고 상대가 왼쪽 무릎 니 쉴드를 대면 내 오른팔을 상대 왼다리 위로 넘겨 오른다리 밑으로 넣어 바닥을 짚는다(엮기)','머리와 어깨를 낮춰 상대 무릎 두 개를 한데 모은다','스프롤로 엉덩이를 낮추며 감긴 오른다리를 뺀다','엮은 상대 다리를 돌아 사이드 컨트롤로 간다']::text[] where slug = 'leg-weave-pass' and owner_id is null and steps = array['한 팔을 상대 위쪽 다리(니 쉴드) 위로 넘겨 아래 다리 밑으로 넣어 바닥을 짚는다(엮기)','머리와 어깨를 낮춰 상대 무릎 두 개를 한데 모은다','스프롤로 엉덩이를 낮추며 감긴 다리를 뺀다','상대 다리를 돌아 사이드 컨트롤로 간다']::text[];
