update public.techniques set steps = array['내 오른다리가 감기면 상대 니 쉴드(왼다리) 위로 내 오른팔을 넘긴다','상대 오른다리 밑으로 오른손을 넣어 바닥을 짚는다','머리를 낮춰 상대 무릎을 모은다','레그 위브 패스로 잇는다']::text[] where slug = 'half-guard-to-leg-weave' and owner_id is null and steps = array['상대 니 쉴드 다리 위로 팔을 넘긴다','아래 다리 밑으로 손을 넣어 바닥을 짚는다','머리를 낮춰 상대 무릎을 모은다','레그 위브 패스로 잇는다']::text[];
update public.techniques set steps = array['내 오른다리가 감기면 내 오른팔로 크로스페이스를 걸어 상대 얼굴을 상대 오른쪽으로 돌린다','내 왼팔은 상대 오른쪽 겨드랑이 아래로 넣어 언더훅을 먼저 잡는다','가슴을 상대 가슴에 붙이고 엉덩이를 낮춰 등을 바닥에 눌러 둔다','내 왼발로 감긴 오른발을 밀거나 오른쪽 무릎을 바닥에 붙여 다리를 뺄 준비를 한다']::text[] where slug = 'half-guard-top-control' and owner_id is null and steps = array['감긴 다리 쪽 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','반대 팔은 상대 겨드랑이 아래로 넣어 언더훅을 먼저 잡는다','가슴을 상대 가슴에 붙이고 엉덩이를 낮춰 등을 바닥에 눌러 둔다','감긴 다리 발을 반대 발에 걸거나 무릎을 바닥에 붙여 다리를 뺄 준비를 한다']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 하프에서 내 왼팔로 언더훅을 잡고 오른쪽 옆으로 돌아 머리를 상대 오른쪽 겨드랑이 아래로 뺀다','무릎으로 일어나며 감았던 상대 오른다리를 양팔로 안는다','머리를 상대 오른쪽 옆구리에 붙이고 일어선다','안은 오른다리를 들어 올리며 밀어 넘어뜨리고 위로 올라온다']::text[] where slug = 'half-guard-to-single-leg' and owner_id is null and steps = array['하프가드에서 언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로 뺀다','무릎으로 일어나며 감았던 상대 다리를 양팔로 안는다','머리를 상대 옆구리에 붙이고 일어선다','안은 다리를 들어 올리며 밀어 넘어뜨리고 위로 올라온다']::text[];
update public.techniques set steps = array['상대가 크로스페이스를 걸려고 오른팔을 내 머리 쪽으로 뻗을 때 내 왼손으로 그 손목을 잡아 밀어낸다','내 왼쪽 무릎 니 쉴드로 거리를 만들고 감고 있던 오른다리를 빼낸다','내 왼다리를 상대 오른쪽 어깨 위로 넘겨 목 뒤에 걸고 왼발목을 내 오른쪽 오금에 잠근다','안에 남은 상대 왼팔을 내 왼쪽으로 넘기고 머리를 당기며 조인다']::text[] where slug = 'triangle-from-half-guard' and owner_id is null and steps = array['상대가 크로스페이스를 걸려고 팔을 내 머리 쪽으로 뻗을 때 그 손목을 잡아 밀어낸다','니 쉴드로 거리를 만들고 감은 아래 다리를 빼낸다','밀어낸 팔 쪽 어깨 위로 다리를 넘겨 상대 목 뒤에 걸고 발목을 반대 오금에 잠근다','안에 남은 팔을 반대쪽으로 넘기고 머리를 당기며 조인다']::text[];
update public.techniques set steps = array['상대 오른다리를 감은 하프에서 오른쪽 옆으로 돌아 눕고 내 오른팔을 상대 오른다리 바깥으로 넣어 허벅지를 안는다','내 왼손으로 상대 왼쪽 발목이나 바지 무릎을 잡는다','안은 오른다리를 들어 올리며 상대 왼쪽 발목을 당겨 중심을 뺏는다','상대가 뒤로 넘어지면 올라와 사이드나 하프 탑으로 간다']::text[] where slug = 'coyote-half-guard' and owner_id is null and steps = array['하프가드에서 옆으로 돌아 눕고 아래 팔을 상대 감긴 다리 바깥으로 넣어 허벅지를 안는다(다리 언더훅)','위쪽 손으로 상대 반대 발목이나 바지 무릎을 잡는다','안은 다리를 들어 올리며 상대 반대 발목을 당겨 중심을 뺏는다','상대가 뒤로 넘어지면 올라와 사이드나 하프 탑으로 간다']::text[];
update public.techniques set steps = array['딥 하프에서 내 오른팔로 상대 오른쪽 허벅지를 안은 채 왼손으로 상대 허리띠를 잡는다','상대 오른다리를 들어 올려 상대가 손을 짚고 몸을 돌리게 만든다','허리띠를 당기며 상대 오른다리 아래에서 등 뒤로 빠져나온다','가슴을 등에 붙이고 훅을 넣어 백 컨트롤로 간다']::text[] where slug = 'deep-half-to-back' and owner_id is null and steps = array['딥 하프에서 상대 허벅지를 안은 채 반대 손으로 허리띠를 잡는다','상대 다리를 들어 올려 상대가 손을 짚고 몸을 돌리게 만든다','허리띠를 당기며 상대 다리 아래에서 등 뒤로 빠져나온다','가슴을 등에 붙이고 훅을 넣어 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['내 오른다리가 감긴 하프 탑에서 크로스페이스 대신 내 오른팔을 상대 목 뒤로 넣어 감는다','상대 오른팔을 내 머리와 오른쪽 어깨로 밀어 상대 얼굴 옆에 붙이고 양손을 맞잡는다','머리를 바닥 쪽으로 낮추고 가슴으로 상대 오른쪽 어깨를 눌러 상대 팔이 목을 조이게 한다','감긴 오른다리를 빼지 못하면 그대로 조이고, 빼면 상대 왼쪽으로 돌아 조인다']::text[] where slug = 'arm-triangle-from-half-top' and owner_id is null and steps = array['하프 탑에서 크로스페이스 대신 상대 머리 아래로 팔을 넣어 목을 감는다','상대 팔을 내 어깨로 밀어 상대 얼굴 옆에 붙이고 양손을 맞잡는다','머리를 바닥 쪽으로 낮추고 가슴으로 어깨를 눌러 상대 팔이 목을 조이게 한다','감긴 다리를 빼지 못하면 그대로 조이고, 빼면 반대쪽으로 돌아 조인다']::text[];
update public.techniques set steps = array['허리를 펴고 머리를 세워 상대가 당기지 못하게 한다','내 오른손은 상대 명치를 누르고 왼손은 상대 허리띠나 오른쪽 골반 옆 바지를 잡아 팔을 편다','양 팔꿈치를 몸에 붙여 암바 · 기무라에 팔을 내주지 않는다','양 무릎을 넓게 벌려 베이스를 만든 뒤 가드 열기로 간다']::text[] where slug = 'posture-in-closed-guard' and owner_id is null and steps = array['허리를 펴고 머리를 세워 상대가 당기지 못하게 한다','한 손은 상대 명치를 누르고 반대 손은 허리띠나 골반 옆 바지를 잡아 팔을 편다','팔꿈치를 몸에 붙여 암바 · 기무라에 팔을 내주지 않는다','무릎을 넓게 벌려 베이스를 만든 뒤 가드 열기로 간다']::text[];
update public.techniques set steps = array['자세를 세운 채 내 오른쪽 무릎을 상대 꼬리뼈 아래에 쐐기처럼 넣고 왼다리는 옆으로 벌린다','뒤로 앉으며 상대 발목 잠금에 압력을 건다','내 왼손으로 상대 오른쪽 무릎을 눌러 다리를 연다 — 오른팔은 상대 왼쪽 허벅지를 계속 막는다(두 팔을 동시에 뒤로 빼지 않는다)','열리면 오른쪽 무릎을 상대 다리 사이로 넣어 니슬라이스로 잇는다']::text[] where slug = 'closed-guard-break-knee' and owner_id is null and steps = array['자세를 세운 채 한 무릎을 상대 꼬리뼈 아래에 쐐기처럼 넣는다','뒤로 앉으며 상대 발목 잠금에 압력을 건다','한 손으로 상대 무릎을 눌러 다리를 연다 — 반대 팔은 상대 허벅지를 계속 막는다(두 팔을 동시에 뒤로 빼지 않는다)','열리면 무릎을 다리 사이로 넣어 니슬라이스로 잇는다']::text[];
update public.techniques set steps = array['내 오른손은 상대 양쪽 깃(또는 가슴)을 모아 잡고 왼손은 허리띠를 잡아 자세를 세운다','오른발부터 세우고 왼발도 세워 일어선다','허리를 펴고 내 왼손으로 상대 오른쪽 무릎(허벅지 안쪽)을 밀어 내리며 뒤로 한 발 물러난다','다리가 풀리면 상대 오른다리를 내 허벅지 사이에 끼우거나 내 어깨에 걸어 컨트롤한다','바로 니슬라이스나 토레안도로 잇는다']::text[] where slug = 'standing-guard-break' and owner_id is null and steps = array['한 손은 상대 깃(또는 가슴)을 잡고 반대 손은 허리띠를 잡아 자세를 세운다','깃 잡은 쪽 발부터 세우고 반대 발도 세워 일어선다','허리를 펴고 허리띠 잡은 손으로 상대 무릎(허벅지 안쪽)을 밀어 내리며 뒤로 한 발 물러난다','다리가 풀리면 한 다리를 내 허벅지 사이에 끼우거나 어깨에 걸어 컨트롤한다','바로 니슬라이스나 토레안도로 잇는다']::text[];
update public.techniques set steps = array['내 오른쪽 무릎(정강이)을 상대 왼쪽 허벅지 안쪽 위에 올리고 왼발은 뒤에 세워 미는 힘을 만든다','내 오른팔로 상대 왼팔 언더훅(또는 깃)을 잡아 상대 왼쪽 어깨를 바닥에 붙인다','오른쪽 정강이를 바닥까지 미끄러뜨리며 왼다리를 끝까지 빼낸다 — 다리가 다 빠지기 전에 골반을 돌리지 않는다','빠지면 골반을 돌려 가슴을 붙이고 상대 왼쪽 사이드 컨트롤로']::text[] where slug = 'knee-slice-pass' and owner_id is null and steps = array['한 무릎(정강이)을 상대 허벅지 안쪽 위에 올리고 뒷발은 세워 미는 힘을 만든다','같은 쪽 팔로 언더훅(또는 깃)을 잡아 상대 어깨를 바닥에 붙인다','정강이를 바닥까지 미끄러뜨리며 다리를 끝까지 빼낸다 — 다리가 다 빠지기 전에 골반을 돌리지 않는다','빠지면 골반을 돌려 가슴을 붙이고 사이드 컨트롤로']::text[];
update public.techniques set steps = array['내 오른손은 상대 왼쪽 무릎 뒤(바지 끝), 왼손은 상대 오른쪽 무릎 뒤(바지 끝)를 잡는다','상대 두 무릎을 내 왼쪽 바닥으로 눌러 ''죽이고'' 그쪽으로 다리를 밀어 넘긴다','발을 내 오른쪽으로 옮겨 상대 왼쪽 옆으로 돌아 들어간다','어깨를 상대 가슴에 떨어뜨리고 머리를 컨트롤해 사이드 컨트롤로']::text[] where slug = 'toreando-pass' and owner_id is null and steps = array['양손으로 상대 무릎 뒤 또는 바지 끝을 잡는다','한쪽 무릎을 바닥으로 눌러 ''죽이고'' 반대쪽으로 다리를 밀어 넘긴다','발을 옆으로 옮겨 상대 옆으로 돌아 들어간다','어깨를 가슴에 떨어뜨리고 머리를 컨트롤해 사이드 컨트롤로']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 발목(또는 바지 끝)을 잡는다','상대 왼다리를 내 왼쪽 엉덩이 옆으로 끌어와 내 허벅지 사이에 끼운다','내 오른쪽 무릎을 상대 왼쪽 엉덩이 옆에 붙여 돌지 못하게 막는다','상체를 숙여 가슴을 누르며 상대 왼쪽 사이드 컨트롤로']::text[] where slug = 'leg-drag' and owner_id is null and steps = array['상대 한쪽 발목(또는 바지 끝)을 잡는다','그 다리를 내 반대쪽 엉덩이 옆으로 끌어와 허벅지 사이에 끼운다','같은 쪽 무릎을 상대 엉덩이 옆에 붙여 돌지 못하게 막는다','상체를 숙여 가슴을 누르며 사이드 컨트롤로']::text[];
update public.techniques set steps = array['양팔을 상대 양다리 아래로 넣고 손을 모아 허리띠나 깃을 잡는다','상대 엉덩이를 들어 내 허벅지 위에 얹는다(스택)','어깨로 다리를 상대 머리 쪽으로 눌러 공간을 뺏는다','상대 다리를 내 왼쪽으로 떨구며 내 오른쪽으로 돌아 상대 왼쪽 사이드 컨트롤로']::text[] where slug = 'double-under-pass' and owner_id is null and steps = array['양팔을 상대 다리 아래로 넣고 손을 모아 허리띠나 깃을 잡는다','상대 엉덩이를 들어 내 허벅지 위에 얹는다(스택)','어깨로 다리를 머리 쪽으로 눌러 공간을 뺏는다','한쪽으로 돌며 다리를 빼내고 사이드 컨트롤로']::text[];
update public.techniques set steps = array['내 오른팔은 상대 왼다리 아래(언더), 왼팔은 상대 오른다리 위(오버)로 감는다','머리를 상대 오른쪽 엉덩이 옆에 붙이고 가슴을 낮춘다','상대 오른다리를 내 다리 사이에 끼우고 발끝으로 서서 상대 왼다리를 내 오른쪽 어깨로 든다','다리를 바닥에 눌러 두고 돌아 나와 상대 오른쪽 사이드 컨트롤로']::text[] where slug = 'over-under-pass' and owner_id is null and steps = array['한 팔은 상대 다리 아래(언더), 반대 팔은 다리 위(오버)로 감는다','머리를 오버 쪽 상대 엉덩이 옆에 붙이고 가슴을 낮춘다','오버 쪽 다리를 내 다리 사이에 끼우고 발끝으로 서서 언더 쪽 다리를 어깨로 든다','다리를 바닥에 눌러 두고 돌아 나와 사이드 컨트롤로']::text[];
update public.techniques set steps = array['내 왼손은 상대 오른쪽 무릎, 오른손은 상대 왼쪽 깃(또는 어깨)을 잡아 거리를 잡는다','내 왼다리를 뒤로 길게 뻗으며 엉덩이를 바닥 쪽으로 낮춘다(스프롤)','상대 오른다리를 바닥으로 눌러 훅이 걸리지 않게 한다','뻗은 왼다리를 돌려 상대 오른쪽 옆으로 들어가 사이드 컨트롤로']::text[] where slug = 'long-step-pass' and owner_id is null and steps = array['상대 무릎과 반대 어깨(또는 깃)를 잡아 거리를 잡는다','한 다리를 뒤로 길게 뻗으며 엉덩이를 바닥 쪽으로 낮춘다(스프롤)','상대 다리를 바닥으로 눌러 훅이 걸리지 않게 한다','뻗은 다리를 돌려 상대 옆으로 들어가 사이드 컨트롤로']::text[];
update public.techniques set steps = array['내 오른다리가 감기면 내 왼팔로 상대 오른팔 언더훅을 먼저 잡고 상대 오른쪽 어깨를 바닥에 눌러 평평하게 만든다','내 오른팔로 크로스페이스를 걸어 상대 얼굴을 상대 오른쪽으로 돌린다','자유로운 내 왼다리로 상대 오른다리를 걸어 눌러 가드 회복을 막는다','감긴 오른다리를 빼내고 가슴을 붙여 사이드 컨트롤로']::text[] where slug = 'half-guard-pass' and owner_id is null and steps = array['언더훅을 먼저 잡고 상대 어깨를 바닥에 눌러 평평하게 만든다','반대 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','내 자유로운 다리로 상대 먼 쪽 다리를 걸어 눌러 가드 회복을 막는다','감긴 다리를 빼내고 가슴을 붙여 사이드 컨트롤로']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 하프가드로 감고 오른쪽 무릎으로 니 쉴드를 댔을 때','내 왼손으로 상대 오른쪽 무릎을 상대 왼쪽 바닥으로 눌러 내린다','상대 양 무릎이 상대 왼쪽으로 겹치게 내 엉덩이 체중으로 눌러 골반을 비튼다','내 오른쪽 팔꿈치를 바닥에 가깝게 두고 머리로 상대 가슴을 누른다','감긴 내 오른다리를 빼며 상대 오른쪽으로 돌아 사이드 컨트롤로']::text[] where slug = 'smash-pass' and owner_id is null and steps = array['하프가드 위에서 상대 니 쉴드 무릎을 바닥으로 누른다','상대 양 무릎이 겹치게 체중으로 눌러 골반을 비튼다','팔꿈치를 바닥에 가깝게 두고 머리로 상대 가슴을 누른다','감긴 다리를 빼며 돌아 사이드 컨트롤로']::text[];
update public.techniques set steps = array['양 훅 위로 그냥 걸어 들어가지 말고 상대 오른발 훅을 누를 훅으로 고른다','내 왼손으로 상대 오른발(내 왼쪽 허벅지 아래 훅)을 바닥으로 눌러 내린다','내 오른쪽 엉덩이를 뒤로 넓게 빼서 상대 왼발 훅이 들지 못하게 한다','상대 오른다리 위로 내려앉아 내 오른쪽 무릎으로 니슬라이스를 잇는다']::text[] where slug = 'butterfly-pass' and owner_id is null and steps = array['양쪽 훅에 똑같이 체중을 싣고 걸어 들어가지 않고 죽일 훅을 한쪽 고른다','한 손으로 상대 그쪽 훅(발)을 바닥으로 밀어 내린다','반대쪽 엉덩이를 뒤로 넓게 빼서 남은 훅이 들지 못하게 한다','하프가드로 내려앉아 니슬라이스로 잇는다']::text[];
update public.techniques set steps = array['상대 오픈 가드 앞에서 내 왼쪽 무릎은 바닥, 오른쪽 무릎은 세운다','세운 내 오른쪽 무릎을 상대 두 다리 사이에 둔다','허리를 펴고 내 왼손은 상대 오른쪽 무릎, 오른손은 상대 왼쪽 깃을 잡아 거리를 잡는다','상대 반응을 보고 니슬라이스나 헤드쿼터로 잇는다']::text[] where slug = 'combat-base' and owner_id is null and steps = array['상대 오픈 가드 앞에서 한 무릎은 바닥, 반대 무릎은 세운다','세운 무릎을 상대 다리 사이에 둔다','허리를 펴고 양손으로 상대 무릎이나 깃을 잡아 거리를 잡는다','상대 반응을 보고 니슬라이스나 헤드쿼터로 잇는다']::text[];
update public.techniques set steps = array['세운 내 오른쪽 무릎을 상대 오른쪽 허벅지 안쪽 위로 올려 정강이를 걸친다','내 오른손으로 상대 왼쪽 깃을 잡거나 오른팔로 상대 왼팔 언더훅을 잡아 상체를 누른다','내 오른쪽 정강이를 상대 오른쪽 허벅지 너머 바닥까지 미끄러뜨려 다리를 빼낸다','골반을 돌려 가슴을 붙이고 상대 오른쪽에서 사이드 컨트롤을 잡는다']::text[] where slug = 'knee-slide-from-combat-base' and owner_id is null and steps = array['세운 무릎을 상대 허벅지 안쪽 위로 올려 정강이를 걸친다','같은 쪽 팔로 깃이나 언더훅을 잡아 상대 상체를 누른다','정강이를 바닥까지 미끄러뜨리며 다리를 끝까지 빼낸다','골반을 돌려 가슴을 붙이고 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['가슴을 상대 가슴에 붙이고 엉덩이를 낮춰 공간을 없앤다','상대 양 다리를 상대 왼쪽(내 오른쪽)으로 몰아 내 무릎과 체중으로 누른다','상대가 힘을 쓰면 버티고 느슨해지면 내 다리를 상대 오른쪽으로 조금씩 빼낸다','다리가 빠지면 내 왼팔로 크로스페이스를 걸어 상대 오른쪽에서 사이드 컨트롤로 간다']::text[] where slug = 'pressure-pass' and owner_id is null and steps = array['가슴을 상대 가슴에 붙이고 엉덩이를 낮춰 공간을 없앤다','상대 양 다리를 한쪽으로 몰아 무릎과 체중으로 누른다','상대가 힘을 쓰면 버티고 느슨해지면 조금씩 다리를 빼낸다','다리가 빠지면 크로스페이스를 걸어 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['세운 내 오른발을 상대 다리 사이에 둔 채 바닥의 왼쪽 무릎을 들어 일어선다','상대 오른다리를 내 양 허벅지 사이에 끼우고 무릎으로 조인다','내 오른손으로 상대 왼쪽 무릎을 바닥으로 눌러 둔다','허리를 펴고 체중을 끼운 상대 오른다리에 실어 헤드쿼터를 만든다']::text[] where slug = 'combat-base-to-headquarters' and owner_id is null and steps = array['세운 발을 상대 다리 사이에 둔 채 뒷무릎을 들어 일어선다','상대 한 다리를 내 양 허벅지 사이에 끼우고 무릎으로 조인다','반대 손으로 상대 남은 다리 무릎을 바닥으로 눌러 둔다','허리를 펴고 체중을 끼운 다리에 실어 헤드쿼터를 만든다']::text[];
