update public.techniques set steps = array['내 오른쪽 팔뚝으로 상대 왼쪽 어깨나 목에 프레임을 만든다','엉덩이를 뒤로 빼며 내 오른쪽 무릎을 가슴 쪽으로 당긴다','내 오른발등을 상대 왼쪽 허벅지 안쪽에 걸어 훅을 넣는다','같은 방법으로 내 왼발도 상대 오른쪽 허벅지 안쪽에 훅으로 넣는다','상체를 세워 버터플라이 가드를 잡는다']::text[] where slug = 'butterfly-hook-recovery' and owner_id is null and steps = array['엉덩이를 뒤로 빼며 한 발을 상대 허벅지 안쪽으로 넣는다','넣은 훅으로 상대를 밀어 거리를 만든다','같은 방법으로 반대 발도 훅으로 넣는다','상체를 세워 버터플라이 가드를 잡는다']::text[];
update public.techniques set steps = array['상대가 앞으로 체중을 실어 스택할 때를 기다린다','내 오른손으로 상대 왼쪽 소매나 손목을 잡아 내 몸에 붙인다','내 오른쪽(잡은 상대 왼팔 쪽)으로 엉덩이를 돌리며 상대를 그 방향으로 굴린다','상대가 왼팔로 짚지 못해 넘어가면 따라 올라가 위를 잡는다']::text[] where slug = 'sweep-from-double-unders' and owner_id is null and steps = array['상대가 다리를 들어 스택할 때 한 손으로 상대 소매나 손목을 잡는다','반대 손으로 바닥을 짚거나 상대 허리띠를 잡고 엉덩이를 옆으로 돌린다','다리로 상대 어깨를 밀어 옆으로 넘긴다','넘어가는 쪽으로 따라 올라가 위를 잡는다']::text[];
update public.techniques set steps = array['상대 오른다리를 내 오른쪽 엉덩이 옆으로 끌어와 끼운다','내 왼쪽 무릎을 상대 오른쪽 엉덩이에 붙이고 오른다리는 뒤로 뻗어 베이스를 잡는다','상체를 눌러 상대가 못 돌게 한다','사이드 · 백 · 니 온 밸리 중 상대 반응에 맞게 잇는다']::text[] where slug = 'leg-drag-control' and owner_id is null and steps = array['상대 다리를 내 반대 엉덩이 옆에 끼운다','같은 쪽 무릎을 상대 엉덩이에 붙이고 반대 다리는 뒤로 뻗어 베이스를 잡는다','상체를 눌러 상대가 못 돌게 한다','사이드 · 백 · 니 온 밸리 중 상대 반응에 맞게 잇는다']::text[];
update public.techniques set steps = array['끼운 상대 오른다리를 눌러 둔 채 가슴을 상대 가슴에 붙인다','내 왼쪽 무릎을 바닥에 내려 상대 다리를 지나간다','머리 쪽 팔인 내 왼팔로 크로스페이스를 걸어 상대 얼굴을 상대 왼쪽으로 돌린다','내 오른팔로 상대 오른팔을 눌러 상대 오른쪽에서 사이드 컨트롤을 잡는다']::text[] where slug = 'leg-drag-pass-to-side-control' and owner_id is null and steps = array['끼운 다리를 눌러 둔 채 가슴을 상대 가슴에 붙인다','무릎을 바닥에 내려 상대 다리를 지나간다','머리 쪽 팔로 크로스페이스를 걸어 상대 얼굴을 돌린다','반대 팔로 상대 가까운 팔을 눌러 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대가 나를 등지고 상대 왼쪽으로 돌아 도망가면 내 오른손으로 허리띠(또는 허리)를 잡는다','내 왼쪽 무릎을 상대 등 뒤에 붙여 따라간다','내 오른발 훅을 상대 오른쪽 허벅지 안쪽에 먼저 넣고 왼발 훅도 넣는다','내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 상대 왼쪽 겨드랑이 아래로 시트벨트를 잡아 백 컨트롤로 간다']::text[] where slug = 'leg-drag-to-back-take' and owner_id is null and steps = array['상대가 나를 등지고 돌아 도망가면 허리띠(또는 허리)를 잡는다','끼운 다리 쪽 무릎을 상대 등 뒤에 붙여 따라간다','가까운 발부터 훅을 넣고 반대 훅도 넣는다','시트벨트를 잡아 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['끼운 상대 오른다리를 눌러 둔 채 내 오른쪽 무릎을 상대 배 위로 올린다','내 왼손은 상대 오른쪽 깃, 오른손은 상대 허리띠나 바지를 잡아 고정한다','내 왼다리는 펴서 발로 바닥을 밀며 베이스를 잡는다','오른쪽 무릎에 체중을 실어 상대 오른쪽에서 니 온 밸리를 만든다']::text[] where slug = 'leg-drag-to-knee-on-belly' and owner_id is null and steps = array['끼운 다리를 눌러 둔 채 무릎을 상대 배 위로 올린다','한 손은 깃, 반대 손은 허리띠나 바지를 잡아 고정한다','반대 다리는 펴서 발로 바닥을 밀며 베이스를 잡는다','무릎에 체중을 실어 니 온 밸리를 만든다']::text[];
update public.techniques set steps = array['내 왼팔 크로스페이스로 상대 상체를 눌러 둔다','내 오른손으로 상대 오른팔을 눌러 걸리지 않게 한다','내 오른쪽 무릎을 상대 배 위로 가로질러 상대 왼쪽 바닥까지 미끄러뜨린다','무릎이 상대 왼쪽 바닥에 닿고 내 왼발이 상대 오른쪽에 남으면 엉덩이를 낮춰 마운트를 잡는다']::text[] where slug = 'leg-drag-to-mount' and owner_id is null and steps = array['다리를 끼운 채 그쪽 무릎을 상대 배 위로 미끄러뜨린다','상대 팔이 걸리지 않게 반대 손으로 눌러 둔다','반대 다리를 상대 몸 너머로 넘긴다','엉덩이를 낮추고 무릎을 모아 마운트를 잡는다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 끌어 내 오른쪽에서 레그 드래그를 잡았을 때','내 오른쪽 팔뚝은 상대 어깨, 내 왼손은 상대 골반에 대어 프레임을 만든다','상대에게서 먼 내 왼쪽으로 엉덩이를 빼며(쉬림프) 공간을 만든다','끼인 내 오른다리를 빼내 오른발을 상대 골반에 댄다','내 왼다리도 상대 앞으로 가져와 가드를 되찾는다']::text[] where slug = 'frame-and-shrimp-from-leg-drag' and owner_id is null and steps = array['팔뚝으로 상대 골반과 어깨에 프레임을 만든다','끼인 다리 반대쪽으로 엉덩이를 빼며(쉬림프) 공간을 만든다','끼인 다리를 빼내 발을 상대 골반에 댄다','반대 다리도 상대 앞으로 가져와 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 끌어 내 오른쪽에 있을 때 내 왼다리로 상대 왼다리를 감는다','끼인 내 오른다리를 빼내 감은 왼다리 위에 겹쳐 하프가드로 잡는다','내 오른쪽 옆구리를 바닥에 대고 상대 쪽으로 돌아 눕는다','위쪽 내 왼쪽 무릎을 상대 배 앞에 세워 니 쉴드 하프가드를 만든다']::text[] where slug = 'half-guard-recovery-from-leg-drag' and owner_id is null and steps = array['자유로운 다리로 상대 가까운 다리를 감는다','끼인 다리를 빼내 감은 다리 위에 겹쳐 하프가드로 잡는다','상대 쪽으로 옆으로 돌아 눕는다','위쪽 무릎을 상대 배 앞에 세워 니 쉴드 하프가드를 만든다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 끌어 레그 드래그를 잡았을 때','끼인 내 오른다리를 빼내 상대 왼다리(앞다리) 바깥으로 감는다','내 오른손으로 상대 왼쪽 발목을 잡는다','내 왼발은 상대 오른쪽 골반이나 허벅지에 댄다','거리를 잡아 데라히바 가드로 돌아간다']::text[] where slug = 'leg-recovery-to-de-la-riva' and owner_id is null and steps = array['끼인 다리를 빼내 상대 앞다리 바깥으로 감는다','같은 쪽 손으로 상대 발목을 잡는다','반대 발은 상대 골반이나 반대 허벅지에 댄다','거리를 잡아 데라히바 가드로 돌아간다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 끌어 레그 드래그를 잡았을 때','내 오른쪽 팔뚝 프레임으로 상대를 밀며 엉덩이를 빼 공간을 만든다','끼인 내 오른쪽 무릎을 가슴 쪽으로 당겨 빼낸다','빼낸 내 오른다리를 상대 허리에 감는다','내 왼다리도 감아 양발을 걸어 잠가 클로즈드 가드를 되찾는다']::text[] where slug = 'leg-drag-escape-to-closed-guard' and owner_id is null and steps = array['프레임으로 상대를 밀며 엉덩이를 빼 공간을 만든다','빼낸 다리를 상대 허리 위로 올린다','반대 다리도 상대 허리에 감는다','양발을 걸어 잠가 클로즈드 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대가 내 쪽으로 돌며 오른팔로 언더훅을 잡으려 하면 그 팔 아래로 내 왼팔을 넣는다','내 왼팔을 상대 목 뒤 상대 왼쪽까지 깊게 꿰어 내 오른팔 이두를 잡는다','머리를 누르며 몸을 낮춰 상대 왼쪽 어깨를 바닥에 붙인다','가슴으로 상대 머리와 오른팔을 함께 눌러 다스 초크로 조인다']::text[] where slug = 'leg-drag-to-darce' and owner_id is null and steps = array['상대가 나를 향해 돌며 언더훅을 잡으려 하면 그 팔 아래로 내 팔을 넣는다','넣은 팔을 상대 목 반대편까지 깊게 꿰어 반대 팔 이두를 잡는다','머리를 누르며 몸을 낮춰 상대 어깨를 바닥에 붙인다','가슴으로 머리와 팔을 함께 눌러 다스 초크로 조인다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 엮어 레그 위브를 잡았을 때','엮인 내 오른쪽 무릎을 당기며 내 오른손 프레임으로 상대 왼쪽 어깨를 민다','자유로운 내 왼다리로 상대 오른다리를 감는다','내 오른쪽 옆구리를 바닥에 대고 상대 쪽으로 돌아 눕는다','내 왼팔 언더훅이나 왼쪽 무릎 니 쉴드를 잡아 하프가드를 만든다']::text[] where slug = 'leg-weave-escape-to-half-guard' and owner_id is null and steps = array['엮인 다리 무릎을 당기며 상대 어깨를 프레임으로 민다','자유로운 다리로 상대 다리를 감는다','상대 쪽으로 옆으로 돌아 눕는다','언더훅이나 니 쉴드를 잡아 하프가드를 만든다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 엮었을 때 내 왼팔로 상대 오른팔 언더훅을 잡는다','상대 어깨를 밀며 내 오른쪽 팔꿈치와 무릎으로 일어난다','엮인 내 오른다리를 풀며 내 오른손으로 상대 오른다리를 안는다','상대와 무릎을 맞댄 도그파이트 자세에서 스윕이나 백 테이크로 잇는다']::text[] where slug = 'leg-weave-to-dogfight' and owner_id is null and steps = array['언더훅을 잡고 상대 어깨를 밀며 무릎으로 일어난다','엮인 다리를 풀며 상대 다리를 안는다','상대와 무릎을 맞댄 도그파이트 자세를 만든다','상대 반응에 따라 스윕이나 백 테이크로 잇는다']::text[];
update public.techniques set steps = array['내 오른쪽 옆구리를 바닥에 대고 상대 쪽으로 돌아 누워 내 왼팔로 상대 오른팔 언더훅을 잡는다','내 오른손으로 상대 왼쪽 소매나 손목을 잡아 짚지 못하게 한다','상대가 앞으로 체중을 실을 때 브릿지하며 상대를 상대 왼쪽(막은 팔 쪽)으로 굴린다','넘어간 쪽으로 따라 올라가 위를 잡는다']::text[] where slug = 'sweep-from-leg-weave' and owner_id is null and steps = array['상대가 다리를 엮고 머리를 낮추면 그쪽 어깨를 손으로 민다','엉덩이를 들며 엮인 다리로 상대를 들어 올린다','상대가 뜨면 옆으로 넘긴다','넘어간 쪽으로 따라 올라가 위를 잡는다']::text[];
update public.techniques set steps = array['머리를 낮춰 상대 양 무릎을 모은 채 다리를 뒤로 뻗는다(스프롤)','내 오른팔로 엮은 상대 다리를 계속 누르며 감긴 내 오른다리를 빼낸다','다리가 빠지면 상대 머리 쪽, 상대 오른쪽으로 돌아 들어간다','내 왼팔로 크로스페이스를 걸어 상대 오른쪽에서 사이드 컨트롤로 마무리한다']::text[] where slug = 'complete-leg-weave-pass' and owner_id is null and steps = array['머리를 낮춰 상대 양 무릎을 모은 채 다리를 뒤로 뻗는다(스프롤)','엮은 팔로 다리를 계속 누르며 감긴 다리를 빼낸다','다리가 빠지면 상대 머리 쪽으로 돌아 들어간다','크로스페이스를 걸어 사이드 컨트롤로 마무리한다']::text[];
update public.techniques set steps = array['내 왼발로 상대 오른다리를 걸어 바닥에 눌러 둔다','상체는 내 왼팔 크로스페이스나 내 오른팔 상대 왼팔 언더훅으로 고정한다','걸어 둔 상대 오른다리 너머로 내 오른쪽 무릎을 넘겨 상대 오른쪽 엉덩이에 붙인다','가슴을 붙여 상대 오른쪽에서 사이드 컨트롤을 잡는다']::text[] where slug = 'leg-hook-pass' and owner_id is null and steps = array['내 다리로 상대 한 다리를 걸어 바닥에 눌러 둔다','상체는 크로스페이스나 언더훅으로 고정한다','걸어 둔 다리 너머로 무릎을 넘겨 상대 엉덩이에 붙인다','가슴을 붙여 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 왼다리를 걸어 누르고 내 오른쪽으로 넘어오려 할 때','걸린 내 왼다리를 빼며 엉덩이를 뒤로 뺀다','내 오른쪽 옆구리를 바닥에 대고 빼낸 왼쪽 무릎을 상대 배 앞에 세워 쉴드를 만든다','아래쪽 내 오른다리로 상대 왼다리를 감는다','니 쉴드 하프가드로 거리를 지킨다']::text[] where slug = 'shin-shield-recovery' and owner_id is null and steps = array['걸린 다리를 빼며 엉덩이를 뒤로 뺀다','빼낸 다리 무릎을 상대 배 앞에 세워 쉴드를 만든다','아래쪽 다리로 상대 다리를 감는다','니 쉴드 하프가드로 거리를 지킨다']::text[];
update public.techniques set steps = array['상대가 내 왼다리를 걸어 누르고 있을 때','걸린 내 왼쪽 무릎을 상대 쪽(내 오른쪽)으로 돌려 훅을 푼다','엉덩이를 빼며 내 왼다리를 빼낸다','빼낸 내 왼다리로 상대 왼다리를 감아 하프가드를 잡는다','내 왼팔로 언더훅을 노린다']::text[] where slug = 'escape-leg-hook' and owner_id is null and steps = array['걸린 다리 무릎을 상대 쪽으로 돌려 훅을 푼다','엉덩이를 빼며 다리를 빼낸다','빼낸 다리로 상대 다리를 감는다','하프가드를 잡고 언더훅을 노린다']::text[];
update public.techniques set steps = array['서서 내 왼손으로 상대 오른쪽 무릎, 오른손으로 상대 왼쪽 무릎 바지를 잡는다','내 왼발을 상대 다리 사이로 내 오른쪽 대각선 깊숙이 내딛는다(X자 스텝)','상대가 내 오른쪽을 막으면 내 왼쪽(상대 오른쪽)으로 빠르게 돌아 나간다','다리를 바닥에 눌러 두고 가슴을 떨어뜨려 상대 오른쪽에서 사이드 컨트롤을 잡는다']::text[] where slug = 'x-pass' and owner_id is null and steps = array['상대 한 다리를 손으로 잡아 몸 반대쪽으로 넘긴다','넘긴 다리 위로 무릎을 올려 눌러 둔다','반대 다리 쪽으로 몸을 돌려 지나간다','가슴을 떨어뜨려 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['내 오른손은 상대 깃을 모아 가슴을, 왼손은 상대 허리띠나 골반을 눌러 자세를 세운다','내 오른발을 먼저 세우고 왼발도 세워 일어선다','허리를 곧게 펴고 엉덩이를 앞으로 밀어 상대 다리 잠금을 푼다','가드가 열리면 바로 다리를 잡고 패스로 잇는다']::text[] where slug = 'stand-up-in-closed-guard' and owner_id is null and steps = array['상대 양 이두나 깃 · 허리띠를 잡는다','한 발을 세우고 반대 발도 세워 일어선다','허리를 펴고 엉덩이를 뒤로 빼 상대가 당기지 못하게 한다','가드가 열리면 바로 패스로 잇는다']::text[];
update public.techniques set steps = array['가드를 연 뒤 내 양팔을 상대 양 다리 아래로 넣는다','상대 엉덩이를 내 허벅지 위로 올린다','어깨로 상대 다리를 상대 머리 쪽으로 눌러 스택한다','상대 오른쪽(내 왼쪽)으로 돌아 다리를 빼내고 사이드 컨트롤로 간다']::text[] where slug = 'stack-pass-from-closed-guard' and owner_id is null and steps = array['가드를 연 뒤 양팔을 상대 다리 아래로 넣는다','상대 엉덩이를 내 허벅지 위로 올린다','어깨로 상대 다리를 머리 쪽으로 눌러 스택한다','한쪽으로 돌아 다리를 빼내고 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['내 오른쪽 무릎을 상대 엉덩이 아래 쐐기로 넣어 가드를 연다','열리면 내 오른쪽 무릎을 상대 오른쪽 허벅지 안쪽 위로 올린다','내 오른손으로 상대 왼쪽 깃을 잡거나 오른팔로 상대 왼팔 언더훅을 잡는다','내 오른쪽 정강이를 바닥으로 미끄러뜨려 상대 오른쪽에서 사이드 컨트롤로 간다']::text[] where slug = 'knee-slice-from-closed-guard' and owner_id is null and steps = array['무릎 쐐기로 가드를 연다','열리면 무릎을 상대 허벅지 안쪽 위로 올린다','같은 쪽 팔로 깃이나 언더훅을 잡는다','정강이를 바닥으로 미끄러뜨려 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['내 왼손으로 앉은 상대 오른쪽 어깨나 깃을 밀어 눕힌다','내 오른쪽 무릎을 상대 오른쪽 허벅지 위에 올린다','내 오른손으로 상대 왼쪽 깃을 잡거나 오른팔로 상대 왼팔 언더훅을 잡아 상체를 누른다','내 오른쪽 정강이를 미끄러뜨려 상대 오른쪽에서 사이드 컨트롤로 간다']::text[] where slug = 'knee-slice-from-seated-guard' and owner_id is null and steps = array['앉은 상대 어깨나 깃을 밀어 눕힌다','무릎을 상대 허벅지 위에 올린다','같은 쪽 팔로 깃이나 언더훅을 잡아 상체를 누른다','정강이를 미끄러뜨려 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['앉은 상대 허리를 양팔로 안고 내 양손을 상대 등 뒤에서 맞잡는다','가슴을 붙이고 밀어 눕힌다','상대 다리를 상대 왼쪽(내 오른쪽)으로 몰아 누른다','내 다리가 빠지면 상대 오른쪽에서 사이드 컨트롤로 간다']::text[] where slug = 'bodylock-pass-from-seated' and owner_id is null and steps = array['앉은 상대 허리를 양팔로 안는다','가슴을 붙이고 밀어 눕힌다','다리를 한쪽으로 몰아 누른다','다리가 빠지면 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['앉은 상대 양 무릎을 내 왼손은 상대 오른쪽, 오른손은 상대 왼쪽으로 잡는다','밀어 눕히며 상대 두 다리를 상대 왼쪽(내 오른쪽)으로 넘긴다','반대로 내 왼쪽(상대 오른쪽)으로 돌아 들어간다','가슴을 떨어뜨려 상대 오른쪽에서 사이드 컨트롤을 잡는다']::text[] where slug = 'bull-pass-from-seated' and owner_id is null and steps = array['앉은 상대 양 무릎을 잡는다','밀어 눕히며 한쪽으로 넘긴다','반대로 돌아 들어간다','가슴을 떨어뜨려 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대가 정강이를 내 오른쪽 정강이에 대고 내 오른쪽 발목을 잡았을 때','대인 내 오른다리를 뒤로 빼거나 바깥으로 돌린다','내 오른손으로 내 발목을 잡은 상대 왼손 그립을 끊는다','내 오른쪽 무릎을 상대 두 다리 사이로 넣어 상대 오른쪽 허벅지 위에 올린다','무릎을 올린 채 니슬라이스로 상대 오른쪽으로 패스한다']::text[] where slug = 'pass-shin-to-shin-guard' and owner_id is null and steps = array['상대 정강이에 대인 다리를 뒤로 빼거나 바깥으로 돌린다','상대 발목 그립을 끊는다','무릎을 상대 다리 위로 올린다','무릎을 올린 채 니슬라이스로 패스한다']::text[];
update public.techniques set steps = array['상대가 정강이를 내 오른쪽 정강이에 댔을 때 내 오른쪽 무릎을 상대 두 다리 사이로 밀어 넣는다','내 오른손으로 상대 왼쪽 깃을 잡아 상체를 누른다','내 오른쪽 무릎을 상대 오른쪽 허벅지 너머 바닥으로 미끄러뜨린다','다리가 빠지면 상대 오른쪽에서 사이드 컨트롤로 간다']::text[] where slug = 'knee-through-vs-shin-to-shin' and owner_id is null and steps = array['정강이에 대인 다리 무릎을 상대 다리 안쪽으로 밀어 넣는다','깃을 잡아 상체를 누른다','무릎을 바닥으로 미끄러뜨린다','다리가 빠지면 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['내 골반에 댄 상대 양발을 양손으로 잡아 상대 왼쪽(내 오른쪽)으로 넘긴다','상대 양 무릎을 상대 왼쪽으로 모아 눌러 둔다','내 발을 내 왼쪽으로 옮겨 상대 오른쪽으로 돌아 들어간다','가슴을 떨어뜨려 상대 오른쪽에서 사이드 컨트롤을 잡는다']::text[] where slug = 'pass-feet-on-hips-guard' and owner_id is null and steps = array['골반에 댄 상대 발을 손으로 잡아 옆으로 넘긴다','양 무릎을 한쪽으로 모아 눌러 둔다','발을 옮겨 상대 옆으로 돌아 들어간다','가슴을 떨어뜨려 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대가 나를 내 오른쪽으로 넘기는 스윕을 걸면 내 오른손을 바닥에 짚는다(포스트)','짚은 오른손 쪽으로 체중을 옮겨 버틴다','상대가 밀던 다리를 내 왼손으로 눌러 힘을 뺀다','상대가 다시 자세를 잡기 전에 바로 패스로 잇는다']::text[] where slug = 'counter-sweep' and owner_id is null and steps = array['상대가 스윕을 걸면 넘어가는 방향으로 손을 짚는다(포스트)','짚은 쪽으로 체중을 옮겨 버틴다','상대가 밀던 다리를 눌러 힘을 뺀다','상대가 다시 자세를 잡기 전에 바로 패스로 잇는다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 감고 오른쪽 무릎으로 니 쉴드를 대면 내 왼손으로 그 무릎을 눌러 둔다','내 왼다리를 뒤로 크게 돌려 상대 다리 쪽을 보고 앉는다','엉덩이를 바닥에 붙이고 상대 양다리를 내 다리 사이에 가둔다','상대가 돌아오지 못하게 양팔로 상대 허리나 다리를 감는다','내 오른다리를 빼내 상대 오른쪽에서 사이드 컨트롤이나 니 온 밸리로 잇는다']::text[] where slug = 'backstep-pass' and owner_id is null and steps = array['상대 니 쉴드 무릎을 손으로 눌러 두고 반대 다리를 뒤로 크게 돌려 앉는다','엉덩이를 바닥에 붙이고 상대 다리를 내 다리 사이에 가둔다','상대가 돌아오지 못하게 팔로 허리나 다리를 감는다','다리를 빼내 사이드 컨트롤이나 니 온 밸리로 잇는다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 감고 오른쪽 무릎으로 니 쉴드를 대면 내 왼손으로 그 무릎을 눌러 가슴에서 떼어 낸다','내 가슴을 상대 오른쪽 무릎 위에 붙여 쉴드를 눕힌다','내 왼팔로 상대 오른팔 아래 언더훅을 잡아 상대 오른쪽 어깨를 바닥에 붙인다','니슬라이스처럼 내 오른쪽 정강이로 상대 왼쪽 허벅지 위를 미끄러져 다리를 빼낸다','내 오른팔로 크로스페이스를 걸어 상대 왼쪽에서 사이드 컨트롤로 간다']::text[] where slug = 'knee-shield-pass' and owner_id is null and steps = array['상대 니 쉴드 무릎을 손으로 눌러 가슴에서 떼어 낸다','내 가슴을 상대 무릎 위에 붙여 쉴드를 눕힌다','언더훅을 잡아 상대 어깨를 바닥에 붙인다','니슬라이스처럼 정강이로 미끄러져 다리를 빼낸다','크로스페이스를 걸어 사이드 컨트롤로 간다']::text[];
update public.techniques set steps = array['상대 오른쪽으로 다리를 지나는 순간 엉덩이를 낮추고 가슴을 상대 가슴에 붙인다','내 왼팔로 크로스페이스를 걸어 상대 얼굴을 상대 왼쪽으로 돌린다','내 오른팔로 상대 오른팔을 눌러 언더훅과 프레임을 막는다','양 무릎을 상대 오른쪽 옆구리와 엉덩이에 붙여 쉬림프 공간을 없앤다','3초 이상 버틴 뒤 서브미션이나 마운트로 넘어간다']::text[] where slug = 'pass-finish-to-side-control' and owner_id is null and steps = array['다리를 지나는 순간 엉덩이를 낮추고 가슴을 상대 가슴에 붙인다','머리 쪽 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','반대 팔로 상대 가까운 팔을 눌러 언더훅과 프레임을 막는다','무릎을 상대 옆구리에 붙여 쉬림프 공간을 없앤다','3초 이상 버틴 뒤 서브미션이나 마운트로 넘어간다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 양 무릎을 상대 오른쪽 옆구리에 붙이고 가슴으로 상대 가슴을 누른다','내 왼팔을 상대 목 아래로 넣어 상대 왼쪽 겨드랑이를 잡고 어깨로 턱을 밀어 얼굴을 상대 왼쪽으로 돌린다','내 오른팔로 상대 오른팔을 옆구리에 눌러 언더훅을 못 잡게 한다','상대가 오른쪽 무릎을 넣으려 하면 골반을 바닥에 떨어뜨려 막는다']::text[] where slug = 'side-control-maintain' and owner_id is null and steps = array['무릎을 상대 옆구리에 붙이고 가슴으로 상대 가슴을 누른다','머리 쪽 팔은 상대 목 아래로 넣어 먼 겨드랑이를 잡고 어깨로 턱을 밀어 얼굴을 돌린다(크로스페이스)','반대 팔은 상대 가까운 팔을 옆구리에 눌러 언더훅을 못 잡게 한다','상대가 무릎을 넣으려 하면 골반을 바닥에 떨어뜨려 막는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 사이드를 잡았을 때 내 왼팔뚝은 상대 목, 오른팔뚝은 상대 골반에 대어 프레임을 만든다','먼저 브릿지로 상대를 띄우고 프레임으로 공간을 지킨다','엉덩이를 내 왼쪽으로 빼서(쉬림프) 공간을 만든다 — 한 번에 안 되면 두 번','내 오른쪽 무릎을 상대와 나 사이로 넣어 가드를 되찾거나 내 오른팔로 언더훅을 잡고 일어난다']::text[] where slug = 'side-control-escape' and owner_id is null and steps = array['팔뚝 뼈로 상대 목과 골반에 프레임을 만든다','먼저 브릿지로 상대를 띄우고 프레임으로 공간을 지킨다','엉덩이를 빼서(쉬림프) 공간을 만든다 — 한 번에 안 되면 두 번','무릎을 상대와 나 사이로 넣어 가드를 되찾거나 언더훅을 잡고 일어난다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼팔 크로스페이스로 상대 얼굴을 상대 왼쪽으로 돌려 둔다','내 오른쪽 무릎을 상대 배 위로 미끄러뜨린다','내 오른손으로 상대 오른쪽 무릎이나 허벅지를 눌러 다리로 걸지 못하게 한다','내 오른쪽 무릎이 상대 왼쪽 바닥에 닿으면 체중을 낮춰 마운트']::text[] where slug = 'side-to-mount' and owner_id is null and steps = array['크로스페이스로 상대 머리를 반대쪽으로 돌려 둔다','골반 쪽 무릎을 상대 배 위로 미끄러뜨린다','반대 손으로 상대 무릎이나 허벅지를 눌러 다리로 걸지 못하게 한다','무릎이 반대편 바닥에 닿으면 체중을 낮춰 마운트']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼손으로 상대 왼쪽 손목을 바닥에 눌러 팔꿈치가 90도로 굽혀지게 한다(손바닥 위로)','내 오른팔을 상대 왼쪽 팔꿈치 아래로 넣어 내 왼쪽 손목을 잡는다(8자 그립)','상대 왼쪽 팔꿈치는 어깨 높이 근처에 두고 손목은 바닥에 붙여 둔다','상대 왼손목을 상대 엉덩이 쪽으로 끌며 팔꿈치를 천천히 들어 어깨를 꺾는다']::text[] where slug = 'americana-side' and owner_id is null and steps = array['상대 손목을 바닥에 눌러 팔꿈치가 90도로 굽혀지게 한다(손바닥은 위로)','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 몸에 붙이고 손목은 바닥에 붙여 둔다','손목을 바닥에 붙인 채 상대 엉덩이 쪽으로 끌며 팔꿈치를 들어 어깨를 꺾는다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대가 왼손으로 내 목을 밀 때 내 왼손으로 그 손목을 잡는다','내 오른팔을 상대 왼팔 아래로 넣어 내 왼쪽 손목을 잡는다(8자 그립)','상대 머리 쪽으로 돌아 내 왼쪽 무릎을 상대 머리와 왼팔 사이에 넣는다','상대 왼쪽 팔꿈치를 내 몸에 붙인 채 상대 왼손을 등 뒤로 올려 어깨를 꺾는다']::text[] where slug = 'kimura-side' and owner_id is null and steps = array['상대가 내 목을 밀 때 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 머리 쪽으로 돌아 무릎을 상대 머리와 팔 사이에 넣는다','팔꿈치를 몸에 붙인 채 상대 손을 등 뒤로 올려 어깨를 꺾는다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대 오른팔을 얼굴 너머 상대 왼쪽으로 밀어 넘겨 목과 오른팔이 함께 잡히게 한다','내 오른팔을 상대 목 아래로 넣고 내 왼손과 맞잡는다(또는 내 왼팔 이두를 잡는다)','내 머리를 상대 오른팔 바깥쪽에 붙여 팔이 빠지지 않게 한다','상대 왼쪽으로 넘어가 다리를 벌리고 내 오른쪽 어깨로 눌러 조인다']::text[] where slug = 'arm-triangle' and owner_id is null and steps = array['상대 팔을 머리 너머로 넘겨 목과 팔이 함께 잡히게 한다','한 팔을 상대 목 아래로 넣고 반대 손과 맞잡는다(또는 이두를 잡는다)','머리를 상대 팔 바깥쪽에 붙여 팔이 빠지지 않게 한다','반대쪽으로 넘어가 다리를 벌리고 어깨를 눌러 조인다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대가 오른팔로 언더훅을 잡으려 넣을 때 그 팔 아래로 내 오른팔을 넣는다','내 오른팔을 상대 목 뒤를 지나 상대 왼쪽 겨드랑이까지 깊게 꿴다','내 오른손으로 내 왼팔 이두를 잡고 내 왼손은 상대 등이나 머리 뒤에 둔다','내 오른쪽 엉덩이를 바닥에 내리며 상대와 직각이 되게 돈다','팔꿈치를 모으며 어깨로 상대 머리를 눌러 천천히 조인다']::text[] where slug = 'darce-choke' and owner_id is null and steps = array['상대가 쉬림프하며 언더훅을 잡으려 할 때 그 팔 아래로 내 팔을 넣는다','넣은 팔을 상대 목 반대편까지 깊게 꿰어 넣는다','반대 팔의 이두를 잡아 8자(피겨 포)를 만들고 상대 머리를 아래로 누른다','먼 쪽 엉덩이로 눕듯 몸을 낮춰 가슴으로 머리와 팔을 함께 조인다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 사이드를 잡고 내 오른팔을 끼우면 브릿지로 상대 체중을 띄운다','내 오른쪽 팔꿈치를 내 몸 쪽으로 당기며 오른팔을 빼낸다','빼낸 오른팔로 상대 골반에, 왼팔로 상대 목에 프레임을 만든다','엉덩이를 내 왼쪽으로 빼(쉬림프) 공간을 만들고 하프나 가드를 되찾는다']::text[] where slug = 'arm-extraction' and owner_id is null and steps = array['상대가 내 가까운 팔을 끼우면 브릿지로 상대 체중을 띄운다','팔꿈치를 내 몸 쪽으로 당기며 팔을 빼낸다','빼낸 팔로 상대 목이나 골반에 프레임을 만든다','쉬림프로 공간을 만들어 하프나 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 사이드를 잡았을 때 내 오른쪽 팔꿈치를 상대 골반에 대어 프레임을 만든다','엉덩이를 내 왼쪽으로 빼며(쉬림프) 내 오른쪽 무릎을 상대와 나 사이로 넣는다','내 왼다리로 상대 오른다리를 감는다','하프가드로 잡거나 다리를 빼 풀 가드로 돌아간다']::text[] where slug = 'elbow-escape-to-guard' and owner_id is null and steps = array['팔꿈치를 상대 골반에 대어 프레임을 만든다','엉덩이를 빼며(쉬림프) 가까운 무릎을 상대와 나 사이로 넣는다','반대 다리로 상대 다리를 감는다','하프가드로 잡거나 다리를 빼 풀 가드로 돌아간다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 사이드를 잡았을 때 프레임으로 밀며 엉덩이를 내 왼쪽으로 빼 공간을 만든다','내 오른쪽(상대 쪽)으로 몸을 돌리며 내 왼쪽 무릎을 끌어와 바닥에 댄다','양 팔꿈치와 양 무릎을 붙여 터틀을 만들고 목을 지킨다','일어서거나 바로 가드로 돌아간다']::text[] where slug = 'roll-to-turtle' and owner_id is null and steps = array['프레임으로 밀며 엉덩이를 빼 공간을 만든다','상대 쪽으로 몸을 돌리며 먼 쪽 무릎을 끌어와 바닥에 댄다','팔꿈치와 무릎을 붙여 터틀을 만들고 목을 지킨다','일어서거나 바로 가드로 돌아간다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 크로스페이스 없이 사이드를 잡으면 내 오른팔을 상대 몸 아래로 빼며 내 오른쪽으로 돈다','다리를 상대 머리 쪽으로 돌리며 엉덩이를 뒤로 빼 몸을 빼낸다','무릎을 꿇고 일어나며 상대 등이나 옆구리를 잡는다','상대가 따라오면 터틀 탑이나 백으로 잇는다']::text[] where slug = 'ghost-escape' and owner_id is null and steps = array['상대가 크로스페이스를 안 걸었을 때 가까운 팔을 상대 몸 아래로 빼고 상대 쪽으로 몸을 돌린다','다리를 상대 머리 쪽으로 돌리며 엉덩이를 뒤로 빼 몸을 빼낸다','무릎을 꿇고 일어나며 상대 등이나 옆구리를 잡는다','상대가 따라오면 터틀 탑이나 백으로 잇는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 사이드를 잡았을 때 내 오른팔로 언더훅을 잡고 엉덩이를 내 왼쪽으로 뺀다','무릎으로 일어나며 내 왼다리를 몸 아래로 빼 상대 뒤쪽으로 뻗는다','상대 옆이나 뒤로 돌아선다','상대가 엎드리면 터틀 탑을 잡는다']::text[] where slug = 'sit-out-from-side-control' and owner_id is null and steps = array['언더훅을 잡고 상대 반대쪽으로 엉덩이를 뺀다','무릎으로 일어나며 다리를 상대 뒤로 뺀다','상대 옆이나 뒤로 돌아선다','상대가 엎드리면 터틀 탑을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 사이드를 잡았을 때 양팔로 상대 등이나 허리를 감아 안는다','내 오른발을 엉덩이 쪽으로 당겨 세우고 내 오른쪽(상대 쪽)으로 강하게 브릿지한다','상대가 손을 짚지 못하게 끌어안은 채 내 오른쪽으로 굴러 넘긴다','넘어간 뒤 상대 가드 안에서 탑을 잡는다']::text[] where slug = 'bridge-and-roll-from-side' and owner_id is null and steps = array['양팔로 상대 등이나 허리를 감아 안는다','상대 쪽 발을 당겨 세우고 상대 쪽으로 강하게 브릿지한다','상대가 손을 짚지 못하게 끌어안은 채 굴러 넘긴다','넘어간 뒤 상대 가드 안에서 탑을 잡는다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대 오른팔을 상대 머리 쪽으로 밀어 올리고 양손으로 그 손목을 잡는다','상대 오른팔을 내 가슴에 붙인 채 일어나 내 왼다리를 상대 머리 위로 넘긴다','상대 오른쪽 어깨 옆에 엉덩이를 붙여 앉으며 뒤로 눕는다','무릎을 모으고 상대 오른손 엄지가 위를 보게 한 뒤 엉덩이를 들어 편다']::text[] where slug = 'armbar-from-side-control' and owner_id is null and steps = array['상대 먼 쪽 팔을 언더훅으로 잡아 내 가슴에 붙인다','다리를 상대 머리 쪽으로 돌리며 한 다리를 상대 머리 위로 넘긴다','무릎을 모아 팔꿈치를 가두고 상대 엄지가 위를 보게 한다','엉덩이를 들어 팔을 편다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼팔로 상대 왼쪽 팔꿈치를 당겨 내 왼쪽 겨드랑이에 가둔다','내 왼다리(머리 쪽 다리)를 상대 머리 위로 넘긴다','상대 왼쪽 어깨 옆에 앉으며 뒤로 누워 무릎을 모은다','엉덩이를 들어 상대 왼팔을 편다']::text[] where slug = 'far-side-armbar' and owner_id is null and steps = array['상대 먼 쪽 팔꿈치를 당겨 내 겨드랑이에 가둔다','가까운(머리 쪽) 다리를 상대 머리 위로 넘긴다','앉으며 뒤로 누워 무릎을 모은다','엉덩이를 들어 팔을 편다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼팔을 상대 머리 아래로 넣는다','내 왼손으로 내 오른팔 소매 안쪽을 잡는다','내 오른손 손날을 상대 목 앞에 밀어 넣는다','가슴을 낮추며 양팔을 조여 마무리한다']::text[] where slug = 'ezekiel-choke-from-side' and owner_id is null and steps = array['한 팔을 상대 머리 아래로 넣는다','넣은 손으로 반대 팔 소매 안쪽을 잡는다','반대 손날을 상대 목 앞에 밀어 넣는다','가슴을 낮추며 양팔을 조여 마무리한다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대 오른팔을 상대 머리 위로 밀어 올려 치운다','내 왼팔로 상대 목을 감으며 상대 머리 쪽(남북)으로 돈다','내 왼쪽 어깨를 상대 턱 아래 목에 떨어뜨리고 양손을 맞잡는다','엉덩이를 바닥으로 낮추고 체중을 어깨에 실어 조인다']::text[] where slug = 'north-south-choke-from-side' and owner_id is null and steps = array['한 팔을 상대 목 아래로 넣으며 남북으로 돈다','어깨를 상대 목에 떨어뜨린다','손을 맞잡고 머리 쪽으로 더 내려간다','체중을 어깨로 실어 조인다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼손으로 상대 왼쪽 깃을 당겨 느슨하게 만든다','내 오른손을 상대 목 뒤로 넣어 상대 왼쪽 깃을 깊게 잡는다','내 왼팔뚝 날을 상대 목 앞에 가로로 댄다','엉덩이를 뒤로 빼 체중을 팔뚝에 실으며 깃을 당겨 조인다']::text[] where slug = 'breadcutter-choke' and owner_id is null and steps = array['상대 먼 쪽 깃을 잡는다','팔뚝을 상대 목 앞에 가로로 댄다','무릎을 상대 머리 옆에 붙이고 체중을 싣는다','깃을 당기며 팔뚝으로 조인다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼손으로 상대 오른쪽 깃을 잡고 상대가 나를 향해 돌거나 머리를 들게 만든다','내 왼쪽 팔꿈치를 상대 머리 위로 돌려 목을 감는다','내 오른팔을 상대 등 뒤(오른쪽 겨드랑이 아래)로 넣는다','상대 머리 쪽으로 몸을 돌리며 깃을 당겨 조인다']::text[] where slug = 'loop-choke-from-side' and owner_id is null and steps = array['상대 깃을 잡고 상대가 나를 향해 돌거나 머리를 들게 만든다','깃 잡은 팔의 팔꿈치를 상대 머리 위로 돌려 목을 감는다','반대 팔을 상대 등 뒤(겨드랑이)로 넣는다','상대 머리 쪽으로 몸을 돌리며 깃을 당겨 조인다']::text[];
update public.techniques set steps = array['상대가 오른팔로 길로틴을 잡으면 상대 왼쪽(조르는 팔 반대쪽)으로 넘어가 사이드를 잡는다','상대가 손을 놓지 않으면 가슴을 붙인 채 다리를 넓게 벌린다','내 오른쪽 어깨를 상대 목 왼쪽에 떨어뜨린다','엉덩이를 상대 머리 쪽으로 조금씩 옮기며 어깨로 눌러 조인다']::text[] where slug = 'von-flue-choke' and owner_id is null and steps = array['상대가 사이드 아래에서 내 머리를 길로틴으로 잡고 있을 때 어깨를 상대 목에 떨어뜨린다','양손을 맞잡아 상대 어깨 뒤로 감는다','머리를 바닥에 붙이고 가슴으로 상대 어깨와 목을 함께 누른다','체중을 상대 머리 쪽으로 실어 조인다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대 오른팔을 목 쪽에 가둔 채 내 왼다리를 상대 목 위로 넘긴다','내 왼쪽 발목을 내 오른쪽 무릎 뒤에 끼워 잠근다','상대 머리를 당기고 몸을 상대와 직각으로 맞춘다','무릎을 모으며 엉덩이를 상대 머리 쪽으로 밀어 조인다']::text[] where slug = 'triangle-choke-from-side' and owner_id is null and steps = array['상대 먼 팔을 당겨 가두고 가까운 다리를 상대 목 위로 넘긴다','반대 다리를 넘긴 다리 발목 위에 걸어 잠근다','상대 머리를 당기고 무릎을 모은다','허리를 조여 마무리한다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대 왼쪽 손목을 양손으로 잡아 내 가슴에 붙인다','내 왼다리를 상대 머리 위로 넘기며 무릎을 축으로 엎드린다','무릎을 모아 상대 왼팔을 내 허벅지 사이에 가둔다','손목을 가슴 쪽으로 당기며 엉덩이를 바닥 쪽으로 천천히 눌러 꺾는다']::text[] where slug = 'belly-down-armbar-from-side' and owner_id is null and steps = array['먼 팔을 가둔 채 다리를 상대 머리 위로 넘기며 엎드린다','무릎을 모아 팔을 가슴에 붙인다','엎드린 채 상대 엄지가 위를 보게 손목을 잡는다','엉덩이를 들어 팔을 편다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 상대 오른팔을 내 왼쪽 겨드랑이에 끼운다','엉덩이를 돌려 상대 머리 쪽을 보고 앉으며 내 오른팔로 상대 목 뒤를 감는다','내 오른다리는 앞으로, 왼다리는 뒤로 벌려 베이스를 잡는다','내 오른쪽 가슴으로 상대 가슴을 눌러 곁누르기를 만든다']::text[] where slug = 'side-control-to-kesa' and owner_id is null and steps = array['상대 가까운 팔을 내 겨드랑이에 끼운다','엉덩이를 돌려 앉으며 머리 쪽 팔로 상대 머리를 감는다','다리를 앞뒤로 벌려 베이스를 잡는다','가슴으로 상대 가슴을 눌러 곁누르기를 만든다']::text[];
update public.techniques set steps = array['상대 오른팔을 얼굴 너머 상대 왼쪽으로 넘긴 채 내 오른팔을 상대 목 아래로 넣는다','내 오른손으로 내 왼손을 맞잡거나 내 왼팔 이두를 잡는다','상대 왼쪽으로 넘어가 다리를 벌린다','내 오른쪽 어깨를 낮춰 조인다']::text[] where slug = 'arm-triangle-from-top' and owner_id is null and steps = array['상대 팔을 머리 너머로 넘긴 채 목 아래로 팔을 넣는다','손을 맞잡거나 이두를 잡는다','반대쪽으로 넘어가 다리를 벌린다','어깨를 낮춰 조인다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 오른손으로 상대 왼팔을 당겨 상대 얼굴을 가로지르게 둔다','내 왼팔을 상대 머리 뒤로 넣어 상대 왼쪽 손목을 잡는다','내 오른손으로 상대 왼쪽 팔꿈치를 눌러 팔이 빠지지 않게 한다','테크니컬 마운트나 백으로 잇는다']::text[] where slug = 'gift-wrap-from-side' and owner_id is null and steps = array['상대 먼 팔을 당겨 얼굴을 가로지르게 둔다','머리 쪽 팔을 상대 머리 뒤로 넣어 그 손목을 잡는다','반대 손은 상대 팔꿈치를 눌러 팔이 빠지지 않게 한다','테크니컬 마운트나 백으로 잇는다']::text[];
update public.techniques set steps = array['기프트 랩(상대 왼팔)을 유지한 채 상대를 오른쪽 옆으로 눕힌다','내 오른쪽 무릎을 상대 등 뒤, 머리 가까이 바닥에 댄다','내 왼발은 상대 배 앞 바닥에 디뎌 균형을 잡는다','가슴으로 상대 왼쪽 어깨를 누르고 백이나 암바로 잇는다']::text[] where slug = 'gift-wrap-to-technical-mount' and owner_id is null and steps = array['기프트 랩을 유지한 채 가까운 무릎을 상대 등 뒤로 넣는다','반대 발을 상대 머리 옆에 세운다','가슴으로 상대 어깨를 누른다','테크니컬 마운트를 잡고 백이나 암바로 잇는다']::text[];
update public.techniques set steps = array['기프트 랩으로 상대 왼팔을 가두면 상대 오른팔이 떠서 쉽게 잡힌다','상대 오른팔을 잡고 내 왼다리를 상대 머리 위로 넘긴다','무릎을 모아 상대 오른쪽 팔꿈치를 가둔다','엉덩이를 들어 상대 오른팔을 편다']::text[] where slug = 'armbar-on-free-arm' and owner_id is null and steps = array['기프트 랩으로 한 팔을 가두면 반대 팔이 떠서 쉽게 잡힌다','그 팔을 잡고 다리를 상대 머리 위로 넘긴다','무릎을 모아 팔꿈치를 가둔다','엉덩이를 들어 팔을 편다']::text[];
update public.techniques set steps = array['상대 왼쪽 손목을 잡은 내 왼손은 두고 내 오른팔을 상대 왼팔 아래로 넣어 내 왼쪽 손목을 잡는다','상대 왼쪽 팔꿈치를 내 몸에 붙인다','상대 왼손을 등 뒤로 돌린다','어깨가 꺾이면 마무리한다']::text[] where slug = 'kimura-from-gift-wrap' and owner_id is null and steps = array['기프트 랩 손목 그립을 기무라 그립(8자 그립)으로 바꾼다','상대 팔꿈치를 내 몸에 붙인다','상대 손을 등 뒤로 돌린다','어깨가 꺾이면 마무리한다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 내 왼팔을 기프트 랩으로 가두면 내 왼쪽 팔꿈치를 가슴 쪽으로 당겨 빼낸다','브릿지하며 엉덩이를 내 왼쪽으로 뺀다','자유로운 오른팔로 상대 골반에 프레임을 만든다','내 오른쪽 무릎을 넣어 가드를 되찾는다']::text[] where slug = 'hip-escape-from-gift-wrap' and owner_id is null and steps = array['가둬진 팔의 팔꿈치를 가슴 쪽으로 당겨 빼낸다','브릿지하며 엉덩이를 뺀다','자유로운 팔로 상대 골반에 프레임을 만든다','무릎을 넣어 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼손은 상대 오른쪽 깃, 내 오른손은 상대 허리띠나 바지를 잡는다','그립을 당겨 올리며 내 오른쪽 무릎을 상대 배 위로 올린다','내 왼다리는 펴서 왼발로 바닥을 밀며 베이스를 잡는다','오른쪽 무릎에 체중을 실어 상대가 돌지 못하게 한다','상대가 밀면 마운트나 다시 사이드로 바꾼다']::text[] where slug = 'side-to-knee-on-belly' and owner_id is null and steps = array['한 손은 상대 깃, 반대 손은 허리띠나 바지를 잡는다','그립을 당겨 올리며 골반 쪽 무릎을 상대 배 위로 올린다','반대 다리는 펴서 발로 바닥을 밀며 베이스를 잡는다','무릎에 체중을 실어 상대가 돌지 못하게 한다','상대가 밀면 마운트나 다시 사이드로 바꾼다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼팔은 상대 왼쪽 겨드랑이 아래로, 내 오른팔은 상대 오른쪽 골반으로 옮긴다','상대 손이 내 골반을 막으면 그 위로 체중을 떨어뜨려 눌러 둔다','다리를 상대 머리 쪽으로 걸어 돌며 가슴으로 상대 가슴을 누른다','엉덩이를 너무 상대 가슴 위로 올리지 않고 체중을 뒤로 둔 채 기무라 · 초크를 노린다']::text[] where slug = 'north-south' and owner_id is null and steps = array['사이드에서 머리 쪽 팔을 상대 겨드랑이 아래로, 반대 팔은 상대 골반으로 옮긴다','상대 손이 내 골반을 막으면 그 위로 체중을 떨어뜨려 눌러 둔다','다리를 상대 머리 쪽으로 걸어 돌며 가슴으로 상대 가슴을 누른다','엉덩이를 너무 상대 가슴 위로 올리지 않고 체중을 뒤로 둔 채 기무라 · 초크를 노린다']::text[];
update public.techniques set steps = array['상대가 내 머리 쪽에서 남북을 잡았을 때 양손을 상대 골반에 대어 프레임을 만든다','브릿지하며 몸을 내 오른쪽으로 돌린다','양 무릎을 끌어와 상대와 나 사이로 넣는다','하프가드나 가드를 되찾는다']::text[] where slug = 'north-south-escape' and owner_id is null and steps = array['양손을 상대 골반에 대어 프레임을 만든다','브릿지하며 몸을 한쪽으로 돌린다','무릎을 상대와 나 사이로 넣는다','하프가드나 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대가 내 머리 쪽에서 남북을 잡았을 때 브릿지로 상대를 띄운다','내 오른쪽으로 몸을 뒤집으며 양 무릎을 끌어온다','양 무릎과 양 팔꿈치를 붙여 터틀을 만든다','일어서거나 가드로 돌아간다']::text[] where slug = 'bridge-and-turn-to-turtle-ns' and owner_id is null and steps = array['브릿지로 상대를 띄운다','한쪽으로 몸을 뒤집으며 무릎을 끌어온다','무릎과 팔꿈치를 붙여 터틀을 만든다','일어서거나 가드로 돌아간다']::text[];
update public.techniques set steps = array['남북에서 상대 오른팔이 뜨면 내 오른손으로 그 손목을 잡는다','내 왼팔을 상대 오른팔 아래로 넣어 내 오른쪽 손목을 잡는다(8자 그립)','내 오른쪽 무릎을 상대 머리 오른쪽 옆으로 옮겨 상대가 따라 돌지 못하게 한다','상대 오른쪽 팔꿈치를 내 몸에 붙이고 상대 오른손을 등 뒤로 돌려 꺾는다']::text[] where slug = 'north-south-to-kimura' and owner_id is null and steps = array['남북에서 상대 팔이 뜨면 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','무릎을 상대 머리 옆으로 옮겨 상대가 따라 돌지 못하게 한다','팔꿈치를 몸에 붙이고 상대 손을 등 뒤로 돌려 꺾는다']::text[];
update public.techniques set steps = array['남북에서 상대 오른팔을 상대 머리 너머 왼쪽으로 밀어 올린다','내 오른팔을 상대 목 아래로 넣고 내 왼손과 맞잡는다','상대 왼쪽 사이드로 돌아가며 상대 오른팔을 목과 함께 가둔다','가슴을 낮춰 내 오른쪽 어깨로 조인다']::text[] where slug = 'arm-triangle-setup-ns' and owner_id is null and steps = array['상대 팔을 머리 너머로 밀어 올린다','팔을 목 아래로 넣고 손을 맞잡는다','사이드로 돌아가며 상대 팔을 가둔다','가슴을 낮춰 어깨로 조인다']::text[];
update public.techniques set steps = array['남북에서 상대 오른팔을 양팔로 감아 내 가슴에 붙인다','상대 오른쪽 어깨 옆으로 엉덩이를 돌려 상대와 직각이 되게 한다','내 왼다리를 상대 얼굴 위로 넘기며 앉아 뒤로 눕는다','무릎을 모으고 상대 오른손 엄지가 위를 보게 한 뒤 엉덩이를 들어 편다']::text[] where slug = 'armbar-from-north-south' and owner_id is null and steps = array['상대 팔을 내 가슴에 가둔다','한 다리를 상대 머리 위로 넘기며 앉는다','무릎을 모아 팔꿈치를 가둔다','엉덩이를 들어 팔을 편다']::text[];
update public.techniques set steps = array['남북에서 내 오른손으로 상대 오른쪽 손목을 바닥에 누른다','상대 오른팔 아래로 내 왼팔을 넣어 내 오른쪽 손목을 잡는다','어깨를 눌러 상대가 돌지 못하게 고정한다','상대 오른쪽 팔꿈치를 들어 꺾는다']::text[] where slug = 'americana-from-north-south' and owner_id is null and steps = array['상대 손목을 바닥에 누른다','팔 아래로 반대 팔을 넣어 내 손목을 잡는다','어깨를 눌러 상대가 돌지 못하게 고정한다','팔꿈치를 들어 꺾는다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 사이드: 내 왼손은 상대 오른쪽 깃, 내 오른손은 상대 바지(또는 허리띠)를 잡는다','내 오른쪽 무릎을 상대 배 위에 올리고 오른발 끝은 바닥에 닿지 않게 한다','내 왼다리는 펴서 왼발로 바닥을 밀며 중심을 잡는다','깃을 위로 당기고 무릎으로 눌러 압박하며 암바 · 초크 · 마운트를 노린다']::text[] where slug = 'knee-on-belly' and owner_id is null and steps = array['깃과 바지(또는 허리띠)를 잡는다','가까운 쪽 무릎을 상대 배 위에 올리고 발끝은 바닥에 닿지 않게 한다','반대 다리는 펴서 발로 바닥을 밀며 중심을 잡는다','깃을 위로 당기고 무릎으로 눌러 압박하며 암바 · 초크 · 마운트를 노린다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 니 온 밸리를 잡으면 무릎을 손으로 치우지 말고 양 팔뚝으로 상대 오른쪽 무릎과 골반에 프레임을 만든다','내 오른쪽(상대 쪽)으로 돌며 엉덩이를 내 왼쪽으로 빼서 무릎을 떨어뜨린다','내 오른쪽 무릎을 상대와 나 사이로 넣는다','가드로 돌아오거나 터틀로 돌아 일어난다']::text[] where slug = 'knee-on-belly-escape' and owner_id is null and steps = array['상대 무릎을 손으로 치우려 하지 말고 팔뚝으로 무릎과 골반에 프레임을 만든다','상대 쪽으로 돌며 엉덩이를 빼서 무릎을 떨어뜨린다','가까운 무릎을 상대와 나 사이로 넣는다','가드로 돌아오거나 터틀로 돌아 일어난다']::text[];
update public.techniques set steps = array['내 왼손으로 깃을 당기고 내 오른손으로 허리띠나 바지를 잡아 상대가 엉덩이를 빼지 못하게 한다','배에 올린 내 오른쪽 무릎을 상대 왼쪽 옆구리까지 미끄러뜨려 넘긴다','바닥에 디뎠던 왼다리의 무릎도 바닥에 내려 양 무릎으로 상대 몸통을 조인다','엉덩이를 낮추고 손은 바닥이나 깃을 잡아 마운트를 굳힌다']::text[] where slug = 'kob-to-mount' and owner_id is null and steps = array['깃을 당기고 반대 손으로 허리띠나 바지를 잡아 상대가 엉덩이를 빼지 못하게 한다','배에 올린 무릎을 상대 반대쪽 옆구리까지 미끄러뜨려 넘긴다','바닥에 디뎠던 다리의 무릎도 바닥에 내려 양 무릎으로 상대 몸통을 조인다','엉덩이를 낮추고 손은 바닥이나 깃을 잡아 마운트를 굳힌다']::text[];
update public.techniques set steps = array['배에 올린 내 오른쪽 무릎을 상대 오른쪽 옆구리 쪽 바닥으로 내리며 가슴을 상대 가슴에 붙인다','내 왼팔로 크로스페이스를 걸어 상대 얼굴을 상대 왼쪽으로 돌린다','내 오른팔은 상대 오른팔 아래로 넣어 언더훅을 잡거나 상대 오른쪽 엉덩이를 막는다','양 무릎을 상대 오른쪽 옆구리와 엉덩이에 붙여 공간을 없앤다']::text[] where slug = 'kob-to-side-control' and owner_id is null and steps = array['올린 무릎을 상대 옆구리 쪽 바닥으로 내리며 가슴을 상대 가슴에 붙인다','머리 쪽 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','반대 팔은 상대 먼 팔 아래로 넣어 언더훅을 잡거나 엉덩이를 막는다','무릎을 상대 옆구리와 엉덩이에 붙여 공간을 없앤다']::text[];
update public.techniques set steps = array['상대 오른쪽 니 온 밸리에서 상대가 왼팔로 내 오른쪽 무릎을 밀면 그 팔을 양팔로 가슴에 안는다','바닥에 디뎠던 내 왼발을 상대 머리 너머로 넘겨 상대 왼쪽에 딛는다','내 오른쪽 무릎은 상대 가슴 위에 두고 상대 왼쪽 어깨 옆에 엉덩이를 붙여 앉는다','무릎을 모으고 상대 왼손 엄지가 위로 오게 잡은 뒤 엉덩이를 들어 팔꿈치를 편다']::text[] where slug = 'far-side-armbar-from-kob' and owner_id is null and steps = array['상대가 먼 쪽 팔로 내 무릎을 밀면 그 팔을 양팔로 가슴에 안는다','바닥에 디뎠던 발을 상대 머리 너머로 넘겨 반대쪽에 딛는다','배에 올렸던 무릎은 상대 가슴 위에 그대로 두고 상대 어깨 옆에 엉덩이를 붙여 앉는다','무릎을 모으고 상대 엄지가 위로 오게 잡은 뒤 엉덩이를 들어 팔꿈치를 편다']::text[];
update public.techniques set steps = array['내 왼손 네 손가락을 상대 오른쪽 깃 안쪽에 깊게 넣고(손바닥 위) 내 오른손은 바로 아래 엄지를 깃 안에 넣는다','손 위치를 바꾸지 않은 채 오른쪽 무릎을 내리며 상대 머리 쪽으로 돈다','남북 자세까지 돌며 가슴을 낮추고 양 팔꿈치를 모은다','팔뚝으로 목을 가위처럼 조여 마무리한다']::text[] where slug = 'baseball-bat-choke' and owner_id is null and steps = array['한 손은 네 손가락을 상대 깃 안쪽에 넣어 깊게 잡고(손바닥이 위) 반대 손은 바로 아래에 엄지를 깃 안에 넣어 야구 방망이 쥐듯 잡는다','손 위치를 바꾸지 않은 채 무릎을 내리며 상대 머리 쪽으로 돈다','남북 자세까지 돌며 가슴을 낮추고 양 팔꿈치를 모은다','팔뚝으로 목을 가위처럼 조여 마무리한다']::text[];
update public.techniques set steps = array['상대 오른쪽 니 온 밸리에서 깃을 잡은 내 왼손을 상대 오른쪽 깃 안쪽 깊숙이 밀어 넣는다(손바닥 위)','내 오른손을 왼손 아래로 교차해 상대 왼쪽 깃을 깊게 잡는다','오른쪽 무릎으로 배를 계속 누르며 머리를 낮추고 팔꿈치를 몸 쪽으로 당긴다','손목을 안으로 비틀어 양 팔뚝으로 목을 조인다']::text[] where slug = 'cross-collar-choke-from-kob' and owner_id is null and steps = array['니 온 밸리에서 깃을 잡은 손을 상대 깃 안쪽 깊숙이 밀어 넣는다(손바닥 위)','반대 손을 첫 손 아래로 교차해 반대쪽 깃을 깊게 잡는다','무릎으로 배를 계속 누르며 머리를 낮추고 팔꿈치를 몸 쪽으로 당긴다','손목을 안으로 비틀어 양 팔뚝으로 목을 조인다']::text[];
update public.techniques set steps = array['상대 오른쪽 니 온 밸리에서 상대가 오른손으로 내 오른쪽 무릎을 밀면 그 팔을 양팔로 안아 가슴에 붙인다','바닥에 디뎠던 내 왼발을 상대 머리 너머로 넘겨 상대 왼쪽 귀 옆에 딛는다','엉덩이를 상대 오른쪽 어깨에 바짝 붙여 앉으며 뒤로 눕는다','무릎을 모으고 상대 오른손 엄지가 위로 오게 한 뒤 엉덩이를 들어 팔꿈치를 편다']::text[] where slug = 'armbar-from-kob' and owner_id is null and steps = array['상대가 가까운 쪽 손으로 내 무릎을 밀면 그 팔을 양팔로 안아 가슴에 붙인다','바닥에 디뎠던 발을 상대 머리 너머로 넘겨 반대쪽 귀 옆에 딛는다','엉덩이를 상대 어깨에 바짝 붙여 앉으며 뒤로 눕는다','무릎을 모으고 상대 엄지가 위로 오게 한 뒤 엉덩이를 들어 팔꿈치를 편다']::text[];
update public.techniques set steps = array['상대 오른쪽 니 온 밸리에서 상대가 오른손으로 내 무릎을 밀면 내 오른손으로 그 손목을 잡아 바닥 쪽으로 누른다','내 왼팔을 상대 오른팔 아래로 넣어 내 오른쪽 손목을 잡는다(8자 그립)','내 오른쪽 무릎을 상대 오른쪽 옆구리 쪽 바닥에 내리고 가슴으로 상대 오른쪽 어깨를 눌러 고정한다','상대 오른쪽 팔꿈치를 몸에 붙인 채 상대 오른손을 등 뒤로 돌려 꺾는다']::text[] where slug = 'kimura-from-kob' and owner_id is null and steps = array['상대가 가까운 쪽 손으로 내 무릎을 밀면 그 손목을 잡아 바닥 쪽으로 누른다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','무릎을 상대 옆구리 쪽 바닥에 내리고 가슴으로 어깨를 눌러 고정한다','상대 팔꿈치를 몸에 붙인 채 손을 등 뒤로 돌려 꺾는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 니 온 밸리를 잡으면 양 팔뚝으로 상대 오른쪽 무릎과 골반에 프레임(손바닥으로 밀지 않기)','팔꿈치를 몸에 붙인 채 내 오른쪽(상대 쪽)으로 돌며 엉덩이를 내 왼쪽으로 빼(쉬림프) 무릎을 떨어뜨린다','내 오른쪽 무릎을 상대 몸 앞으로 넣어 정강이로 막는다','내 왼다리도 넣어 하프가드나 오픈 가드로 돌아온다']::text[] where slug = 'push-knee-and-reguard' and owner_id is null and steps = array['팔꿈치를 몸에 붙이고 팔뚝으로 상대 무릎과 골반에 프레임을 만든다(손바닥으로 밀지 않는다)','상대 쪽으로 몸을 돌리며 엉덩이를 뒤로 빼(쉬림프) 무릎을 떨어뜨린다','가까운 쪽 무릎을 상대 몸 앞으로 넣어 정강이로 막는다','다른 다리도 넣어 하프가드나 오픈 가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 니 온 밸리를 잡으면 내 오른 팔꿈치를 붙이고 오른 팔뚝으로 무릎을 막는다','엉덩이를 내 왼쪽으로 빼 무릎 압박을 줄인다','내 오른쪽(상대 쪽)으로 몸을 돌려 양 무릎을 바닥에 대고 엎드린다(터틀)','양 팔꿈치와 무릎을 붙이고 턱을 당겨 목과 겨드랑이 공간을 막는다','내 앞에 온 상대 다리를 양팔로 잡아 싱글 레그로 일어서거나 가드로 돌아온다']::text[] where slug = 'turn-to-turtle-from-kob' and owner_id is null and steps = array['팔꿈치를 붙이고 팔뚝으로 무릎을 막으며 엉덩이를 빼 무릎 압박을 줄인다','상대 쪽으로 몸을 돌려 무릎을 바닥에 대고 엎드린다(터틀)','팔꿈치와 무릎을 붙이고 턱을 당겨 목과 겨드랑이 공간을 막는다','상대 다리를 잡아 싱글 레그로 일어서거나 가드로 돌아온다']::text[];
update public.techniques set steps = array['상대 오른쪽에서 내 오른 무릎을 배에 올리고 오른손은 상대 왼쪽 깃, 왼손은 허리띠(또는 바지)를 잡는다','바닥에 디딘 내 왼발로 바닥을 차며 왼다리를 상대 다리 너머 상대 왼쪽으로 넘긴다','내 오른 무릎을 배에서 들어 올리며 넘긴 왼다리의 무릎을 상대 배에 새로 올린다','상대 왼쪽에서 왼 무릎 니 온 밸리로 자리 잡고 상대가 돌아서면 백이나 암바를 노린다']::text[] where slug = 'kob-switch-sides' and owner_id is null and steps = array['깃과 허리띠(또는 바지)를 잡은 채 상대 배에 올린 무릎에 체중을 싣는다','바닥에 디딘 발로 바닥을 차며 그 다리를 상대 다리 너머 반대쪽으로 넘긴다','배에 있던 무릎을 들어 올리며 넘긴 다리의 무릎을 상대 배에 새로 올린다','반대쪽 니 온 밸리로 자리 잡고 상대가 돌아서면 백이나 암바를 노린다']::text[];
update public.techniques set steps = array['상대 오른쪽 니 온 밸리에서 상대가 왼쪽으로 돌아 등을 보이면 무릎을 내리고 상대 등에 가슴을 붙인다','내 오른팔은 상대 오른 어깨 위로, 왼팔은 상대 왼 겨드랑이 아래로 넣어 맞잡는다(시트벨트)','내 오른발 훅부터 상대 오른 허벅지 안쪽에 넣는다','내 왼발 훅을 상대 왼 허벅지 안쪽에 넣고 내 왼쪽으로 함께 눕혀 백 컨트롤을 완성한다']::text[] where slug = 'kob-to-back-take' and owner_id is null and steps = array['니 온 밸리 압박에 상대가 나를 등지고 돌아서면 무릎을 내리고 상대 등에 가슴을 붙인다','상대 팔 아래로 팔을 넣어 시트벨트를 잡는다','가까운 쪽 훅부터 상대 허벅지 안쪽에 넣는다','반대 훅을 넣고 상대를 옆으로 눕혀 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대 오른쪽 사이드에서 상대 오른팔을 내 왼 겨드랑이에 끼워 왼손으로 잡는다','엉덩이를 상대 오른 옆구리에 붙이고 돌아앉으며 내 오른팔로 상대 목 뒤를 감는다','내 오른다리는 앞(상대 머리 쪽), 왼다리는 뒤로 넓게 벌려 베이스를 만든다','가슴으로 상대 오른 어깨를 눌러 고정하고 암락이나 마운트 전환을 노린다']::text[] where slug = 'kesa-gatame' and owner_id is null and steps = array['사이드에서 상대 가까운 팔을 내 겨드랑이에 끼워 잡는다','엉덩이를 상대 옆구리에 붙이고 돌아앉으며 반대 팔로 상대 머리를 감는다','다리를 앞뒤로 넓게 벌려 베이스를 만든다','상대 어깨를 가슴으로 눌러 고정하고 암락이나 마운트 전환을 노린다']::text[];
update public.techniques set steps = array['내 왼 겨드랑이에 끼운 상대 오른팔의 손목을 내 왼손으로 잡는다','목을 감았던 내 오른팔을 풀어 상대 오른팔 아래로 넣고 내 왼 손목을 잡는다(8자 그립)','상대 오른 팔꿈치를 내 가슴에 붙이고 체중으로 상대 오른 어깨를 눌러 둔다','상대 오른손을 상대 등 쪽으로 돌려 올리며 꺾는다']::text[] where slug = 'kimura-from-kesa' and owner_id is null and steps = array['겨드랑이에 끼운 상대 팔의 손목을 엉덩이 쪽 손으로 잡는다','머리를 감았던 팔을 풀어 상대 팔 아래로 넣고 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 내 가슴에 붙이고 체중으로 어깨를 눌러 둔다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[];
update public.techniques set steps = array['상대가 왼손(먼 쪽 손)으로 내 얼굴을 밀면 내 왼손으로 그 손목을 잡는다','상대 왼 손목을 상대 머리 쪽 바닥으로 눌러 팔꿈치를 90도로 접는다','목 감은 내 오른팔은 유지하고 상대 왼 손목을 바닥에 붙여 둔다','손목은 그대로 두고 상대 왼 팔꿈치를 들어 올려 어깨를 꺾는다']::text[] where slug = 'americana-from-kesa' and owner_id is null and steps = array['겨드랑이에 끼운 상대 팔을 풀어 손목을 잡고 손등이 바닥에 닿게 눌러 팔꿈치를 90도로 만든다','상대 손목 위에 내 다리를 올리고 무릎을 접어 발을 바닥에 두어 손목을 고정한다','머리 감은 팔은 유지한 채 자유로운 손으로 상대 팔꿈치를 잡는다','손목은 바닥에 붙인 채 팔꿈치만 들어 올려 어깨를 꺾는다']::text[];
update public.techniques set steps = array['내 왼 겨드랑이에 끼운 상대 오른팔을 풀어 상대 머리 너머로 밀어 올려 상대 목 앞을 가로지르게 한다','목을 감은 내 오른팔을 상대 목 아래로 깊게 넣고 내 왼손과 손바닥을 맞잡는다','내 머리를 상대 오른 어깨에 붙이고 가슴을 낮춰 옆이나 엎드린 자세로 간다','양 팔꿈치를 모으고 어깨를 낮추며 조인다']::text[] where slug = 'arm-triangle-from-kesa' and owner_id is null and steps = array['겨드랑이에 끼운 상대 팔을 풀어 상대 머리 너머로 밀어 올려 팔이 자기 목을 가로지르게 한다','머리를 감은 팔을 상대 목 아래로 깊게 넣고 반대 손과 손바닥을 맞잡는다','머리를 상대 어깨에 붙이고 가슴을 낮춰 옆이나 엎드린 자세로 간다','팔꿈치를 모으고 어깨를 낮추며 조인다']::text[];
update public.techniques set steps = array['상대 목을 감은 내 오른팔과 왼 겨드랑이에 끼운 상대 오른팔은 그대로 유지한다','뒤로 접었던 내 왼다리를 상대 배 위로 넘겨 상대 왼쪽 바닥에 무릎을 댄다','앞으로 뻗었던 내 오른다리를 당겨 무릎을 상대 오른 옆구리에 붙인다','엉덩이를 낮추고 양 무릎을 조여 마운트를 굳힌다']::text[] where slug = 'kesa-to-mount' and owner_id is null and steps = array['머리를 감은 팔과 겨드랑이에 끼운 팔은 그대로 유지한다','뒤로 접었던 다리(엉덩이 쪽)를 상대 배 위로 넘겨 반대쪽 바닥에 무릎을 댄다','앞으로 뻗었던 다리를 당겨 무릎을 상대 옆구리에 붙인다','엉덩이를 낮추고 양 무릎을 조여 마운트를 굳힌다']::text[];
update public.techniques set steps = array['목 감은 내 오른팔과 끼운 왼팔을 유지한 채 엉덩이를 들어 상대 쪽으로 돌린다','뒤로 접었던 내 왼다리의 무릎을 상대 오른 옆구리에 붙이고 가슴을 상대 가슴에 포갠다','목 감은 내 오른팔을 크로스페이스로 바꿔 상대 얼굴을 상대 왼쪽으로 돌린다','끼웠던 내 왼팔은 상대 오른팔 아래 언더훅으로 바꾸고 왼 무릎과 왼 팔꿈치 사이를 붙인다']::text[] where slug = 'kesa-to-side-control' and owner_id is null and steps = array['머리를 감은 팔과 끼운 팔을 유지한 채 엉덩이를 들어 돌린다','뒤로 접었던 다리의 무릎을 상대 옆구리에 붙이고 가슴을 상대 가슴에 포갠다','머리 감은 팔을 크로스페이스로 바꿔 상대 얼굴을 반대쪽으로 돌린다','끼운 팔은 언더훅으로 바꾸고 무릎과 팔꿈치 사이 공간을 없앤다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 곁누르기를 잡으면 끼인 내 오른 팔꿈치를 가슴 쪽으로 당겨 오른손을 몸에 붙인다','내 왼손으로 상대 허리띠나 등을 잡고 양발을 당겨 세운다','내 오른쪽(상대 쪽)으로 브릿지한 뒤 엉덩이를 왼쪽으로 빼서 상대와 나 사이에 오른 무릎을 넣는다','하프가드로 돌아오거나 상대 등 뒤로 돌아 백을 잡는다']::text[] where slug = 'escape-kesa-gatame' and owner_id is null and steps = array['끼인 팔의 팔꿈치를 가슴 쪽으로 당기며 손을 내 몸에 붙인다','먼 쪽 손으로 상대 허리띠나 등을 잡고 발을 당겨 세운다','상대 쪽으로 브릿지하며 엉덩이를 빼서 상대와 나 사이에 무릎을 넣는다','하프가드로 돌아오거나 상대 등 뒤로 돌아 백을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 곁누르기를 잡으면 내 왼팔로 상대 허리띠나 등을 감아 잡고 양발을 엉덩이 가까이 세운다','끼인 내 오른 팔꿈치를 가슴 쪽으로 당겨 상대 왼팔 조임을 느슨하게 한다','내 머리 쪽으로 강하게 브릿지하며 상대를 내 몸 너머 내 왼쪽으로 굴린다','넘어가면 사이드 탑, 상대가 손을 짚어 버티면 그 틈에 엉덩이를 빼 하프가드로 돌아온다']::text[] where slug = 'bridge-escape-from-kesa' and owner_id is null and steps = array['먼 쪽 팔로 상대 허리띠나 등을 감아 잡고 양발을 엉덩이 가까이 당겨 세운다','끼인 팔의 팔꿈치를 가슴 쪽으로 당겨 상대 팔 조임을 느슨하게 한다','머리 쪽으로 강하게 브릿지하며 상대를 내 몸 너머 반대쪽으로 굴린다','넘어가면 사이드 탑, 상대가 손을 짚어 버티면 그 틈에 엉덩이를 빼 하프가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 곁누르기를 잡으면 내 왼손으로 상대 허리띠나 등 쪽 도복을 잡는다','끼인 내 오른 팔꿈치를 가슴 쪽으로 당겨 빼며 내 오른쪽(상대 쪽)으로 몸을 돌린다','무릎을 세우고 상대 등 뒤로 돌아 올라가 내 오른팔은 상대 오른 어깨 위, 왼팔은 왼 겨드랑이 아래로 시트벨트를 잡는다','오른발·왼발 훅을 상대 양 허벅지 안쪽에 넣어 백 컨트롤을 완성한다']::text[] where slug = 'back-take-from-kesa' and owner_id is null and steps = array['먼 쪽 손으로 상대 허리띠나 등 쪽 도복을 잡는다','끼인 팔꿈치를 가슴 쪽으로 당겨 빼며 상대 쪽으로 몸을 돌린다','무릎을 세우고 상대 등 뒤로 돌아 올라가 시트벨트를 잡는다','훅을 넣어 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대 오른쪽 곁누르기에서 목을 감는 대신 내 오른팔을 상대 왼 겨드랑이 아래로 넣어 언더훅을 잡는다','상대 오른팔은 내 왼 겨드랑이에 끼운다','내 오른다리는 앞, 왼다리는 뒤로 벌려 베이스를 잡고 엉덩이를 상대 오른 옆구리에 붙인다','여기서 기무라 · 아메리카나 · 마운트 전환을 노린다']::text[] where slug = 'kuzure-kesa-gatame' and owner_id is null and steps = array['곁누르기에서 머리를 감는 대신 상대 먼 팔 겨드랑이 아래로 팔을 넣어 언더훅을 잡는다','가까운 팔은 내 겨드랑이에 끼운다','다리를 앞뒤로 벌려 베이스를 잡고 엉덩이를 상대 옆구리에 붙인다','여기서 기무라 · 아메리카나 · 마운트 전환을 노린다']::text[];
update public.techniques set steps = array['내 왼 겨드랑이에 끼운 상대 오른팔을 풀어 왼손으로 손목을 잡고 손등이 바닥에 닿게 눌러 팔꿈치를 90도로 만든다','상대 오른 손목 위에 내 왼다리를 올리고 무릎을 접어 손목을 바닥에 고정한다','내 오른팔 언더훅은 유지한 채 자유로운 왼손으로 상대 오른 팔꿈치를 잡는다','손목은 바닥에 둔 채 상대 오른 팔꿈치를 들어 올려 어깨를 꺾는다']::text[] where slug = 'americana-from-kuzure-kesa' and owner_id is null and steps = array['겨드랑이에 끼운 상대 팔을 풀어 손목을 잡고 손등이 바닥에 닿게 눌러 팔꿈치를 90도로 만든다','상대 손목 위에 다리를 올리고 무릎을 접어 손목을 바닥에 고정한다','언더훅은 유지한 채 자유로운 손으로 상대 팔꿈치를 잡는다','손목은 바닥에 둔 채 팔꿈치를 들어 올려 어깨를 꺾는다']::text[];
update public.techniques set steps = array['언더훅한 내 오른팔을 빼고 오른손 엄지를 상대 왼쪽 깃 안에 넣어 깊게 잡는다','깃 잡은 내 오른 팔뚝(손목 뼈 쪽)이 상대 목 앞을 가로지르게 눕힌다','내 왼손은 상대 머리 옆 바닥을 짚어 균형을 잡는다','양다리를 뒤로 뻗어 가슴을 낮추며 오른 팔뚝에 체중을 실어 조인다']::text[] where slug = 'breadcutter-from-kuzure-kesa' and owner_id is null and steps = array['언더훅 넣은 손으로 상대 뒤쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손은 상대 가까운 쪽 깃을 잡고 팔뚝을 목 앞에 가로로 댄다','엉덩이를 들어 상대 머리 쪽으로 돌며 팔뚝에 체중을 싣는다','뒤 깃을 당기고 팔뚝을 눕히듯 눌러 조인다']::text[];
update public.techniques set steps = array['언더훅으로 넣은 내 오른손으로 상대 목 뒤쪽 깃을 네 손가락을 넣어 깊게 잡는다','내 왼손으로 상대 오른쪽 깃을 잡고 왼 팔뚝을 상대 목 앞에 가로로 댄다','오른손으로 뒤 깃을 당겨 상대 머리를 들며 내 왼 팔꿈치를 바닥으로 떨어뜨린다','가슴을 낮춰 체중을 실어 조인다']::text[] where slug = 'paper-cutter-choke' and owner_id is null and steps = array['언더훅 넣은 손으로 상대 목 뒤쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손으로 상대 가까운 쪽 깃을 잡고 팔뚝을 목 앞에 가로로 댄다','뒤 깃을 당겨 상대 머리를 들어 올리며 팔뚝 쪽 팔꿈치를 바닥으로 떨어뜨린다','가슴을 낮춰 체중을 실어 조인다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 누르면 끼인 내 오른팔은 팔꿈치를 굽혀 몸 쪽으로 붙여 둔다','내 왼 팔뚝으로 상대 골반이나 목에 프레임을 댄다','내 오른쪽(상대 쪽)으로 짧게 브릿지해 무게가 뜬 순간 끼인 오른 팔꿈치를 뽑아낸다','내 왼쪽으로 엉덩이를 빼며 오른 무릎을 상대 몸 앞에 넣는다','왼다리도 넣어 하프가드나 가드로 돌아온다']::text[] where slug = 'arm-recovery-to-guard-kesa' and owner_id is null and steps = array['끼인 팔의 팔꿈치를 가슴 쪽으로 당겨 상대 겨드랑이에서 빼낸다','뺀 팔로 상대 목이나 어깨에 프레임을 만든다','상대 반대쪽으로 엉덩이를 빼며(쉬림프) 무릎을 상대 몸 앞에 넣는다','다른 다리도 넣어 하프가드나 오픈 가드로 돌아온다']::text[];
update public.techniques set steps = array['내 왼 겨드랑이에 끼운 상대 오른팔의 손목을 왼손으로 잡고 팔꿈치 안쪽이 위를 보게 돌린다','앞으로 뻗은 내 오른다리의 무릎을 세워 오른 허벅지를 상대 오른 팔꿈치 아래에 받친다','목 감은 내 오른팔과 가슴으로 상대 오른 어깨를 눌러 움직이지 못하게 한다','상대 오른 손목을 바닥 쪽으로 눌러 내 오른 허벅지 위에서 팔꿈치를 편다']::text[] where slug = 'kesa-straight-armlock' and owner_id is null and steps = array['겨드랑이에 끼운 상대 팔의 손목을 잡고 팔꿈치 안쪽이 위를 보게 돌린다','앞으로 뻗은 다리의 무릎을 세워 허벅지를 상대 팔꿈치 아래에 받친다','머리 감은 팔과 가슴으로 상대 어깨를 눌러 움직이지 못하게 한다','손목을 바닥 쪽으로 눌러 허벅지 위에서 팔꿈치를 편다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽 곁누르기에서 머리를 높이 들고 있으면 끼인 내 오른 팔꿈치를 가슴 쪽으로 당겨 둔다','내 왼손으로 상대 어깨나 턱을 밀어 머리를 더 뒤로 보낸다','내 오른다리를 들어 올려 오른발이나 정강이로 상대 얼굴 앞을 걸어 뒤로 당긴다','상대가 뒤로 넘어가면 오른팔을 빼고 일어나 사이드 탑이나 암바로 간다']::text[] where slug = 'kesa-leg-hook-escape' and owner_id is null and steps = array['상대 머리가 높이 떠 있을 때 끼인 팔꿈치를 가슴 쪽으로 당겨 둔다','먼 손으로 상대 어깨나 턱을 밀어 머리를 더 뒤로 보낸다','상대 등 뒤에서 가까운 다리를 들어 올려 발이나 정강이로 상대 얼굴을 걸어 뒤로 당긴다','상대가 뒤로 넘어가면 팔을 빼고 일어나 사이드 탑이나 암바로 간다']::text[];
update public.techniques set steps = array['상대 오른쪽 사이드에서 상대 발 쪽을 보고 돌아앉으며 엉덩이를 상대 오른 옆구리에 붙인다','내 오른팔로 상대 오른팔을 언더훅해 내 오른 겨드랑이에 끼운다','내 왼손은 상대 왼쪽 바지나 엉덩이를 잡고 양다리를 벌려 베이스를 만든다','내 오른다리를 상대 허리 위로 넘겨 마운트로 가거나 그대로 눌러 둔다']::text[] where slug = 'reverse-kesa-gatame' and owner_id is null and steps = array['사이드에서 상대 발 쪽을 보고 돌아앉으며 엉덩이를 상대 옆구리에 붙인다','머리 쪽 팔로 상대 가까운 팔을 언더훅해 겨드랑이에 끼운다','반대 손은 상대 먼 쪽 바지나 엉덩이를 잡고 다리를 벌려 베이스를 만든다','엉덩이 쪽 다리를 상대 허리 위로 넘겨 마운트로 가거나 그대로 눌러 둔다']::text[];
update public.techniques set steps = array['엉덩이를 낮추고 양 무릎을 상대 몸에 바짝 붙인다','상대가 내 오른쪽으로 브릿지하면 내 오른손을 넓게 짚어 균형을 잡는다(왼쪽이면 왼손)','상대가 엉덩이를 내 왼쪽으로 빼면 내 왼 무릎으로 골반을 막고 다시 가운데로 앉는다','상대가 많이 움직이면 양발을 상대 양다리 안쪽에 감아(그레이프바인) 낮게 버틴다','상대 팔이 떨어지면 양 무릎을 겨드랑이 쪽으로 걸어 올려 하이 마운트로 간다']::text[] where slug = 'mount-maintain' and owner_id is null and steps = array['무릎을 상대 겨드랑이 가까이 올리고 엉덩이를 낮춘다','상대가 브릿지하면 그쪽으로 손을 짚어 균형을 잡는다','발을 상대 다리 안쪽으로 감아(그레이프바인) 엉덩이 빼기를 막는다','한 팔로 크로스페이스를 걸어 얼굴을 돌려 두면 상대가 반응해 공격 기회가 생긴다']::text[];
update public.techniques set steps = array['상대 오른팔을 내 양손으로 감싸 가슴에 붙이고 내 왼발로 상대 오른발 바깥을 걸어 묶는다(트랩)','양발을 엉덩이 가까이 당겨 세운다','내 왼쪽 어깨 너머로 높게 브릿지하며 몸을 왼쪽으로 돌린다','굴러 넘겨 상대 클로즈드 가드 안에서 자세를 세운다']::text[] where slug = 'mount-escape-upa' and owner_id is null and steps = array['상대 한 팔을 양손으로 감싸 가슴에 붙이고 같은 쪽 발을 내 발로 밟아 묶는다(트랩)','양발을 엉덩이 가까이 당겨 세운다','묶은 쪽 어깨 너머로 높게 브릿지하며 몸을 돌린다','굴러 넘겨 상대 클로즈드 가드 안에서 자세를 세운다']::text[];
update public.techniques set steps = array['마운트 아래에서 몸을 내 오른쪽으로 돌려 오른 팔꿈치로 상대 왼 무릎이나 골반에 프레임을 만든다','엉덩이를 내 왼쪽으로 빼며(쉬림프) 공간을 만든다','내 오른 무릎을 상대 왼다리 안쪽으로 넣어 다리를 빼낸다','왼쪽으로 돌아 왼 팔꿈치 프레임으로 왼다리도 빼서 하프가드나 클로즈드 가드로 돌아온다']::text[] where slug = 'mount-escape-elbow' and owner_id is null and steps = array['마운트 아래에서 팔꿈치로 상대 무릎이나 골반에 프레임을 만든다','한쪽 엉덩이를 빼며(쉬림프) 공간을 만든다','같은 쪽 무릎을 상대 다리 아래로 넣어 빼낸다','반대쪽도 같은 방법으로 빼서 하프가드나 클로즈드 가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 오른쪽으로 돌아누우면 내 오른 무릎을 상대 등 뒤에 붙인다','내 왼발은 상대 머리 앞 옆에 세워 왼 무릎을 높인다','가슴으로 상대 왼 어깨를 눌러 상대가 다시 눕지도 엎드리지도 못하게 한다','여기서 암바 · 백 테이크 · 초크를 고른다']::text[] where slug = 'technical-mount' and owner_id is null and steps = array['상대가 옆으로 돌면 그쪽 무릎을 상대 등 뒤에 붙인다','반대 다리는 상대 머리 옆에 발을 세워 무릎을 높인다','가슴으로 상대 어깨를 눌러 등이 바닥에서 뜨지 않게 한다','여기서 암바 · 백 테이크 · 초크를 고른다']::text[];
update public.techniques set steps = array['상대 오른팔을 내 양팔로 감싸 가슴에 붙인다','내 왼 무릎을 상대 머리 오른쪽까지 올려 S 자세로 앉는다','머리 옆에 올린 그 왼다리를 상대 얼굴 위로 넘기며 상대 오른쪽으로 뒤로 눕고 무릎을 모은다','상대 오른 손목을 엄지가 위로 오게 잡고 엉덩이를 들어 팔꿈치를 편다']::text[] where slug = 'mount-armbar' and owner_id is null and steps = array['상대 한 팔을 가슴에 붙여 잡고 반대 손은 바닥을 짚는다','잡은 팔 쪽 무릎을 상대 머리 옆으로 올려 S 자세로 앉는다','반대 다리를 상대 얼굴 위로 넘기며 뒤로 눕는다 — 다리를 펴지 말고 상대를 몸 쪽으로 조인다','무릎을 모으고 엄지가 위로 가게 손목을 잡은 뒤 엉덩이를 들어 팔꿈치를 편다']::text[];
update public.techniques set steps = array['마운트에서 내 오른손을 상대 오른쪽 깃 깊숙이 넣는다(손바닥 위로)','내 왼손을 오른팔 아래로 교차해 상대 왼쪽 깃을 잡는다','상체를 숙여 머리를 상대 머리 옆 바닥 가까이 둔다','양 팔꿈치를 바닥 쪽으로 벌리며 손목을 비틀어 조인다']::text[] where slug = 'mount-cross-collar-choke' and owner_id is null and steps = array['마운트에서 한 손을 상대 깃 깊숙이 넣는다(손바닥 위로)','반대 손을 첫 손 아래로 교차해 반대 깃을 잡는다','상체를 숙여 머리를 상대 머리 옆 바닥 가까이 둔다','팔꿈치를 바닥 쪽으로 벌리며 손목을 비틀어 조인다']::text[];
update public.techniques set steps = array['마운트에서 내 오른팔을 상대 머리 아래로 넣는다','머리 아래로 넣은 오른손으로 내 왼팔 소매 안쪽(손목 부분)을 잡는다','소매가 잡힌 내 왼손의 손날을 상대 목 앞으로 가로질러 넣는다','오른손으로 소매를 당기고 왼 손날을 밀어 넣으며 팔꿈치를 모아 조인다']::text[] where slug = 'ezekiel-choke' and owner_id is null and steps = array['마운트에서 한 팔을 상대 머리 아래로 넣는다','머리 아래로 넣은 손으로 반대쪽 팔의 소매 안쪽(손목 부분)을 잡는다','소매가 잡힌 손의 손날을 상대 목 앞으로 가로질러 넣는다','소매를 당기고 손날을 밀어 넣으며 팔꿈치를 모아 조인다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 왼 손목을 잡아 상대 머리 옆 바닥에 눌러 팔꿈치가 90도가 되게 한다','내 오른팔을 상대 왼팔 아래로 넣어 내 왼 손목을 잡는다(8자 그립)','가슴을 낮춰 상대 왼 어깨를 바닥에 고정한다','손목은 바닥에 붙인 채 상대 왼 팔꿈치를 들어 올려 어깨를 꺾는다']::text[] where slug = 'mount-americana' and owner_id is null and steps = array['상대 손목을 바닥에 눌러 팔꿈치가 90도가 되게 한다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','가슴을 낮춰 상대 어깨를 바닥에 고정한다','손목은 바닥에 붙인 채 팔꿈치를 들어 올려 어깨를 꺾는다']::text[];
update public.techniques set steps = array['상대가 오른쪽으로 돌아누우면 상대 왼팔을 얼굴 앞으로 가로질러 상대 오른쪽으로 밀어 넘긴다','내 오른팔을 상대 머리 뒤로 넣어 그 왼 손목을 잡는다(기프트 랩)','내 왼손으로 상대 어깨나 골반을 누르며 내 오른다리를 상대 등 뒤로 넣는다','상대 등 쪽(내 오른쪽)으로 굴러 앉으며 시트벨트를 잡고 훅을 넣어 백 컨트롤로 간다']::text[] where slug = 'gift-wrap' and owner_id is null and steps = array['상대가 옆으로 돌면 상대 위쪽 팔을 얼굴을 가로질러 반대쪽으로 밀어 넘긴다','상대 머리 뒤로 팔을 넣어 그 손목을 잡는다(기프트 랩)','자유로운 손으로 상대 어깨나 골반을 누르며 다리를 상대 등 뒤로 넣는다','그쪽으로 굴러 앉으며 시트벨트를 잡고 훅을 넣어 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['양손으로 상대 양 팔꿈치를 밀어 올리며 양 무릎을 번갈아 겨드랑이까지 걸어 올라간다','엉덩이를 낮추고 양발을 상대 몸에 붙인다','손은 바닥을 짚거나 내 오른손으로 상대 깃을 잡아 균형을 잡는다','여기서 크로스 칼라 초크나 암바를 노린다']::text[] where slug = 'consolidate-mount' and owner_id is null and steps = array['상대 팔꿈치를 밀어 올리며 무릎을 겨드랑이까지 걸어 올라간다','엉덩이를 낮추고 발을 상대 몸에 붙인다','손은 바닥을 짚거나 상대 깃을 잡아 균형을 잡는다','여기서 크로스 칼라 초크나 암바를 노린다']::text[];
update public.techniques set steps = array['상대 오른팔을 내 양손으로 감싸 가슴에 붙이고 내 왼발로 상대 오른발 바깥을 걸어 묶는다','양발을 엉덩이 가까이 당겨 세운다','내 왼쪽 어깨 너머로 브릿지하며 상대를 내 왼쪽으로 굴려 넘긴다','상대 가드 안에서 자세를 세워 탑을 잡는다']::text[] where slug = 'bridge-and-roll' and owner_id is null and steps = array['상대 한 팔을 양손으로 감싸 가슴에 붙이고 같은 쪽 발을 내 발로 묶는다','양발을 엉덩이 가까이 당겨 세운다','묶은 쪽 어깨 너머로 브릿지하며 상대를 굴려 넘긴다','상대 가드 안에서 자세를 세워 탑을 잡는다']::text[];
update public.techniques set steps = array['몸을 내 오른쪽으로 돌려 오른 팔꿈치로 상대 왼 골반에 프레임을 만들고 엉덩이를 왼쪽으로 살짝 뺀다','내 왼발 뒤꿈치로 상대 왼 발목을 걸어 내 양다리 사이로 끌어온다','상대 왼다리 위로 내 왼 무릎을 넘겨 양다리로 감는다(하프가드)','내 오른팔로 상대 왼 겨드랑이 언더훅을 잡거나 니 쉴드를 세워 하프가드를 지킨다']::text[] where slug = 'heel-drag-escape' and owner_id is null and steps = array['팔꿈치를 붙여 상대 골반에 프레임을 만들고 한쪽 엉덩이를 살짝 뺀다','같은 쪽 발뒤꿈치로 상대 발목을 안쪽으로 끌어와 내 다리 사이로 넣는다','그 다리 위로 내 무릎을 넘겨 상대 다리를 내 양다리로 감는다(하프가드)','언더훅을 잡거나 니 쉴드를 세워 하프가드를 지킨다']::text[];
update public.techniques set steps = array['엘보 이스케이프로 상대 왼다리를 내 양다리로 감아 하프가드를 만든다','내 오른팔을 상대 왼 겨드랑이 아래로 넣어 언더훅을 잡고 내 왼쪽 옆으로 돌아 눕는다','언더훅 쪽(내 오른쪽)으로 몸을 세우며 상대 왼쪽을 지나 등 뒤로 돈다','시트벨트를 잡고 양발 훅을 넣어 백 컨트롤을 완성한다']::text[] where slug = 'mount-escape-to-half-guard-back-take' and owner_id is null and steps = array['엘보 이스케이프로 상대 한쪽 다리를 감아 하프가드를 만든다','상대 겨드랑이 아래로 팔을 넣어 언더훅을 잡고 옆으로 돌아 눕는다','언더훅 쪽으로 몸을 세우며 상대 등 뒤로 돈다','시트벨트를 잡고 훅을 넣어 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대가 오른쪽으로 돌아누우면 내 오른 무릎(상대 등 쪽)을 상대 등 뒤에 붙인다','내 왼발은 상대 머리 앞 옆에 세워 왼 무릎을 높인다','가슴으로 상대 왼 어깨를 눌러 상대가 다시 눕지도 엎드리지도 못하게 한다','여기서 암바나 백 테이크를 고른다']::text[] where slug = 'mount-to-technical-mount' and owner_id is null and steps = array['상대가 옆으로 돌면 그쪽(등 쪽) 무릎을 상대 등 뒤에 붙인다','반대 다리는 상대 머리 옆에 발을 세워 무릎을 높인다','가슴으로 상대 어깨를 눌러 상대가 다시 눕지도 엎드리지도 못하게 한다','여기서 암바나 백 테이크를 고른다']::text[];
update public.techniques set steps = array['테크니컬 마운트에서 내 왼팔은 상대 왼 어깨 위, 오른팔은 상대 오른 겨드랑이 아래로 시트벨트를 잡는다','상대 머리 옆에 세웠던 내 왼발을 상대 배 앞으로 넘겨 상대 왼 허벅지 안쪽에 훅으로 넣는다','등 뒤에 붙였던 오른 무릎 쪽(내 오른쪽)으로 눕히며 오른발도 상대 오른 허벅지 안쪽에 넣는다','가슴을 상대 등에 붙여 백 컨트롤을 완성한다']::text[] where slug = 'technical-mount-to-back' and owner_id is null and steps = array['테크니컬 마운트에서 시트벨트를 먼저 잡는다','상대 머리 옆에 세웠던 발을 상대 배 앞으로 넘겨 허벅지 안쪽에 훅으로 넣는다','등 뒤에 붙였던 무릎 쪽으로 몸을 눕히며 그 다리도 훅으로 넣는다','가슴을 등에 붙여 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대 왼팔(위쪽 팔)을 내 양팔로 안아 가슴에 붙인다','상대 머리 옆에 세웠던 내 왼발을 상대 머리 너머로 넘긴다','엉덩이를 상대 왼 어깨에 붙인 채 뒤로 눕고 무릎을 모은다','상대 왼 엄지가 위로 오게 손목을 잡고 엉덩이를 들어 팔꿈치를 편다']::text[] where slug = 'armbar-from-technical-mount' and owner_id is null and steps = array['상대 위쪽 팔을 양팔로 안아 가슴에 붙인다','머리 옆에 세웠던 발을 상대 머리 너머로 넘긴다','엉덩이를 상대 어깨에 붙인 채 뒤로 눕고 무릎을 모은다','상대 엄지가 위로 오게 잡고 엉덩이를 들어 팔꿈치를 편다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 왼 손목을 잡아 상대 어깨 위쪽 바닥으로 밀어 눕힌다','손목을 바닥에 눌러 상대 왼 팔꿈치를 90도로 만든다','내 오른팔을 상대 왼팔 아래로 넣어 내 왼 손목을 잡는다(8자 그립)','가슴으로 상대 왼 어깨를 고정하고 손목은 바닥에 둔 채 팔꿈치를 들어 꺾는다']::text[] where slug = 'americana-from-technical-mount' and owner_id is null and steps = array['상대 위쪽 팔의 손목을 잡아 상대 어깨 위 바닥으로 밀어 눕힌다','손목을 바닥에 눌러 팔꿈치를 90도로 만든다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','가슴으로 어깨를 고정하고 손목은 바닥에 둔 채 팔꿈치를 들어 꺾는다']::text[];
update public.techniques set steps = array['내가 오른쪽으로 누워 깔리면 턱을 당기고 왼 팔꿈치를 몸에 붙여 왼 팔뚝으로 상대가 세운 다리를 막는다','엉덩이를 내 발 쪽으로 빼며 내 등 뒤 상대 무릎과 내 등 사이 공간을 만든다','내 오른 무릎(아래쪽)을 상대 골반 앞으로 넣어 상대 다리를 감는다','하프가드로 돌아오거나 가드를 회복한다']::text[] where slug = 'escape-technical-mount' and owner_id is null and steps = array['턱을 당기고 위쪽 팔꿈치를 몸에 붙여 팔뚝으로 상대 세운 다리를 막는다','엉덩이를 발 쪽으로 빼며 상대 등 뒤 무릎과 내 등 사이 공간을 만든다','아래쪽 무릎을 상대 골반 앞으로 넣어 다리를 감는다','하프가드로 돌아오거나 가드를 회복한다']::text[];
update public.techniques set steps = array['하이 마운트에서 내 왼 무릎을 상대 머리 오른쪽으로 올려 왼발을 바닥에 딛는다','내 오른다리는 무릎을 접어 오른발을 상대 왼 겨드랑이 아래에 넣어 S 모양을 만든다','엉덩이를 상대 가슴 위에 앉힌다','여기서 상대 오른팔 암바나 마운티드 트라이앵글을 노린다']::text[] where slug = 's-mount' and owner_id is null and steps = array['하이 마운트에서 한 무릎을 상대 머리 옆으로 올려 발을 바닥에 딛는다','반대 다리는 무릎을 접어 발을 상대 겨드랑이 아래에 넣어 S 모양을 만든다','엉덩이를 상대 가슴 위에 앉힌다','여기서 암바나 마운티드 트라이앵글을 노린다']::text[];
update public.techniques set steps = array['S 마운트에서 상대 오른팔을 내 양팔로 감싸 가슴에 붙인다','상대 머리 오른쪽에 세운 내 왼다리를 상대 얼굴 위로 넘긴다','상대 오른쪽으로 뒤로 눕되 무릎을 모아 상대를 몸 쪽으로 조인다','상대 오른 엄지가 위로 오게 손목을 잡고 엉덩이를 들어 팔꿈치를 편다']::text[] where slug = 'armbar-from-s-mount' and owner_id is null and steps = array['S 마운트에서 상대 팔을 가슴에 붙인다','머리 옆 다리를 얼굴 위로 넘긴다','뒤로 눕되 상대를 몸 쪽으로 조인다','엉덩이를 들어 편다']::text[];
update public.techniques set steps = array['S 마운트에서 상대 오른팔은 내 다리 안쪽에, 왼팔은 바깥에 두게 만든다','상대 머리 오른쪽에 세운 내 왼다리를 상대 목 뒤로 넘겨 왼 발목을 오른 무릎 뒤에 건다','상대 머리를 끌어안고 앞으로 몸을 낮춰 상대 오른 어깨를 목 쪽으로 밀어 넣는다','다리를 조이며 마무리하거나 뒤로 굴러 가드 트라이앵글로 간다']::text[] where slug = 's-mount-to-mounted-triangle' and owner_id is null and steps = array['S 마운트에서 상대 한 팔은 내 다리 안쪽에 반대 팔은 바깥에 두게 만든다','머리 옆에 세운 다리를 상대 목 뒤로 넘겨 발목을 반대 무릎 뒤에 건다','상대 머리를 끌어안고 앞으로 몸을 낮춰 상대 어깨를 목으로 밀어 넣는다','다리를 조이며 마무리하거나 뒤로 굴러 가드 트라이앵글로 간다']::text[];
update public.techniques set steps = array['상대가 내 오른팔 쪽으로 S 마운트를 잡으면 양 팔꿈치를 가슴 쪽으로 당겨 팔이 뽑히지 않게 지킨다','상대 무릎이 낮은 쪽(접힌 다리 쪽, 내 왼쪽)으로 몸을 돌려 옆으로 눕는다','엉덩이를 빼며 위쪽 내 오른 무릎을 상대 골반 앞으로 넣는다','상대 다리를 감아 하프가드로 돌아온다']::text[] where slug = 'frame-and-shrimp-from-s-mount' and owner_id is null and steps = array['양 팔꿈치를 가슴 쪽으로 당겨 팔이 뽑히지 않게 지킨다','상대 무릎이 낮은 쪽(접힌 다리 쪽)으로 몸을 돌려 옆으로 눕는다','엉덩이를 빼며 위쪽 무릎을 상대 골반 앞으로 넣는다','상대 다리를 감아 하프가드로 돌아온다']::text[];
update public.techniques set steps = array['하이 마운트에서 상대 오른팔은 안쪽에 두고 내 왼다리를 상대 목 뒤로 넘긴다','넘긴 왼 발목을 내 오른 무릎 뒤에 걸어 잠근다','상대 머리를 당기며 앞으로 몸을 낮추거나 뒤로 굴러 가드 트라이앵글로 간다','다리를 조여 마무리한다']::text[] where slug = 'mounted-triangle' and owner_id is null and steps = array['하이 마운트에서 상대 한 팔을 안쪽에 두고 그쪽 다리를 상대 목 뒤로 넘긴다','넘긴 발목을 반대 무릎 뒤에 걸어 잠근다','상대 머리를 당기며 앞으로 몸을 낮추거나 뒤로 굴러 가드 트라이앵글로 간다','다리를 조여 마무리한다']::text[];
update public.techniques set steps = array['상대가 내 오른팔을 안에 넣고 걸면 턱을 당기고 오른 팔꿈치를 몸 쪽으로 당겨 목에 공간을 만든다','양손으로 상대 허벅지나 골반을 잡고 내 머리 쪽으로 강하게 브릿지한다','상대가 앞으로 넘어가 손을 짚으면 다리 걸림이 느슨해진 틈에 머리를 뺀다','엉덩이를 빼며 무릎을 넣어 하프가드나 가드로 돌아온다']::text[] where slug = 'escape-mounted-triangle' and owner_id is null and steps = array['턱을 당기고 갇힌 팔의 팔꿈치를 몸 쪽으로 당겨 목에 공간을 만든다','양손으로 상대 허벅지나 골반을 잡고 머리 쪽으로 강하게 브릿지한다','상대가 앞으로 넘어가 손을 짚으면 다리 걸림이 느슨해진 틈에 머리를 뺀다','엉덩이를 빼며 무릎을 넣어 하프가드나 가드로 돌아온다']::text[];
update public.techniques set steps = array['하이 마운트에서 상대 오른팔을 머리 쪽으로 밀어 올리고 내 왼 무릎을 그 팔 위에 올려 가둔다','상대 왼팔은 내 오른팔로 감아(오버훅) 오른 겨드랑이에 끼운다','상대 양팔이 벌어진 십자 모양이 되게 체중을 낮춘다','여기서 에제키엘이나 깃 초크 · 암바를 노린다']::text[] where slug = 'mounted-crucifix' and owner_id is null and steps = array['하이 마운트에서 상대 한 팔을 머리 쪽으로 밀어 올리고 그 팔 위에 무릎을 올려 다리로 가둔다','반대쪽 팔은 내 팔로 감아(오버훅) 겨드랑이에 끼운다','상대 양팔이 벌어진 십자 모양이 되게 체중을 낮춘다','여기서 에제키엘이나 깃 초크 · 암바를 노린다']::text[];
update public.techniques set steps = array['하이 마운트에서 내 오른손을 상대 오른쪽 깃 안쪽 깊숙이 넣는다(손바닥 위)','내 왼손을 오른팔 아래로 교차해 상대 왼쪽 깃을 깊게 잡는다','머리를 상대 머리 옆 바닥 가까이 낮추고 양 팔꿈치를 몸 쪽으로 당긴다','양 손목을 안으로 비틀어 양 팔뚝으로 목을 조인다']::text[] where slug = 'cross-collar-choke-from-high-mount' and owner_id is null and steps = array['하이 마운트에서 한 손을 상대 깃 안쪽 깊숙이 넣는다(손바닥 위)','반대 손을 첫 손 아래로 교차해 반대쪽 깃을 깊게 잡는다','머리를 상대 머리 옆 바닥 가까이 낮추고 팔꿈치를 몸 쪽으로 당긴다','손목을 안으로 비틀어 양 팔뚝으로 목을 조인다']::text[];
update public.techniques set steps = array['상대 오른 팔꿈치를 밀어 올려 그 팔이 상대 얼굴 앞을 가로질러 상대 왼쪽으로 가게 한다','내 머리를 상대 머리 왼쪽 바닥, 그 팔 옆에 붙여 팔이 빠지지 않게 가둔다','내 오른팔을 상대 목 뒤로 깊게 넣어 내 왼손과 손바닥을 맞잡는다','갇힌 팔 반대쪽인 상대 왼쪽(내 오른쪽)으로 마운트에서 내려와 다리를 넓게 벌린다','가슴을 낮추고 어깨로 상대 오른팔을 목 쪽으로 밀며 팔꿈치를 모아 조인다']::text[] where slug = 'arm-triangle-from-mount' and owner_id is null and steps = array['상대 한쪽 팔꿈치를 조금씩 밀어 올려 그 팔이 상대 얼굴을 가로지르게 하고 내 머리를 그 손 바깥쪽에 붙인다','상대 머리 뒤로 팔을 둘러 목 아래 깊게 넣고 반대 손과 손바닥을 맞잡는다','갇힌 팔의 어깨 쪽으로 마운트에서 내려와 다리를 넓게 벌려 베이스를 잡는다','머리를 바닥 쪽으로 낮추고 어깨로 상대 팔을 목에 밀어 넣으며 조인다']::text[];
update public.techniques set steps = array['상대가 밀어내는 오른 손목을 내 왼손으로 잡아 바닥에 누른다','내 오른팔을 상대 오른팔 아래로 넣어 내 왼 손목을 잡는다(8자 그립)','상대 오른 팔꿈치를 내 가슴에 붙이고 내 오른발을 상대 머리 왼쪽에 세워 구르지 못하게 한다','상대 오른손을 상대 등 쪽으로 돌려 올리며 꺾는다']::text[] where slug = 'kimura-from-mount' and owner_id is null and steps = array['상대가 밀어내는 손목을 잡아 바닥에 누른다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 내 가슴에 붙이고 반대쪽 발을 상대 머리 옆에 세워 상대가 구르지 못하게 한다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[];
update public.techniques set steps = array['상대가 오른쪽으로 돌아누우면 내 오른 무릎은 상대 등 뒤, 왼 무릎은 상대 배 앞 바닥에 붙인다','상대 왼팔(위쪽 팔)을 내 왼팔이나 왼 겨드랑이로 가둔다','엉덩이를 낮추고 가슴으로 상대 왼 어깨를 눌러 상대가 눕거나 엎드리지 못하게 한다','여기서 깃 초크나 기무라를 노린다']::text[] where slug = 'modified-mount' and owner_id is null and steps = array['상대가 옆으로 돌면 한 무릎은 상대 등 뒤 반대 무릎은 상대 배 앞 바닥에 붙인다','상대 위쪽 팔을 내 팔이나 겨드랑이로 가둔다','엉덩이를 낮추고 가슴으로 상대 어깨를 눌러 상대가 눕거나 엎드리지 못하게 한다','여기서 깃 초크나 기무라를 노린다']::text[];
update public.techniques set steps = array['오른쪽으로 누운 상대의 왼쪽(위쪽) 깃에 내 오른손 네 손가락을 넣어 깊게 잡는다','내 왼손을 교차해 상대 오른쪽(아래쪽) 깃이나 상대 어깨 뒤 도복을 잡는다','몸을 낮추며 양 팔꿈치를 몸 쪽으로 당긴다','양 손목을 비틀어 양 팔뚝으로 목을 조인다']::text[] where slug = 'cross-collar-choke-from-modified-mount' and owner_id is null and steps = array['옆으로 누운 상대의 위쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손을 교차해 아래쪽 깃을 잡거나 상대 어깨 뒤 도복을 잡는다','몸을 낮추며 팔꿈치를 몸 쪽으로 당긴다','손목을 비틀어 양 팔뚝으로 목을 조인다']::text[];
update public.techniques set steps = array['상대 왼팔(위쪽 팔)의 손목을 내 왼손으로 잡는다','내 오른팔을 상대 왼팔 아래로 넣어 내 왼 손목을 잡는다(8자 그립)','상대 왼 팔꿈치를 내 몸에 붙이고 가슴으로 상대 왼 어깨를 눌러 둔다','상대 왼손을 상대 등 쪽으로 돌려 올리며 꺾는다']::text[] where slug = 'kimura-from-modified-mount' and owner_id is null and steps = array['상대 위쪽 팔의 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 내 몸에 붙이고 가슴으로 어깨를 눌러 둔다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[];
update public.techniques set steps = array['내가 오른쪽 옆으로 누운 모디파이드 마운트 기준 — 내 왼팔 팔꿈치를 몸에 붙이고 팔뚝으로 상대 왼쪽 골반이나 왼쪽 무릎을 막는다','브릿지하며 엉덩이를 뒤로(내 왼쪽으로) 빼서 상대 왼쪽 무릎과 내 몸 사이에 공간을 만든다','그 틈으로 내 오른쪽 무릎을 넣고 두 다리로 상대 왼다리를 감는다','하프가드로 돌아온다']::text[] where slug = 'bridge-escape-from-modified-mount' and owner_id is null and steps = array['위쪽 팔의 팔꿈치를 몸에 붙이고 팔뚝으로 상대 골반이나 무릎에 프레임을 만든다','브릿지하며 엉덩이를 빼서 상대 무릎과 내 몸 사이에 공간을 만든다','그 틈으로 아래쪽 무릎을 넣어 상대 다리를 감는다','하프가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 하프가드처럼 감아도 내 왼쪽 무릎은 바닥에 붙이고 엉덩이를 낮춰 버틴다','내 오른팔로 크로스페이스해 상대 얼굴을 상대 오른쪽(내 왼쪽)으로 돌린다','내 왼발로 상대 발목을 밀어 내리거나 내 오른쪽 무릎을 세워 오른다리를 빼낸다','빼낸 오른다리를 바닥에 내려 풀 마운트를 완성한다']::text[] where slug = '3-4-mount' and owner_id is null and steps = array['상대가 내 한쪽 다리를 하프가드처럼 감아도 반대 무릎은 바닥에 붙이고 엉덩이를 낮춰 버틴다','크로스페이스로 상대 얼굴을 걸린 다리 반대쪽으로 돌린다','자유로운 발로 상대 발목을 밀어 내리거나 걸린 다리 무릎을 세워 빼낸다','뺀 다리를 바닥에 내려 풀 마운트를 완성한다']::text[];
update public.techniques set steps = array['내가 상대 오른다리를 감은 3/4 마운트 기준 — 내 왼쪽 옆으로 돌며 오른팔 팔뚝으로 상대 오른쪽 골반을 막는다','엉덩이를 내 오른쪽으로 빼며(쉬림프) 상대 오른다리와 내 몸 사이 공간을 만든다','그 공간에 내 오른쪽 무릎을 넣어 니 쉴드를 세우거나 내 왼팔로 상대 오른팔 아래 언더훅을 잡는다','하프가드를 굳히거나 가드를 회복한다']::text[] where slug = 'elbow-escape-from-3-4-mount' and owner_id is null and steps = array['팔꿈치를 붙이고 팔뚝으로 상대 골반에 프레임을 만든다','걸리지 않은 쪽으로 엉덩이를 빼며(쉬림프) 상대 다리와 내 몸 사이 공간을 만든다','자유로운 무릎을 넣어 니 쉴드를 세우거나 언더훅을 잡는다','하프가드를 굳히거나 가드를 회복한다']::text[];
update public.techniques set steps = array['상대 오른팔을 머리 쪽으로 밀어 올려 내 다리 안쪽에 두고 상대 왼팔은 바깥에 둔다','내 오른쪽 무릎을 상대 왼쪽 어깨 너머 머리 옆까지 올린다','내 오른다리를 상대 목 뒤로 넘겨 오른발목을 내 왼쪽 무릎 뒤에 건다','마운티드 트라이앵글에서 조이거나 뒤로 굴러 마무리한다']::text[] where slug = 'triangle-from-mount' and owner_id is null and steps = array['상대 한 팔을 머리 쪽으로 밀어 올려 내 다리 안쪽에 두고 반대 팔은 바깥에 둔다','안쪽에 둔 팔 쪽 무릎을 상대 머리 옆까지 올린다','그 다리를 상대 목 뒤로 넘겨 발목을 반대 무릎 뒤에 건다','마운티드 트라이앵글에서 조이거나 뒤로 굴러 마무리한다']::text[];
update public.techniques set steps = array['상대가 오른손으로 내 가슴을 밀면 그 오른손목을 내 왼쪽 겨드랑이에 끼워 가둔다','상대 오른팔꿈치의 뾰족한 부분이 위를 보도록 팔을 비튼다','내 양손을 포개 상대 오른팔꿈치 바로 위를 감싸 잡는다','왼쪽 겨드랑이로 손목을 누르며 팔꿈치를 내 가슴 쪽으로 당겨 편다']::text[] where slug = 'reverse-armbar-from-mount' and owner_id is null and steps = array['상대가 내 가슴을 밀면 그 손목을 겨드랑이에 끼워 가둔다','상대 팔꿈치의 뾰족한 부분이 위를 보도록 팔을 비튼다','양손으로 상대 팔꿈치 바로 위를 감싸 잡는다','겨드랑이로 손목을 누르며 팔꿈치를 가슴 쪽으로 당겨 편다']::text[];
update public.techniques set steps = array['양 팔꿈치를 몸에 붙이고 양손으로 상대 양 무릎을 밀며 내 몸을 머리 쪽으로 조금씩 올려 상대를 배 쪽으로 내린다','내 양팔로 상대 오른팔을 가슴에 안아 잡고 내 왼발로 상대 오른발 바깥을 막아 묶는다','내 오른발을 엉덩이 가까이 세우고 내 왼쪽 어깨 너머로 브릿지해 굴린다','상대 가드 안에서 자세를 세워 탑을 잡는다']::text[] where slug = 'trap-and-roll-from-high-mount' and owner_id is null and steps = array['팔꿈치를 몸에 붙이고 엉덩이를 발 쪽으로 빼 상대 마운트를 배 아래로 내린다','상대 한 팔을 가슴에 안아 잡고 같은 쪽 발을 내 발로 묶는다','발을 세워 묶은 쪽 어깨 너머로 브릿지해 굴린다','상대 가드 안에서 자세를 세워 탑을 잡는다']::text[];
update public.techniques set steps = array['양 팔꿈치를 몸에 붙이고 양 팔뚝으로 상대 양쪽 골반을 막는다','짧게 브릿지해 상대가 앞으로 쏠린 순간 골반을 내 발 쪽으로 밀어 낸다','쉬림프로 내 몸을 머리 쪽으로 올려 상대를 내 배 아래로 보낸다','오른쪽 옆으로 돌며 내 오른쪽 무릎을 상대 왼다리 안쪽에 넣어 하프가드로 돌아오거나 엘보 이스케이프로 이어 간다']::text[] where slug = 'frame-escape-from-high-mount' and owner_id is null and steps = array['팔꿈치를 몸에 붙이고 양 팔뚝으로 상대 골반을 밀어 프레임을 만든다','브릿지하며 엉덩이를 발 쪽으로 빼 상대를 배 아래로 내린다','프레임을 유지한 채 쉬림프로 무릎을 상대 다리 안으로 넣는다','하프가드로 돌아오거나 엘보 이스케이프로 이어 간다']::text[];
update public.techniques set steps = array['상대 오른손이 내 오른쪽 깃에 들어오면 턱을 당기고 내 양손으로 그 오른손목을 잡아 더 깊이 못 들어오게 한다','상대 왼손이 교차해 내 왼쪽 깃으로 들어오려 하면 상대 왼팔꿈치나 왼손목을 밀어 막는다','상대가 몸을 숙이면 잡은 상대 오른팔과 상대 오른발(내 왼발로)을 묶고 내 왼쪽으로 브릿지한다(업파)','넘기거나 틈이 생기면 엘보 이스케이프로 가드를 회복한다']::text[] where slug = 'mount-collar-choke-defense' and owner_id is null and steps = array['상대 첫 손이 깃에 들어오면 턱을 당기고 그 손목을 양손으로 잡아 더 깊이 못 들어오게 한다','두 번째 손이 교차해 들어오려 하면 그 팔의 팔꿈치나 손목을 밀어 막는다','상대가 몸을 숙이면 그쪽 팔과 발을 묶고 브릿지한다(업파)','넘기거나 틈이 생기면 엘보 이스케이프로 가드를 회복한다']::text[];
update public.techniques set steps = array['내 오른팔은 상대 오른쪽 어깨 위로, 왼팔은 상대 왼쪽 겨드랑이 아래로 넣어 맞잡는다(시트벨트)','조르는 내 오른손이 아래, 왼손이 그 위를 덮어 보호한다','양발을 상대 양 허벅지 안쪽에 넣는다(훅) — 내 왼쪽으로 함께 누우면 아래쪽인 왼발 훅이 더 중요','내 왼팔꿈치(언더훅)는 몸에 붙이고 오른팔은 상대 목을 길게 감는다','상대가 빠지려 하면 위쪽 오른다리를 상대 골반 위로 넘기고 올라앉아 다시 잡는다']::text[] where slug = 'back-control-maintain' and owner_id is null and steps = array['한 팔은 상대 어깨 위, 반대 팔은 겨드랑이 아래로 넣어 손을 맞잡는다(시트벨트) — 어깨 위로 넘긴 조르는 손이 아래, 겨드랑이 아래로 넣은 손이 그 위를 덮어 보호한다','양 발을 상대 허벅지 안쪽에 넣는다(훅) — 아래쪽 훅이 더 중요','언더훅 팔꿈치는 몸에 붙이고 어깨 위 팔은 길게 감는다','상대가 빠지려 하면 위쪽 다리를 상대 골반 위로 넘기고 앉아 올라가 다시 잡는다']::text[];
update public.techniques set steps = array['시트벨트와 훅을 유지한 채 상대 손과 싸워 내 오른팔을 상대 턱 아래로 밀어 넣는다','내 오른손을 내 왼팔 이두에 걸고 왼손은 상대 뒤통수에 둔다','가슴을 상대 등에 붙이고 내 턱을 당긴다','가슴을 펴며 양 팔꿈치를 모아 조인다']::text[] where slug = 'rear-naked-choke' and owner_id is null and steps = array['시트벨트와 훅을 유지한 채 상대 손과 싸워 조르는 팔을 턱 아래로 밀어 넣는다','그 손을 반대 팔 이두에 걸고 반대 손은 상대 뒤통수에 둔다','가슴을 상대 등에 붙이고 턱을 당긴다','가슴을 펴며 팔꿈치를 모아 조인다']::text[];
update public.techniques set steps = array['뒤에서 내 오른팔을 상대 오른쪽 어깨 위로 넘겨 상대 왼쪽 깃을 네 손가락을 넣어 깊게 잡는다','오른손 반대쪽인 내 왼쪽으로 엉덩이를 빼며 왼발 훅을 풀고 왼쪽 옆으로 눕는다','내 왼손으로 상대 왼쪽 바지 무릎 부분을 잡는다','내 오른다리를 상대 왼쪽 어깨 위로 넘긴다','깃은 당기고 바지는 아래로 당겨 몸을 활처럼 펴며 조인다']::text[] where slug = 'bow-and-arrow-choke' and owner_id is null and steps = array['백에서 한 팔을 상대 어깨 위로 넘겨 반대쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손으로 깃 잡은 손과 같은 쪽 상대 바지(무릎 쪽)를 잡는다','깃 잡은 쪽 다리를 상대 어깨 위로 넘기며 옆으로 눕는다','깃을 당기고 다리로 밀어 활처럼 당겨 조인다']::text[];
update public.techniques set steps = array['백에서 내 왼다리를 상대 배 앞으로 가로질러 넣는다','내 왼발목을 내 오른쪽 무릎 뒤에 걸어 삼각형으로 잠근다','시트벨트(오른팔 어깨 위 · 왼팔 겨드랑이 아래)를 유지한 채 상대와 함께 내 왼쪽으로 눕는다','상대가 돌지 못하게 조이며 초크를 준비한다']::text[] where slug = 'body-triangle' and owner_id is null and steps = array['백에서 한 다리를 상대 배 앞으로 가로질러 넣는다','그 발목을 반대 무릎 뒤에 걸어 삼각형으로 잠근다','시트벨트를 유지한 채 상대를 내 쪽으로 눕힌다','상대가 돌지 못하게 조이며 초크를 준비한다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 오른쪽 어깨 위를 감은 기준 — 턱을 당기고 양손으로 상대 오른팔을 잡아 막는다(핸드 파이팅)','상대 언더훅 반대쪽인 내 오른쪽으로 오른쪽 어깨를 바닥에 붙이며 눕는다','엉덩이를 바닥 쪽으로 밀어 상대 오른발 훅을 빼낸다','상대 오른다리를 넘어 엉덩이를 바닥에 붙이고 내 왼쪽으로 돌아서 가드나 사이드 탑으로 간다']::text[] where slug = 'back-escape' and owner_id is null and steps = array['턱을 당기고 양손으로 상대 조르는 팔을 잡아 막는다(핸드 파이팅)','상대 언더훅 반대쪽(조르는 팔 쪽)으로 어깨를 바닥에 붙이며 눕는다','엉덩이를 바닥 쪽으로 밀어 훅 하나를 빼낸다','상대 다리를 넘어 돌아서 가드나 사이드 탑으로 간다']::text[];
update public.techniques set steps = array['턱을 당기고 양 어깨를 올려 목 공간을 좁힌다','상대가 내 오른쪽 어깨 위로 넘긴 오른팔(조르는 팔)의 손목을 내 양손으로 잡는다','덮고 있는 상대 왼손이 아니라 그 아래의 상대 오른손을 막아야 한다','손목을 내 배 쪽으로 밀어 내리며 내 오른쪽 어깨를 바닥에 붙여 탈출로 이어 간다']::text[] where slug = 'hand-fighting-from-back' and owner_id is null and steps = array['턱을 당기고 어깨를 올려 목 공간을 좁힌다','양손으로 상대 어깨 위로 넘어온 팔(조르는 팔)의 손목을 잡는다','덮고 있는 손이 아니라 그 아래의 조르는 손을 막아야 한다','손목을 아래로 밀어 내리며 조르는 팔 쪽으로 어깨를 바닥에 붙여 탈출로 이어 간다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 오른쪽 어깨 위를 감은 기준 — 양손으로 그 팔을 막으며 내 오른쪽 어깨를 바닥에 붙인다','엉덩이를 바닥 쪽으로 밀어 내려 상대 오른발 훅(아래쪽 훅)을 빼낸다','엉덩이를 상대 오른다리 너머로 넘겨 바닥에 붙인다','내 왼쪽(상대 쪽)으로 돌아서 하프가드로 가거나 사이드 탑으로 올라간다']::text[] where slug = 'hip-escape-from-back' and owner_id is null and steps = array['조르는 팔을 양손으로 막으며 그쪽 어깨를 바닥에 붙인다','엉덩이를 바닥 쪽으로 밀어 내려 아래쪽 훅을 빼낸다','뺀 다리로 상대 다리를 넘어가 엉덩이를 바닥에 붙인다','돌아서 하프가드로 가거나 사이드 탑으로 올라간다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 오른쪽 어깨 위를 감은 기준 — 양손으로 그 팔을 막고 내 오른쪽 어깨를 바닥에 붙인다','엉덩이를 바닥으로 내려 상대 오른발 훅(아래쪽 훅)을 빼낸다','엉덩이를 바닥에 붙인 채 내 왼쪽으로 몸을 돌려 상대와 가슴을 마주 댄다','상대 위에 올라 상대 가드 안(탑)에서 자세를 세운다']::text[] where slug = 'turn-into-opponent' and owner_id is null and steps = array['조르는 팔을 막으며 어깨를 바닥에 붙여 훅 하나를 빼낸다','엉덩이를 바닥에 붙이고 상대 쪽으로 몸을 돌려 마주 본다','상대 다리를 내 다리로 감는다','하프가드나 클로즈드 가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 오른쪽 어깨 위를 감은 기준 — 양손으로 그 팔을 막고 내 오른쪽 어깨를 바닥에 붙인다','왼쪽·오른쪽 어깨를 번갈아 밀며 몸을 상대 발 쪽으로 조금씩 미끄러뜨린다','엉덩이가 상대 오른발 훅 아래로 빠지면 상대 오른다리를 넘어간다','내 왼쪽(상대 쪽)으로 돌아서 사이드 탑으로 간다']::text[] where slug = 'shoulder-walk-escape' and owner_id is null and steps = array['조르는 팔을 양손으로 막고 그쪽 어깨를 바닥에 붙인다','양 어깨를 번갈아 밀며 몸을 상대 다리 쪽(아래)으로 조금씩 미끄러뜨린다','엉덩이가 상대 훅 아래로 빠지면 상대 다리를 넘어간다','돌아서 사이드 탑으로 간다']::text[];
update public.techniques set steps = array['시트벨트에서 덮고 있는 내 왼손으로 상대 손을 떼어 아래로 밀어 낸다','그 왼손으로 상대 이마를 뒤로 당겨 턱을 들게 한다','내 오른팔을 턱 아래로 넣어 오른팔꿈치가 턱 정중앙 아래에 오게 한다','오른손으로 내 왼팔 이두를 잡고 왼손은 상대 뒤통수에 둔다']::text[] where slug = 'rear-naked-choke-setup' and owner_id is null and steps = array['시트벨트에서 덮고 있는 손으로 상대 손을 떼어내 밀어 내린다','조르는 팔의 손날을 상대 턱 아래로 파고들게 하거나 상대 어깨를 밀어 턱을 들게 한다','조르는 팔꿈치가 상대 턱 아래 정중앙에 오게 넣는다','반대 팔 이두를 잡고 뒤통수에 손을 얹어 마무리한다']::text[];
update public.techniques set steps = array['훅 없이 시트벨트(내 오른팔 상대 오른쪽 어깨 위 · 왼팔 상대 왼쪽 겨드랑이 아래)를 잡고 가슴을 등에 붙인다','조르는 내 오른팔이 위로 오게 언더훅 쪽인 내 왼쪽으로 함께 눕는다','상대가 돌아 나오려 하면 시트벨트를 당기며 따라 돈다','틈이 나면 아래쪽 왼발 훅부터 상대 왼쪽 허벅지 안쪽에 넣어 풀 백 컨트롤로 간다']::text[] where slug = 'seat-belt-control' and owner_id is null and steps = array['훅 없이 시트벨트만 잡고 가슴을 상대 등에 붙인다','상대 옆으로 누우며 상대 어깨를 바닥에 붙여 등이 뜨지 않게 한다','상대가 돌아 나오려 하면 시트벨트를 당기며 따라 돈다','틈이 나면 훅을 넣어 풀 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['시트벨트를 잡고 조르는 내 오른팔이 위로 오게 상대와 함께 내 왼쪽으로 눕는다','아래쪽 내 왼발 훅을 상대 왼쪽 허벅지 안쪽에 먼저 넣는다','위쪽 내 오른발 훅을 상대 오른쪽 허벅지 안쪽에 넣는다','가슴을 등에 붙이고 양 팔꿈치를 모아 백 컨트롤을 굳힌다']::text[] where slug = 'seat-belt-to-full-back' and owner_id is null and steps = array['시트벨트를 잡고 조르는 팔이 위로 오게 상대와 함께 옆으로 눕는다','아래쪽 다리의 훅을 상대 허벅지 안쪽에 먼저 넣는다','위쪽 다리의 훅을 넣는다','가슴을 등에 붙이고 팔꿈치를 모아 백 컨트롤을 굳힌다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 오른쪽 어깨 위를 감은 기준 — 턱을 당기고 양손으로 그 오른팔을 잡아 막는다','내 오른쪽 어깨를 바닥에 붙이며 엉덩이를 바닥으로 내린다','상대가 훅을 넣기 전에 상대 오른다리를 넘어 내 왼쪽으로 돌아선다','터틀로 가거나 가드를 회복한다']::text[] where slug = 'escape-seat-belt-control' and owner_id is null and steps = array['턱을 당기고 양손으로 상대 조르는 팔을 잡아 막는다','조르는 팔 쪽으로 어깨를 바닥에 붙이며 엉덩이를 바닥으로 내린다','상대가 훅을 넣기 전에 상대 다리를 넘어 돌아선다','터틀로 가거나 가드를 회복한다']::text[];
update public.techniques set steps = array['백에서 내 왼다리를 상대 배 앞으로 가로질러 넣는다','내 왼발목을 내 오른쪽 무릎 뒤에 걸어 삼각형으로 잠근다','다리를 조여 상대가 엉덩이를 빼지 못하게 한다','시트벨트(오른팔 어깨 위 · 왼팔 겨드랑이 아래)를 유지하며 초크를 노린다']::text[] where slug = 'body-triangle-lock' and owner_id is null and steps = array['백에서 한 다리를 상대 배 앞으로 가로질러 넣는다','그 발목을 반대 다리 무릎 뒤에 걸어 삼각형으로 잠근다','다리를 조여 상대가 엉덩이를 빼지 못하게 한다','시트벨트를 유지하며 초크를 노린다']::text[];
update public.techniques set steps = array['바디 트라이앵글(내 왼다리가 배 앞)로 상대를 고정하고 가슴을 등에 붙인다','핸드 파이팅으로 상대 손을 떼어 내고 내 오른팔을 턱 아래로 넣는다','오른손을 내 왼팔 이두에 걸고 왼손은 상대 뒤통수에 둔다','가슴을 펴고 양 팔꿈치를 모아 조인다']::text[] where slug = 'rnc-from-body-triangle' and owner_id is null and steps = array['바디 트라이앵글로 상대를 고정하고 가슴을 등에 붙인다','핸드 파이팅으로 상대 손을 떼어 내고 조르는 팔을 턱 아래로 넣는다','그 손을 반대 팔 이두에 걸고 반대 손은 뒤통수에 둔다','가슴을 펴고 팔꿈치를 모아 조인다']::text[];
update public.techniques set steps = array['백에서 내 오른팔을 상대 오른쪽 어깨 위로 넘겨 상대 왼쪽 깃을 네 손가락을 넣어 깊게 잡는다','내 왼손은 상대 왼쪽 겨드랑이 아래로 넣어 상대 오른쪽 깃이나 어깨 도복을 잡아 당겨 깃을 팽팽하게 한다','잡은 깃 쪽인 내 왼쪽으로 몸을 눕히며 오른팔꿈치를 뒤로 당긴다','깃을 당기고 가슴을 펴며 조인다']::text[] where slug = 'cross-collar-choke-from-back' and owner_id is null and steps = array['백에서 한 팔을 상대 어깨 위로 넘겨 반대쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손은 상대 겨드랑이 아래로 넣어 반대쪽 깃이나 어깨 도복을 잡아 당겨 깃을 팽팽하게 한다','깃 잡은 쪽으로 몸을 옆으로 눕히며 팔꿈치를 당긴다','깃을 당기고 가슴을 펴며 조인다']::text[];
update public.techniques set steps = array['내 오른팔이 턱 아래로 다 들어가지 않을 때 오른 팔뚝을 상대 턱 아래에 건다','내 왼손으로 내 오른손목을 잡아 맞잡는다','가슴을 펴고 양 어깨를 뒤로 당기며 오른 팔뚝을 목 쪽으로 끌어당긴다','양 팔꿈치를 모아 조인다']::text[] where slug = 'short-choke' and owner_id is null and steps = array['조르는 팔이 턱 아래로 다 들어가지 않을 때 팔뚝을 턱 아래에 건다','반대 손으로 그 손목을 잡아 맞잡는다','가슴을 펴고 어깨를 뒤로 당기며 팔뚝을 목 쪽으로 끌어당긴다','팔꿈치를 모아 조인다']::text[];
update public.techniques set steps = array['상대 왼다리가 내 배 앞을 지나 발목이 내 오른쪽에서 잠긴 기준 — 조르는 팔을 막으며 내 오른쪽 어깨를 바닥에 붙인다','내 왼손으로 위쪽에 있는 상대 왼쪽 무릎을 내 발 쪽으로 눌러 밀며 엉덩이를 뺀다','삼각형이 느슨해지면 상대 오른다리를 넘어간다','내 왼쪽(상대 쪽)으로 돌아서 사이드 탑으로 올라간다']::text[] where slug = 'body-triangle-escape-to-side' and owner_id is null and steps = array['조르는 팔을 막으며 발목이 걸린 무릎 쪽으로 몸을 돌려 그쪽 어깨를 바닥에 붙인다','손으로 상대 위쪽 무릎을 아래로 눌러 밀며 엉덩이를 뺀다','삼각형이 느슨해지면 상대 다리를 넘어간다','돌아서 사이드 탑으로 올라간다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 오른쪽 어깨 위를 감은 기준 — 그 팔을 양손으로 막으며 엉덩이를 바닥 쪽으로 빼 훅을 느슨하게 한다','내 오른쪽으로 몸을 엎어 양 무릎과 양 팔꿈치를 바닥에 댄다(터틀)','팔꿈치를 무릎에 붙이고 턱을 당겨 목 공간을 막는다','내 오른발을 세워 베이스를 잡고 일어서거나 가드로 돌아온다']::text[] where slug = 'hip-escape-to-turtle-from-back' and owner_id is null and steps = array['조르는 팔을 막으며 엉덩이를 바닥 쪽으로 빼 훅을 느슨하게 한다','몸을 엎어 무릎과 팔꿈치를 바닥에 댄다(터틀)','팔꿈치와 무릎을 붙이고 턱을 당겨 목 공간을 막는다','한 발을 세워 베이스를 잡고 일어서거나 가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 양손으로 내 오른팔(조르는 팔)을 잡고 버티면 상대 왼팔을 내 양팔로 가슴에 안는다','위쪽 내 오른다리를 상대 머리 위로 넘겨 얼굴을 가로지르게 한다','상대 왼쪽 옆으로 떨어져 누우며 아래쪽 내 왼다리는 상대 가슴 위로 올려 무릎을 모은다','상대 왼손 엄지가 위로 오게 잡고 엉덩이를 들어 왼팔꿈치를 편다']::text[] where slug = 'armbar-from-back' and owner_id is null and steps = array['상대가 양손으로 내 조르는 팔을 잡고 밀면 그 위쪽 팔을 양팔로 가슴에 안는다','위쪽 다리를 상대 어깨 위로 넘겨 얼굴을 가로지르게 한다','옆으로 떨어져 누우며 아래쪽 다리는 상대 가슴 위로 올려 무릎을 모은다','상대 엄지가 위로 오게 잡고 엉덩이를 들어 팔꿈치를 편다']::text[];
update public.techniques set steps = array['시트벨트에서 상대 왼팔을 내 왼팔(언더훅) 쪽에 가두고 내 오른다리를 상대 오른쪽 어깨 위로 넘긴다','내 오른발목을 손으로 끌어당겨 내 왼쪽 무릎 뒤에 걸어 삼각형을 만든다','내 왼쪽으로 몸을 눕히며 상대 머리를 당긴다','다리를 조여 마무리한다']::text[] where slug = 'rear-triangle' and owner_id is null and steps = array['시트벨트에서 상대 한 팔을 언더훅 쪽에 가두고 위쪽 다리를 그 어깨 위로 넘긴다','넘긴 다리의 발목을 손으로 끌어당겨 반대 다리 무릎 뒤에 걸어 삼각형을 만든다','몸을 옆으로 눕히며 상대 머리를 당긴다','다리를 조여 마무리한다']::text[];
update public.techniques set steps = array['상대가 왼손으로 내 왼손(언더훅 손)을 잡으면 어깨 위로 넘긴 내 오른손으로 상대 왼손목을 잡는다','내 왼팔을 빼서 상대 왼팔 아래로 넣어 내 오른손목을 잡는다(8자 그립)','상대 왼팔꿈치를 내 몸에 붙이고 내 왼쪽으로 몸을 틀어 눕는다','상대 왼손을 등 뒤로 돌려 올리며 꺾는다']::text[] where slug = 'kimura-from-back' and owner_id is null and steps = array['상대가 내 아래쪽(언더훅) 손을 잡으면 어깨 위로 넘긴 손으로 그 손목을 잡는다','아래쪽 팔을 빼서 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 몸에 붙이고 그쪽으로 몸을 옆으로 틀어 눕는다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 오른쪽 어깨 위를 감은 기준 — 양손으로 그 팔을 막고 내 오른쪽 어깨를 바닥에 붙여 상대 오른발 훅을 빼낸다','등이 바닥에 닿아 목 위협이 사라진 뒤에만 손을 푼다','위쪽에 있는 상대 왼다리를 내 양팔로 안고 무릎을 꿇으며 내 왼쪽으로 몸을 돌린다','상대를 옆으로 눕히고 등 뒤에 붙어 시트벨트를 잡는다']::text[] where slug = 'rolling-back-take-reversal' and owner_id is null and steps = array['조르는 팔을 막고 어깨를 바닥에 붙여 훅 하나를 빼낸다','상대 다리를 넘어가 그 다리를 양팔로 안는다','안은 다리 쪽으로 구르며 상대를 넘긴다','상대 등 뒤로 돌아 올라가 시트벨트를 잡는다']::text[];
update public.techniques set steps = array['상대가 조르는 팔 쪽(내 오른쪽)으로 등을 바닥에 붙이며 빠지려 하면 시트벨트를 잡은 채 내 오른발 훅을 빼지 않고 버틴다','상대 등이 바닥에 닿으면 내 왼다리를 상대 배 위로 넘겨 상대 오른쪽 옆구리에 무릎을 댄다','상대 몸 아래에 있던 내 오른다리를 빼서 상대 왼쪽 옆구리에 무릎을 붙인다','엉덩이를 낮춰 마운트를 굳힌다']::text[] where slug = 'back-to-mount-transition' and owner_id is null and steps = array['상대가 등을 바닥에 붙이며 빠지려 하면 시트벨트를 잡은 채 아래쪽 훅을 빼지 않고 버틴다','상대 등이 바닥에 닿으면 위쪽 다리를 상대 배 위로 넘긴다','뒤에 있던 다리를 빼서 양 무릎을 상대 옆구리에 붙인다','엉덩이를 낮춰 마운트를 굳힌다']::text[];
update public.techniques set steps = array['백에서 내 오른팔을 상대 오른쪽 어깨 위로 넘겨 목을 감는다','오른손으로 내 왼팔 소매 안쪽(손목 부분)을 잡는다','소매가 잡힌 내 왼손의 손날을 상대 목 앞으로 가로질러 넣는다','가슴을 펴고 소매를 당기며 왼손 손날을 밀어 조인다']::text[] where slug = 'ezekiel-from-back' and owner_id is null and steps = array['백에서 한 팔을 상대 어깨 위로 넘겨 목을 감는다','그 손으로 반대쪽 팔 소매 안쪽(손목 부분)을 잡는다','소매가 잡힌 손의 손날을 상대 목 앞으로 가로질러 넣는다','가슴을 펴고 소매를 당기며 손날을 밀어 조인다']::text[];
update public.techniques set steps = array['양 무릎과 양 팔꿈치를 바닥에 대고 팔꿈치를 무릎에 붙여 틈을 없앤다','턱을 당기고 두 손으로 깃이나 목을 지켜 초크 그립을 막는다','팔을 밖으로 뻗지 않는다(팔이 나가면 크루시픽스에 걸린다)','상대가 내 왼쪽 옆에 붙으면 내 오른쪽으로 엉덩이를 빼며 다리를 상대 쪽으로 돌려 가드를 되찾는다']::text[] where slug = 'turtle-basics' and owner_id is null and steps = array['무릎과 팔꿈치를 바닥에 대고 팔꿈치를 무릎에 붙여 틈을 없앤다','턱을 당기고 두 손으로 깃이나 목을 지켜 초크 그립을 막는다','팔을 밖으로 뻗지 않는다(팔이 나가면 크루시픽스에 걸린다)','상대가 한쪽에 붙으면 반대쪽으로 엉덩이를 빼며 다리를 돌려 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대 왼쪽 옆에서 가슴을 등에 붙이고 시트벨트를 잡는다(내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 아래)','내 왼발을 상대 왼쪽 허벅지 안쪽에 훅으로 넣는다','시트벨트를 당기며 훅 넣은 내 왼쪽으로 함께 옆으로 눕는다','내 오른발도 상대 오른쪽 허벅지 안쪽에 넣어 백 컨트롤을 잡는다']::text[] where slug = 'turtle-back-take' and owner_id is null and steps = array['상대 옆에서 가슴을 등에 붙이고 손으로 목을 위협해 상대 팔꿈치를 들게 한다','가까운 무릎을 상대 팔꿈치와 무릎 사이에 쐐기처럼 넣는다','반대 손으로 상대 먼 쪽 골반을 당겨 내 쪽으로 붙이고 반대 다리로 상대 다리 뒤를 건다(첫 훅)','상대가 옆으로 넘어가면 나머지 훅을 넣고 시트벨트를 잡는다']::text[];
update public.techniques set steps = array['상대 왼쪽 옆에서 가슴을 상대 등에 싣고 양팔을 상대 몸 아래로 넣는다','내 왼손은 상대 오른쪽 팔꿈치(또는 손목), 내 오른손은 상대 오른쪽 무릎을 잡는다','두 곳을 내 쪽으로 당기며 어깨로 상대 왼쪽 옆구리를 밀어 상대 오른쪽으로 넘긴다','상대 등이 바닥에 닿으면 바로 가슴을 붙여 사이드 컨트롤을 잡는다']::text[] where slug = 'turtle-flatten' and owner_id is null and steps = array['터틀 옆에서 가까운 팔을 상대 가까운 겨드랑이 아래로 넣어 상대 손목을 잡는다','반대 손은 상대 가까운 무릎 뒤(오금)를 잡는다','손목을 내 쪽으로 당기고 무릎을 뽑아 상대를 내 쪽으로 굴린다','상대 등이 바닥에 닿으면 가슴을 붙여 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대 왼쪽 옆에서 내 왼손을 상대 목 아래로 넣어 상대 오른쪽 깃을 깊게 잡는다(손바닥이 위를 향하게)','내 오른손으로 상대 왼쪽 손목이나 소매를 잡아 팔을 못 쓰게 한다','가슴을 상대 등 위에 싣고 다리를 상대 머리 쪽으로 걸어 돈다(시계 바늘처럼)','체중으로 눌러 깃이 목을 조이게 한다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'clock-choke' and owner_id is null and steps = array['터틀 옆에서 가까운 손을 상대 목 아래로 넣어 먼 쪽 깃을 깊게 잡는다(손바닥이 위를 향하게)','반대 손으로 상대 가까운 손목이나 소매를 잡아 팔을 못 쓰게 한다','가슴을 상대 등 위에 싣고 다리를 상대 머리 쪽으로 걸어 돌린다(시계 바늘처럼)','체중으로 눌러 깃이 목을 조이게 한다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 옆에 있을 때 — 내 왼손으로 내 허리를 감은 상대 오른손목을 잡아 내 몸에 붙인다','내 오른손으로 바닥을 짚고 다리를 몸 아래로 앞으로 차 내며 엉덩이를 앉힌다','손목을 놓지 않고 내 왼쪽(상대 쪽)으로 몸을 돌려 들어간다','상대 옆이나 뒤에 붙어 탑 포지션을 잡는다']::text[] where slug = 'sit-out' and owner_id is null and steps = array['터틀에서 상대가 옆이나 뒤에 있을 때 가까운 쪽 손으로 상대 손목을 잡는다','반대 다리를 상대 반대편으로 길게 빼며 엉덩이를 바닥에 앉힌다','잡은 손목을 당기며 어깨로 상대 가슴을 밀어 뒤로 돌아간다','상대 뒤나 옆에 서서 백이나 탑 포지션으로']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 옆에 있을 때 — 상대 반대쪽인 내 오른쪽 어깨를 바닥에 대고 턱을 당긴다','엉덩이를 들어 내 오른쪽 어깨 위로 둥글게 구른다','구르는 동안 다리를 상대 쪽으로 돌려 상대 몸을 향하게 한다','다리가 상대 앞에 오면 가드(오픈 · 클로즈드)로 잡는다']::text[] where slug = 'granby-roll' and owner_id is null and steps = array['터틀에서 상대 반대쪽 어깨를 바닥에 대고 턱을 당긴다','엉덩이를 들어 어깨 위로 둥글게 구른다','구르는 동안 다리를 상대 쪽으로 돌려 상대 몸을 향하게 한다','다리가 상대 앞에 오면 가드(오픈 · 클로즈드)로 잡는다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 옆에 있을 때 — 내 왼손은 상대를 막고 오른손으로 바닥을 짚는다','내 왼발을 앞에 세운다','엉덩이를 들어 뒤로 빼며 내 오른다리를 뒤로 뺀다','두 발로 선 뒤 상대와 마주 보고 거리를 잡는다']::text[] where slug = 'standing-up-in-base' and owner_id is null and steps = array['터틀에서 상대 쪽 손은 상대를 막고 반대 손으로 바닥을 짚는다','짚은 손과 반대쪽 발을 앞에 세운다','엉덩이를 들어 뒤로 빼며 짚은 손 쪽 다리를 뒤로 뺀다','두 발로 선 뒤 상대와 마주 보고 거리를 잡는다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 옆에 있을 때 — 내 왼쪽 팔꿈치와 왼쪽 무릎을 붙여 훅이 들어올 틈을 막는다','상대 반대쪽인 내 오른쪽으로 엉덩이를 바닥에 앉힌다','내 왼다리를 돌려 무릎이 상대를 향하게 한다','양발을 상대 양쪽 골반에 올리고 프레임을 세워 오픈 가드를 잡는다']::text[] where slug = 'turtle-to-guard' and owner_id is null and steps = array['터틀에서 상대 쪽 팔꿈치와 무릎을 붙여 훅이 들어올 틈을 막는다','상대 반대쪽으로 엉덩이를 바닥에 앉힌다','상대 쪽 다리를 돌려 무릎이 상대를 향하게 한다','발을 상대 골반에 올리고 프레임을 세워 오픈 가드를 잡는다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 옆에 있을 때 — 턱을 당기고 상대 반대쪽인 내 오른쪽 어깨를 바닥에 댄다','엉덩이를 들어 내 오른쪽 어깨 너머로 구른다','구르면서 다리를 상대 쪽으로 돌린다','양발이 상대 앞에 오면 오픈 가드를 잡는다']::text[] where slug = 'rolling-to-guard' and owner_id is null and steps = array['터틀에서 턱을 당기고 상대 반대쪽 어깨를 바닥에 댄다','엉덩이를 들어 어깨 너머로 구른다','구르면서 다리를 상대 쪽으로 돌린다','발이 상대 앞에 오면 오픈 가드를 잡는다']::text[];
update public.techniques set steps = array['상대가 내 왼쪽 옆에 있을 때 — 내 왼손으로 상대 손목이나 팔을 잡는다','내 오른다리를 몸 아래로 통과시켜 상대 쪽(내 왼쪽)으로 길게 빼며 엉덩이를 바닥에 앉힌다','내 왼쪽(상대 쪽)으로 몸을 돌려 무릎이 상대를 향하게 한다','다리를 상대 앞에 두고 하프 가드나 오픈 가드를 잡는다']::text[] where slug = 'sit-through-to-guard' and owner_id is null and steps = array['터틀에서 상대 쪽 손으로 상대 손목이나 팔을 잡는다','먼 쪽 다리를 상대 쪽으로 길게 빼며 엉덩이를 바닥에 앉힌다','상대 쪽으로 몸을 돌려 무릎이 상대를 향하게 한다','다리를 상대 앞에 두고 하프 가드나 오픈 가드를 잡는다']::text[];
update public.techniques set steps = array['상대가 뒤에서 허리를 감으면 내 배 앞에 온 상대 오른손목을 잡아 내 배에 꽉 붙인다','내 오른다리로 상대 오른다리를 안쪽에서 건다','내 오른쪽 어깨를 바닥에 대고 내 오른쪽으로 구른다','상대 등이 바닥에 닿으면 몸을 돌려 사이드 컨트롤을 잡는다']::text[] where slug = 'peterson-roll' and owner_id is null and steps = array['상대가 뒤에서 허리를 감으면 그 손목을 잡아 내 배에 꽉 붙인다','잡은 팔 쪽 어깨를 바닥에 대고 그쪽으로 구른다','구르면서 상대가 내 위를 넘어가 등이 바닥에 닿는다','잡은 팔을 놓지 않은 채 몸을 돌려 사이드 컨트롤 탑을 잡는다']::text[];
update public.techniques set steps = array['상대가 뒤에 있을 때 턱을 당기고 머리를 숙인다','내 오른쪽 어깨를 바닥에 대고 앞으로 구른다','구르면서 다리를 상대 쪽으로 돌린다','앉은 자세에서 양발을 상대 앞에 두고 오픈 가드를 잡는다']::text[] where slug = 'forward-roll-from-turtle' and owner_id is null and steps = array['상대가 뒤에 있을 때 턱을 당기고 머리를 숙인다','한쪽 어깨를 바닥에 대고 앞으로 구른다','구르면서 다리를 상대 쪽으로 돌린다','앉은 자세에서 발을 상대 앞에 두고 오픈 가드를 잡는다']::text[];
update public.techniques set steps = array['상대 왼쪽 옆에서 가슴을 등에 붙이고 시트벨트를 잡는다(내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 아래)','내 왼발을 상대 왼쪽 허벅지 안쪽에 훅으로 넣는다','훅 쪽(내 왼쪽)으로 상대를 당겨 함께 옆으로 눕는다','내 오른발도 상대 오른쪽 허벅지 안쪽에 훅으로 넣어 백 컨트롤을 완성한다']::text[] where slug = 'turtle-to-back-control' and owner_id is null and steps = array['터틀 옆에서 가슴을 상대 등에 붙이고 시트벨트를 잡는다(한 팔은 어깨 위, 한 팔은 겨드랑이 아래)','가까운 발을 상대 허벅지 안쪽에 훅으로 넣는다','훅 쪽으로 상대를 당겨 내 쪽으로 눕힌다','반대 발도 훅으로 넣어 백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대 왼쪽 옆에서 시트벨트(내 오른팔 어깨 위 · 왼팔 겨드랑이 아래)를 잡고 가슴을 등에 붙인다','내 왼발을 상대 왼쪽 허벅지 안쪽에 훅으로 넣는다','머리를 상대 오른쪽 겨드랑이 아래로 넣으며 상대 오른쪽 방향으로 구른다','상대를 내 위로 함께 넘긴 뒤 내 오른발 훅을 상대 오른쪽 허벅지 안쪽에 넣어 백 컨트롤을 잡는다']::text[] where slug = 'rolling-back-take' and owner_id is null and steps = array['터틀 옆에서 가까운 팔로 상대 먼 쪽 겨드랑이를 언더훅하고 반대 손으로 허리띠나 허리를 잡는다','상대 등 너머로 어깨를 대고 구른다','구르면서 상대를 함께 넘겨 등 뒤에 자리 잡는다','훅을 넣고 시트벨트를 잡아 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['상대 왼쪽 옆에서 시트벨트를 잡고 내 왼발을 상대 왼쪽 허벅지 안쪽에 훅으로 넣는다','의자에 앉듯 상대 왼쪽 옆에 엉덩이를 내리며 상대를 내 왼쪽 허벅지 위로 당긴다','상대가 내 쪽으로 넘어오면 내 오른발도 상대 오른쪽 허벅지 안쪽에 넣는다','시트벨트를 유지한 채 백 컨트롤로 간다']::text[] where slug = 'chair-sit-to-back' and owner_id is null and steps = array['터틀 옆에서 시트벨트를 잡고 가까운 발을 상대 허벅지 안쪽에 훅으로 넣는다','의자에 앉듯 상대 옆에 엉덩이를 내리며 상대를 내 허벅지 위로 당긴다','상대가 내 쪽으로 넘어오면 반대 발도 훅으로 넣는다','시트벨트를 유지한 채 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['상대 왼쪽 옆에서 내 오른쪽 무릎을 상대 왼팔꿈치와 왼쪽 무릎 사이에 넣어 팔을 벌린다','상대 왼팔을 내 두 다리 사이에 끼우고 발을 걸어 가둔다','내 왼손으로 상대 오른팔(손목이나 팔꿈치)을 잡는다','상대 등 너머로 구르며 상대를 넘겨 내 등이 바닥에 닿게 한다','다리로 상대 왼팔, 손으로 상대 오른팔을 잡은 채 크루시픽스를 완성한다']::text[] where slug = 'crucifix-from-turtle' and owner_id is null and steps = array['터틀 옆에서 가까운 무릎을 상대 팔꿈치와 무릎 사이에 넣어 팔을 벌린다','그 팔을 내 두 다리 사이에 끼우고 발을 걸어 가둔다','반대 손으로 상대 먼 쪽 팔(손목이나 팔꿈치)을 잡는다','상대 등 너머로 구르며 상대를 넘겨 내 등이 바닥에 닿게 한다','다리로 한 팔, 손으로 반대 팔을 잡은 채 크루시픽스를 완성한다']::text[];
update public.techniques set steps = array['크루시픽스에서 상대 왼팔은 내 다리로, 오른팔은 내 왼손으로 가둔 상태를 유지한다','내 오른손을 상대 턱 아래로 넣어 상대 오른쪽 깃(노기는 팔뚝)을 깊게 잡는다','가슴을 펴고 등을 뒤로 눕히며 상대 턱을 올린다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'choke-from-crucifix' and owner_id is null and steps = array['크루시픽스에서 상대 한 팔은 다리로, 다른 팔은 손으로 가둔 상태를 유지한다','자유로운 손을 상대 턱 아래로 넣어 깃(노기는 팔뚝)을 깊게 잡는다','가슴을 펴고 등을 뒤로 눕히며 상대 턱을 올린다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['크루시픽스에서 다리로 가둔 상대 왼팔의 팔꿈치가 내 허벅지 사이에 오게 한다','양 무릎을 모아 상대 왼팔을 꽉 끼운다','다리를 천천히 뻗으며 엉덩이를 밀어 상대 왼팔꿈치를 편다','탭하면 바로 푼다']::text[] where slug = 'armbar-from-crucifix' and owner_id is null and steps = array['크루시픽스에서 다리로 가둔 상대 팔의 팔꿈치가 내 허벅지 사이에 오게 한다','무릎을 모아 팔을 꽉 끼운다','다리를 천천히 뻗으며 엉덩이를 밀어 팔꿈치를 편다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대 오른팔을 내 다리로 가둔 크루시픽스에서 내 왼손으로 상대 왼쪽 손목을 잡는다','내 오른팔을 상대 왼팔 아래로 넣어 내 왼손목을 잡는다(8자 그립)','상대 왼쪽 팔꿈치가 90도로 굽은 상태를 유지한다','상대 왼쪽 손목을 상대 등 쪽으로 천천히 돌리며 조인다','탭하면 바로 푼다']::text[] where slug = 'kimura-from-crucifix' and owner_id is null and steps = array['크루시픽스에서 손으로 잡고 있던 상대 팔의 손목을 한 손으로 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치가 90도로 굽은 상태를 유지한다','손목을 상대 등 쪽으로 천천히 돌리며 조인다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 내 오른팔을 다리로 가두면 오른쪽 팔꿈치를 굽혀 오른손을 내 몸에 붙인다','상대가 있는 내 오른쪽으로 몸을 돌리며 오른쪽 무릎을 바닥에 댄다','상대 다리에 끼인 내 오른팔을 아래로 빼며 터틀로 돌아간다','엉덩이를 내 왼쪽으로 빼고 다리를 상대 쪽으로 돌려 가드를 되찾는다']::text[] where slug = 'escape-crucifix' and owner_id is null and steps = array['가둬진 팔의 팔꿈치를 굽혀 몸 쪽으로 당기고 손을 내 몸에 붙인다','상대 쪽으로 몸을 돌리며 가까운 무릎을 바닥에 댄다','다리에 끼인 팔을 아래로 빼며 터틀로 돌아간다','엉덩이를 빼고 다리를 돌려 가드를 되찾는다']::text[];
update public.techniques set steps = array['터틀 상대 오른쪽 옆에서 내 오른팔을 상대 오른쪽 겨드랑이 아래로 넣어 목 왼쪽까지 깊게 꿴다','꿴 오른손으로 내 왼팔 이두를 잡고 내 왼손은 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 아래로 누르며 내 가슴을 상대 오른쪽 어깨에 싣는다','다리를 상대 머리 쪽으로 걸어 돌며 가슴을 조여 마무리한다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'darce-from-turtle' and owner_id is null and steps = array['터틀 상대 옆에서 상대 가까운 팔 아래로 내 팔을 넣어 목 반대편까지 깊게 꿰어 넣는다','꿰어 넣은 손으로 반대 팔의 이두를 잡고 반대 손은 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 아래로 누르며 가슴을 상대 어깨에 싣는다','다리를 상대 머리 쪽으로 걸어 돌며 가슴을 조여 마무리한다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['터틀 상대 앞에서 내 오른팔을 상대 목 아래로 넣어 상대 오른쪽 겨드랑이 아래로 뺀다','뺀 오른손으로 내 왼팔 이두를 잡고 내 왼손은 상대 등에 올린다(8자 그립)','갇힌 상대 왼팔 쪽(내 오른쪽)으로 오른쪽 어깨를 대고 구르며 상대를 옆으로 넘긴다','무릎으로 상대 쪽으로 걸어 들어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'anaconda-from-turtle' and owner_id is null and steps = array['터틀 상대 앞에서 한 팔을 상대 목 아래로 넣어 반대쪽 겨드랑이 아래로 뺀다','뺀 손으로 반대 팔의 이두를 잡고 그 손은 상대 등에 올린다(8자 그립)','상대 팔이 갇힌 쪽으로 구르며 상대를 옆으로 넘긴다','무릎으로 상대 쪽으로 걸어 들어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['터틀 상대 앞에서 상대 머리를 내 오른쪽 겨드랑이 아래로 당겨 오른팔로 목을 감는다(턱 아래에 손목)','내 왼손으로 내 오른쪽 손목을 잡는다','엉덩이를 뒤로 빼며 상대를 당겨 앉히거나 뒤로 눕는다','두 다리로 상대 허리를 감고 가슴을 펴며 오른쪽 팔꿈치를 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'guillotine-from-turtle' and owner_id is null and steps = array['터틀 상대 앞에서 상대 머리를 겨드랑이 아래로 당겨 팔로 목을 감는다(턱 아래에 손목이 오게)','반대 손으로 감은 손의 손목을 잡는다','엉덩이를 뒤로 빼며 상대를 당겨 앉히거나 뒤로 눕는다','다리로 상대 허리를 감고 가슴을 펴며 팔꿈치를 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['터틀 상대 앞에서 내 오른손으로 상대 오른쪽 깃(내 왼쪽에 보이는 깃)을 깊게 잡는다','내 왼손으로 상대 뒤통수를 눌러 머리를 내 오른쪽 겨드랑이 아래로 넣는다','깃 잡은 오른쪽 팔꿈치를 상대 목 뒤로 넘겨 고리를 만든다','내 오른쪽 어깨를 바닥에 대고 상대 몸 아래로 구르며 깃을 당긴다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'loop-choke-from-turtle' and owner_id is null and steps = array['터틀 상대 앞에서 한 손으로 상대 깃을 잡는다(네 손가락 안쪽)','상대 머리를 내 겨드랑이 아래로 눌러 넣으며 깃 잡은 팔로 목을 감는다','반대 팔을 상대 겨드랑이 아래로 넣어 머리 뒤를 받친다','깃을 당기며 몸을 옆으로 돌려 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['터틀 상대 오른쪽 옆에서 내 왼손으로 상대 오른쪽 손목을 잡는다','내 오른팔을 상대 등 위로 넘겨 상대 오른팔 아래로 넣고 내 왼손목을 잡는다(8자 그립)','상대를 상대 오른쪽 어깨 쪽으로 굴려 등이 바닥에 닿게 한다','상대 오른쪽 팔꿈치를 90도로 유지하며 손을 등 쪽으로 천천히 돌려 조인다','탭하면 바로 푼다']::text[] where slug = 'kimura-from-turtle' and owner_id is null and steps = array['터틀 상대 옆에서 상대 손목을 한 손으로 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대를 옆으로 굴려 등이 바닥에 닿게 한다','팔꿈치를 90도로 유지하며 손을 등 쪽으로 천천히 돌려 조인다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽 옆에 있을 때, 터틀에서 두 팔로 상대 오른다리를 감싸 가슴에 붙인다','내 머리를 상대 오른쪽 옆구리에 붙이고 내 오른발을 바닥에 세운다','상대 오른다리를 잡은 채 베이스를 잡고 일어선다','상대 오른다리를 들어 올려 넘어뜨리고 탑 포지션을 잡는다']::text[] where slug = 'single-leg-from-turtle' and owner_id is null and steps = array['터틀에서 상대 가까운 다리를 두 팔로 감싸 가슴에 붙인다','머리를 상대 옆구리에 붙이고 한 발을 세운다','다리를 잡은 채 베이스를 잡고 일어선다','상대 다리를 들어 올려 넘어뜨리고 탑 포지션을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 등 뒤에서 내 오른쪽 허벅지 안에 훅을 넣으면 왼쪽 팔꿈치를 왼쪽 무릎에 붙여 두 번째 훅을 막는다','내 오른손으로 훅 들어온 상대 오른발을 잡아 내 오른쪽 무릎 아래로 밀어 낸다','훅이 빠지면 상대 몸에서 먼 내 왼쪽으로 엉덩이를 앉힌다','다리를 상대 쪽으로 돌려 가드를 되찾는다']::text[] where slug = 'clear-hook-from-turtle' and owner_id is null and steps = array['상대가 훅을 넣으면 그쪽 팔꿈치를 무릎에 붙여 두 번째 훅을 막는다','손으로 훅 들어온 발을 잡아 무릎 아래로 밀어 낸다','훅이 빠지면 상대 반대쪽으로 엉덩이를 앉힌다','다리를 돌려 가드를 되찾는다']::text[];
update public.techniques set steps = array['상대 머리가 내려오면 내 오른팔로 턱 아래를 감고 내 왼손으로 상대 오른쪽 팔꿈치(삼두)를 잡는다','가슴으로 상대 머리를 누르고 상대 이마가 바닥을 보게 한다','엉덩이를 뒤로 빼고 두 발을 넓게 벌려 상대가 다리를 못 잡게 한다','백 테이크 · 길로틴 · 아나콘다 · 다스로 이어 간다']::text[] where slug = 'front-headlock' and owner_id is null and steps = array['상대 머리가 아래로 내려오면 한 팔로 턱 아래를 감고 반대 손으로 상대 팔꿈치(삼두)를 잡는다','가슴으로 상대 머리를 누르고 상대 이마가 바닥을 보게 한다','엉덩이를 뒤로 빼고 발을 넓게 벌려 상대가 다리를 못 잡게 한다','백 테이크 · 길로틴 · 아나콘다 · 다스로 이어 간다']::text[];
update public.techniques set steps = array['프론트 헤드락에서 상대 오른쪽 삼두를 잡은 내 왼손으로 그 팔을 내 쪽으로 당긴다','내 오른팔로 머리를 누른 채 내 왼쪽(상대 오른쪽 옆)으로 돌아 들어간다','상대 등 뒤에서 시트벨트를 잡는다','두 발로 훅을 넣고 백 컨트롤로 간다']::text[] where slug = 'front-headlock-to-back' and owner_id is null and steps = array['프론트 헤드락에서 상대 팔꿈치를 잡은 손으로 그 팔을 내 쪽으로 당긴다','머리를 누른 채 잡은 팔 쪽으로 돌아 상대 옆으로 간다','상대 등 뒤에서 시트벨트를 잡는다','훅을 넣고 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['프론트 헤드락에서 목을 감은 내 오른팔의 손목이 상대 턱 아래로 오게 더 깊게 넣는다','내 왼손으로 내 오른쪽 손목을 잡아 그립을 완성한다','엉덩이를 뒤로 빼며 상대를 당겨 앉히거나 가드로 끌어들인다','오른쪽 팔꿈치를 내 몸에 붙이고 길로틴 컨트롤을 유지한다']::text[] where slug = 'guillotine-setup' and owner_id is null and steps = array['프론트 헤드락에서 목을 감은 손의 손목이 상대 턱 아래로 오게 더 깊게 넣는다','반대 손으로 그 손목을 잡아 그립을 완성한다','엉덩이를 뒤로 빼며 상대를 당겨 앉히거나 가드로 끌어들인다','팔꿈치를 몸에 붙이고 길로틴 컨트롤을 유지한다']::text[];
update public.techniques set steps = array['오른팔로 목을 감고 왼손으로 오른손목을 잡은 그립에서 오른쪽 팔꿈치를 몸에 붙인다','뒤로 눕지 말고 목을 감은 오른팔 쪽(내 오른쪽)으로 몸을 튼다','두 다리로 상대 허리를 감는다','가슴을 펴고 오른쪽 팔꿈치를 당기며 체중으로 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'guillotine-choke-finish' and owner_id is null and steps = array['그립을 잡고 팔꿈치를 몸에 붙인다','뒤로 눕지 말고 목을 감은 팔 쪽으로 몸을 튼다','다리로 상대 허리를 감는다','가슴을 펴고 팔꿈치를 당기며 체중으로 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['내 오른팔로 목을 감아 오른손목이 상대 턱 아래 목 앞에 오게 깊게 넣는다','내 왼팔을 상대 오른쪽 어깨 위로 넘겨 내 오른손을 잡는다','오른쪽 팔꿈치를 높게 들어 상대 머리 뒤쪽으로 넘긴다','두 다리로 상대 허리를 감고 오른손목을 위로 당기며 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'high-elbow-guillotine' and owner_id is null and steps = array['목을 감은 팔의 손목이 턱 아래에 오게 깊게 넣는다','반대 팔을 상대 어깨 위로 넘겨 팔꿈치를 높게 세우고 두 손을 손목 그립으로 맞잡는다','높게 올린 팔꿈치로 상대 뒤통수를 아래로 누른다','다리로 상대 허리를 감고 목을 감은 팔 쪽으로 몸을 틀어 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['내 오른팔로 상대 머리와 상대 왼팔을 함께 감아 오른손목이 목 아래 깊이 들어가게 한다','내 왼손으로 내 오른쪽 손목을 잡고 오른쪽 팔꿈치를 높이 든다','두 다리로 상대 허리를 감아 상대가 뒤로 빠지지 못하게 한다','가슴을 펴고 오른쪽 팔꿈치를 내 몸 쪽으로 당기며 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'arm-in-guillotine' and owner_id is null and steps = array['상대 한 팔과 머리를 함께 감아 손목이 턱 아래에 오게 한다','반대 손으로 그 손목을 잡는다','갇힌 팔 쪽으로 몸을 틀어 눕고 다리로 상대 허리를 감는다','가슴을 펴고 팔꿈치를 당기며 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대 목을 감은 내 오른손과 왼손을 열 손가락으로 깍지 끼듯 맞잡는다','두 팔꿈치를 모아 상대 머리를 내 가슴에 붙인다','오른쪽 손목 날로 상대 턱을 위로 들어 올리며 가슴을 편다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'ten-finger-guillotine' and owner_id is null and steps = array['목을 감은 손과 반대 손을 열 손가락으로 깍지 끼듯 맞잡는다','팔꿈치를 모아 상대 머리를 내 가슴에 붙인다','손목 날로 상대 턱을 위로 들어 올리며 가슴을 편다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 목을 감으면 턱을 당기고 두 손으로 상대 오른쪽 손목을 잡아 목에서 떼어 낸다','내 왼팔을 상대 오른쪽 어깨 너머로 넘겨 상대 등을 감싼다','내 왼쪽 어깨로 상대 턱 아래를 누르며 허리를 세운다','내 왼쪽(상대 오른쪽)으로 돌아 상대 옆으로 빠져 사이드 컨트롤을 잡는다']::text[] where slug = 'guillotine-defense' and owner_id is null and steps = array['턱을 당기고 두 손으로 상대 손목을 잡아 목에서 떼어 낸다','머리가 끼인 쪽 팔을 상대 어깨 너머로 넘겨 등을 감싼다','그 어깨로 상대 턱 아래를 누르며 허리를 세운다','같은 쪽으로 돌아 상대 옆으로 빠져 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대가 오른팔로 내 목을 감으면 턱을 당기고 두 손으로 상대 오른쪽 손목을 잡아 아래로 당긴다','엉덩이를 뒤로 빼며 머리를 상대 오른쪽 겨드랑이에서 뽑아낸다','앉으며 두 다리를 상대 앞에 둔다','오픈 가드나 버터플라이 가드를 잡는다']::text[] where slug = 'guard-recovery-from-guillotine' and owner_id is null and steps = array['턱을 당기고 두 손으로 상대 손목을 잡아 아래로 당긴다','엉덩이를 뒤로 빼며 머리를 겨드랑이에서 뽑아낸다','앉으며 다리를 상대 앞에 둔다','오픈 가드나 버터플라이 가드를 잡는다']::text[];
update public.techniques set steps = array['프론트 헤드락에서 내 오른팔을 상대 목 아래로 넣어 상대 오른쪽 겨드랑이 아래로 뺀다','뺀 오른손으로 내 왼팔 이두를 잡고 내 왼손은 상대 등에 올린다(8자 그립)','갇힌 상대 왼팔 쪽(내 오른쪽)으로 오른쪽 어깨를 대고 구르며(게이터 롤) 상대를 넘긴다','무릎으로 상대 쪽으로 걸어 들어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'anaconda-choke' and owner_id is null and steps = array['프론트 헤드락에서 팔을 상대 목 아래로 넣어 반대쪽 겨드랑이 아래로 뺀다','뺀 손으로 반대 팔의 이두를 잡고 그 손은 상대 등에 올린다(8자 그립)','갇힌 팔 쪽으로 구르며(게이터 롤) 상대를 옆으로 넘긴다','무릎으로 상대 쪽으로 걸어 들어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['아나콘다가 안 조이면 억지로 조이지 말고 그립을 푼다','내 왼손으로 상대 오른쪽 삼두를 잡고 내 오른팔로 머리를 누르며 무릎으로 일어난다','머리를 누른 채 내 왼쪽(상대 오른쪽 옆)으로 돌아간다','사이드 컨트롤이나 남북으로 자리 잡는다']::text[] where slug = 'anaconda-to-side-control' and owner_id is null and steps = array['아나콘다가 안 조이면 억지로 조이지 말고 그립을 푼다','자유로운 손으로 상대 삼두(팔꿈치)를 잡고 머리를 눌러 무릎으로 일어난다','머리를 누른 채 상대 옆으로 돌아간다','사이드 컨트롤이나 남북으로 자리 잡는다']::text[];
update public.techniques set steps = array['상대 아나콘다에 내 왼팔이 갇히면 턱을 당기고 왼쪽 팔꿈치를 몸에 붙여 조일 공간을 없앤다','자유로운 내 오른손으로 상대 왼쪽 골반을 밀어 프레임을 세운다','뒤로 빼지 말고 상대 쪽으로 걸어 들어가며 허리를 세운다','상대가 구르려 하면 같은 방향(내 왼쪽)으로 따라 돌아 머리를 뽑아낸다']::text[] where slug = 'frame-and-posture-from-anaconda' and owner_id is null and steps = array['턱을 당기고 갇힌 팔의 팔꿈치를 몸에 붙여 조일 공간을 없앤다','자유로운 손으로 상대 골반을 밀어 프레임을 세운다','뒤로 빼지 말고 상대 쪽으로 걸어 들어가며 허리를 세운다','상대가 구르려 하면 같은 방향으로 따라 돌아 머리를 뽑아낸다']::text[];
update public.techniques set steps = array['내 오른팔을 상대 왼쪽 겨드랑이 아래로 넣어 상대 목 오른쪽까지 깊게 꿰어 넣는다','꿴 오른손으로 내 왼팔 이두를 잡고 내 왼손은 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 아래로 누르며 내 가슴을 상대 왼쪽 어깨에 싣는다','엉덩이를 바닥에 내리고 상대 머리 쪽으로 걸어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'darce-choke-front-headlock' and owner_id is null and steps = array['상대 한 팔 아래로 내 팔을 넣어 목 반대편까지 깊게 꿰어 넣는다','꿰어 넣은 손으로 반대 팔의 이두를 잡고 그 손을 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 아래로 누르며 가슴을 상대 어깨에 싣는다','엉덩이를 바닥에 내리고 상대 머리 쪽으로 걸어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['다스가 안 조이면 그립을 풀고 상대 왼쪽 겨드랑이에 꿰었던 내 오른팔을 뺀다','내 오른팔을 상대 목 아래로 다시 넣어 상대 오른쪽 겨드랑이 아래로 뺀다','뺀 오른손으로 내 왼팔 이두를 잡아 8자 그립을 만든다','갇힌 상대 왼팔 쪽(내 오른쪽)으로 구르며 아나콘다로 조인다']::text[] where slug = 'darce-to-anaconda-switch' and owner_id is null and steps = array['다스가 안 조이면 그립을 풀고 꿰었던 팔을 뺀다','팔을 상대 목 아래로 다시 넣어 반대쪽 겨드랑이 아래로 뺀다','뺀 손으로 반대 팔 이두를 잡아 8자 그립을 만든다','갇힌 팔 쪽으로 구르며 아나콘다로 조인다']::text[];
update public.techniques set steps = array['상대 다스에 내 왼팔이 갇히면 턱을 당기고 왼쪽 팔꿈치를 내 몸에 붙인다','자유로운 내 오른팔로 상대 골반이나 허벅지를 밀어 프레임을 세운다','엉덩이를 상대에게서 멀리 빼며 공간을 만든다','허리를 세우며 머리와 갇힌 왼팔을 뽑아낸다','내 오른쪽 무릎을 상대 몸 앞에 넣어 하프 가드나 오픈 가드를 잡는다']::text[] where slug = 'frame-escape-from-darce' and owner_id is null and steps = array['턱을 당기고 갇힌 팔로 상대 골반이나 허벅지를 밀어 프레임을 세운다','상대가 눕는 쪽 반대로 엉덩이를 뺀다','허리를 세우며 머리를 뽑아낸다','하프 가드나 오픈 가드를 잡는다']::text[];
update public.techniques set steps = array['상대 다스에 내 왼팔이 갇히면 턱을 당기고 자유로운 오른손으로 상대 왼쪽 골반을 짚는다','골반을 밀며 내 몸을 상대 쪽으로 돌린다','머리를 낮춰 상대 오른팔(조르는 팔) 뒤쪽 빈틈으로 밀어 넣는다','머리가 빠지면 갇힌 왼팔도 빼고 상대 등 뒤로 돌아 나온다','일어나 위 자세를 잡는다']::text[] where slug = 'back-door-escape-darce' and owner_id is null and steps = array['상대가 조이기 전 턱을 당기고 갇힌 팔로 상대 허벅지를 민다','상대 다리 아래쪽(백 도어)으로 몸을 낮춰 빠져나간다','머리를 뽑아내며 상대 뒤로 나온다','일어나 탑 포지션을 잡는다']::text[];
update public.techniques set steps = array['상대 오른팔을 상대 머리 쪽으로 밀어 올려 그 팔과 머리를 함께 감는다','내 오른팔을 상대 목 아래로 넣고 두 손을 손바닥끼리 맞잡는다','상대를 옆으로 눕히고 갇힌 오른팔 반대쪽인 상대 왼쪽으로 내려온다','두 발을 넓게 벌리고 내 오른쪽 어깨로 상대 머리를 밀며 가슴을 낮춰 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'arm-triangle-from-front-headlock' and owner_id is null and steps = array['프론트 헤드락에서 상대 한 팔을 머리 쪽으로 밀어 올려 팔과 머리를 함께 감는다','목 아래로 팔을 넣고 손을 맞잡는다(손바닥끼리)','상대를 옆으로 눕히고 머리 쪽으로 돌아 발을 넓게 벌린다','어깨로 상대 머리를 밀며 가슴을 낮춰 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['프론트 헤드락에서 내 왼손으로 상대 오른쪽 손목을 잡는다','내 오른팔을 상대 등 위로 넘겨 상대 오른팔 아래로 넣고 내 왼손목을 잡는다(8자 그립)','상대를 상대 오른쪽 어깨 쪽으로 굴려 등이 바닥에 닿게 한다','상대 오른쪽 팔꿈치를 90도로 유지하며 손을 등 쪽으로 천천히 돌려 조인다','탭하면 바로 푼다']::text[] where slug = 'kimura-from-front-headlock' and owner_id is null and steps = array['프론트 헤드락에서 상대 손목을 한 손으로 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대를 옆으로 굴려 등이 바닥에 닿게 한다','팔꿈치를 90도로 유지하며 손을 등 쪽으로 천천히 돌려 조인다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 오른팔로 머리를 감으면 두 손으로 상대 오른쪽 손목을 잡아 그립을 막는다','턱을 당기고 허리를 세운다','감은 오른팔 반대쪽인 내 오른쪽(상대 왼쪽, 팔꿈치가 열린 쪽)으로 돌며 머리를 뽑아낸다','거리를 벌리고 자세를 다시 잡는다']::text[] where slug = 'stand-and-circle-away' and owner_id is null and steps = array['상대가 머리를 감으면 두 손으로 상대 손목을 잡아 그립을 막는다','턱을 당기고 허리를 세운다','목을 감은 팔 반대쪽(팔꿈치가 열린 쪽)으로 돌며 머리를 뽑아낸다','거리를 벌리고 자세를 다시 잡는다']::text[];
update public.techniques set steps = array['상대가 오른팔로 머리를 감으면 내 오른손으로 상대 오른쪽 팔꿈치(삼두)를 잡는다','그 팔꿈치를 내 오른쪽으로 끌어내며 머리를 뽑아낸다','상대 오른쪽 옆(내 왼쪽)으로 돌아가거나 앉으며 다리를 상대 앞에 둔다','오픈 가드나 백을 잡는다']::text[] where slug = 'arm-drag-escape-front-headlock' and owner_id is null and steps = array['상대가 머리를 감으면 그 팔의 팔꿈치(삼두)를 반대 손으로 잡는다','팔꿈치를 옆으로 끌어내며 머리를 뽑아낸다','상대 옆으로 돌아가거나 앉으며 다리를 상대 앞에 둔다','오픈 가드나 백을 잡는다']::text[];
update public.techniques set steps = array['상대가 오른팔로 머리를 감으면 두 손으로 상대 오른쪽 손목을 잡아 그립을 막고 턱을 당긴다','엉덩이를 뒤로 빼며 머리를 상대 오른쪽 겨드랑이에서 뽑아낸다','앉으며 두 다리를 상대 앞에 둔다','오픈 가드를 잡는다']::text[] where slug = 'hip-escape-from-front-headlock' and owner_id is null and steps = array['두 손으로 상대 손목을 잡아 그립을 막고 턱을 당긴다','엉덩이를 뒤로 빼며 머리를 뽑아낸다','앉으며 다리를 상대 앞에 둔다','오픈 가드를 잡는다']::text[];
update public.techniques set steps = array['상대가 오른팔로 머리를 감으면 두 손으로 상대 오른쪽 손목을 잡아 내 가슴에 붙인다','감긴 팔 쪽인 내 왼쪽 어깨를 바닥에 대고 상대 쪽으로 구른다','구르면서 상대가 내 위를 넘어가 등이 바닥에 닿는다','위로 올라와 사이드 컨트롤이나 프론트 헤드락을 잡는다']::text[] where slug = 'roll-through-to-reversal' and owner_id is null and steps = array['상대가 머리를 감으면 그 팔의 손목을 잡아 내 가슴에 붙인다','감긴 팔 쪽 어깨를 바닥에 대고 상대 쪽으로 구른다','구르면서 상대가 내 위를 넘어가 등이 바닥에 닿는다','위로 올라와 사이드 컨트롤이나 프론트 헤드락을 잡는다']::text[];
update public.techniques set steps = array['프론트 헤드락에서 내 오른팔로 상대 목과 상대 왼팔을 함께 감고 두 손을 맞잡는다','갇힌 상대 왼팔 쪽에 있는 내 오른다리를 상대 등 위로 넘겨 올린다','내 왼다리는 상대 머리 뒤로 걸친 채 뒤로 앉는다','두 다리를 모으며 그립을 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'peruvian-necktie' and owner_id is null and steps = array['프론트 헤드락에서 상대 목과 한 팔을 함께 감고 손을 맞잡는다','감은 팔 쪽 다리를 상대 등 위로 넘겨 올린다','반대 다리는 상대 머리 뒤로 걸친 채 뒤로 앉는다','다리를 모으며 그립을 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['다스처럼 내 오른팔을 상대 왼쪽 겨드랑이 아래로 넣어 목까지 꿰고 내 왼팔 이두를 잡는다','그립을 잡은 채 내 오른쪽 옆구리를 바닥에 대고 상대 옆으로 눕는다','위쪽에 있는 내 왼다리를 상대 등 위로 넘겨 허리를 누른다','몸을 둥글게 말며 상대 머리를 아래로 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'japanese-necktie' and owner_id is null and steps = array['다스처럼 상대 팔 아래로 팔을 넣어 목까지 꿰고 반대 팔의 이두를 잡는다','그립을 잡은 채 상대 옆으로 눕는다','위쪽 다리를 상대 등 위로 넘겨 허리를 누른다','몸을 둥글게 말며 머리를 아래로 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 태클을 들어오면 스프롤로 두 다리를 뒤로 빼고 가슴으로 상대 등을 누른다','내 오른팔을 상대 왼쪽 겨드랑이 아래로 넣어 상대 목 오른쪽까지 깊게 꿰어 넣는다','꿴 오른손으로 내 왼팔 이두를 잡고 내 왼손은 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 누르며 엉덩이를 내리고 머리 쪽으로 걸어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'darce-from-sprawl' and owner_id is null and steps = array['상대가 태클을 들어오면 스프롤로 다리를 뒤로 빼고 가슴으로 상대 등을 누른다','상대 팔 아래로 내 팔을 넣어 목 반대편까지 깊게 꿰어 넣는다','꿰어 넣은 손으로 반대 팔의 이두를 잡고 그 손은 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 누르며 엉덩이를 내리고 머리 쪽으로 걸어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 오른팔로 머리를 감으면 두 손으로 상대 오른쪽 손목을 잡아 목에서 떼어 낸다','턱을 당기고 얼굴을 상대 오른쪽 팔꿈치가 열린 쪽(내 왼쪽)으로 돌린다','내 왼쪽 어깨를 밀어 넣으며 머리를 상대 오른쪽 겨드랑이 밖으로 뽑아낸다','상대 오른쪽 옆이나 등 뒤로 돌아가 자리를 잡는다']::text[] where slug = 'peek-out-escape' and owner_id is null and steps = array['상대가 머리를 감으면 두 손으로 상대 손목을 잡아 목에서 떼어 낸다','턱을 당기고 얼굴을 상대 팔꿈치가 열린 쪽으로 돌린다','같은 쪽 어깨를 밀어 넣으며 머리를 겨드랑이 밖으로 뽑아낸다','상대 옆이나 뒤로 돌아가 자리를 잡는다']::text[];
update public.techniques set steps = array['두 손으로 상대 오른쪽 손목을 엄지가 천장으로 가게 잡고 오른팔을 내 가슴에 붙인다','두 무릎을 모아 상대 오른쪽 팔꿈치를 가둔다','두 뒤꿈치를 당겨 상대를 내 몸 쪽으로 조인다','엉덩이를 천천히 들어 상대 오른쪽 팔꿈치를 편다','탭하면 바로 푼다']::text[] where slug = 'armbar-finish' and owner_id is null and steps = array['상대 팔을 가슴에 붙이고 엄지가 위(천장)로 가게 손목을 잡는다','무릎을 모아 팔꿈치를 가둔다','뒤꿈치를 당겨 상대를 내 몸 쪽으로 조인다','엉덩이를 천천히 들어 팔꿈치를 편다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대 오른팔 암바에서 상대가 돌며 방어하면 오른팔을 놓지 않고 같이 돌아 엎드린다','두 무릎을 모은 채 상대 오른팔을 내 가슴에 붙인다','머리를 들고 엉덩이를 천천히 밀어 상대 오른쪽 팔꿈치를 편다','탭하면 바로 푼다']::text[] where slug = 'belly-down-armbar' and owner_id is null and steps = array['암바 자세에서 상대가 돌며 방어하면 팔을 놓지 않고 같이 돌아 엎드린다','무릎을 모은 채 상대 팔을 가슴에 붙인다','머리를 들고 엉덩이를 천천히 밀어 팔꿈치를 편다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 내 오른팔에 암바를 걸면 왼손으로 오른손을 맞잡거나 오른팔을 감싸 팔꿈치를 굽힌다','상대 다리 위로 체중을 실어 일어난다(스택)','내 오른쪽 팔꿈치를 돌려 상대 두 다리 사이로 빼낸다','가드 안으로 돌아간다']::text[] where slug = 'armbar-defense' and owner_id is null and steps = array['손을 맞잡거나 내 팔을 감싸 팔꿈치를 굽힌다','상대 다리 위로 체중을 실어 일어난다(스택)','팔꿈치를 돌려 상대 다리 사이로 빼낸다','가드 안으로 돌아간다']::text[];
update public.techniques set steps = array['상대가 내 오른팔에 암바를 걸면 오른손 엄지를 상대 다리 쪽(아래)으로 돌린다','엄지 방향으로 몸을 돌리며 상대 다리 쪽으로 구른다','내 오른쪽 팔꿈치가 상대 골반에서 벗어나면 오른팔을 빼낸다','위로 올라와 탑 포지션을 잡는다']::text[] where slug = 'hitchhiker-escape' and owner_id is null and steps = array['암바 걸린 팔의 엄지를 상대 다리 쪽(아래)으로 돌린다','엄지 방향으로 몸을 돌리며 상대 다리 쪽으로 구른다','팔꿈치가 상대 골반에서 벗어나면 팔을 빼낸다','위로 올라와 탑 포지션을 잡는다']::text[];
update public.techniques set steps = array['상대 오른팔 암바에서 상대가 팔을 빼며 내 쪽으로 돌면 다리를 풀고 상대 등 뒤로 돈다','허리띠를 잡거나 내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 아래로 시트벨트를 잡는다','두 발로 훅을 넣는다','백 컨트롤을 완성한다']::text[] where slug = 'back-take-from-armbar' and owner_id is null and steps = array['상대가 팔을 빼며 내 쪽으로 돌면 다리를 풀고 상대 등 뒤로 돈다','허리띠나 시트벨트를 잡는다','훅을 넣는다','백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대 오른팔 암바가 안 펴지면 상대 머리 위에 있던 내 왼다리를 상대 목 뒤로 돌린다','내 오른쪽 무릎을 내 왼쪽 발목 위에 걸어 삼각형을 만든다','두 손으로 상대 머리를 당기고 각도를 만든다','두 무릎을 모으며 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'triangle-from-armbar' and owner_id is null and steps = array['암바가 안 펴지면 상대 머리 위에 있던 다리를 상대 목 뒤로 돌린다','반대 다리로 그 발목 위에 무릎을 걸어 삼각형을 만든다','상대 머리를 당기고 각도를 만든다','무릎을 모으며 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 손을 맞잡아 오른팔을 굽히면 내 왼손으로 상대 오른쪽 손목을 잡는다','내 오른팔을 상대 오른팔 아래로 넣어 내 왼손목을 잡는다(8자 그립)','상대 오른쪽 팔꿈치를 내 가슴에 붙인 채 앉아 올라온다','상대 오른손을 등 쪽으로 천천히 돌리고 탭하면 바로 푼다']::text[] where slug = 'kimura-from-armbar-control' and owner_id is null and steps = array['상대가 손을 맞잡아 방어하면 위쪽 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','앉아 올라오며 상대 팔을 등 쪽으로 돌린다','천천히 돌리고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대 오른팔 암바가 막히면 상대 머리 위에 있던 내 왼다리를 상대 오른쪽 어깨 뒤로 돌려 팔을 감는다','상대 쪽으로 앉아 올라온다','내 오른팔로 상대 허리를 감아 앞구르기를 막는다','엉덩이를 앞으로 밀며 천천히 상대 오른쪽 어깨를 꺾는다','탭하면 바로 푼다']::text[] where slug = 'omoplata-from-armbar' and owner_id is null and steps = array['암바가 막히면 상대 머리 위에 있던 다리를 상대 어깨 뒤로 돌려 팔을 감는다','상대 쪽으로 앉아 올라온다','손으로 상대 허리를 잡아 앞구르기를 막는다','엉덩이를 앞으로 밀며 천천히 어깨를 꺾는다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 손목을, 내 오른팔은 그 팔 아래로 넣어 기무라 그립을 잡고 바로 꺾지 않는다','상대가 돌거나 짚는 방향에 따라 스윕 · 백 · 암바로 바꾼다','두 팔꿈치를 내 몸에 붙여 그립을 지킨다','기회가 오면 상대 오른팔 기무라로 마무리한다']::text[] where slug = 'kimura-trap' and owner_id is null and steps = array['기무라 그립을 잡으면 바로 꺾지 말고 그립을 유지한다','상대가 돌거나 짚는 방향에 따라 스윕 · 백 · 암바로 바꾼다','팔꿈치를 몸에 붙여 그립을 지킨다','기회가 오면 기무라로 마무리한다']::text[];
update public.techniques set steps = array['상대 오른팔에 8자 그립을 잡고 상대 오른쪽 팔꿈치가 90도로 굽은 상태를 유지한다','상대 오른쪽 팔꿈치를 내 몸에 붙이고 상대 오른쪽 어깨가 바닥에서 뜨지 않게 누른다','상대 오른쪽 손목을 상대 등 뒤 머리 쪽으로 천천히 돌린다','탭하면 바로 푼다']::text[] where slug = 'kimura-finish' and owner_id is null and steps = array['8자 그립에서 상대 팔꿈치가 90도로 굽은 상태를 유지한다','상대 팔꿈치를 내 몸에 붙이고 상대 어깨가 바닥에서 뜨지 않게 누른다','손목을 상대 등 뒤 머리 쪽으로 천천히 돌린다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['기무라 그립으로 상대 오른팔을 등 뒤로 돌려 상대 오른손을 등에 붙인다','상대가 팔을 지키려 돌면 상대 오른팔을 가둔 채 상대 등 뒤로 돌아간다','두 발로 훅을 넣는다','백 컨트롤을 완성한다']::text[] where slug = 'kimura-to-back-take' and owner_id is null and steps = array['기무라 그립으로 상대 팔을 등 뒤로 돌려 손을 등에 붙인다','상대가 팔을 지키려 돌면 그 팔을 가둔 채 등 뒤로 돌아간다','훅을 넣는다','백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['내 왼손으로 상대 오른쪽 손목을, 내 오른팔을 그 팔 아래로 넣어 기무라 그립을 잡고 상대 쪽으로 구른다','구르면서 상대도 함께 넘어가게 한다','그립을 놓지 않고 위로 올라온다','상대 오른팔 기무라로 마무리하거나 백으로 간다','탭하면 바로 푼다']::text[] where slug = 'rolling-kimura' and owner_id is null and steps = array['기무라 그립을 잡고 상대 쪽으로 구른다','구르면서 상대도 함께 넘어가게 한다','그립을 놓지 않고 위로 올라온다','기무라로 마무리하거나 백으로 간다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 내 오른팔에 기무라를 걸면 내 오른손으로 내 허리띠나 다리를 잡는다','오른쪽 팔꿈치를 몸에 붙이고 상대 쪽으로 돈다','상대 그립 방향으로 굴러 압력을 뺀다','내 오른팔을 빼낸다']::text[] where slug = 'kimura-defense' and owner_id is null and steps = array['잡힌 팔의 손으로 내 허리띠나 다리를 잡는다','팔꿈치를 몸에 붙이고 상대 쪽으로 돈다','상대 그립 방향으로 굴러 압력을 뺀다','팔을 빼낸다']::text[];
update public.techniques set steps = array['상대가 내 오른팔에 기무라를 걸면 내 오른쪽 어깨 쪽으로 먼저 구른다(어깨가 돌아가는 방향)','구르면서 상대를 함께 넘긴다','오른쪽 팔꿈치를 몸에 붙인 채 위로 올라온다','가드 안이나 탑 포지션을 잡는다']::text[] where slug = 'kimura-counter-via-roll' and owner_id is null and steps = array['상대가 기무라를 걸면 잡힌 팔 쪽으로 먼저 구른다(어깨가 돌아가는 방향)','구르면서 상대를 함께 넘긴다','팔꿈치를 몸에 붙인 채 위로 올라온다','가드 안이나 탑 포지션을 잡는다']::text[];
update public.techniques set steps = array['상대 오른쪽 어깨를 두 다리로 누른 채 내 오른팔로 상대 허리를 감아 앞구르기를 막는다','상대 골반을 바닥에 눕히고 엉덩이를 상대에게서 멀리 뺀다','앉아 올라오며 엉덩이를 앞으로 민다','천천히 상대 오른쪽 어깨를 꺾고 탭하면 바로 푼다']::text[] where slug = 'omoplata-finish' and owner_id is null and steps = array['상대 어깨를 다리로 누른 채 손으로 상대 허리를 잡아 앞구르기를 막는다','상대 골반을 바닥에 눕히고 엉덩이를 상대에게서 멀리 뺀다','앉아 올라오며 엉덩이를 앞으로 민다','천천히 어깨를 꺾고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 앞구르기를 버티면 두 다리로 상대 오른쪽 어깨를 계속 누른다','내 오른팔로 상대 왼팔이나 허리를 감아 상대가 왼손으로 바닥을 짚지 못하게 한다','엉덩이를 들고 짚을 팔이 막힌 상대 왼쪽으로 밀어 넘긴다','상대가 넘어가면 따라 올라와 마운트나 사이드 컨트롤을 잡는다']::text[] where slug = 'omoplata-to-sweep' and owner_id is null and steps = array['상대가 꺾이지 않으면 다리로 어깨를 계속 누른다','상대 반대쪽으로 몸을 돌려 상대를 민다','상대가 넘어가면 위로 올라온다','마운트나 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대 오른팔에 오모플라타를 건 상태에서 상대가 앞구르기로 빠지려 하면 다리를 푼다','상대 오른쪽 옆구리를 지나 상대 등 뒤로 돌아간다','허리띠를 잡거나 내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 밑으로 시트벨트를 잡는다','내 두 발을 상대 양쪽 허벅지 안쪽에 훅으로 넣는다','백 컨트롤을 완성한다']::text[] where slug = 'omoplata-to-back' and owner_id is null and steps = array['상대가 앞구르기로 빠지려 하면 다리를 풀고 등 뒤로 돈다','허리띠나 시트벨트를 잡는다','훅을 넣는다','백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대가 내 오른팔에 오모플라타를 걸면, 허리를 잡히기 전에 내 오른쪽 어깨를 바닥에 댄다','고개를 내 왼쪽으로 숙여 넣고 오른쪽 어깨 위로 앞구르기를 한다','구르면서 상대가 넘어가고 내 오른쪽 어깨가 풀린다','위로 올라와 사이드 컨트롤을 잡는다']::text[] where slug = 'roll-forward-from-omoplata' and owner_id is null and steps = array['상대가 허리를 잡기 전에 잡힌 팔 쪽 어깨를 바닥에 댄다','그쪽으로 앞구르기를 한다','구르면서 상대가 넘어가고 어깨가 풀린다','위로 올라와 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 오른팔에 오모플라타를 걸고 앉아 올라오기 전, 상대 다리 위로 체중을 실어 누른다(스택)','갇힌 내 오른쪽 팔꿈치를 내 몸 쪽으로 당긴다','오른팔을 빼내며 패스 자세로 올라온다','하프 가드 탑이나 사이드 컨트롤을 잡는다']::text[] where slug = 'stack-defense-from-omoplata' and owner_id is null and steps = array['상대가 앉아 올라오기 전 상대 다리 위로 체중을 실어 누른다(스택)','잡힌 팔의 팔꿈치를 내 몸 쪽으로 당긴다','팔을 빼내며 패스 자세로 올라온다','하프 가드 탑이나 사이드 컨트롤을 잡는다']::text[];
update public.techniques set steps = array['상대가 내 오른팔에 오모플라타를 걸고 앉아 올라오기 전에 내 왼손으로 바닥을 짚는다','두 다리를 들어 내 오른쪽, 상대 몸 너머로 옆돌기 하듯 넘어간다','내 오른쪽 어깨가 풀리면 오른팔을 빼낸다','오픈 가드 탑에서 자세를 잡는다']::text[] where slug = 'cartwheel-escape-from-omoplata' and owner_id is null and steps = array['상대가 앉아 올라오기 전에 자유로운 손으로 바닥을 짚는다','다리를 들어 상대 너머로 옆돌기 하듯 넘어간다','어깨가 풀리면 팔을 빼낸다','오픈 가드 탑에서 자세를 잡는다']::text[];
update public.techniques set steps = array['내 오른다리를 상대 목 뒤에 걸고 상대 오른팔을 다리 사이에 가둔 채 머리를 당겨 자세를 무너뜨린다','갇힌 상대 오른팔을 상대 몸 가운데를 지나 내 오른쪽으로 넘긴다','내 오른손으로 상대 왼다리를 잡고 엉덩이를 내 왼쪽으로 빼 상대와 거의 직각이 되게 눕는다','왼쪽 오금으로 내 오른발목을 잠그고 무릎을 모아 엉덩이를 들어 조인다','천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'triangle-finish' and owner_id is null and steps = array['머리를 당겨 상대 자세를 낮춘다','목 위 다리 반대쪽으로 몸을 틀어 각도를 만든다','갇힌 팔을 내 몸 반대쪽으로 넘긴다','무릎을 모으고 엉덩이를 들어 조인다','천천히 조이고 탭하면 바로 푼다']::text[];
update public.techniques set steps = array['트라이앵글(내 오른다리가 상대 목 뒤)에서 갇힌 상대 오른쪽 손목을 내 두 손으로 잡는다','엉덩이를 내 왼쪽으로 틀어 상대 오른팔을 내 가슴 가운데에 붙인다(엄지가 위로)','다리는 풀지 않은 채 두 무릎을 모은다','엉덩이를 천천히 들어 상대 오른쪽 팔꿈치를 편다','탭하면 바로 푼다']::text[] where slug = 'triangle-to-armbar' and owner_id is null and steps = array['트라이앵글에서 갇힌 팔의 손목을 두 손으로 잡는다','엉덩이를 돌려 그 팔을 내 가슴에 붙인다(엄지가 위로)','다리는 풀지 않은 채 무릎을 모은다','엉덩이를 천천히 들어 팔꿈치를 편다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['트라이앵글에서 상대가 갇힌 오른팔을 아래로 빼려 하면 다리를 풀고 내 왼다리를 상대 오른쪽 어깨 위로 넘긴다','상대 오른쪽 옆으로 앉아 올라온다','내 왼팔로 상대 허리를 감싸 앞구르기를 막는다','엉덩이를 앞으로 밀며 천천히 상대 오른쪽 어깨를 꺾는다','탭하면 바로 푼다']::text[] where slug = 'triangle-to-omoplata' and owner_id is null and steps = array['상대가 갇힌 팔을 아래로 빼려 하면 다리를 풀어 그 팔 위로 다리를 넘긴다','상대 쪽으로 앉아 올라온다','손으로 상대 허리를 잡아 앞구르기를 막는다','엉덩이를 앞으로 밀며 천천히 어깨를 꺾는다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['트라이앵글에서 상대가 스택하거나 자세를 세우면 다리를 풀고 상대 오른쪽(갇혔던 팔 쪽) 옆으로 돈다','상대 오른쪽 옆구리를 지나 등 뒤로 돌아간다','내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 밑으로 시트벨트를 잡고 두 발 훅을 넣는다','백 컨트롤을 완성한다']::text[] where slug = 'triangle-to-back' and owner_id is null and steps = array['상대가 스택하거나 자세를 세우면 다리를 풀고 옆으로 돈다','상대 등 뒤로 돌아간다','허리띠나 시트벨트를 잡고 훅을 넣는다','백 컨트롤을 완성한다']::text[];
update public.techniques set steps = array['상대 오른다리가 내 목 뒤에 걸리면 턱을 당기고 갇힌 내 오른쪽 팔꿈치를 몸 쪽으로 당긴다','두 무릎을 앞으로 당겨 자세를 단단히 한다','자유로운 내 왼손으로 상대 골반을 누르며 허리를 곧게 세운다','어깨를 상대 엉덩이와 정면으로 맞춰 각도를 없앤다','다리가 풀리면 가드 안으로 돌아간다']::text[] where slug = 'triangle-escape-posture' and owner_id is null and steps = array['갇힌 팔꿈치를 내 쪽으로 당기고 허리를 세운다','머리를 들고 상대 다리를 아래로 민다','갇힌 팔 쪽으로 몸을 틀어 각도를 깬다','다리를 풀고 가드 안으로']::text[];
update public.techniques set steps = array['갇힌 내 오른쪽 팔꿈치를 몸에 붙이고 내 왼손으로 상대 골반 쪽 허벅지를 짚으며 일어선다','상대 엉덩이를 들어 올려 체중을 상대 머리 쪽으로 싣는다(스택)','갇힌 내 오른팔을 돌려 상대 다리 사이에서 빼낸다','하프 가드 탑이나 사이드 컨트롤로 간다','스택할 때 상대 목을 과하게 누르지 않는다']::text[] where slug = 'stack-escape-from-triangle' and owner_id is null and steps = array['갇힌 팔꿈치를 몸에 붙이고 반대 손으로 상대 허벅지를 짚으며 일어선다','상대 엉덩이를 들어 올려 체중을 상대 머리 쪽으로 싣는다(스택)','갇힌 팔을 돌려 다리 사이에서 빼낸다','하프 가드 탑이나 사이드 컨트롤로 간다','스택할 때 상대 목을 과하게 누르지 않는다']::text[];
update public.techniques set steps = array['상대가 갇힌 오른쪽 어깨를 안으로 돌려 막으면 다리 잠금을 유지한다','내 오른손으로 상대 왼쪽 골반이나 허리띠를 잡는다','엉덩이를 상대 등 쪽으로 돌려 몸 방향을 바꾼다','상대 머리와 오른팔이 다리 사이에 다시 갇히게 삼각형을 고쳐 잡는다','무릎을 모으며 천천히 조이고 탭하면 바로 푼다']::text[] where slug = 'inverted-triangle' and owner_id is null and steps = array['상대가 스택하며 머리가 옆으로 빠지면 다리를 풀어 반대 방향으로 다시 감는다','상대 머리와 한 팔을 다리로 다시 가둔다','발목 위에 반대 무릎을 걸어 삼각형을 만든다','무릎을 모으며 천천히 조인다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['상대가 손을 맞잡아 버티면 무릎을 모은 채 상대 오른쪽 손목을 내 두 손으로 잡는다','왼다리로 얼굴을 누른 채 엉덩이를 들며 내 오른발로 상대 왼쪽 옆구리를 밀어 힘을 키운다','맞잡은 손이 벌어지면 바로 상대 오른팔을 가슴에 붙이고 엄지가 위로 가게 한다','엉덩이를 천천히 들어 팔꿈치를 편다','탭하면 바로 푼다']::text[] where slug = 'armbar-grip-break' and owner_id is null and steps = array['상대가 손을 맞잡아 버티면 무릎을 모은 채 상대 손목을 두 손으로 잡는다','엉덩이를 상대 머리 쪽으로 들며 발로 상대 등이나 엉덩이를 밀어 당기는 힘을 키운다','맞잡은 손이 벌어지면 바로 팔을 가슴에 붙이고 엄지가 위로 가게 한다','엉덩이를 천천히 들어 팔꿈치를 편다','탭하면 바로 푼다']::text[];
update public.techniques set steps = array['뒤에서 내 오른팔은 상대 오른쪽 어깨 위, 왼팔은 왼쪽 겨드랑이 밑으로 시트벨트를 꽉 잡는다','내 오른발로 상대 오른쪽 무릎 뒤를 눌러 무릎을 꺾는다','상대를 뒤로 끌어당기며 내 오른쪽 엉덩이부터 비스듬히 바닥에 내린다','앉는 순간 오른발, 왼발 순서로 상대 허벅지 안쪽에 훅을 넣는다','백 컨트롤로 끝난다']::text[] where slug = 'takedown-to-grounded-back-control' and owner_id is null and steps = array['뒤에서 시트벨트(한 팔은 어깨 위, 한 팔은 겨드랑이 아래)로 상대 상체를 꽉 잡는다','한 발로 상대 무릎 뒤를 눌러 무릎을 꺾는다','상대를 뒤로 끌어당기며 옆으로 비스듬히 엉덩이를 바닥에 내린다','앉는 순간 다리 사이에 훅을 하나씩 넣는다','백 컨트롤로 끝난다']::text[];
update public.techniques set steps = array['내 오른손으로 상대 왼쪽 소매(또는 깃)를 잡고 상대에게 가까이 다가선다','상대 오른발(앞다리) 쪽으로 엉덩이를 낮춰 앉는다','앉으면서 내 왼쪽 정강이를 상대 오른쪽 정강이 안쪽에 댄다','내 왼손으로 상대 오른쪽 발목(바지)을 잡고, 오른발은 바닥에 두어 버틴다','신 투 신 가드로 끝난다']::text[] where slug = 'shin-to-shin-pull' and owner_id is null and steps = array['같은 쪽 소매(또는 깃과 소매)를 잡고 상대에게 가까이 다가선다','상대 앞다리 쪽으로 엉덩이를 낮춰 앉는다','앉으면서 내 정강이를 상대 앞다리 정강이 안쪽에 댄다','같은 쪽 손으로 그 다리 발목(바지)을 잡고, 반대 발은 바닥에 두어 버틴다','신 투 신 가드로 끝난다']::text[];
update public.techniques set steps = array['내 왼팔로 상대 오른팔을 오버훅해 겨드랑이에 끼우고, 왼다리로 상대 등을 높이 눌러 자세를 무너뜨린다','내 오른손으로 상대 왼팔을 밀어 내 다리 사이 밖으로 뺀다','내 오른다리를 상대 목 뒤로 넘기고, 왼쪽 오금으로 내 오른발목을 걸어 잠근다','몸을 비스듬히 틀고 상대 머리를 당기며 무릎을 조여 트라이앵글 초크로 끝낸다']::text[] where slug = 'triangle-from-clamp-guard' and owner_id is null and steps = array['오버훅으로 상대 한 팔을 내 겨드랑이에 꽉 끼우고, 같은 쪽 다리로 상대 등을 높이 눌러 자세를 무너뜨린다','다른 손으로 상대 반대 팔을 밀어 내 다리 사이 밖으로 뺀다','팔이 빠진 쪽 다리를 상대 목 뒤로 넘기고, 반대 다리 오금으로 그 발목을 걸어 잠근다','몸을 비스듬히 틀고 상대 머리를 당기며 무릎을 조여 트라이앵글 초크로 끝낸다']::text[];
update public.techniques set steps = array['내 왼팔로 상대 오른팔을 오버훅해 겨드랑이에 끼우고 왼손으로 상대 왼쪽 깃을 잡는다','내 오른발로 상대 왼쪽 골반을 밀어 몸을 비스듬히 돌린다','내 왼다리를 상대 얼굴 앞으로 넘겨 머리를 누른다','무릎을 모으고 내 손을 상대 오른쪽 손목 쪽으로 옮긴다','엄지가 위로 가게 상대 오른팔을 당기며 엉덩이를 천천히 들어 암바로 끝낸다']::text[] where slug = 'armbar-from-clamp-guard' and owner_id is null and steps = array['오버훅으로 상대 팔을 겨드랑이에 끼우고, 그 손으로 상대 반대쪽 깃을 잡아 팔을 묶는다','반대쪽 발로 상대 골반을 밀어 몸을 비스듬히 돌린다(머리는 잡은 팔 반대쪽으로)','잡은 팔 반대쪽 다리를 상대 얼굴 앞으로 넘겨 머리를 누른다','무릎을 모으고 오버훅을 손목 쪽으로 미끄러뜨린 뒤 엉덩이를 들어 암바로 끝낸다']::text[];
update public.techniques set steps = array['상대가 왼다리를 내 다리 사이에 넣어 K 가드를 만들면 허리를 낮추고 무릎을 모아 공간을 막는다','내 오른손으로 상대 왼쪽 무릎을 바닥에 눌러 고정한다','걸린 내 오른다리를 뒤로 빼면서 엉덩이를 낮춘다','내 오른쪽 무릎을 상대 왼쪽 허벅지 위로 넘겨 니슬라이스로 지나간다','상대 왼쪽에서 사이드 컨트롤로 끝난다']::text[] where slug = 'pass-k-guard' and owner_id is null and steps = array['상대가 K 가드를 만들면 허리를 낮추고 무릎을 모아 다리 사이 공간을 막는다','상대 안쪽 무릎을 손으로 바닥에 눌러 고정한다','걸린 다리를 뒤로 빼면서 엉덩이를 낮춘다','무릎을 상대 허벅지 위로 넘겨 니슬라이스로 지나간다','사이드 컨트롤로 끝난다']::text[];
update public.techniques set steps = array['K 가드에서 내 왼팔로 상대 오른쪽 발목을 감싸 겨드랑이에 끼운다','상대 다리 사이에 넣은 내 오른다리로 상대 오른쪽 허벅지를 들며 엉덩이를 그 밑으로 넣는다','내 오른발을 상대 왼쪽 골반에 댄다','내 왼다리로 상대 오른쪽 무릎 뒤를 감는다','싱글 레그 X 가드로 끝난다']::text[] where slug = 'k-guard-to-single-leg-x' and owner_id is null and steps = array['K 가드에서 상대 앞다리 발목을 겨드랑이에 끼워 팔로 감싼다','상대 다리 사이에 넣은 안쪽 다리로 허벅지를 들어 올리며 엉덩이를 다리 밑으로 넣는다','그 안쪽 발을 상대 반대쪽 골반에 댄다','바깥쪽 다리로 상대 무릎 뒤를 감는다','싱글 레그 X 가드로 끝난다']::text[];
update public.techniques set steps = array['버터플라이 가드에서 내 오른팔로 상대 목을 감아 길로틴 그립을 잡는다','내 오른쪽으로 몸을 기울이며 오른쪽 어깨부터 옆으로 눕는다','내 왼발 훅으로 상대 오른다리를 들어 올려 내 오른쪽으로 넘긴다','상대가 넘어가면 그립을 놓지 않고 따라 올라가 마운트에서 조인다']::text[] where slug = 'butterfly-sweep-with-guillotine' and owner_id is null and steps = array['버터플라이 가드에서 상대 목을 감아 길로틴 그립을 잡는다','목을 감은 팔 쪽으로 몸을 기울이며 옆으로 눕는다','반대쪽 버터플라이 훅으로 상대 다리를 들어 올려 넘긴다','상대가 넘어가면 그립을 놓지 않고 따라 올라가 마운트에서 조인다']::text[];
update public.techniques set steps = array['내 오른다리로 상대 오른다리 안쪽에 리버스 데라히바 훅을 걸고 내 오른손으로 상대 왼쪽 바지(또는 발목)를 잡는다','훅으로 상대 오른다리를 바깥(내 왼쪽)으로 밀어 상대 무게를 앞쪽으로 무너뜨린다','내 왼쪽 어깨로 굴러 상대 다리 사이 밑으로 들어가며 상대 엉덩이 뒤쪽으로 몸을 돌린다','상체를 일으켜 상대 허리 뒤에 붙고 두 발을 상대 무릎 안쪽에 걸어 크랩 라이드로 잡는다']::text[] where slug = 'rdlr-to-crab-ride' and owner_id is null and steps = array['리버스 데라히바 훅을 상대 앞다리 안쪽에 걸고 반대 손으로 상대 뒤쪽 바지(또는 발목)를 잡는다','훅으로 앞다리를 바깥으로 밀어 상대 무게를 앞쪽으로 무너뜨린다','어깨로 굴러 상대 다리 사이 밑으로 들어가며 상대 엉덩이 뒤쪽으로 몸을 돌린다','상체를 일으켜 상대 허리 뒤에 붙고 두 발을 상대 무릎 안쪽에 걸어 크랩 라이드로 잡는다']::text[];
update public.techniques set steps = array['내 두 손으로 상대 두 소매를 잡고 발로 상대 팔을 밀어 거리를 만든다','상대가 오른발을 앞으로 디디면 내 왼손으로 오른쪽 소매를 놓고 오른쪽 발목(바지 끝)을 잡는다','내 왼다리로 상대 오른다리를 바깥에서 감아 발등을 상대 오른쪽 허벅지 안쪽에 건다','내 오른손은 상대 왼쪽 소매를 계속 잡고, 오른발은 상대 왼쪽 골반이나 무릎에 둔다','데라히바 가드로 끝난다']::text[] where slug = 'double-sleeve-to-de-la-riva' and owner_id is null and steps = array['상대 두 소매를 잡고 발로 상대 팔을 밀어 거리를 만든다','상대가 한 발을 앞으로 디디면 그 다리 쪽 소매를 놓고 그 손으로 발목(바지 끝)을 잡는다','같은 쪽 다리로 상대 다리를 바깥에서 감아 발등을 허벅지 안쪽에 건다','다른 손은 남은 소매를 계속 잡고, 반대 발은 골반이나 무릎에 둔다','데라히바 가드로 끝난다']::text[];
update public.techniques set steps = array['위 사람이 내 오른쪽 정강이(니 쉴드)를 눌러 오면 내 오른손으로 상대 왼쪽 무릎이나 골반을 민다','내 왼손은 상대 깃이나 오른쪽 어깨를 밀어 머리가 가까이 오지 못하게 한다','엉덩이를 내 왼쪽으로 빼서 정강이와 상대 몸 사이에 공간을 만든다','오른쪽 정강이를 상대 골반이나 배에 다시 걸어 니 쉴드로 돌아온다']::text[] where slug = 'knee-shield-retention' and owner_id is null and steps = array['위 사람이 무릎을 눌러 오면 같은 쪽 손으로 그 무릎을 밀어 정강이 각도를 다시 세운다','반대 손은 상대 깃이나 어깨를 밀어 머리가 가까이 오지 못하게 막는다','엉덩이를 바깥으로 빼서(쉬림프) 정강이와 상대 몸 사이에 공간을 다시 만든다','정강이를 상대 골반이나 배에 다시 걸어 니 쉴드 하프가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 내 다리 쪽을 보고 앉으면 걸린 다리를 풀지 말고 꽉 조인다','내 오른손으로 상대 골반을 밀어 몸이 더 내려오지 못하게 막는다','내 왼발로 바닥을 밀어 엉덩이를 빼고 몸을 내 오른쪽(상대 쪽)으로 돌린다','돌면서 내 오른팔을 상대 겨드랑이 밑으로 넣어 언더훅을 잡는다','내 왼쪽 무릎을 상대 배 앞에 세워 하프가드(니 쉴드)로 돌아온다']::text[] where slug = 'guard-recovery-from-reverse-half-guard' and owner_id is null and steps = array['위 사람이 엉덩이를 돌려 내 다리 쪽을 보고 앉으면 다리 걸린 것을 풀지 말고 꽉 조인다','위쪽 손으로 상대 골반을 밀어 몸이 더 내려오지 못하게 막는다','엉덩이를 빼서 공간을 만들고 무릎을 상대 몸 앞으로 끌어 넣는다','상대가 다시 정면으로 돌아오면 니 쉴드나 언더훅을 잡아 하프가드로 돌아온다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 감은 하프가드 위에서 내 왼팔로 상대 머리를 감싼 채 엉덩이를 돌려 상대 다리 쪽을 보고 앉는다','내 왼발바닥으로 상대 위쪽 무릎을 밀어 걸린 오른다리를 조금씩 뺀다','오른다리가 빠지면 엉덩이를 다시 상대 머리 쪽으로 돌려 가슴을 붙인다','내 왼팔 크로스페이스와 오른팔 언더훅을 잡아 사이드 컨트롤로 자리 잡는다']::text[] where slug = 'pass-reverse-half' and owner_id is null and steps = array['하프가드 위에서 엉덩이를 돌려 상대 다리 쪽을 보고 앉고 팔로 상대 머리 쪽을 감싼다','걸리지 않은 발바닥으로 상대 무릎을 밀어 걸린 다리를 조금씩 뺀다','다리가 빠지면 엉덩이를 다시 상대 머리 쪽으로 돌려 가슴을 붙인다','크로스페이스와 언더훅을 잡아 사이드 컨트롤로 자리 잡는다']::text[];
update public.techniques set steps = array['상대가 내 오른다리를 감은 하프가드 위에서 내 왼팔 크로스페이스, 오른팔 언더훅으로 상대를 눕힌다','걸리지 않은 내 왼발이나 손으로 상대 위쪽 무릎을 바닥 쪽으로 누른다','걸린 내 오른쪽 무릎을 앞으로 빼서 오른발목만 걸린 상태로 만든다','가슴 압박을 유지한 채 쿼터 가드에서 마지막 오른발목을 뺄 준비를 한다']::text[] where slug = 'half-guard-to-quarter-guard' and owner_id is null and steps = array['하프가드 위에서 크로스페이스와 언더훅으로 상대를 바닥에 눕힌다','걸리지 않은 발이나 손으로 상대 위쪽 무릎을 바닥 쪽으로 누른다','걸린 다리의 무릎을 앞으로 빼서 발목만 걸린 상태로 만든다','가슴 압박을 유지한 채 쿼터 가드에서 마지막 발목을 뺄 준비를 한다']::text[];
update public.techniques set steps = array['상대가 다리를 높이 들고 버티면 내 오른손으로 상대 무릎을 눌러 다리를 내 왼쪽으로 치운다','상대 몸통 왼쪽 옆(내 오른쪽) 바닥에 두 손을 짚는다','다리를 차올려 옆돌기하듯 상대 다리 위를 넘어 상대 왼쪽에 착지한다','착지하자마자 가슴을 상대 가슴에 붙여 누른다','상대 왼쪽에서 사이드 컨트롤로 끝난다']::text[] where slug = 'cartwheel-pass' and owner_id is null and steps = array['상대가 다리를 높이 들고 버티면 한 손으로 무릎을 눌러 다리를 한쪽으로 치운다','반대쪽 상대 몸통 옆 바닥에 두 손을 짚는다','다리를 차올려 옆돌기하듯 상대 다리 위를 넘어간다','착지하자마자 가슴을 상대 가슴에 붙여 누른다','사이드 컨트롤로 끝난다']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 사이드를 잡으면 내 왼팔로 상대 목 뒤를 감는다','내 오른손과 맞잡아 상대 목을 내 왼쪽 겨드랑이 쪽으로 끌어안는다','내 왼다리를 들어 맞잡은 내 손목 위로 넘긴다','내 오른쪽 오금으로 왼발목을 걸어 다리를 삼각으로 잠근다','다리로 팔을 당기며 몸을 웅크려 조른다 → 탭']::text[] where slug = 'buggy-choke' and owner_id is null and steps = array['사이드 아래에서 상대 머리 쪽 팔로 상대 목 뒤를 감는다','다른 손과 맞잡아 상대 목을 내 겨드랑이 쪽으로 끌어안는다','머리 쪽 다리를 들어 맞잡은 내 손목 위로 넘긴다','다른 다리로 그 발목을 걸어 다리를 삼각으로 잠근다','다리로 팔을 당기며 몸을 웅크려 조른다 → 탭']::text[];
update public.techniques set steps = array['상대 왼쪽에서 사이드를 잡고 내 오른팔 크로스페이스를 상대 머리 뒤로 깊게 넣는다','내 오른쪽 어깨를 상대 턱 왼쪽에 대고 상대 고개를 상대 오른쪽으로 민다','엉덩이는 낮추고 발끝으로 버텨 체중을 오른쪽 어깨에 싣는다','상대가 밀어내려고 팔을 뻗으면 그 팔을 노린다 → 기무라 · 아메리카나 · 마운트']::text[] where slug = 'side-control-to-shoulder-of-justice' and owner_id is null and steps = array['사이드 위에서 크로스페이스 팔을 상대 머리 뒤로 깊게 넣는다','내 어깨를 상대 턱 옆에 대고 고개를 반대쪽으로 민다','엉덩이는 낮추고 발끝으로 버텨 체중을 어깨에 싣는다','상대가 밀어내려고 팔을 뻗으면 그 팔을 노린다 → 기무라 · 아메리카나 · 마운트']::text[];
update public.techniques set steps = array['상대가 내 오른쪽에서 누르면 턱을 당기고 내 오른쪽 팔꿈치로 상대 골반을 막는다','내 왼팔 팔뚝을 상대 목 아래에 끼워 프레임을 만든다','브릿지로 상대를 살짝 띄우고 고개를 내 오른쪽(상대 쪽)으로 돌린다','엉덩이를 내 왼쪽으로 빼며 오른쪽 무릎을 넣어 다리를 감는다 → 하프가드']::text[] where slug = 'escape-shoulder-of-justice' and owner_id is null and steps = array['턱을 당겨 목을 지키고 가까운 팔꿈치로 상대 골반을 막는다','먼 팔 팔뚝을 상대 목 아래에 끼워 프레임을 만든다','브릿지로 상대를 살짝 띄우고 고개를 상대 쪽으로 돌린다','엉덩이를 빼며 가까운 무릎을 넣어 다리를 감는다 → 하프가드']::text[];
update public.techniques set steps = array['상대 왼쪽에서 상대 오른팔을 목 앞으로 감아, 머리 뒤로 넣은 내 오른손으로 상대 오른쪽 손목을 잡는다','가슴으로 상대 왼쪽 어깨를 눌러 등을 바닥에 붙인다','상대가 팔을 빼려 하면 오른쪽 손목을 내 쪽으로 당겨 팔꿈치를 목에 붙인다','무게를 머리 쪽에 둔 채 다음 공격을 고른다 → 기무라 · 암바 · 백 테이크']::text[] where slug = 'gift-wrap-maintenance' and owner_id is null and steps = array['상대 먼 팔을 목 앞으로 감아 머리 뒤로 넣은 내 손으로 손목을 잡는다','가슴으로 상대 어깨를 눌러 등을 바닥에 붙인다','상대가 팔을 빼려 하면 손목을 내 쪽으로 당겨 팔꿈치를 목에 붙인다','무게를 머리 쪽에 둔 채 다음 공격을 고른다 → 기무라 · 암바 · 백 테이크']::text[];
update public.techniques set steps = array['남북 위에서 상대 오른팔을 겨드랑이 쪽에서 잡고 가슴으로 누른다','상대 오른쪽 옆으로 돌며 체중을 상대 배 쪽으로 옮긴다','내 왼다리를 상대 배 위로 넘겨 상대 다리 쪽을 보고 앉는다','두 무릎으로 상대 옆구리를 조여 고정한다 → 리버스 마운트 (암바 · 리스트락 연결)']::text[] where slug = 'reverse-mount-transition' and owner_id is null and steps = array['남북 위에서 상대 가까운 팔을 겨드랑이 쪽에서 잡고 가슴으로 누른다','상대 몸 옆으로 돌며 체중을 상대 배 쪽으로 옮긴다','한 다리를 상대 배 위로 넘겨 다리 쪽을 보고 앉는다','무릎으로 상대 옆구리를 조여 고정한다 → 리버스 마운트 (암바 · 리스트락 연결)']::text[];
update public.techniques set steps = array['상대 오른쪽에서 리버스 곁누르기로 상대 오른팔을 내 오른쪽 겨드랑이에 끼운 채 유지한다','엉덩이를 바닥에 끌며 몸을 내 왼쪽으로 돌려 상대 머리 쪽을 바라본다','오른쪽 무릎은 상대 엉덩이 옆, 왼쪽 무릎은 상대 오른쪽 겨드랑이 옆에 붙인다','가슴을 붙이고 내 왼팔로 크로스페이스를 잡는다 → 사이드 컨트롤']::text[] where slug = 'ushiro-kesa-gatame-to-side-control' and owner_id is null and steps = array['리버스 곁누르기에서 상대 가까운 팔을 겨드랑이에 끼운 채 유지한다','엉덩이를 바닥에 끌며 몸을 돌려 상대 머리 쪽을 바라본다','무릎을 상대 엉덩이와 겨드랑이 옆에 붙인다','가슴을 상대 가슴에 붙이고 크로스페이스를 잡는다 → 사이드 컨트롤']::text[];
update public.techniques set steps = array['상대 오른쪽에서 리버스 곁누르기로 가슴으로 상대 가슴을 계속 누른다','상대 오른쪽 어깨에서 머리 위쪽으로 다리를 한 걸음씩 걸어 돌아간다','상대 머리 위에서 무릎을 꿇고 가슴을 맞댄다','양팔로 상대 양쪽 겨드랑이나 띠를 잡아 고정한다 → 남북']::text[] where slug = 'ushiro-kesa-gatame-to-north-south' and owner_id is null and steps = array['리버스 곁누르기에서 가슴으로 상대 가슴을 계속 누른다','상대 머리 위쪽으로 다리를 한 걸음씩 걸어 돌아간다','상대 머리 위에서 무릎을 꿇고 가슴을 맞댄다','양팔로 상대 겨드랑이나 띠를 잡아 고정한다 → 남북']::text[];
update public.techniques set steps = array['갇힌 내 오른팔은 손을 배 쪽으로 당겨 팔꿈치를 오른쪽 옆구리에 붙인다','자유로운 내 왼손으로 상대 허리를 밀어 버틴다','발로 바닥을 밀어 엉덩이를 내 왼쪽으로 빼며(새우빼기) 공간을 만든다','생긴 공간으로 내 오른쪽 무릎을 상대와 내 몸 사이에 넣는다','두 다리로 상대 왼다리를 감아 하프가드로 정리한다']::text[] where slug = 'escape-ushiro-kesa-gatame' and owner_id is null and steps = array['갇힌 팔은 손을 내 배 쪽으로 당겨 팔꿈치를 몸에 붙인다','자유로운 손으로 상대 허리를 밀어 공간을 만든다','몸을 상대 쪽으로 돌리며 가까운 무릎을 상대 엉덩이 아래로 넣는다','다리로 상대 다리를 감는다 → 하프가드']::text[];
update public.techniques set steps = array['리버스 마운트에서 양손을 상대 골반 옆 바닥에 짚는다','체중을 상대 배에 싣고 엉덩이를 살짝 든다','무릎을 빠르게 바꿔 디디며 몸을 내 오른쪽으로 돌려 상대 머리 쪽을 본다','두 무릎을 상대 양쪽 겨드랑이 쪽에 붙이고 엉덩이를 내린다','마운트']::text[] where slug = 'reverse-mount-to-mount' and owner_id is null and steps = array['리버스 마운트에서 양손을 상대 골반 옆 바닥에 짚는다','체중을 상대 배에 싣고 엉덩이를 살짝 든다','무릎을 빠르게 바꿔 디디며 몸을 상대 머리 쪽으로 돌린다','무릎을 상대 겨드랑이 쪽에 붙이고 엉덩이를 내린다','마운트']::text[];
update public.techniques set steps = array['리버스 마운트에서 가슴을 상대 배 쪽으로 낮춘다','내 왼다리를 상대 몸 위로 넘겨 두 다리를 상대 오른쪽에 모은다','가슴을 붙인 채 몸을 내 왼쪽으로 돌려 상대 머리 쪽을 본다','내 왼팔로 크로스페이스, 오른팔로 상대 오른팔 언더훅을 잡는다','상대 오른쪽에서 사이드 컨트롤']::text[] where slug = 'reverse-mount-to-side-control' and owner_id is null and steps = array['리버스 마운트에서 가슴을 상대 배 쪽으로 낮춘다','한 다리를 상대 몸 위로 넘겨 두 다리를 한쪽에 모은다','가슴을 붙인 채 몸을 상대 머리 쪽으로 돌린다','크로스페이스와 언더훅을 잡는다','사이드 컨트롤']::text[];
update public.techniques set steps = array['리버스 마운트에서 상대가 내 허리를 미는 오른팔을 내 두 팔로 감아 가슴에 붙인다','엉덩이를 상대 오른쪽 어깨 옆으로 옮기며 몸을 내 왼쪽으로 돌려 상대 몸통을 마주 본다','내 왼다리를 상대 얼굴 위로 넘긴다','무릎을 모은 채 뒤로 눕고 엉덩이를 들어 상대 오른쪽 팔꿈치를 편다']::text[] where slug = 'armbar-from-reverse-mount' and owner_id is null and steps = array['리버스 마운트에서 상대가 내 허리를 미는 팔을 양팔로 감아 가슴에 붙인다','잡은 팔 쪽으로 몸을 돌리며 엉덩이를 상대 어깨 쪽으로 옮긴다','반대 다리를 상대 얼굴 위로 넘긴다','무릎을 모은 채 뒤로 눕고 엉덩이를 들어 팔꿈치를 편다']::text[];
update public.techniques set steps = array['두 팔꿈치를 몸에 붙이고 양손으로 상대 허리 뒤를 받친다','브릿지로 상대를 내 다리 쪽으로 밀어낸다','엉덩이를 내 왼쪽으로 빼며(새우빼기) 내 오른쪽 무릎을 상대 다리 사이로 넣는다','상대 오른다리를 내 두 다리로 감는다','하프가드']::text[] where slug = 'escape-reverse-mount' and owner_id is null and steps = array['팔꿈치를 몸에 붙이고 양손으로 상대 허리 뒤를 받친다','브릿지로 상대를 내 다리 쪽으로 밀어낸다','엉덩이를 옆으로 빼며(새우빼기) 무릎을 상대 다리 사이로 넣는다','상대 한 다리를 내 두 다리로 감는다','하프가드']::text[];
update public.techniques set steps = array['두 발을 엉덩이 가까이 붙이고 두 팔꿈치를 몸에 붙인다','상대 무게가 다리 쪽으로 쏠린 순간 내 왼쪽 어깨 쪽으로 크게 브릿지한다','상대가 뜬 틈에 몸을 내 왼쪽으로 틀어 두 무릎을 배 아래로 끌어온다','배를 바닥에 대고 팔꿈치와 무릎을 모은다','터틀']::text[] where slug = 'bridge-from-reverse-mount' and owner_id is null and steps = array['발을 엉덩이 가까이 붙이고 팔꿈치를 몸에 붙인다','상대 무게가 다리 쪽으로 쏠린 순간 크게 브릿지한다','상대가 뜬 틈에 몸을 옆으로 틀어 무릎을 배 아래로 끌어온다','배를 바닥에 대고 팔꿈치와 무릎을 모은다','터틀']::text[];
update public.techniques set steps = array['턱을 당기고 갇힌 내 오른팔은 굽혀 몸 쪽으로 당긴다','두 발을 엉덩이 가까이 붙인다','내 오른쪽(갇힌 팔 쪽)으로 크게 브릿지해 상대를 띄운다','뜬 틈에 오른팔을 몸 쪽으로 빼내며 내 오른쪽으로 돌아 배를 바닥으로 향한다','두 무릎을 배 아래로 끌어와 팔꿈치와 모은다 → 터틀']::text[] where slug = 'explosive-bridge-to-turtle' and owner_id is null and steps = array['갇힌 팔은 굽혀 몸 쪽으로 당겨 펴지지 않게 지킨다','발을 엉덩이 가까이 붙인다','상대 무게가 머리 쪽으로 쏠린 순간 크게 브릿지한다','상대가 뜬 틈에 몸을 옆으로 틀어 무릎을 끌어온다','터틀']::text[];
update public.techniques set steps = array['턱을 당기고 두 손으로 내 오른쪽 어깨 위로 오는 상대 오른팔부터 막는다','내 왼쪽 옆구리에 걸린 상대 오른발목 위에 내 왼발을 얹어 눌러 잠금을 푼다','엉덩이를 내 오른쪽 바닥으로 미끄러뜨려 등을 매트에 붙인다','몸을 내 왼쪽(상대 쪽)으로 돌리며 상대 오른다리를 내 두 다리로 감는다','하프가드']::text[] where slug = 'body-triangle-escape-to-half-guard' and owner_id is null and steps = array['턱을 당기고 두 손으로 조르는 팔부터 막는다','상대 발목이 걸린 곳 위에 내 발을 얹어 눌러 잠금을 푼다','엉덩이를 바닥 쪽으로 밀어 등을 매트에 붙인다','상대 쪽으로 돌며 한 다리를 내 두 다리로 감는다','하프가드']::text[];
update public.techniques set steps = array['백(내 오른팔이 조르는 팔, 오른쪽이 바닥)에서 상대가 두 손으로 내 오른팔을 막을 때 시작한다','내 왼다리를 들어 상대 왼팔을 넘어 팔꿈치 안쪽에 건다','내 왼손으로 상대 왼팔을 아래로 끌어내리고 두 다리 사이에 가둔다','상대 왼팔이 묶인 채 남은 상대 오른손을 막는다','크루시픽스 — 초크 · 암바']::text[] where slug = 'back-control-to-crucifix' and owner_id is null and steps = array['백에서 상대가 두 손으로 조르는 팔을 막고 있을 때 시작한다','위쪽 다리를 들어 상대 위쪽 팔을 넘어 팔꿈치 안쪽에 건다','손으로 그 팔을 아래로 끌어내리고 두 다리 사이에 가둔다','상대 한 팔이 묶인 채 남은 손을 막는다','크루시픽스 — 초크 · 암바']::text[];
update public.techniques set steps = array['상대 등 뒤에 앉아 두 발을 상대 양쪽 허벅지 안쪽에 걸고 내 오른손으로 띠를 잡는다','상대가 일어나거나 앞으로 나가려 하면 띠를 당기며 훅으로 상대 엉덩이를 내 쪽으로 끌어온다','상대가 내 다리 위로 주저앉으면 가슴을 등에 붙이고 오른팔은 어깨 위, 왼팔은 겨드랑이 밑으로 시트벨트를 잡는다','두 훅을 상대 양쪽 허벅지 안쪽에 다시 넣어 백 컨트롤로 끝낸다']::text[] where slug = 'crab-ride-to-back' and owner_id is null and steps = array['상대 등 뒤에 앉아 두 발을 상대 허벅지 안쪽에 걸고 한 손으로 띠를 잡는다','상대가 일어나거나 앞으로 나가려 하면 띠를 당기며 훅으로 상대 엉덩이를 내 쪽으로 끌어온다','상대가 내 다리 위로 주저앉으면 가슴을 상대 등에 붙이고 시트벨트를 잡는다','두 훅을 상대 허벅지 안쪽에 다시 넣어 백 컨트롤로 끝낸다']::text[];
update public.techniques set steps = array['엉덩이를 바닥 쪽으로 낮춰 상대가 띠로 끌어당기지 못하게 한다','내 오른손으로 내 오른쪽 허벅지에 걸린 상대 오른발 훅을 내 오른쪽 무릎 바깥으로 밀어 뗀다','훅이 빠진 내 오른쪽으로 몸을 돌려 상대를 마주 본다','상대 오른다리를 내 두 다리 사이에 가두며 하프가드로 정리한다']::text[] where slug = 'escape-from-crab-ride' and owner_id is null and steps = array['엉덩이를 바닥 쪽으로 낮춰 상대가 띠로 끌어당기지 못하게 한다','손으로 상대 발(훅) 하나를 내 무릎 바깥으로 밀어 뗀다','훅이 빠진 쪽으로 몸을 돌려 상대를 마주 본다','상대 다리 하나를 내 다리 사이에 가두며 하프가드로 정리한다']::text[];
update public.techniques set steps = array['터틀한 상대 왼쪽 뒤 옆에서 가슴을 상대 등에 얹는다','내 오른발을 상대 왼쪽 허벅지 안쪽에 깊게 넣어 첫 훅을 건다','내 오른손은 상대 오른쪽 깃(노기는 겨드랑이)을, 왼손은 띠를 잡는다','엉덩이를 상대 엉덩이 위에 무겁게 올려 상대가 앉거나 돌지 못하게 누른다','상대가 버티면 상대 왼쪽으로 무게를 실어 눕히고 왼발 두 번째 훅을 넣어 백 컨트롤로 간다']::text[] where slug = 'turtle-to-rodeo-ride' and owner_id is null and steps = array['터틀한 상대 뒤쪽 옆에서 가슴을 상대 등에 얹는다','가까운 쪽 발을 상대 허벅지 안쪽에 깊게 넣어 훅 하나를 건다','한 손은 상대 먼 쪽 깃(노기는 겨드랑이)을, 다른 손은 띠를 잡는다','엉덩이를 상대 엉덩이 위에 무겁게 올려 상대가 앉거나 돌지 못하게 누른다','상대가 버티면 훅 쪽으로 무게를 실어 눕히고 두 번째 훅을 넣어 백 컨트롤로 간다']::text[];
update public.techniques set steps = array['내 왼쪽 정강이를 상대 목 앞에 가로로 대고, 왼발은 상대 오른쪽 어깨 너머로 넘긴 상태에서 시작한다','양손으로 상대 뒷머리를 깍지 끼어 잡는다(손이 닿으면 내 왼발끝을 잡아도 된다)','내 오른다리로 상대 등이나 골반을 눌러 상대가 자세를 세우지 못하게 한다','머리를 당기면서 왼쪽 정강이를 목 쪽으로 밀어 넣어 탭을 받는다']::text[] where slug = 'gogoplata-from-gogoplata-control' and owner_id is null and steps = array['내 정강이를 상대 목 앞에 가로로 대고, 발은 상대 어깨 너머로 넘긴 상태에서 시작한다','양손으로 상대 뒷머리를 깍지 끼어 잡는다(손이 닿으면 내 발끝을 잡아도 된다)','반대 다리로 상대 등이나 골반을 눌러 상대가 자세를 세우지 못하게 한다','머리를 당기면서 정강이를 목 쪽으로 밀어 넣어 탭을 받는다']::text[];
update public.techniques set steps = array['상대 왼쪽 정강이가 목에 걸리면 바로 턱을 당기고 양손으로 정강이를 밀어 목에서 떼어 낸다','상대가 뒷머리를 당기는 손을 머리를 흔들어 털어 내거나 손으로 걷어 낸다','무릎을 상대 엉덩이에 붙이고 허리를 펴 상대 왼다리를 내 오른쪽 어깨 밖으로 떨어뜨린다','자세를 세운 채 상대 가드 안(오픈 가드 위)에서 다시 시작한다']::text[] where slug = 'posture-up-from-gogoplata' and owner_id is null and steps = array['정강이가 목에 걸리면 바로 턱을 당기고 양손으로 정강이를 밀어 목에서 떼어 낸다','상대가 뒷머리를 당기는 손을 머리를 흔들어 털어 내거나 손으로 걷어 낸다','무릎을 상대 엉덩이에 붙이고 허리를 펴 상대 다리를 어깨 밖으로 떨어뜨린다','자세를 세운 채 상대 가드 안(오픈 가드 위)에서 다시 시작한다']::text[];
update public.techniques set steps = array['트라이앵글에서 상대가 버티면 다리는 그대로 조인 채 내 왼손으로 갇힌 상대 오른쪽 손목을 잡는다','내 오른팔을 상대 오른팔 위로 넘겨 내 왼손목을 잡아 기무라 그립(숫자 4)을 만든다','다리 삼각을 계속 조여 상대가 자세를 세우거나 팔을 빼지 못하게 한다','상대 오른손을 등 쪽으로 돌려 어깨를 비틀어 탭을 받는다']::text[] where slug = 'kimura-from-triangle-control' and owner_id is null and steps = array['트라이앵글을 걸었는데 상대가 버티면, 다리는 그대로 조인 채 갇힌 팔 손목을 잡는다','반대 팔을 상대 팔 위로 넘겨 내 손목을 잡아 기무라 그립(숫자 4)을 만든다','다리 삼각을 계속 조여 상대가 자세를 세우거나 팔을 빼지 못하게 한다','상대 손을 등 쪽으로 돌려 어깨를 비틀어 탭을 받는다']::text[];
update public.techniques set steps = array['상대 왼쪽 위에서 기무라 그립(숫자 4)으로 상대 왼팔을 잡고 내 가슴에 붙인 상태에서 시작한다','팔을 놓지 않고 엉덩이를 상대 머리 쪽으로 돌려 상대 다리 쪽을 바라본다','상대 왼쪽 어깨 옆에 엉덩이를 내리고 다리를 넓게 벌려 무게를 싣는다','잡은 왼팔을 내 옆구리에 묶은 채 리버스 곁누르기(우시로 케사)로 누르고 다음 서브미션을 노린다']::text[] where slug = 'kimura-trap-to-ushiro-kesa-gatame' and owner_id is null and steps = array['위에서 기무라 그립(숫자 4)으로 상대 팔을 잡고 내 가슴에 붙인 상태에서 시작한다','팔을 놓지 않고 상대 머리 쪽으로 엉덩이를 돌려 상대 다리 쪽을 바라본다','상대 어깨 옆에 엉덩이를 내리고 다리를 넓게 벌려 무게를 싣는다','잡은 팔을 내 옆구리에 묶은 채 리버스 곁누르기(우시로 케사)로 누르고 다음 서브미션을 노린다']::text[];
update public.techniques set steps = array['상대 왼쪽 위에서 상대 오른팔에 기무라 그립(내 왼손이 손목)을 잡았는데 상대가 팔을 머리 쪽으로 밀어 올린다','팔이 머리 쪽으로 올라가면 내 오른손으로 상대 오른쪽 손목을 바닥에 눌러 고정한다(팔꿈치는 직각)','내 왼손을 상대 오른쪽 팔꿈치 아래로 넣어 내 오른손목을 잡아 아메리카나 그립으로 바꾼다','손목을 상대 엉덩이 쪽으로 미끄러뜨리며 팔꿈치를 들어 어깨를 비틀어 탭을 받는다']::text[] where slug = 'americana-from-kimura-trap' and owner_id is null and steps = array['위에서 기무라 그립을 잡았는데 상대가 팔을 머리 쪽으로 밀어 올려 버틴다','팔이 머리 쪽으로 올라가면 그 손목을 바닥에 눌러 고정한다(팔꿈치는 직각)','반대 손을 상대 팔꿈치 아래로 넣어 내 손목을 잡아 아메리카나 그립으로 바꾼다','손목을 상대 엉덩이 쪽으로 미끄러뜨리며 팔꿈치를 들어 어깨를 비틀어 탭을 받는다']::text[];
